INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种善游水、嘴扁脚有蹼的家禽。", "primary_collocate": null, "pronunciation": "yā", "ipa": "ja˥", "syllable_count": 1, "sentences": [{"text": "他家在乡下养鸡又养鸭。", "target_word": "鸭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民每天早上在池塘边放鸭。", "target_word": "鸭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农场里的鸡和鸭加起来有两百只。", "target_word": "鸭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王在市场上卖鸡，也卖几只鸭。", "target_word": "鸭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家去年养过三百只鸭。", "target_word": "鸭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人都靠养鸭赚钱。", "target_word": "鸭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说，过年要杀一只鸭招待客人。", "target_word": "鸭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸡吃玉米，鸭喜欢吃小鱼和水草。", "target_word": "鸭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天给鸡喂米，给鸭喂菜叶。", "target_word": "鸭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位农民养的一群鸭比鸡多得多。", "target_word": "鸭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "群", "label": "量词"}, {"form": "鸭子", "label": "复合"}, {"form": "烤鸭", "label": "复合"}, {"form": "鸭蛋", "label": "复合"}, {"form": "鴨", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家禽鸭：农家饲养、放养、买卖的鸭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e112e63-5ad4-468e-9be9-bdfe716f53e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97532, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鸭", "is_correct": true, "explanation": "鸭（yā，第一声）是一种善游水、嘴扁脚有蹼的家禽。"}, {"text": "牙", "is_correct": false, "explanation": "牙（yá，第二声）与 yā（第一声）声调不同，意思是牙齿。"}, {"text": "雅", "is_correct": false, "explanation": "雅（yǎ，第三声）与 yā（第一声）声调不同，意思是文雅。"}, {"text": "亚", "is_correct": false, "explanation": "亚（yà，第四声）与 yā（第一声）声调不同，意思是亚洲的亚。"}, {"text": "烟", "is_correct": false, "explanation": "烟（yān）比 yā 多一个鼻音 n，意思是烟雾。"}, {"text": "央", "is_correct": false, "explanation": "央（yāng）比 yā 多一个鼻音 ng，意思是中间，如“中央”。"}], "explanations": {"鸭": "鸭（yā，第一声）是一种善游水、嘴扁脚有蹼的家禽。", "牙": "牙（yá，第二声）与 yā（第一声）声调不同，意思是牙齿。", "雅": "雅（yǎ，第三声）与 yā（第一声）声调不同，意思是文雅。", "亚": "亚（yà，第四声）与 yā（第一声）声调不同，意思是亚洲的亚。", "烟": "烟（yān）比 yā 多一个鼻音 n，意思是烟雾。", "央": "央（yāng）比 yā 多一个鼻音 ng，意思是中间，如“中央”。"}, "sentence_index": null, "correct_answer": "鸭"}, "level_3": {"options": [{"text": "鸭", "is_correct": true, "explanation": "正确：鸭是家禽，与前文的“养鸡”并列，符合“养”的对象。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能饲养，与“养鸡又养”的意思不符。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“养”多用于动物或植物，不说“养电脑”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“养”不能与“房子”搭配，句子不通。"}], "explanations": {"鸭": "正确：鸭是家禽，与前文的“养鸡”并列，符合“养”的对象。", "垃圾": "语义：垃圾不能饲养，与“养鸡又养”的意思不符。", "电脑": "搭配：“养”多用于动物或植物，不说“养电脑”。", "房子": "搭配：“养”不能与“房子”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "鸭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家养了三头鸭，每天都要喂它们。", "explanation": "这里应该用〈只〉。鸭用量词“只”，“头”用于牛、猪等大型牲畜。"}, {"text": "他家养了三棵鸭，每天都要喂它们。", "explanation": "这里应该用〈只〉。鸭用量词“只”，“棵”用于树木和植物。"}, {"text": "他家养了三匹鸭，每天都要喂它们。", "explanation": "这里应该用〈只〉。鸭用量词“只”，“匹”用于马、驴等牲口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97532, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鸭", "is_correct": true, "explanation": "鸭（yā，第一声）是一种善游水、嘴扁脚有蹼的家禽。"}, {"text": "芽", "is_correct": false, "explanation": "芽（yá，第二声）与 yā（第一声）声调不同，意思是植物的嫩芽。"}, {"text": "哑", "is_correct": false, "explanation": "哑（yǎ，第三声）与 yā（第一声）声调不同，意思是不能说话。"}, {"text": "讶", "is_correct": false, "explanation": "讶（yà，第四声）与 yā（第一声）声调不同，意思是惊讶。"}, {"text": "腰", "is_correct": false, "explanation": "腰（yāo）比 yā 多一个元音 o，意思是人体的腰部。"}], "explanations": {"鸭": "鸭（yā，第一声）是一种善游水、嘴扁脚有蹼的家禽。", "芽": "芽（yá，第二声）与 yā（第一声）声调不同，意思是植物的嫩芽。", "哑": "哑（yǎ，第三声）与 yā（第一声）声调不同，意思是不能说话。", "讶": "讶（yà，第四声）与 yā（第一声）声调不同，意思是惊讶。", "腰": "腰（yāo）比 yā 多一个元音 o，意思是人体的腰部。"}, "sentence_index": null, "correct_answer": "鸭"}, "level_3": {"options": [{"text": "鸭", "is_correct": true, "explanation": "正确：鸭可以杀来招待客人，符合“杀一只”的搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能被杀。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是活物，“杀”不能用于桌子。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“杀”不能与“电话”搭配，句子不通。"}], "explanations": {"鸭": "正确：鸭可以杀来招待客人，符合“杀一只”的搭配。", "石头": "语义：石头没有生命，不能被杀。", "桌子": "语义：桌子不是活物，“杀”不能用于桌子。", "电话": "搭配：“杀”不能与“电话”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "鸭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民家里有三条鸭，每天都去喂。", "explanation": "这里应该用〈只〉。鸭用量词“只”，“条”用于细长的东西。"}, {"text": "我家里养着一张鸭，每天都去喂它。", "explanation": "这里应该用〈只〉。鸭用量词“只”，“张”用于纸、桌子等平面的东西。"}, {"text": "池塘边有一把鸭在游水。", "explanation": "这里应该用〈只〉。鸭用量词“只”，“把”用于有柄的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家养了三条鸭。", "corrected_sentence": "他家养了三只鸭。", "error_description": "错误：“三条鸭”，量词用错。正确：“三只鸭”。鸭用量词“只”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农场里有一群只鸭。", "corrected_sentence": "农场里有一群鸭。", "error_description": "错误：“一群只鸭”，群和只重复计量。正确：“一群鸭”。“群”本身已表示数量单位，后面不再加“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a389f1-db1f-4163-b6e5-f974fae02da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
