INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97535, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从以前到现在，一直都是这样。", "primary_collocate": null, "pronunciation": "yì zhí yǐ lái", "ipa": "i˥˩ ʈʂɻ̩˧˥ i˨˩ lai̯˧˥", "syllable_count": 4, "sentences": [{"text": "一直以来，我都习惯早上六点起床。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来，他对我都很好。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来，这家店的生意都不错。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来，妈妈都不让我喝咖啡。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来，我们都住在这个小城市。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直以来都喜欢画画儿。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来，大家都叫他小王。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来，我都觉得学汉语很有意思。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天一直以来都很冷。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来，爸爸每天都走路去上班。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：从过去到现在一直如此，常放在句首或主语后，与“都”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一直以来", "is_correct": true, "explanation": "正确：表示从过去到现在一直如此，与“都习惯”相符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指突然发生，与长期的习惯矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示不常发生，不能与“都”连用。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上，与“习惯”的长期性矛盾。"}], "explanations": {"一直以来": "正确：表示从过去到现在一直如此，与“都习惯”相符。", "忽然": "语义：“忽然”指突然发生，与长期的习惯矛盾。", "偶尔": "搭配：“偶尔”表示不常发生，不能与“都”连用。", "立刻": "语义：“立刻”指马上，与“习惯”的长期性矛盾。"}, "sentence_index": 0, "correct_answer": "一直以来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直以来住在北京，后来搬到了上海。", "explanation": "这里应该用〈以前〉。“一直以来”表示持续到现在，与“后来搬到了上海”矛盾。"}, {"text": "他一直以来是老师，现在在银行工作。", "explanation": "这里应该用〈曾经〉。“一直以来”表示持续到现在，与“现在在银行工作”矛盾。"}, {"text": "他一直以来都很瘦，现在胖多了。", "explanation": "这里应该用〈以前〉。“一直以来”表示持续到现在，与“现在胖多了”矛盾；说过去的情况要用“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一直以来", "is_correct": true, "explanation": "正确：表示长期以来一直如此，与“大家都叫他小王”相符。"}, {"text": "一下子", "is_correct": false, "explanation": "搭配：“一下子”指短时间内发生，不搭配长期的称呼。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指意外发生，与长期的状态矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "语义：“猛然”强调瞬间，与“大家都叫他”的长期状态矛盾。"}], "explanations": {"一直以来": "正确：表示长期以来一直如此，与“大家都叫他小王”相符。", "一下子": "搭配：“一下子”指短时间内发生，不搭配长期的称呼。", "突然": "语义：“突然”指意外发生，与长期的状态矛盾。", "猛然": "语义：“猛然”强调瞬间，与“大家都叫他”的长期状态矛盾。"}, "sentence_index": 6, "correct_answer": "一直以来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一直以来，我每天都坐公交车去学校，后来搬到了外地。", "explanation": "这里应该用〈从前〉。“一直以来”表示持续到现在，与“后来搬到了外地”矛盾；说过去的习惯要用“从前”。"}, {"text": "一直以来，他每天都去跑步，后来就再也没去过。", "explanation": "这里应该用〈原先〉。“一直以来”表示持续到现在，与“后来就再也没去过”矛盾；说过去的情况要用“原先”。"}, {"text": "一直以来，我们住在乡下，后来搬到了城里。", "explanation": "这里应该用〈早先〉。“一直以来”表示持续到现在，与“后来搬到了城里”的时间顺序冲突；说过去的情况要用“早先”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一直以来，他将要很努力地学习。", "corrected_sentence": "一直以来，他都很努力地学习。", "error_description": "时间矛盾：“一直以来”指从过去持续到现在，不能与表示将来的“将要”连用，应把“将要”改为“都”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一直以来了都住在这里。", "corrected_sentence": "我们一直以来都住在这里。", "error_description": "体标错误：“一直以来”是副词性的固定说法，后面不能加“了”，应把“一直以来了”改为“一直以来”，删去多余的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
