INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从过去开始直到现在的整个时期。", "primary_collocate": null, "pronunciation": "yì zhí yǐ lái", "ipa": "i˥˩ ʈʂɻ̩˧˥ i˨˩ lai̯˧˥", "syllable_count": 4, "sentences": [{"text": "谢谢你一直以来的帮助。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我一直以来的愿望。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来的努力没有白费。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直以来的习惯是晚上看书。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很感谢老师一直以来的关心。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这就是他一直以来的想法。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来的梦想终于实现了。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一直以来的做法是先问客人。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢大家一直以来的支持。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来的问题，今天终于解决了。", "target_word": "一直以来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：指从过去到现在的整个时期，常作定语，后接“的”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一直以来", "is_correct": true, "explanation": "正确：名词，指从过去到现在的整个时期，此处作定语修饰“帮助”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能提供帮助，与“谢谢你……的帮助”不符。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是食物，不能给人帮助。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“帮助”一般由人或组织给予，不说“雨水的帮助”。"}], "explanations": {"一直以来": "正确：名词，指从过去到现在的整个时期，此处作定语修饰“帮助”。", "桌子": "语义：桌子不能提供帮助，与“谢谢你……的帮助”不符。", "苹果": "语义：苹果是食物，不能给人帮助。", "雨水": "搭配：“帮助”一般由人或组织给予，不说“雨水的帮助”。"}, "sentence_index": 0, "correct_answer": "一直以来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直以来的习惯是晚上看书，现在改成早上看书了。", "explanation": "这里应该用〈以前〉。“一直以来”表示持续到现在，与“现在改成早上看书了”矛盾。"}, {"text": "他一直以来的梦想是当医生，后来他放弃了。", "explanation": "这里应该用〈曾经〉。“一直以来”表示持续到现在，与“后来他放弃了”矛盾。"}, {"text": "他一直以来的习惯，是上个月才养成的。", "explanation": "这里应该用〈最近〉。“一直以来的”指从过去持续到现在的整个时期，不能与“上个月才养成”连用；刚形成不久的情况要说“最近的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一直以来", "is_correct": true, "explanation": "正确：名词，指从过去到现在的整个时期，此处作定语修饰“梦想”。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“梦想”的主体一般是人，“早餐”没有梦想，不能说“早餐的梦想”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有梦想，与“梦想”的主体不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“梦想”的主体一般是人，不说“冰箱的梦想”。"}], "explanations": {"一直以来": "正确：名词，指从过去到现在的整个时期，此处作定语修饰“梦想”。", "早餐": "搭配：“梦想”的主体一般是人，“早餐”没有梦想，不能说“早餐的梦想”。", "石头": "语义：石头没有梦想，与“梦想”的主体不符。", "冰箱": "搭配：“梦想”的主体一般是人，不说“冰箱的梦想”。"}, "sentence_index": 6, "correct_answer": "一直以来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一直以来的变化是昨天才出现的。", "explanation": "这里应该用〈近来〉。“一直以来的”指从过去持续到现在的整个时期，与“昨天才出现”的时间矛盾；最近才发生的变化要说“近来的”。"}, {"text": "他一直以来的工作是教书，后来辞职了。", "explanation": "这里应该用〈原先〉。“一直以来的”指从过去持续到现在，与“后来辞职了”矛盾；过去有、后来不再有的要说“原先的”。"}, {"text": "一直以来的老房子，三年前就拆了。", "explanation": "这里应该用〈从前〉。“一直以来的”指持续到现在，与“三年前就拆了”矛盾；过去存在、如今已不在的事物要说“从前的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是他一直以来心愿。", "corrected_sentence": "这是他一直以来的心愿。", "error_description": "结构错误：“一直以来”作定语修饰名词时，后面要加“的”，应说“一直以来的心愿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我们一直以来目标。", "corrected_sentence": "这是我们一直以来的目标。", "error_description": "结构错误：“一直以来”作定语修饰名词时，后面要加“的”，应说“一直以来的目标”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
