INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家都要遵守的普通规矩。", "primary_collocate": null, "pronunciation": "yì bān guī dìng", "ipa": "i˥˩ pan˥ kweɪ˥ tiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "学校有一般规定，上课不能玩手机。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小区的一般规定，大家都要遵守。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆的一般规定是不能大声说话。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新同事要先学习公司的一般规定。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不知道一般规定，所以迟到了。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来这里住的人，都要遵守一般规定。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一般规定写在门口的牌子上。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乘坐地铁有一般规定，比如不能吃东西。", "target_word": "一般规定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都记住了教室的一般规定。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游泳池的一般规定贴在墙上。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大家日常都要遵守的普通规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eca7faf1-53e9-4820-92b2-8ca5390197ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97539, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一般规定", "is_correct": true, "explanation": "正确。「学校有一般规定，上课不能玩手机」中，「一般规定」指大家都要遵守的普通校规。"}, {"text": "财务规定", "is_correct": false, "explanation": "语义：「财务规定」管钱款和账目，与「上课不能玩手机」无关。"}, {"text": "交通规定", "is_correct": false, "explanation": "语义：「交通规定」管道路和车辆通行，与「上课不能玩手机」无关。"}, {"text": "家规", "is_correct": false, "explanation": "语义：「家规」是家庭内部的规矩，不是学校的规矩，与句中“学校有……”不符。"}], "explanations": {"一般规定": "正确。「学校有一般规定，上课不能玩手机」中，「一般规定」指大家都要遵守的普通校规。", "财务规定": "语义：「财务规定」管钱款和账目，与「上课不能玩手机」无关。", "交通规定": "语义：「交通规定」管道路和车辆通行，与「上课不能玩手机」无关。", "家规": "语义：「家规」是家庭内部的规矩，不是学校的规矩，与句中“学校有……”不符。"}, "sentence_index": 0, "correct_answer": "一般规定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新同事要先学习公司的一般规定，但是可以随便不遵守。", "explanation": "这里应该用〈自愿〉。「一般规定」是大家都要遵守的规矩；说「可以随便不遵守」等于把它当成了〈自愿〉的事，与词义相反。"}, {"text": "公司的一般规定只有老板一个人能看。", "explanation": "这里应该用〈内部规定〉。「一般规定」是人人都要遵守的规矩，应当人人可知；只有老板能看的应是〈内部规定〉。"}, {"text": "老师给我们提了一些一般规定，大家听听就好，不用真的照做。", "explanation": "这里应该用〈建议〉。「建议」可听可不听，供人参考；「一般规定」是必须遵守的规矩，不能说“不用照做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一般规定", "is_correct": true, "explanation": "正确。「一般规定写在门口的牌子上」中，指的是大家都要遵守、要公开张贴的普通规矩。"}, {"text": "剧本", "is_correct": false, "explanation": "语义：「剧本」是戏剧的文字稿，不会写在门口的牌子上。"}, {"text": "病历", "is_correct": false, "explanation": "语义：「病历」是病人的私人医疗记录，不会公开贴在门口。"}, {"text": "乐谱", "is_correct": false, "explanation": "搭配：「乐谱」一般不说写在牌子上，搭配不当。"}], "explanations": {"一般规定": "正确。「一般规定写在门口的牌子上」中，指的是大家都要遵守、要公开张贴的普通规矩。", "剧本": "语义：「剧本」是戏剧的文字稿，不会写在门口的牌子上。", "病历": "语义：「病历」是病人的私人医疗记录，不会公开贴在门口。", "乐谱": "搭配：「乐谱」一般不说写在牌子上，搭配不当。"}, "sentence_index": 6, "correct_answer": "一般规定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游泳池的一般规定只为专家准备，普通人不用遵守。", "explanation": "这里应该用〈专业规范〉。「一般规定」是大家都要遵守的普通规矩；只为专家准备的应是〈专业规范〉，此句与词义相反。"}, {"text": "游泳池的一般规定很好吃，大家都喜欢。", "explanation": "这里应该用〈点心〉。「一般规定」是规矩，不能说“好吃”；能吃的应是〈点心〉之类的食物。"}, {"text": "游泳池的一般规定位于市中心，大家都知道在哪里。", "explanation": "这里应该用〈地址〉。「一般规定」是规矩的内容，不能说它位于某地；说位置要用〈地址〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只一般规定，大家都要遵守。", "corrected_sentence": "这条一般规定，大家都要遵守。", "error_description": "量词错误：「一般规定」应该用量词「条」，写成「这只一般规定」是把「只」用于规定。「只」用于动物或单个物件，规定要说「这条」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆的一块一般规定，大家都要照着做。", "corrected_sentence": "图书馆的一条一般规定，大家都要照着做。", "error_description": "量词错误：「一般规定」应该用量词「条」，写成「一块一般规定」是把「块」用于规定。「块」用于块状物，规定要说「一条」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
