INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "适用于一般情况的规定。", "primary_collocate": null, "pronunciation": "yì bān guī dìng", "ipa": "i˥˩ pan˥ kweɪ˥ tiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这是一般规定，特殊情况可以不同。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "按一般规定，请假要提前一天说。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一般规定不能用于这种特殊情况。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了一般规定以外，还有一些特别的办法。", "target_word": "一般规定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的一般规定很清楚，大家照着做就行。", "target_word": "一般规定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条一般规定适用于所有新学生。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师先讲了一般规定，再讲例外。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先看看一般规定，再问有没有例外。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文件写的是一般规定。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一般规定里没有这种情况。", "target_word": "一般规定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "适用于普通情况、不含例外的规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eca7faf1-53e9-4820-92b2-8ca5390197ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一般规定", "is_correct": true, "explanation": "正确。「一般规定」指适用于一般情况的规定，句中「特殊情况可以不同」正说明它是一般性的规定。"}, {"text": "绝对规定", "is_correct": false, "explanation": "语义：「绝对」表示没有例外，与句中「特殊情况可以不同」矛盾。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是规定，无法用“这是……，特殊情况可以不同”来描述。"}, {"text": "特殊规定", "is_correct": false, "explanation": "搭配：「特殊规定」与后句的「特殊情况」重复，且语义冲突，句子不通。"}], "explanations": {"一般规定": "正确。「一般规定」指适用于一般情况的规定，句中「特殊情况可以不同」正说明它是一般性的规定。", "绝对规定": "语义：「绝对」表示没有例外，与句中「特殊情况可以不同」矛盾。", "天气": "语义：「天气」不是规定，无法用“这是……，特殊情况可以不同”来描述。", "特殊规定": "搭配：「特殊规定」与后句的「特殊情况」重复，且语义冲突，句子不通。"}, "sentence_index": 0, "correct_answer": "一般规定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条一般规定只适用于少数例外情况。", "explanation": "这里应该用〈特殊规定〉。「一般规定」适用于一般情况，只适用于少数例外情况的应是〈特殊规定〉，与词义相反。"}, {"text": "这条一般规定只针对张三一个人。", "explanation": "这里应该用〈专门规定〉。「一般规定」适用于一般情况；只针对张三一个人的规定属于〈专门规定〉，与此词的词义相反。"}, {"text": "这条一般规定只在春节期间有效。", "explanation": "这里应该用〈临时规定〉。只在春节期间有效的应是〈临时规定〉；「一般规定」适用于一般情况，不限于某段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一般规定", "is_correct": true, "explanation": "正确。「老师先讲了一般规定，再讲例外」中，「一般规定」与后面的「例外」相对，说明它是一般情况下的规定。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是规定，无法作“先讲……，再讲例外”的内容。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是规定，“先讲颜色，再讲例外”句意不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：「早饭」是一顿饭，不是规定，没有“例外”可讲，句意不通。"}], "explanations": {"一般规定": "正确。「老师先讲了一般规定，再讲例外」中，「一般规定」与后面的「例外」相对，说明它是一般情况下的规定。", "天气": "语义：「天气」不是规定，无法作“先讲……，再讲例外”的内容。", "颜色": "语义：「颜色」不是规定，“先讲颜色，再讲例外”句意不通。", "早饭": "语义：「早饭」是一顿饭，不是规定，没有“例外”可讲，句意不通。"}, "sentence_index": 6, "correct_answer": "一般规定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份一般规定只在我们班有效，其他班不用遵守。", "explanation": "这里应该用〈班规〉。只在一个班有效的规定是班规；「一般规定」适用于一般情况，此句与词义相反。"}, {"text": "这种一般规定专门用来处理特殊情况。", "explanation": "这里应该用〈特殊规定〉。专门用来处理特殊情况的属于〈特殊规定〉；「一般规定」适用于一般情况，此句与词义相反。"}, {"text": "这份一般规定是老板专门为小王写的。", "explanation": "这里应该用〈个别规定〉。专为某一个人制定的属于〈个别规定〉；「一般规定」要适用于一般情况，此句与词义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只一般规定，在大多数情况下都适用。", "corrected_sentence": "这条一般规定，在大多数情况下都适用。", "error_description": "量词错误：「一般规定」应该用量词「条」，写成「这只一般规定」是把「只」用于规定。「只」用于动物或单个物件，规定要说「这条」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的一把一般规定，在大多数情况下都适用。", "corrected_sentence": "学校的一条一般规定，在大多数情况下都适用。", "error_description": "量词错误：「一般规定」应该用量词「条」，写成「一把一般规定」是把「把」用于规定。「把」用于有柄的器具，规定要说「一条」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
