INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97543, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "差不多的一种。", "primary_collocate": null, "pronunciation": "yī lèi", "ipa": "i˥ lei˥˩", "syllable_count": 2, "sentences": [{"text": "他这一类人，说话总是很客气。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这一类电影，看了很多。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是那一类很会做饭的人。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一类问题很容易回答。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢看这一类书，比如故事书。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一类水果很甜，孩子们都爱吃。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一类手机很便宜，学生都爱买。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲过这一类题，我们都会做。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太喜欢这一类音乐。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢和这一类朋友在一起。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一类人", "label": "复合"}, {"form": "一類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "差不多的一种，常说“这一类”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97543, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一类", "is_correct": true, "explanation": "正确答案。yī lèi，指这一种。"}, {"text": "异类", "is_correct": false, "explanation": "声母和韵母相同，只有第一个音节的声调不同：yì（第四声）与 yī（第一声），意思是不同种类、异类。"}, {"text": "一列", "is_correct": false, "explanation": "第二个音节韵母不同：liè 与 lèi（ie 与 ei），意思是一排、一列。"}, {"text": "一例", "is_correct": false, "explanation": "第二个音节韵母不同：lì 与 lèi（i 与 ei），意思是一个例子。"}, {"text": "一垒", "is_correct": false, "explanation": "lěi（第三声）与 lèi（第四声）声调不同，意思是棒球中的一垒。"}, {"text": "一倍", "is_correct": false, "explanation": "第二个音节声母不同：bèi 与 lèi（b 与 l），意思是一倍。"}], "explanations": {"一类": "正确答案。yī lèi，指这一种。", "异类": "声母和韵母相同，只有第一个音节的声调不同：yì（第四声）与 yī（第一声），意思是不同种类、异类。", "一列": "第二个音节韵母不同：liè 与 lèi（ie 与 ei），意思是一排、一列。", "一例": "第二个音节韵母不同：lì 与 lèi（i 与 ei），意思是一个例子。", "一垒": "lěi（第三声）与 lèi（第四声）声调不同，意思是棒球中的一垒。", "一倍": "第二个音节声母不同：bèi 与 lèi（b 与 l），意思是一倍。"}, "sentence_index": null, "correct_answer": "一类"}, "level_3": {"options": [{"text": "一类", "is_correct": true, "explanation": "正确。“他这一类人”指这种人，与“说话总是很客气”相合。"}, {"text": "一件", "is_correct": false, "explanation": "量词：“件”用于物品，不能修饰人，“他这一件人”说不通。"}, {"text": "一天", "is_correct": false, "explanation": "语义：“一天”指一段时间，不能指人群，句子不通。"}, {"text": "一场", "is_correct": false, "explanation": "搭配：“一场”多修饰活动或事件，不能修饰“人”。"}], "explanations": {"一类": "正确。“他这一类人”指这种人，与“说话总是很客气”相合。", "一件": "量词：“件”用于物品，不能修饰人，“他这一件人”说不通。", "一天": "语义：“一天”指一段时间，不能指人群，句子不通。", "一场": "搭配：“一场”多修饰活动或事件，不能修饰“人”。"}, "sentence_index": 0, "correct_answer": "一类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一类是我的弟弟，他很高。", "explanation": "这里应该用〈这一位〉。“这一类”指差不多的一种，指一个人要用“这一位”，不能用“这一类”。"}, {"text": "这一类我没去，因为生病了。", "explanation": "这里应该用〈这一次〉。“这一类”指差不多的一种，指某一次的事要用“这一次”。"}, {"text": "我们一类去爬山吧。", "explanation": "这里应该用〈一起〉。“一类”指差不多的一种，表示共同做事要用“一起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一类", "is_correct": true, "explanation": "正确。“这一类手机”指这种手机，与“很便宜”相合。"}, {"text": "一位", "is_correct": false, "explanation": "搭配：“位”用于人，不能修饰手机，“这一位手机”说不通。"}, {"text": "一伙", "is_correct": false, "explanation": "语义：“一伙”指一群人（多含贬义），不能用来指手机的种类，“这一伙手机”说不通。"}, {"text": "一群", "is_correct": false, "explanation": "语义：“群”指聚在一起的人或动物，手机不成群，与句意不合。"}], "explanations": {"一类": "正确。“这一类手机”指这种手机，与“很便宜”相合。", "一位": "搭配：“位”用于人，不能修饰手机，“这一位手机”说不通。", "一伙": "语义：“一伙”指一群人（多含贬义），不能用来指手机的种类，“这一伙手机”说不通。", "一群": "语义：“群”指聚在一起的人或动物，手机不成群，与句意不合。"}, "sentence_index": 6, "correct_answer": "一类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们这一类三个人去了公园。", "explanation": "这里应该用〈一共〉。“这一类”指差不多的一种，不能用来表示合计人数，合计要用“一共”。"}, {"text": "他和我这一类高。", "explanation": "这里应该用〈一样〉。“这一类”指差不多的一种，表示高矮相同要用“一样”，“这一类高”说不通。"}, {"text": "他这一类就是我的老师，教我数学。", "explanation": "这里应该用〈这一位〉。“这一类”指差不多的一种，指一个人要用“这一位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那一类个电影很有意思，大家都爱看。", "corrected_sentence": "那一类电影很有意思，大家都爱看。", "error_description": "错误：“个”放错了。“那一类”后直接接“电影”，不加“个”，应说“那一类电影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她总是和这一类只同学一起吃饭。", "corrected_sentence": "她总是和这一类同学一起吃饭。", "error_description": "错误：“只”放错了。“同学”指人，不用“只”作量词，应直接说“这一类同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
