INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97544, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同一类；同一种类。", "primary_collocate": null, "pronunciation": "yī lèi", "ipa": "i˥ lei˥˩", "syllable_count": 2, "sentences": [{"text": "猫和老虎是一类动物。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书是一类，都讲历史。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果和香蕉都属于一类。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把这些东西分成一类。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个不是一类人，常常吵架。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把红色的放在一起，它们是一类。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲸鱼和鱼不是一类。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎和狮子是一类，都吃肉。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书和杂志可以归为一类。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生和护士是一类人，都想帮助别人。", "target_word": "一类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一类人", "label": "复合"}, {"form": "一類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "属于同一个种类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd3d28e-d666-4196-aa5b-84357d8ccfe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97544, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一类", "is_correct": true, "explanation": "正确答案。yī lèi，指同一种类。"}, {"text": "异类", "is_correct": false, "explanation": "声母和韵母相同，只有第一个音节的声调不同：yì（第四声）与 yī（第一声），意思是不同种类、异类。"}, {"text": "一列", "is_correct": false, "explanation": "第二个音节韵母不同：liè 与 lèi（ie 与 ei），意思是一排、一列。"}, {"text": "一例", "is_correct": false, "explanation": "第二个音节韵母不同：lì 与 lèi（i 与 ei），意思是一个例子。"}, {"text": "一垒", "is_correct": false, "explanation": "lěi（第三声）与 lèi（第四声）声调不同，意思是棒球中的一垒。"}, {"text": "一倍", "is_correct": false, "explanation": "第二个音节声母不同：bèi 与 lèi（b 与 l），意思是一倍。"}], "explanations": {"一类": "正确答案。yī lèi，指同一种类。", "异类": "声母和韵母相同，只有第一个音节的声调不同：yì（第四声）与 yī（第一声），意思是不同种类、异类。", "一列": "第二个音节韵母不同：liè 与 lèi（ie 与 ei），意思是一排、一列。", "一例": "第二个音节韵母不同：lì 与 lèi（i 与 ei），意思是一个例子。", "一垒": "lěi（第三声）与 lèi（第四声）声调不同，意思是棒球中的一垒。", "一倍": "第二个音节声母不同：bèi 与 lèi（b 与 l），意思是一倍。"}, "sentence_index": null, "correct_answer": "一类"}, "level_3": {"options": [{"text": "一类", "is_correct": true, "explanation": "正确。“猫和老虎是一类动物”表示两者属于同一类别。"}, {"text": "一本", "is_correct": false, "explanation": "量词：“本”用于书籍，不能用来指动物，“猫和老虎是一本动物”说不通。"}, {"text": "一伙", "is_correct": false, "explanation": "语义：“一伙”指一群人（多含贬义），不能用来给动物分类，“一伙动物”说不通。"}, {"text": "一家", "is_correct": false, "explanation": "搭配：“一家”指同一家庭或同一店铺，不能用来给动物分类。"}], "explanations": {"一类": "正确。“猫和老虎是一类动物”表示两者属于同一类别。", "一本": "量词：“本”用于书籍，不能用来指动物，“猫和老虎是一本动物”说不通。", "一伙": "语义：“一伙”指一群人（多含贬义），不能用来给动物分类，“一伙动物”说不通。", "一家": "搭配：“一家”指同一家庭或同一店铺，不能用来给动物分类。"}, "sentence_index": 0, "correct_answer": "一类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一类去看电影吧。", "explanation": "这里应该用〈一起〉。“一类”指种类，表示共同做事要用“一起”，不能用“一类”。"}, {"text": "这是我的一类猫，它很可爱。", "explanation": "这里应该用〈一只〉。“一类”指一种，猫是个体，指一只猫要用“只”，不能说成“一类”。"}, {"text": "他们俩一类高。", "explanation": "这里应该用〈一样〉。“一类”指同一种类，表示高矮相同要用“一样”，“一类高”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一类", "is_correct": true, "explanation": "正确。“鲸鱼和鱼不是一类”表示两者不属于同一类别。"}, {"text": "陆地", "is_correct": false, "explanation": "语义：“陆地”指陆上的区域，鲸鱼和鱼不是陆地，句子无意义。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”指大气状况，不能作为动物的归属类别，搭配不当。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”指特定的日子，与动物的分类无关。"}], "explanations": {"一类": "正确。“鲸鱼和鱼不是一类”表示两者不属于同一类别。", "陆地": "语义：“陆地”指陆上的区域，鲸鱼和鱼不是陆地，句子无意义。", "天气": "搭配：“天气”指大气状况，不能作为动物的归属类别，搭配不当。", "节日": "语义：“节日”指特定的日子，与动物的分类无关。"}, "sentence_index": 6, "correct_answer": "一类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那一类就是我的朋友，他叫小王。", "explanation": "这里应该用〈那一位〉。“一类”指种类，指某一个人要用“位”，不能说“那一类”。"}, {"text": "这本书我读了一类。", "explanation": "这里应该用〈一遍〉。“一类”指种类，表示读了一次要用“一遍”，不能用“一类”。"}, {"text": "我们一类三个人去爬山。", "explanation": "这里应该用〈一共〉。“一类”指种类，表示合计人数要用“一共”，不能用“一类”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三种水果属于一类类，都是热带的。", "corrected_sentence": "这三种水果属于一类，都是热带的。", "error_description": "错误：“类”多写了一次。正确：“一类”，“类”不重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个词一类属于，都是名词。", "corrected_sentence": "这几个词属于一类，都是名词。", "error_description": "错误：语序颠倒。“一类”应放在动词“属于”后面作宾语，应说“属于一类”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60c94d26-4aeb-4153-9511-d5d8392c552d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
