INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97547, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到了新的工作位子，开始做事。", "primary_collocate": null, "pronunciation": "shàng rèn", "ipa": "ʂaŋ˥˩ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "小李升了职，下周就去新部门上任。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的主任今天上任，大家都去欢迎他。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚上任，还不太懂这里的工作。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上任第一天，同事们都帮了我很多。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换了工作，三月一日上任。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新队长上任后，先开了一个小会。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张上任以后，每天最早到公司。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚上任，就把办公室打扫得干干净净。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理上任的那天，公司里很热闹。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候去新公司上任？", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上任了", "label": "体标"}, {"form": "上任后", "label": "复合"}], "register": "中性", "sense_fingerprint": "到新的工作岗位开始做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ba1162-f38e-4526-87af-4a5384970596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上任", "is_correct": true, "explanation": "上任：指到新的岗位开始工作，与“下周就去新部门”搭配。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：刚升职又辞职，与句中的升职情境矛盾。"}, {"text": "放假", "is_correct": false, "explanation": "搭配：“去新部门放假”的说法不通，“放假”不能与“去新部门”搭配。"}, {"text": "失业", "is_correct": false, "explanation": "语义：失业与升职的情境正好相反，句意矛盾。"}], "explanations": {"上任": "上任：指到新的岗位开始工作，与“下周就去新部门”搭配。", "辞职": "语义：刚升职又辞职，与句中的升职情境矛盾。", "放假": "搭配：“去新部门放假”的说法不通，“放假”不能与“去新部门”搭配。", "失业": "语义：失业与升职的情境正好相反，句意矛盾。"}, "sentence_index": 0, "correct_answer": "上任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天八点上任，同事们都很友好。", "explanation": "这里应该用〈上班〉。上任指就任新的岗位，只发生一次，不用于每天的上下班。"}, {"text": "新生今天到学校上任，老师很热情。", "explanation": "这里应该用〈报到〉。上任用于工作岗位，新生到校登记要说“报到”。"}, {"text": "选手明天上任，大家都来加油。", "explanation": "这里应该用〈参赛〉。上任指就任岗位，选手参加比赛要说“参赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上任", "is_correct": true, "explanation": "上任：与“以后”搭配，表示老张就任岗位之后每天都早到公司。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉以后”每天最早到公司，与句中的工作情境矛盾。"}, {"text": "逃学", "is_correct": false, "explanation": "搭配：“逃学”的主体是学生，不能用于老张去公司。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧与“每天最早到公司”的情境矛盾，句意不通。"}], "explanations": {"上任": "上任：与“以后”搭配，表示老张就任岗位之后每天都早到公司。", "睡觉": "语义：“睡觉以后”每天最早到公司，与句中的工作情境矛盾。", "逃学": "搭配：“逃学”的主体是学生，不能用于老张去公司。", "发烧": "语义：发烧与“每天最早到公司”的情境矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "上任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "演员明天上任，你来看吗？", "explanation": "这里应该用〈登台〉。上任指就任岗位，演员登台表演要说“登台”。"}, {"text": "妹妹明年上任，你去送她吗？", "explanation": "这里应该用〈入学〉。上任用于工作岗位，孩子开始上学要说“入学”。"}, {"text": "我们下周上任，去哪里玩？", "explanation": "这里应该用〈放假〉。上任指就任岗位，假期到来要说“放假”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下周就要上任着。", "corrected_sentence": "他下周就要上任了。", "error_description": "错误：“上任”是一次性动作，不能用“着”表示持续；与表示将来的“下周就要”搭配时，应在“上任”后用“了”，写作“就要上任了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下周就去新公司上任过。", "corrected_sentence": "他下周就去新公司上任。", "error_description": "错误：“过”表示已经发生过的经历，与将来的“下周”矛盾；应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
