INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97548, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "官员就职，开始担任职务。", "primary_collocate": null, "pronunciation": "shàng rèn", "ipa": "ʂaŋ˥˩ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "新市长昨天正式上任了。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王局长上任后，先去工厂看了看。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚上任，就遇到了一个大问题。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新校长下个月就要上任。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等新县长上任。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县长上任第一天，就去村里走了走。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她上任以后，学校变化很大。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新上任的部长今天会见记者。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老书记走了，新书记明天上任。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长上任时，对大家说了几句话。", "target_word": "上任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上任了", "label": "体标"}, {"form": "上任后", "label": "复合"}], "register": "正式", "sense_fingerprint": "官员就职，开始担任职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ba1162-f38e-4526-87af-4a5384970596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上任", "is_correct": true, "explanation": "上任：与“正式”“了”搭配，表示市长正式开始任职。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”与市长的任职毫不相关，句意荒谬。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“正式感冒了”说不通，感冒与市长任职毫无关系。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”的主体是学生，不能用于市长。"}], "explanations": {"上任": "上任：与“正式”“了”搭配，表示市长正式开始任职。", "出生": "语义：“出生”与市长的任职毫不相关，句意荒谬。", "感冒": "语义：“正式感冒了”说不通，感冒与市长任职毫无关系。", "毕业": "搭配：“毕业”的主体是学生，不能用于市长。"}, "sentence_index": 0, "correct_answer": "上任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天七点上任，准时到公司。", "explanation": "这里应该用〈上班〉。上任指就任职务、开始担任职位，只发生一次，不用于每天的上下班。"}, {"text": "新生今天到学校上任，办理手续。", "explanation": "这里应该用〈报到〉。上任用于职务，学生到校登记、办理手续要用“报到”。"}, {"text": "孩子七岁就上任，开始读书。", "explanation": "这里应该用〈上学〉。上任指担任职务，孩子开始读书要说“上学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上任", "is_correct": true, "explanation": "上任：与“以后”搭配，表示她就任职务之后，学校发生了很大变化。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病与学校的变化没有关系，句意不通。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”与学校发生很大变化之间没有逻辑关系，句意不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生是人生的开端，与学校变化之间没有逻辑关系。"}], "explanations": {"上任": "上任：与“以后”搭配，表示她就任职务之后，学校发生了很大变化。", "生病": "语义：生病与学校的变化没有关系，句意不通。", "跑步": "语义：“跑步”与学校发生很大变化之间没有逻辑关系，句意不通。", "出生": "语义：出生是人生的开端，与学校变化之间没有逻辑关系。"}, "sentence_index": 6, "correct_answer": "上任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新歌手今晚上任，观众都在等她。", "explanation": "这里应该用〈登场〉。上任指就任职务，歌手登台表演要说“登场”。"}, {"text": "选手明天上任，去参加比赛。", "explanation": "这里应该用〈参赛〉。上任指就任职务，选手去比赛要说“参赛”。"}, {"text": "妹妹明年上任，读小学一年级。", "explanation": "这里应该用〈入学〉。上任用于职务，孩子开始上学要说“入学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天上任过。", "corrected_sentence": "他明天上任。", "error_description": "错误：“过”表示已经发生过的经历，与将来的“明天”矛盾；应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新市长昨天上任了市长。", "corrected_sentence": "新市长昨天上任了。", "error_description": "错误：“上任”是不及物动词，后面不能带职务作宾语，不说“上任了市长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
