INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97552, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中国和外国。", "primary_collocate": null, "pronunciation": "zhōng wài", "ipa": "ʈʂʊŋ˥ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "中外的学生一起上课。", "target_word": "中外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这所大学有很多中外老师。", "target_word": "中外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年都有中外客人来这家饭店。", "target_word": "中外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中外的孩子都爱看这部动画片。", "target_word": "中外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电影在中外都很有名。", "target_word": "中外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们请了中外的专家来开会。", "target_word": "中外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中外的菜他都喜欢吃。", "target_word": "中外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "报纸上有中外新闻。", "target_word": "中外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的书在中外都有人读。", "target_word": "中外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次活动有很多中外朋友参加。", "target_word": "中外", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指中国和外国，常修饰人、事物或表示范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abce999f-3fc1-404e-9d60-5f1209efb4c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中外", "is_correct": true, "explanation": "“中外”指中国和外国，修饰“学生”，表示学生的来源，句意通顺。"}, {"text": "木材", "is_correct": false, "explanation": "语义：“木材”不是人，不能修饰“学生”，句子读不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不能指上课的学生。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“钢铁”多修饰工业或产品，不能用来修饰“学生”。"}], "explanations": {"中外": "“中外”指中国和外国，修饰“学生”，表示学生的来源，句意通顺。", "木材": "语义：“木材”不是人，不能修饰“学生”，句子读不通。", "冰箱": "语义：“冰箱”是家电，不能指上课的学生。", "钢铁": "搭配：“钢铁”多修饰工业或产品，不能用来修饰“学生”。"}, "sentence_index": 0, "correct_answer": "中外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子中外都很干净。", "explanation": "这里应该用〈里外〉。“中外”指中国和外国，不能指房间的里面和外面。"}, {"text": "我的老家在中外。", "explanation": "这里应该用〈中国〉。“中外”是中国和外国的合称，不是一个具体的地方，不能说“老家在中外”。"}, {"text": "我想去中外工作。", "explanation": "这里应该用〈国外〉。“中外”包括中国，不能表示“去国外”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中外", "is_correct": true, "explanation": "“中外”指中国和外国，修饰“菜”，表示菜品的来源，句意通顺。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不能作菜品的修饰语，句子读不通。"}, {"text": "足球", "is_correct": false, "explanation": "语义：“足球”是体育项目，与菜品无关，句子读不通。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“菜”前的修饰语一般是菜系或产地，“汽车”不能用来修饰菜。"}], "explanations": {"中外": "“中外”指中国和外国，修饰“菜”，表示菜品的来源，句意通顺。", "钢琴": "语义：“钢琴”是乐器，不能作菜品的修饰语，句子读不通。", "足球": "语义：“足球”是体育项目，与菜品无关，句子读不通。", "汽车": "搭配：“菜”前的修饰语一般是菜系或产地，“汽车”不能用来修饰菜。"}, "sentence_index": 6, "correct_answer": "中外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在中外出生，一直没离开过。", "explanation": "这里应该用〈这座城市〉。“中外”不是具体的地点，不能用来指出生的城市。"}, {"text": "我们家住在中外。", "explanation": "这里应该用〈海边〉。“中外”是中国和外国的合称，不是一个居住的地方，不能这样说。"}, {"text": "他的国籍是中外。", "explanation": "这里应该用〈中国〉。“中外”指中国和外国两方，不能用来指一个人的国籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们请了中外地学者来讲座。", "corrected_sentence": "我们请了中外的学者来讲座。", "error_description": "错误：“中外”作定语时应用“的”连接，此处误用“地”。“地”标示状语，“中外地学者”不能成立，应改为“中外的学者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很中外选手都可以报名参加。", "corrected_sentence": "中外选手都可以报名参加。", "error_description": "错误：“中外”前加了程度副词“很”。“中外”作定语修饰名词，不能受“很”修饰。正确说法是“中外选手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
