INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在国际会议中担任主席的国家。", "primary_collocate": null, "pronunciation": "zhǔ xí guó", "ipa": "ʈʂu˨˩˦ ɕi˧˥ kwo˧˥", "syllable_count": 3, "sentences": [{"text": "这个国际组织的主席国每半年换一次。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为主席国，我们要让各国意见一致。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国安理会每月有一个主席国。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席国的外交部长主持了会议。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "峰会结束后，主席国发表了声明。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席国邀请各国领导人讨论气候问题。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次国际会议的主席国是法国。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席国要保证每个国家都能发言。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这次谈判中，主席国是一个重要角色。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席国的总统在会上做了开场讲话。", "target_word": "主席国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "主席國", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "主席国：名词，国际会议或国际组织中担任主席的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dce18cdf-2b41-42df-bd93-0b394f53e672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主席国", "is_correct": true, "explanation": "正确：主席国指国际组织中轮值主持的国家，“每半年换一次”与之相符。"}, {"text": "会徽", "is_correct": false, "explanation": "语义：会徽是组织的标志，不会像轮值职务那样每半年更换一次。"}, {"text": "会费", "is_correct": false, "explanation": "搭配：“每半年换一次”搭配人员或职务，不搭配“会费”。"}, {"text": "宪章", "is_correct": false, "explanation": "语义：宪章是组织的根本规章，不是可以轮换的职务，“每半年换一次”说不通。"}], "explanations": {"主席国": "正确：主席国指国际组织中轮值主持的国家，“每半年换一次”与之相符。", "会徽": "语义：会徽是组织的标志，不会像轮值职务那样每半年更换一次。", "会费": "搭配：“每半年换一次”搭配人员或职务，不搭配“会费”。", "宪章": "语义：宪章是组织的根本规章，不是可以轮换的职务，“每半年换一次”说不通。"}, "sentence_index": 0, "correct_answer": "主席国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议选出了一位主席国。", "explanation": "这里应该用〈个〉。“位”用于人，而“主席国”是国家，应该用“个”。"}, {"text": "这次会议由一名主席国主持。", "explanation": "这里应该用〈个〉。“名”用于人，而“主席国”是国家，应该用“个”。"}, {"text": "今年这个组织换了一家主席国。", "explanation": "这里应该用〈个〉。“家”多用于商店、公司或家庭，国家不能用“家”计量，应该用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主席国", "is_correct": true, "explanation": "正确：主席国指这次国际会议轮值主持的国家，与“是法国”相符。"}, {"text": "议程", "is_correct": false, "explanation": "语义：议程是会议的安排，不是国家，“议程是法国”说不通。"}, {"text": "日程", "is_correct": false, "explanation": "语义：日程是时间安排，不是国家，“日程是法国”说不通。"}, {"text": "会旗", "is_correct": false, "explanation": "语义：会旗是标志物，不是国家，“会旗是法国”说不通。"}], "explanations": {"主席国": "正确：主席国指这次国际会议轮值主持的国家，与“是法国”相符。", "议程": "语义：议程是会议的安排，不是国家，“议程是法国”说不通。", "日程": "语义：日程是时间安排，不是国家，“日程是法国”说不通。", "会旗": "语义：会旗是标志物，不是国家，“会旗是法国”说不通。"}, "sentence_index": 6, "correct_answer": "主席国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "安理会这个月由一位主席国负责。", "explanation": "这里应该用〈个〉。“位”用于人，而“主席国”是国家，应该用“个”。"}, {"text": "大会宣布了一名新的主席国。", "explanation": "这里应该用〈个〉。“名”用于人，而“主席国”是国家，应该用“个”。"}, {"text": "这个组织每年选一家主席国。", "explanation": "这里应该用〈个〉。“家”多用于商店、公司或家庭，国家不能用“家”计量，应该用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下一届会议选出了一位新的主席国。", "corrected_sentence": "下一届会议选出了一个新的主席国。", "error_description": "错误：“一位新的主席国”；正确：“一个新的主席国”。“位”只用于人，国家应使用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个的主席国的代表很友好。", "corrected_sentence": "这个主席国的代表很友好。", "error_description": "错误：“这个的主席国的代表”；正确：“这个主席国的代表”。指示词和量词“这个”之后不能加“的”，应直接接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97559, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拖拉", "is_correct": true, "explanation": "正确：“拖拉”指做事慢、不利索，与“干脆”在“做事不拖拉”这一义上构成反义。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与做事快慢无关，不是此义的反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与做事的快慢和果断无关，不是此义的反义词。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相反，与做事是否拖拉无关，不是此义的反义词。"}], "correct_answer": "拖拉", "explanations": {"拖拉": "正确：“拖拉”指做事慢、不利索，与“干脆”在“做事不拖拉”这一义上构成反义。", "热情": "“热情”形容待人的态度，与做事快慢无关，不是此义的反义词。", "明亮": "“明亮”形容光线或颜色，与做事的快慢和果断无关，不是此义的反义词。", "安静": "“安静”与“吵闹”相反，与做事是否拖拉无关，不是此义的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97559, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拖拉", "is_correct": true, "explanation": "正确：“拖拉”指做事慢、不利索，与“干脆”在“做事不拖拉”这一义上构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容头脑反应快，与“做事不拖拉”不构成反义。"}, {"text": "凉爽", "is_correct": false, "explanation": "“凉爽”形容天气或感觉，与做事的快慢无关，不是此义的反义词。"}, {"text": "清淡", "is_correct": false, "explanation": "“清淡”形容口味或颜色，与做事的快慢和果断无关，不是此义的反义词。"}], "correct_answer": "拖拉", "explanations": {"拖拉": "正确：“拖拉”指做事慢、不利索，与“干脆”在“做事不拖拉”这一义上构成反义。", "聪明": "“聪明”形容头脑反应快，与“做事不拖拉”不构成反义。", "凉爽": "“凉爽”形容天气或感觉，与做事的快慢无关，不是此义的反义词。", "清淡": "“清淡”形容口味或颜色，与做事的快慢和果断无关，不是此义的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97559, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事不拖拉，一下就决定了。", "primary_collocate": null, "pronunciation": "gān cuì", "ipa": "kan˥ tsʰweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他做事很干脆，从不拖拖拉拉。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她干脆地付了钱，然后就走了。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应得很干脆，没有想太久。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王办事干脆，大家都信任他。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师干脆地做了决定。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做事又快又干脆。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他辞职辞得很干脆。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你干脆一点，别再想了。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他处理问题很干脆。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都喜欢干脆的人。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干干脆脆", "label": "重叠"}], "register": "口语", "sense_fingerprint": "做事果断、不拖拉，很快就做出决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9f1fea1-908e-4ce9-8922-f29a3023b15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干脆", "is_correct": true, "explanation": "正确：“干脆”形容做事不拖拉，与“从不拖拖拉拉”一致。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：“懒散”指做事没有精神、散漫，与“从不拖拖拉拉”矛盾。"}, {"text": "慢吞吞", "is_correct": false, "explanation": "语义：“慢吞吞”本身就是拖拉的样子，与“从不拖拖拉拉”矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或人多，不用来形容做事的方式。"}], "explanations": {"干脆": "正确：“干脆”形容做事不拖拉，与“从不拖拖拉拉”一致。", "懒散": "语义：“懒散”指做事没有精神、散漫，与“从不拖拖拉拉”矛盾。", "慢吞吞": "语义：“慢吞吞”本身就是拖拉的样子，与“从不拖拖拉拉”矛盾。", "热闹": "搭配：“热闹”形容场面或人多，不用来形容做事的方式。"}, "sentence_index": 0, "correct_answer": "干脆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很干脆，适合出门。", "explanation": "这里应该用〈晴朗〉。干脆形容做事快而果断，不用来形容天气。"}, {"text": "这条河的水很干脆，清得能看见鱼。", "explanation": "这里应该用〈清澈〉。干脆形容做事快而果断，不用来形容水质的透明程度。"}, {"text": "这个节日很干脆，大家都很高兴。", "explanation": "这里应该用〈热闹〉。干脆形容做事快而果断，不用来形容节日的气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干脆", "is_correct": true, "explanation": "正确：“干脆”形容辞职的方式果断利落，符合句意。"}, {"text": "雄壮", "is_correct": false, "explanation": "搭配：“雄壮”形容气势或声音，不用来形容辞职的方式。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”指反应慢，与“干脆”的果断相反。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音洪亮，不用来形容辞职。"}], "explanations": {"干脆": "正确：“干脆”形容辞职的方式果断利落，符合句意。", "雄壮": "搭配：“雄壮”形容气势或声音，不用来形容辞职的方式。", "迟钝": "语义：“迟钝”指反应慢，与“干脆”的果断相反。", "嘹亮": "搭配：“嘹亮”形容声音洪亮，不用来形容辞职。"}, "sentence_index": 6, "correct_answer": "干脆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子坐起来很干脆，很舒服。", "explanation": "这里应该用〈舒适〉。干脆形容做事、说话直截了当，不用来形容椅子的坐感。"}, {"text": "运动完，他觉得浑身很干脆。", "explanation": "这里应该用〈痛快〉。干脆形容做事、说话直截了当，不用来描述身体的舒畅感受。"}, {"text": "这把尺子很干脆，量得很准。", "explanation": "这里应该用〈精准〉。干脆形容做事快而果断，不用来形容尺子的精确程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她做决定很很干脆，当场就签了合同。", "corrected_sentence": "她做决定很干脆，当场就签了合同。", "error_description": "错误：“很很干脆”，程度副词“很”重复；正确：“很干脆”。作谓语的形容词前只用一个“很”，且“很”放在“干脆”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他办事办很干脆，几分钟就搞定了。", "corrected_sentence": "他办事办得很干脆，几分钟就搞定了。", "error_description": "错误：“办事办很干脆”，漏掉了补语标记“得”；正确：“办事办得很干脆”。动词后带表示程度或情态的补语时，须用“得”连接动词和补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
