INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97560, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "直截了当，痛快，不犹豫。", "primary_collocate": null, "pronunciation": "gān cuì", "ipa": "kan˥ tsʰweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他说话很干脆，从不绕圈子。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回答得很干脆，没有一点犹豫。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的态度非常干脆。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他干脆地说：“我不去。”", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人性格干脆，我喜欢和他交朋友。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拒绝得很干脆，让我有点吃惊。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答又干脆又清楚。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说话干脆，大家都听得懂。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她干脆地答应了我们的请求。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很干脆，一句话就说完了。", "target_word": "干脆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干干脆脆", "label": "重叠"}], "register": "口语", "sense_fingerprint": "说话或回答直截了当、痛快、不绕弯子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9f1fea1-908e-4ce9-8922-f29a3023b15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干脆", "is_correct": true, "explanation": "正确：“干脆”形容说话直截了当，与“从不绕圈子”一致。"}, {"text": "委婉", "is_correct": false, "explanation": "语义：“委婉”指说话含蓄、不直说，与“从不绕圈子”矛盾。"}, {"text": "冗长", "is_correct": false, "explanation": "语义：“冗长”指话多、啰嗦，与“从不绕圈子”的直接风格相反。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音洪亮，不用来形容说话的方式。"}], "explanations": {"干脆": "正确：“干脆”形容说话直截了当，与“从不绕圈子”一致。", "委婉": "语义：“委婉”指说话含蓄、不直说，与“从不绕圈子”矛盾。", "冗长": "语义：“冗长”指话多、啰嗦，与“从不绕圈子”的直接风格相反。", "嘹亮": "搭配：“嘹亮”形容声音洪亮，不用来形容说话的方式。"}, "sentence_index": 0, "correct_answer": "干脆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脸色很干脆，看起来很健康。", "explanation": "这里应该用〈红润〉。干脆形容说话、做事直截了当，不用来形容脸色。"}, {"text": "这个地方的风景很干脆，很多人来拍照。", "explanation": "这里应该用〈优美〉。干脆形容说话、做事直截了当，不用来形容风景。"}, {"text": "这座山很干脆，爬起来很轻松。", "explanation": "这里应该用〈平缓〉。干脆形容说话、做事直截了当，不用来形容山坡的坡度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干脆", "is_correct": true, "explanation": "正确：“干脆”与“又清楚”搭配，都是形容回答的特点。"}, {"text": "含糊", "is_correct": false, "explanation": "语义：“含糊”指说得不清楚，与后面的“又清楚”矛盾。"}, {"text": "犹豫", "is_correct": false, "explanation": "语义：“犹豫”指拿不定主意，与“干脆”和“清楚”都相反。"}, {"text": "繁华", "is_correct": false, "explanation": "搭配：“繁华”形容地方热闹，不用来形容回答。"}], "explanations": {"干脆": "正确：“干脆”与“又清楚”搭配，都是形容回答的特点。", "含糊": "语义：“含糊”指说得不清楚，与后面的“又清楚”矛盾。", "犹豫": "语义：“犹豫”指拿不定主意，与“干脆”和“清楚”都相反。", "繁华": "搭配：“繁华”形容地方热闹，不用来形容回答。"}, "sentence_index": 6, "correct_answer": "干脆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫的毛很干脆，摸起来很软。", "explanation": "这里应该用〈顺滑〉。干脆形容说话、做事直截了当，不用来形容毛发的质感。"}, {"text": "这盏台灯很干脆，把桌子照得很亮。", "explanation": "这里应该用〈明亮〉。干脆形容说话、做事直截了当，不用来形容灯光的亮度。"}, {"text": "这条路很干脆，一点儿坡都没有。", "explanation": "这里应该用〈平坦〉。干脆形容说话、做事直截了当，不用来形容道路的坡度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他解释得很很干脆，大家一听就明白。", "corrected_sentence": "他解释得很干脆，大家一听就明白。", "error_description": "错误：“很很干脆”，程度副词“很”重复；正确：“很干脆”。“得”字补语中，程度副词“很”只用一个，放在形容词“干脆”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她干脆的同意了这个方案。", "corrected_sentence": "她干脆地同意了这个方案。", "error_description": "错误：“干脆的同意”；正确：“干脆地同意”。“干脆”作状语修饰动词“同意”，要用结构助词“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
