INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97568, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对一个国家或地区的人口数量及情况进行的调查。", "primary_collocate": null, "pronunciation": "rén kǒu diào chá", "ipa": "ʐən˧˥ kʰoʊ˨˩ tjɑʊ˥˩ tʂʰa˧˥", "syllable_count": 4, "sentences": [{"text": "中国每十年进行一次人口调查，统计全国人口数量。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次人口调查的结果很重要。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在做人口调查。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口调查显示，城市人口增加了。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府根据人口调查制定计划。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我们城市要做人口调查。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口调查需要很多工作人员。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加了去年的人口调查。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家很久没有做人口调查了。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口调查的数据会向大家公开。", "target_word": "人口调查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}], "register": "书面", "sense_fingerprint": "政府对国家或地区人口数量和情况的正式调查", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9f1fea1-908e-4ce9-8922-f29a3023b15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人口调查", "is_correct": true, "explanation": "正确：“人口调查”指对全国人口数量和情况的调查，与“中国每十年进行一次”一致。"}, {"text": "体检", "is_correct": false, "explanation": "语义：“体检”是针对个人身体的检查，不用来指全国性的人口统计。"}, {"text": "演习", "is_correct": false, "explanation": "语义：“演习”指军事或安全方面的训练，不是用来“统计全国人口数量”的。"}, {"text": "家访", "is_correct": false, "explanation": "语义：“家访”指上门看望学生家庭，与全国范围的人口统计不符。"}], "explanations": {"人口调查": "正确：“人口调查”指对全国人口数量和情况的调查，与“中国每十年进行一次”一致。", "体检": "语义：“体检”是针对个人身体的检查，不用来指全国性的人口统计。", "演习": "语义：“演习”指军事或安全方面的训练，不是用来“统计全国人口数量”的。", "家访": "语义：“家访”指上门看望学生家庭，与全国范围的人口统计不符。"}, "sentence_index": 0, "correct_answer": "人口调查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府去年做了一只人口调查。", "explanation": "这里应该用〈次〉。人口调查是一次性的统计活动，应与“次”搭配；专门计量动物的量词不能用于它。"}, {"text": "我们学校做了一台人口调查。", "explanation": "这里应该用〈次〉。人口调查是一次性的统计活动，应与“次”搭配；计量机器的量词不能用于它。"}, {"text": "这个省做了一条人口调查。", "explanation": "这里应该用〈次〉。人口调查是一次性的统计活动，应与“次”搭配；计量细长物体的量词不能用于它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人口调查", "is_correct": true, "explanation": "正确：“人口调查”是需要很多工作人员的大型统计工作，与句意一致。"}, {"text": "日记", "is_correct": false, "explanation": "语义：“日记”是个人记录的文字，不需要很多工作人员。"}, {"text": "作文", "is_correct": false, "explanation": "语义：“作文”是学生写的文章，与“需要很多工作人员”不符。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是个人的休闲活动，不能说“散步需要很多工作人员”。"}], "explanations": {"人口调查": "正确：“人口调查”是需要很多工作人员的大型统计工作，与句意一致。", "日记": "语义：“日记”是个人记录的文字，不需要很多工作人员。", "作文": "语义：“作文”是学生写的文章，与“需要很多工作人员”不符。", "散步": "搭配：“散步”是个人的休闲活动，不能说“散步需要很多工作人员”。"}, "sentence_index": 6, "correct_answer": "人口调查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他做了人口调查，检查心脏。", "explanation": "这里应该用〈体检〉。人口调查指统计人口数量与情况，不用于检查个人身体。"}, {"text": "我们去超市做了人口调查，买了很多东西。", "explanation": "这里应该用〈购物〉。人口调查是统计人口数量与情况的调查，不用于超市的购物活动。"}, {"text": "这批食品做了人口调查，全部合格。", "explanation": "这里应该用〈食品检验〉。人口调查是统计人口的调查，不用于检验食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府去年做了一次人口调查过。", "corrected_sentence": "政府去年做了一次人口调查。", "error_description": "错误：“人口调查过”；正确：“人口调查”。“人口调查”在此作名词性宾语，其后不能直接加动态助词“过”，“过”应接在动词后，如“做过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们小区上个月做了一次人口调查着。", "corrected_sentence": "我们小区上个月做了一次人口调查。", "error_description": "错误：“人口调查着”；正确：“人口调查”。“着”表示动作的持续状态，只能接在动词后，“人口调查”作名词性宾语时不能加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
