INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97571, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "来了多少个人，每个人来一次就算一次。", "primary_collocate": null, "pronunciation": "rén cì", "ipa": "ʐən˧˥ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "昨天公园来了五千人次。", "target_word": "人次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天来一次，一个月就是三十人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个人来三次，就算三人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天图书馆有八百人次来看书。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人来两次，就是两人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店每天只有几十人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人进门三次，算三人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一周去健身房四次，算四人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈昨天去了两次超市，算两人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王来了两次，小李来了一次，一共三人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个人来几次就算几人次，按来的次数重复计数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97571, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人次", "is_correct": true, "explanation": "正确：人次（rén cì），指按人来的次数计算的人数单位。"}, {"text": "仁慈", "is_correct": false, "explanation": "rén cí（第二声）与 rén cì（第四声）第二个音节声调不同。仁慈的意思是心地善良，不是人次。"}, {"text": "人事", "is_correct": false, "explanation": "shì 与 cì 声母不同（sh 与 c）。人事指人员的安排与管理，不是人次。"}, {"text": "人气", "is_correct": false, "explanation": "qì 与 cì 声母不同（q 与 c）。人气指受欢迎的程度，不是人次。"}, {"text": "人字", "is_correct": false, "explanation": "zì 与 cì 声母不同（z 与 c）。人字指“人”字的形状，不是人次。"}], "explanations": {"人次": "正确：人次（rén cì），指按人来的次数计算的人数单位。", "仁慈": "rén cí（第二声）与 rén cì（第四声）第二个音节声调不同。仁慈的意思是心地善良，不是人次。", "人事": "shì 与 cì 声母不同（sh 与 c）。人事指人员的安排与管理，不是人次。", "人气": "qì 与 cì 声母不同（q 与 c）。人气指受欢迎的程度，不是人次。", "人字": "zì 与 cì 声母不同（z 与 c）。人字指“人”字的形状，不是人次。"}, "sentence_index": null, "correct_answer": "人次"}, "level_3": {"options": [{"text": "人次", "is_correct": true, "explanation": "正确：“五千人次”指五千人来的总次数，符合句意。"}, {"text": "张", "is_correct": false, "explanation": "语义：“张”用于纸、票、桌子等平面的东西，不能用来数来公园的人，句子不通。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对物件中的一个，不能计算来公园的人数。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”用于书籍、簿册，不能用来数来公园的人，句子不通。"}], "explanations": {"人次": "正确：“五千人次”指五千人来的总次数，符合句意。", "张": "语义：“张”用于纸、票、桌子等平面的东西，不能用来数来公园的人，句子不通。", "只": "搭配：“只”多用于动物或成对物件中的一个，不能计算来公园的人数。", "本": "语义：“本”用于书籍、簿册，不能用来数来公园的人，句子不通。"}, "sentence_index": 0, "correct_answer": "人次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的人次是四十。", "explanation": "这里应该用〈人数〉。班级人员是固定的，按人头计算；人次是按每次来访计算，不能用来表示班级人数。"}, {"text": "张三一个月去了三次图书馆，只算一人次。", "explanation": "这里把〈人次〉当成了〈人数〉来用。人次按来访次数计算，张三去了三次，应算三人次，不能只算一人次。"}, {"text": "图书馆今天借出的书是三人次。", "explanation": "这里应该用〈本〉。人次只计算人来过的次数，书的数量要用“本”来计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人次", "is_correct": true, "explanation": "正确：“一个人进门三次，算三人次”，每次进门都计算一次，符合句意。"}, {"text": "条", "is_correct": false, "explanation": "语义：“条”用于细长的东西，不能用来计算进门的次数。"}, {"text": "篇", "is_correct": false, "explanation": "语义：“篇”用于文章，不能用来计算一个人进门的次数。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”多用于有柄的物品，不能与“算”搭配来计算进门的次数。"}], "explanations": {"人次": "正确：“一个人进门三次，算三人次”，每次进门都计算一次，符合句意。", "条": "语义：“条”用于细长的东西，不能用来计算进门的次数。", "篇": "语义：“篇”用于文章，不能用来计算一个人进门的次数。", "把": "搭配：“把”多用于有柄的物品，不能与“算”搭配来计算进门的次数。"}, "sentence_index": 6, "correct_answer": "人次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的人次是两百万。", "explanation": "这里应该用〈人口〉。人次计算的是来访次数，城市的常住人数要用〈人口〉。"}, {"text": "我的鞋子穿了三次，算三人次。", "explanation": "这里把〈人次〉当成了〈次数〉来用。人次只统计人来过某处的次数，鞋子不是人，不能按人次计算。"}, {"text": "学校里的老师一共有五百人次。", "explanation": "这里应该用〈人数〉。老师是固定的人员，每人只算一个，不按来过的次数计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末商场来了三万个人次。", "corrected_sentence": "周末商场来了三万人次。", "error_description": "错误形式：“三万个人次”。正确形式：“三万人次”。“人次”本身就是量词，前面的数词可以直接接“人次”，中间不能再加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月健身房接待了八千次人次。", "corrected_sentence": "这个月健身房接待了八千人次。", "error_description": "错误形式：“八千次人次”。正确形式：“八千人次”。“人次”本身已是量词，数词后直接接“人次”，中间不能再加“次”，否则是重复计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
