INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97572, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "计算人数的单位，按人的来往次数计算。", "primary_collocate": null, "pronunciation": "rén cì", "ipa": "ʐən˧˥ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "春节期间，景区接待了十万人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末，博物馆接待了两万人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天游泳馆每天有上千人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这个展览的参观量是三十万人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天医院的门诊有三百人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁每天的客流量是几百万人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站昨天的访问量达到了五万人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国庆节那天，机场一共接待了八万人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的游客数按人次来算。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年图书馆一共接待了二十万人次。", "target_word": "人次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "统计游客、客流、访问量时使用的人数单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97572, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人次", "is_correct": true, "explanation": "正确：人次（rén cì），指按人来的次数计算的人数单位。"}, {"text": "仁慈", "is_correct": false, "explanation": "rén cí（第二声）与 rén cì（第四声）第二个音节声调不同。仁慈的意思是心地善良，不是人次。"}, {"text": "人事", "is_correct": false, "explanation": "shì 与 cì 声母不同（sh 与 c）。人事指人员的安排与管理，不是人次。"}, {"text": "人气", "is_correct": false, "explanation": "qì 与 cì 声母不同（q 与 c）。人气指受欢迎的程度，不是人次。"}, {"text": "人字", "is_correct": false, "explanation": "zì 与 cì 声母不同（z 与 c）。人字指“人”字的形状，不是人次。"}], "explanations": {"人次": "正确：人次（rén cì），指按人来的次数计算的人数单位。", "仁慈": "rén cí（第二声）与 rén cì（第四声）第二个音节声调不同。仁慈的意思是心地善良，不是人次。", "人事": "shì 与 cì 声母不同（sh 与 c）。人事指人员的安排与管理，不是人次。", "人气": "qì 与 cì 声母不同（q 与 c）。人气指受欢迎的程度，不是人次。", "人字": "zì 与 cì 声母不同（z 与 c）。人字指“人”字的形状，不是人次。"}, "sentence_index": null, "correct_answer": "人次"}, "level_3": {"options": [{"text": "人次", "is_correct": true, "explanation": "正确：“景区接待了十万人次”，指十万人来的总次数，符合句意。"}, {"text": "趟", "is_correct": false, "explanation": "搭配：“趟”指一次往返的行程，不用来计算景区接待的游客。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对物件中的一个，不能用来计算接待的游客。"}, {"text": "件", "is_correct": false, "explanation": "语义：“件”多用于事情或物品，不能用来计算接待的游客，句子不通。"}], "explanations": {"人次": "正确：“景区接待了十万人次”，指十万人来的总次数，符合句意。", "趟": "搭配：“趟”指一次往返的行程，不用来计算景区接待的游客。", "只": "搭配：“只”多用于动物或成对物件中的一个，不能用来计算接待的游客。", "件": "语义：“件”多用于事情或物品，不能用来计算接待的游客，句子不通。"}, "sentence_index": 0, "correct_answer": "人次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个展览的画一共有三十万人次。", "explanation": "这里应该用〈幅〉。人次只计算人来过的次数，画要用“幅”来计数。"}, {"text": "小李一个月去了三次健身房，只算一人次。", "explanation": "这里把〈人次〉当成了〈人数〉来用。人次按来访次数计算，小李去了三次，应算三人次，不能只按一个人计算。"}, {"text": "这次比赛的裁判一共有三十人次。", "explanation": "这里应该用〈人数〉。裁判是固定的人员，按人头计算，不按来过的次数计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人次", "is_correct": true, "explanation": "正确：“访问量达到了五万人次”，指五万人次的访问，符合句意。"}, {"text": "篇", "is_correct": false, "explanation": "语义：“篇”用于文章，不能用来计算访问量，句子不通。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”多用于书籍、簿册，不能与“访问量”搭配。"}, {"text": "张", "is_correct": false, "explanation": "语义：“张”用于纸、票等平面的东西，不能用来计算访问量，句子不通。"}], "explanations": {"人次": "正确：“访问量达到了五万人次”，指五万人次的访问，符合句意。", "篇": "语义：“篇”用于文章，不能用来计算访问量，句子不通。", "本": "搭配：“本”多用于书籍、簿册，不能与“访问量”搭配。", "张": "语义：“张”用于纸、票等平面的东西，不能用来计算访问量，句子不通。"}, "sentence_index": 6, "correct_answer": "人次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼一共住了两百万人次。", "explanation": "这里应该用〈人〉。楼里住的人是固定的，按人头计算；人次是按来访次数计算的，不能用来表示住户的人数。"}, {"text": "这家饭店的菜一共卖出了五百人次。", "explanation": "这里应该用〈份〉。人次只计算人来过的次数，菜要用“份”来计算。"}, {"text": "小王今年一共借了三十本书，算三十人次。", "explanation": "人次只计算人来过的次数，不能用来计算书。这里书应该按“三十本”计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "节假日，动物园接待了六万个人次。", "corrected_sentence": "节假日，动物园接待了六万人次。", "error_description": "错误形式：“六万个人次”。正确形式：“六万人次”。“人次”本身已是量词，数词后直接接“人次”，中间不能再加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年景区一共接待了三十万次人次。", "corrected_sentence": "今年景区一共接待了三十万人次。", "error_description": "错误形式：“三十万次人次”。正确形式：“三十万人次”。“人次”本身已是量词，数词后直接接“人次”，中间不能再加“次”，否则是重复计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
