INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97575, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97575, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "脑子不太灵，学东西很慢。", "primary_collocate": null, "pronunciation": "dī néng", "ipa": "ti˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他不是低能，只是学东西比别人慢一点。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人说这个孩子低能，妈妈听了很难过。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说他不低能，只是需要更多时间。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要随便说别人低能，这样很不礼貌。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候学东西慢，同学都笑他低能。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得自己有点低能，什么都学不会。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他反应慢，大家就说他低能。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们常说他低能，其实他很努力。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥学得慢，可他一点也不低能。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么简单的事都不会做，你是不是低能啊？", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低能儿", "label": "复合词"}], "register": "口语", "sense_fingerprint": "口语中指人脑子不灵、学东西慢，常带贬义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0aef20-8c93-4b94-980b-ea0ce9cddfeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低能", "is_correct": true, "explanation": "正确：“低能”指脑子不灵、学东西慢，与“只是学东西比别人慢”的说法一致。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指脑子灵活，与“只是学东西慢”的意思相反，句子自相矛盾。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容待人的态度，与学习快慢无关，放在这里说不通。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容身材或体型，不能用来说一个人的学习能力。"}], "explanations": {"低能": "正确：“低能”指脑子不灵、学东西慢，与“只是学东西比别人慢”的说法一致。", "聪明": "语义：“聪明”指脑子灵活，与“只是学东西慢”的意思相反，句子自相矛盾。", "热情": "语义：“热情”形容待人的态度，与学习快慢无关，放在这里说不通。", "高大": "搭配：“高大”形容身材或体型，不能用来说一个人的学习能力。"}, "sentence_index": 0, "correct_answer": "低能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏台灯的亮度很低能，看书伤眼睛。", "explanation": "这里应该用〈弱〉。形容灯光亮度不够要说“弱”，“低能”只用于人的智力，不用来形容亮度。"}, {"text": "这把椅子很低能，坐一下就晃个不停。", "explanation": "这里应该用〈不稳〉。椅子不牢固要说“不稳”，“低能”只用于人的智力，不能用来形容物品。"}, {"text": "这台冰箱的制冷很低能，放进去的菜第二天就坏了。", "explanation": "这里应该用〈差〉。制冷效果不好要说“差”，“低能”只用于人的智力，不能用来形容机器的性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低能", "is_correct": true, "explanation": "正确：“大家就说他低能”是对反应慢的人的评价，只有“低能”符合语境。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”形容不怕困难或危险，与“反应慢”的评价无关，句子说不通。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容心情好，与“反应慢”不能构成“大家就说他”的理由。"}, {"text": "富有", "is_correct": false, "explanation": "搭配：“富有”多指钱财或品质丰富，不能用来评价一个人的反应能力。"}], "explanations": {"低能": "正确：“大家就说他低能”是对反应慢的人的评价，只有“低能”符合语境。", "勇敢": "语义：“勇敢”形容不怕困难或危险，与“反应慢”的评价无关，句子说不通。", "高兴": "语义：“高兴”形容心情好，与“反应慢”不能构成“大家就说他”的理由。", "富有": "搭配：“富有”多指钱财或品质丰富，不能用来评价一个人的反应能力。"}, "sentence_index": 6, "correct_answer": "低能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布料的厚度很低能，一拉就破。", "explanation": "这里应该用〈薄〉。布料厚度不够要说“薄”，“低能”只用于人的智力，不能用来形容布料。"}, {"text": "这株植物长得很低能，几乎不开花。", "explanation": "这里应该用〈瘦弱〉。形容植物长势弱要说“瘦弱”，“低能”只用于人的智力，不用于植物。"}, {"text": "这根绳子的长度很低能，根本绑不住箱子。", "explanation": "这里应该用〈短〉。绳子长度不够要说“短”，“低能”只用于人的智力，不能用来形容物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他爸爸总说他很低能儿，其实他只是慢一点。", "corrected_sentence": "他爸爸总说他很低能，其实他只是慢一点。", "error_description": "“低能儿”是名词，不能受“很”修饰；应用形容词“低能”，说“很低能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他并不低能儿，只是没仔细看题。", "corrected_sentence": "他并不低能，只是没仔细看题。", "error_description": "“低能儿”是名词，不能直接受“并不”修饰作谓语；应用形容词“低能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
