INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97576, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "智力低于正常水平。", "primary_collocate": null, "pronunciation": "dī néng", "ipa": "ti˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "医生说这个孩子低能，需要特别照顾。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查后发现，孩子有点低能。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校专门教低能的孩子。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生下来就低能，一直需要家人照顾。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，这种病会让孩子变得低能。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的智力测试结果很低，医生认为他低能。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低能的孩子也需要爱和教育。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子生病后变得低能，不能上普通学校。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有一位低能的病人，每天都有人照顾他。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些低能的人也能做简单的工作。", "target_word": "低能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低能儿", "label": "复合词"}], "register": "书面", "sense_fingerprint": "医学或教育语境中指智力发育低于正常水平", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0aef20-8c93-4b94-980b-ea0ce9cddfeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低能", "is_correct": true, "explanation": "正确：“低能”指智力发育低于正常水平，与“需要特别照顾”的医学语境相符。"}, {"text": "健壮", "is_correct": false, "explanation": "体貌：“健壮”形容体格强壮，描述的是身体状况，与智力问题不符。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音高亢清楚，不能用来描述孩子的智力状况。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”形容味道，不能修饰“孩子”。"}], "explanations": {"低能": "正确：“低能”指智力发育低于正常水平，与“需要特别照顾”的医学语境相符。", "健壮": "体貌：“健壮”形容体格强壮，描述的是身体状况，与智力问题不符。", "嘹亮": "语义：“嘹亮”形容声音高亢清楚，不能用来描述孩子的智力状况。", "辛辣": "搭配：“辛辣”形容味道，不能修饰“孩子”。"}, "sentence_index": 0, "correct_answer": "低能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人晚年患上了低能，常常忘记回家的路。", "explanation": "这里应该用〈痴呆〉。老年人认知衰退要说“痴呆”；“低能”指智力发育低于正常水平，不用来形容老年人的认知衰退。"}, {"text": "他因车祸导致肢体低能，只能坐轮椅。", "explanation": "这里应该用〈残疾〉。身体部位受损要说“残疾”，“低能”指智力，不能描述肢体。"}, {"text": "这种药的疗效很低能，吃了一周也没有改善。", "explanation": "这里应该用〈不明显〉。药效不显著要说“不明显”，“低能”只用于人的智力，不能用来形容药物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低能", "is_correct": true, "explanation": "正确：“低能的孩子”指智力发育低，与“也需要爱和教育”的语境相符。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”形容物体质地硬，不能用来形容孩子，句子说不通。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容能透光的物体，与孩子需要爱和教育无关。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度很高，不能修饰“孩子”。"}], "explanations": {"低能": "正确：“低能的孩子”指智力发育低，与“也需要爱和教育”的语境相符。", "坚硬": "语义：“坚硬”形容物体质地硬，不能用来形容孩子，句子说不通。", "透明": "语义：“透明”形容能透光的物体，与孩子需要爱和教育无关。", "滚烫": "搭配：“滚烫”形容温度很高，不能修饰“孩子”。"}, "sentence_index": 6, "correct_answer": "低能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块钢材的强度很低能，轻轻一压就变形。", "explanation": "这里应该用〈低〉。钢材强度不够要说“低”，“低能”只用于人的智力，不能用来形容材料。"}, {"text": "他的眼神很低能，好像在想心事。", "explanation": "这里应该用〈呆滞〉。形容眼神不灵活要说“呆滞”，“低能”指智力，不能用来形容眼神。"}, {"text": "他因病身体低能，需要静养。", "explanation": "这里应该用〈衰弱〉。体力下降要说“衰弱”，“低能”指智力，不能用来形容身体状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生发现这个男孩有点低能儿，需要家人多帮助。", "corrected_sentence": "医生发现这个男孩有点低能，需要家人多帮助。", "error_description": "程度副词“有点”只能修饰形容词“低能”，不能修饰名词“低能儿”，应去掉“儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个低能，需要特别照顾。", "corrected_sentence": "他是个低能儿，需要特别照顾。", "error_description": "“个”后面要接名词，形容词“低能”不能直接跟在“个”后；指人时应说“低能儿”或“低能的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
