INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她以前也使性过，现在好多了。", "corrected_sentence": "她以前也使过性，现在好多了。", "error_description": "错误形式：“使性过”；正确形式：“使过性”。“过”要放在离合词的动词“使”与宾语“性”之间，“使性过”不符合规范。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
