INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97580, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "耍脾气；发火。", "primary_collocate": null, "pronunciation": "shǐ xìng", "ipa": "ʂɻ̩˨˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "经理对客人使性，被老板批评了。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有话好好说，不要对同事使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作太累，回家就对孩子使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听这话就使性，把门关上了。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，他在车里直使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别因为小事就使性，对身体不好。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板今天心情不好，动不动就使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当着大家的面使性，真让人为难。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一使性，就摔了杯子。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢跟爱使性的人一起工作。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "使性子", "label": "复合"}], "register": "口语", "sense_fingerprint": "动词：对人耍脾气、发火，常带“对／跟”引出对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97580, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "使性", "is_correct": true, "explanation": "使性：对人发脾气、发火，为正确答案。"}, {"text": "实行", "is_correct": false, "explanation": "shí xíng 与 shǐ xìng 声调不同，意思是实施、推行。"}, {"text": "时兴", "is_correct": false, "explanation": "shí xīng 与 shǐ xìng 声调不同，意思是一时流行。"}, {"text": "死性", "is_correct": false, "explanation": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。"}, {"text": "食性", "is_correct": false, "explanation": "shí xìng 与 shǐ xìng 声调不同，意思是动物的食物习性。"}], "explanations": {"使性": "使性：对人发脾气、发火，为正确答案。", "实行": "shí xíng 与 shǐ xìng 声调不同，意思是实施、推行。", "时兴": "shí xīng 与 shǐ xìng 声调不同，意思是一时流行。", "死性": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。", "食性": "shí xìng 与 shǐ xìng 声调不同，意思是动物的食物习性。"}, "sentence_index": null, "correct_answer": "使性"}, "level_3": {"options": [{"text": "使性", "is_correct": true, "explanation": "正确：“经理对客人使性”指经理对客人发脾气，符合语境。"}, {"text": "赞成", "is_correct": false, "explanation": "配价：“赞成”的对象是事情或意见，不能引出人作对象，“对客人赞成”说不通。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”针对事情或请求，“对客人同意”搭配不当，语境也不合。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”需带事物作宾语，“对客人拥有”说不通。"}], "explanations": {"使性": "正确：“经理对客人使性”指经理对客人发脾气，符合语境。", "赞成": "配价：“赞成”的对象是事情或意见，不能引出人作对象，“对客人赞成”说不通。", "同意": "配价：“同意”针对事情或请求，“对客人同意”搭配不当，语境也不合。", "拥有": "配价：“拥有”需带事物作宾语，“对客人拥有”说不通。"}, "sentence_index": 0, "correct_answer": "使性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的使性是照顾病人。", "explanation": "这里应该用〈使命〉。使性指发脾气，不表示任务或职责。"}, {"text": "他听到这个好消息，使性得跳了起来。", "explanation": "这里应该用〈兴奋〉。使性指发脾气，不表示因高兴而兴奋地跳起来。"}, {"text": "他见到老朋友，热情地使性。", "explanation": "这里应该用〈打招呼〉。使性指发脾气，与“热情地”的待人态度相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97580, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "使性", "is_correct": true, "explanation": "使性：对人发脾气、发火，为正确答案。"}, {"text": "试行", "is_correct": false, "explanation": "shì xíng 与 shǐ xìng 声调不同，意思是先试验性地施行。"}, {"text": "施行", "is_correct": false, "explanation": "shī xíng 与 shǐ xìng 声调不同，意思是实施、施行。"}, {"text": "室性", "is_correct": false, "explanation": "shì xìng 与 shǐ xìng 声调不同，意思是与心室有关（医学用语）。"}, {"text": "死性", "is_correct": false, "explanation": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。"}], "explanations": {"使性": "使性：对人发脾气、发火，为正确答案。", "试行": "shì xíng 与 shǐ xìng 声调不同，意思是先试验性地施行。", "施行": "shī xíng 与 shǐ xìng 声调不同，意思是实施、施行。", "室性": "shì xìng 与 shǐ xìng 声调不同，意思是与心室有关（医学用语）。", "死性": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。"}, "sentence_index": null, "correct_answer": "使性"}, "level_3": {"options": [{"text": "使性", "is_correct": true, "explanation": "正确：“老板动不动就使性”指老板时常发脾气，符合语境。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：老板心情不好时“动不动就微笑”自相矛盾，不符合语境。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：“欢呼”表示高兴，与“心情不好”相反，不符合语境。"}, {"text": "嘉奖", "is_correct": false, "explanation": "语域：“嘉奖”是书面语，口语中不用；且与“心情不好、动不动就”的语境不合。"}], "explanations": {"使性": "正确：“老板动不动就使性”指老板时常发脾气，符合语境。", "微笑": "语义：老板心情不好时“动不动就微笑”自相矛盾，不符合语境。", "欢呼": "语义：“欢呼”表示高兴，与“心情不好”相反，不符合语境。", "嘉奖": "语域：“嘉奖”是书面语，口语中不用；且与“心情不好、动不动就”的语境不合。"}, "sentence_index": 6, "correct_answer": "使性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是天神派来的使性。", "explanation": "这里应该用〈使者〉。使性是发脾气，不指人或身份。"}, {"text": "这次谈判，他作为使性出席。", "explanation": "这里应该用〈使节〉。使性不指外交人员，也不能表示“作为代表出席”。"}, {"text": "他常去使性处理手续。", "explanation": "这里应该用〈使馆〉。使性不表示地点，“去使馆处理手续”才通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在对我使性着，你先别过去。", "corrected_sentence": "他正在对我使性，你先别过去。", "error_description": "错误形式：“使性着”；正确形式：“使性”。“使性”是动宾式离合词，“着”不能放在整个词后面；句中已有“正在”表示进行，去掉“着”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他前天对我使性过，现在道歉了。", "corrected_sentence": "他前天对我使过性，现在道歉了。", "error_description": "错误形式：“使性过”；正确形式：“使过性”。“过”须放在离合词的动词“使”与宾语“性”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
