INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97583, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "开车来了，可以把车停在那里的地方。", "primary_collocate": null, "pronunciation": "tíng chē chǎng", "ipa": "tʰiŋ˧˥ ʈʂʰɤ˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "我把车开进了停车场。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个停车场很大，能停一百辆车。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场旁边有一个免费的停车场。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末停车场里的车特别多。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在停车场等你，你快一点儿。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在停车场找了半天，还是没找到自己的车。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下停车场的入口在大楼后面。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场里没有空位了，我们去别的地方吧。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的停车场收费很贵。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把车停好，停车场的门晚上十点关。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地下停车场", "label": "复合"}, {"form": "停車場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开车到达后停放自己的车的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "停车场", "is_correct": true, "explanation": "正确：汽车可以开进去停放，与“开进了”搭配。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，汽车开不进去。"}, {"text": "行李箱", "is_correct": false, "explanation": "配价：“开进了”要求处所宾语，行李箱不是处所。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不能把车开进去。"}], "explanations": {"停车场": "正确：汽车可以开进去停放，与“开进了”搭配。", "厨房": "语义：厨房是做饭的地方，汽车开不进去。", "行李箱": "配价：“开进了”要求处所宾语，行李箱不是处所。", "教室": "语义：教室是上课的地方，不能把车开进去。"}, "sentence_index": 0, "correct_answer": "停车场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的停车场里摆着床和衣柜，我每天晚上在这里睡觉。", "explanation": "这里应该用〈卧室〉。停车场是停放车辆的场地，不能住人，睡觉要用卧室。"}, {"text": "停车场的白线画得很清楚，每个停车场只能停一辆车，我的车停在第三个停车场里。", "explanation": "这里应该用〈车位〉。车位是给一辆车停放的位置；停车场是整片场地，能停很多车，不能说一个停车场只停一辆车。"}, {"text": "这个停车场里有很多书，我每周都来借书看。", "explanation": "这里应该用〈图书馆〉。停车场是停车的地方，借书看书要去图书馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停车场", "is_correct": true, "explanation": "正确：「地下停车场」是地下的停车场地，入口可以在大楼后面。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不在地下，「地下天空」说不通。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：「地下」与「草原」搭配不当，草原在地面上。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼没有「入口」，句意说不通。"}], "explanations": {"停车场": "正确：「地下停车场」是地下的停车场地，入口可以在大楼后面。", "天空": "语义：天空不在地下，「地下天空」说不通。", "草原": "搭配：「地下」与「草原」搭配不当，草原在地面上。", "鱼": "语义：鱼没有「入口」，句意说不通。"}, "sentence_index": 6, "correct_answer": "停车场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那家停车场的师傅修车很快，车主都很满意。", "explanation": "这里应该用〈修车厂〉。修车要去修车厂，停车场只提供停放车辆的地方。"}, {"text": "这家停车场的油很便宜，车主都来加。", "explanation": "这里应该用〈加油站〉。停车场不卖油，加油要去加油站。"}, {"text": "这个停车场有很多好玩的项目，孩子们都很喜欢。", "explanation": "这里应该用〈游乐场〉。停车场只供停车，没有游玩项目；孩子们玩耍应该去游乐场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那辆停车场很大，能停好几百辆车。", "corrected_sentence": "那个停车场很大，能停好几百辆车。", "error_description": "量词错误：停车场的量词是「个」，「辆」只用于车辆。把「那个停车场」说成「那辆停车场」是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大楼后面有一辆地下停车场。", "corrected_sentence": "大楼后面有一个地下停车场。", "error_description": "量词错误：停车场的量词是「个」，「辆」只用于车辆，不能说「一辆地下停车场」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
