INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97584, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门供停放汽车的场地。", "primary_collocate": null, "pronunciation": "tíng chē chǎng", "ipa": "tʰiŋ˧˥ ʈʂʰɤ˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "学校新建了一个停车场。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个停车场按小时收费。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场的管理员正在检查每辆车。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里的停车场只给住户用。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场入口有一个很大的牌子。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的停车场里有二十个充电位。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座停车场一共有三层。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家停车场工作，每天站着收钱。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心的停车场不多，所以停车很难。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场里装着很多摄像头。", "target_word": "停车场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "地下停车场", "label": "复合"}, {"form": "停車場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "专门修建、用来停放汽车的场地设施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "停车场", "is_correct": true, "explanation": "正确：学校可以新建供车辆停放的场地设施。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「新建」不能用于空气，空气不能被建造。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不是学校能新建的东西。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是学校能新建的东西。"}], "explanations": {"停车场": "正确：学校可以新建供车辆停放的场地设施。", "空气": "搭配：「新建」不能用于空气，空气不能被建造。", "星星": "语义：星星不是学校能新建的东西。", "海洋": "语义：海洋不是学校能新建的东西。"}, "sentence_index": 0, "correct_answer": "停车场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家停车场的水果很新鲜，我每周都来买。", "explanation": "这里应该用〈超市〉。停车场是停放车辆的场地，不卖水果，买东西要去超市。"}, {"text": "每个停车场都划着白线，只能停一辆车，我的车停在最右边的停车场里。", "explanation": "这里应该用〈车位〉。白线划出的是单个车位，一辆车一个；停车场是整片场地，不能说每个停车场只停一辆车。"}, {"text": "这家停车场的新书很多，我每周都来买。", "explanation": "这里应该用〈书店〉。停车场不卖书，买新书要去书店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停车场", "is_correct": true, "explanation": "正确：「这座停车场」指一座专门供停车的建筑，可以分层。"}, {"text": "山", "is_correct": false, "explanation": "语义：山一般不说有几层，与「一共有三层」的人工建筑语义不符。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌不分楼层，「一共有三层」说不通。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市不以「层」计数，「一共有三层」说不通。"}], "explanations": {"停车场": "正确：「这座停车场」指一座专门供停车的建筑，可以分层。", "山": "语义：山一般不说有几层，与「一共有三层」的人工建筑语义不符。", "诗歌": "语义：诗歌不分楼层，「一共有三层」说不通。", "城市": "语义：城市不以「层」计数，「一共有三层」说不通。"}, "sentence_index": 6, "correct_answer": "停车场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家停车场的师傅修车很快，车主都很满意。", "explanation": "这里应该用〈修车厂〉。修车要去修车厂，停车场只提供停放车辆的地方。"}, {"text": "这家停车场的汽油很便宜，司机都来这里加油。", "explanation": "这里应该用〈加油站〉。停车场不卖汽油，加油要去加油站。"}, {"text": "这个停车场的滑梯很高，孩子们玩得很开心。", "explanation": "这里应该用〈游乐场〉。停车场只供停车，没有滑梯等游玩设施；孩子们玩耍要去游乐场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那辆停车场很大，能停两百辆车。", "corrected_sentence": "那座停车场很大，能停两百辆车。", "error_description": "量词错误：这种设施用量词「座」，「辆」只用于车辆。把「那座停车场」说成「那辆停车场」是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条停车场很大，可以停五十辆车。", "corrected_sentence": "这座停车场很大，可以停五十辆车。", "error_description": "量词错误：停车场是一种设施，用量词「座」。「条」用于长条形的东西，所以不能说「这条停车场」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
