INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97587, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97587, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做运动，让身体变得结实。", "primary_collocate": null, "pronunciation": "jiàn shēn", "ipa": "tɕjɛn˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "他想健身，让自己变得更结实。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟一直在健身，现在很结实。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了变得结实，他开始健身了。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天健身，肩膀越来越宽。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友每个周末都健身。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，我得经常健身，别总坐着。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱健身，所以身体有点儿弱。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常常告诉我们要健身。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边工作，一边健身。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥天天跑步、游泳健身，身体很棒。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "健身房", "label": "复合"}, {"form": "健身操", "label": "复合"}, {"form": "健了身", "label": "体标"}], "register": "中性", "sense_fingerprint": "做运动让身体变结实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "健身", "is_correct": true, "explanation": "正确：「想健身」说明想通过锻炼让身体变结实，与句意相符。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆不能让身体变结实，与「让自己变得更结实」矛盾。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜会伤身，与「变得更结实」的目标相反。"}, {"text": "睡懒觉", "is_correct": false, "explanation": "搭配：「睡懒觉」与「变得更结实」的目的不搭配，句意说不通。"}], "explanations": {"健身": "正确：「想健身」说明想通过锻炼让身体变结实，与句意相符。", "发呆": "语义：发呆不能让身体变结实，与「让自己变得更结实」矛盾。", "熬夜": "语义：熬夜会伤身，与「变得更结实」的目标相反。", "睡懒觉": "搭配：「睡懒觉」与「变得更结实」的目的不搭配，句意说不通。"}, "sentence_index": 0, "correct_answer": "健身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车每天健身，跑得越来越快。", "explanation": "这里应该用〈保养〉。健身指人锻炼身体，汽车的维护要说保养。"}, {"text": "这位医生每天健身病人，病人都好得很快。", "explanation": "这里应该用〈治疗〉。健身只指人自己锻炼身体，给病人看病要说治疗。"}, {"text": "这家饭店每天健身，生意越来越好。", "explanation": "这里应该用〈营业〉。健身只指人锻炼身体，饭店经营要说营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "健身", "is_correct": true, "explanation": "正确：「不爱健身」与「身体有点儿弱」构成因果，符合句意。"}, {"text": "看书", "is_correct": false, "explanation": "语义：不爱看书与身体弱没有因果关系，句意说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：不爱唱歌不会导致身体弱，与「所以身体有点儿弱」矛盾。"}, {"text": "上课", "is_correct": false, "explanation": "搭配：「上课」与「身体有点儿弱」的因果关系搭配不当。"}], "explanations": {"健身": "正确：「不爱健身」与「身体有点儿弱」构成因果，符合句意。", "看书": "语义：不爱看书与身体弱没有因果关系，句意说不通。", "唱歌": "语义：不爱唱歌不会导致身体弱，与「所以身体有点儿弱」矛盾。", "上课": "搭配：「上课」与「身体有点儿弱」的因果关系搭配不当。"}, "sentence_index": 6, "correct_answer": "健身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器每天健身，产量越来越高。", "explanation": "这里应该用〈运转〉。健身只指人锻炼身体，机器的运行要说运转。"}, {"text": "这位老师每天健身学生，学生的成绩都提高了。", "explanation": "这里应该用〈教育〉。健身只指人锻炼身体，教导学生要说教育。"}, {"text": "这家书店每天健身，顾客越来越多。", "explanation": "这里应该用〈营业〉。健身只指人锻炼身体，书店经营要说营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每周都健身身，身体越来越结实。", "corrected_sentence": "他每周都健身，身体越来越结实。", "error_description": "离合词错误：「健身」是动宾式离合词，「身」已包含在词中，不能再加「身」，应说「健身」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在家健身身，身体越来越好。", "corrected_sentence": "他在家健身，身体越来越好。", "error_description": "离合词错误：「健身」是动宾式离合词，「身」已包含在词中，不能再加「身」，应说「健身」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
