INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过运动使身体强健。", "primary_collocate": null, "pronunciation": "jiàn shēn", "ipa": "tɕjɛn˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "我每天早上去公园健身。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢跑步健身。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休以后常常打太极拳健身。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想健身，所以每周游三次泳。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了健身，天天走路上班。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你平时怎么健身？", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他健身已经三年了。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多健身对身体好。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起去河边健身吧。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上在家健身半个小时。", "target_word": "健身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "健身房", "label": "复合"}, {"form": "健身操", "label": "复合"}, {"form": "健过身", "label": "体标"}], "register": "中性", "sense_fingerprint": "靠运动锻炼来增强体质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "健身", "is_correct": true, "explanation": "正确：「去公园健身」指到公园锻炼身体，与句意相符。"}, {"text": "打针", "is_correct": false, "explanation": "搭配：「打针」要去医院，不能说去公园打针。"}, {"text": "挂号", "is_correct": false, "explanation": "搭配：「挂号」要去医院或挂号处，不能去公园挂号。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是考核学习成绩，不能说去公园考试。"}], "explanations": {"健身": "正确：「去公园健身」指到公园锻炼身体，与句意相符。", "打针": "搭配：「打针」要去医院，不能说去公园打针。", "挂号": "搭配：「挂号」要去医院或挂号处，不能去公园挂号。", "考试": "语义：考试是考核学习成绩，不能说去公园考试。"}, "sentence_index": 0, "correct_answer": "健身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑每天健身，运行得越来越快。", "explanation": "这里应该用〈维护〉。健身只指人锻炼身体，电脑的日常维护要说维护。"}, {"text": "这位护士每天健身病人，病人很快就出院了。", "explanation": "这里应该用〈护理〉。健身只指人自己锻炼身体，护理病人要说护理。"}, {"text": "这座花园每天健身，花开得越来越好。", "explanation": "这里应该用〈打理〉。健身只指人锻炼身体，照料花园要说打理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "健身", "is_correct": true, "explanation": "正确：「健身已经三年了」说明持续锻炼身体的时间。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧一般是短期病症，「发烧已经三年了」很少这样说，句意不合常理。"}, {"text": "哭", "is_correct": false, "explanation": "语义：「哭」一般是短时的情绪反应，「哭已经三年了」读起来不合常理。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：「洗澡」是日常短时动作，与「已经三年了」这样的长时段搭配不当。"}], "explanations": {"健身": "正确：「健身已经三年了」说明持续锻炼身体的时间。", "发烧": "语义：发烧一般是短期病症，「发烧已经三年了」很少这样说，句意不合常理。", "哭": "语义：「哭」一般是短时的情绪反应，「哭已经三年了」读起来不合常理。", "洗澡": "搭配：「洗澡」是日常短时动作，与「已经三年了」这样的长时段搭配不当。"}, "sentence_index": 6, "correct_answer": "健身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河每天健身，水越来越干净。", "explanation": "这里应该用〈治理〉。健身只指人锻炼身体，整治河流要说治理。"}, {"text": "这个老板每天健身员工，公司的业绩很好。", "explanation": "这里应该用〈管理〉。健身只指人锻炼身体，带领员工要说管理。"}, {"text": "这所医院每天健身，病人越来越多。", "explanation": "这里应该用〈接诊〉。健身只指人锻炼身体，医院看病要说接诊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天早上在公园健身身，身体很好。", "corrected_sentence": "他每天早上在公园健身，身体很好。", "error_description": "离合词错误：「健身」是动宾式离合词，「身」已包含在词中，不能再加「身」，应说「健身」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他健身得很累。", "corrected_sentence": "他健身健得很累。", "error_description": "补语错误：「健身」后接「得」补语时要重复动词，应说「健身健得很累」，不能省略重复的动词说「健身得很累」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
