INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97589, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情还没来，就已经看出来了的本事。", "primary_collocate": null, "pronunciation": "xiān jiàn", "ipa": "ɕjɛn˥˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他很有先见，早就买下了这块地。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的先见让公司躲过了那次危机。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷有先见，让孩子们都去学英语。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意需要先见，不能只看眼前的钱。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的先见，我现在才明白。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有先见，所以总是来不及准备。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都佩服她的先见。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有先见的人，能提前做好准备。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经理很有先见，早就看出市场会变。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时没人相信他的先见，后来都服了。", "target_word": "先见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "先见之明", "label": "复合"}], "register": "书面", "sense_fingerprint": "先见：事情没发生就看出来的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96ed990e-6a76-4bf4-be27-bf246034c330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97589, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先见", "is_correct": true, "explanation": "正确答案。先见 xiān jiàn，指事情还没发生就看出来的本事。"}, {"text": "相见", "is_correct": false, "explanation": "xiāng（第一声）与 xiān（第一声）韵母不同（ang 与 an），意思是互相见面。"}, {"text": "鲜见", "is_correct": false, "explanation": "xiǎn（第三声）与 xiān（第一声）声调不同，意思是少见、很少看到。"}, {"text": "先进", "is_correct": false, "explanation": "jìn（第四声）与 jiàn（第四声）韵母不同（in 与 ian），意思是领先、进步。"}], "explanations": {"先见": "正确答案。先见 xiān jiàn，指事情还没发生就看出来的本事。", "相见": "xiāng（第一声）与 xiān（第一声）韵母不同（ang 与 an），意思是互相见面。", "鲜见": "xiǎn（第三声）与 xiān（第一声）声调不同，意思是少见、很少看到。", "先进": "jìn（第四声）与 jiàn（第四声）韵母不同（in 与 ian），意思是领先、进步。"}, "sentence_index": null, "correct_answer": "先见"}, "level_3": {"options": [{"text": "灰尘", "is_correct": false, "explanation": "搭配：“很有”后不接“灰尘”，应说“很多灰尘”，句子不通。"}, {"text": "先见", "is_correct": true, "explanation": "正确：“很有先见”是固定说法，指有预见能力，与“早就买下了这块地”前后呼应。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”描写外貌，“很有面容”不通，且与买地无关。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是矿物，不能用来说人的能力，“很有石头”与买地的判断也无关。"}], "explanations": {"灰尘": "搭配：“很有”后不接“灰尘”，应说“很多灰尘”，句子不通。", "先见": "正确：“很有先见”是固定说法，指有预见能力，与“早就买下了这块地”前后呼应。", "面容": "体貌：“面容”描写外貌，“很有面容”不通，且与买地无关。", "石头": "语义：“石头”是矿物，不能用来说人的能力，“很有石头”与买地的判断也无关。"}, "sentence_index": 0, "correct_answer": "先见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的先见很高，不肯随便买东西。", "explanation": "这里应该用〈眼光〉。“眼光高”是固定搭配，形容挑剔或判断力强；“先见”一般说“有先见”，不说“先见很高”。"}, {"text": "这个孩子的先见很好，一看就明白。", "explanation": "这里应该用〈悟性〉。“悟性好”形容理解力强；“先见”指预见事情发展的能力，不能用来说理解得快。"}, {"text": "他的先见很广，去过很多国家。", "explanation": "这里应该用〈见识〉。“见识广”说的是见过的世面多；“先见”指预见事情发展的能力，不能用来说见过多少地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97589, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "先见", "is_correct": true, "explanation": "正确答案。先见 xiān jiàn，指事情还没发生就看出来的本事。"}, {"text": "浅见", "is_correct": false, "explanation": "qiǎn（第三声）与 xiān（第一声）声母、声调都不同，意思是浅薄的见解。"}, {"text": "显见", "is_correct": false, "explanation": "xiǎn（第三声）与 xiān（第一声）声调不同，意思是明显、看得出来。"}, {"text": "先验", "is_correct": false, "explanation": "yàn 与 jiàn 声母不同（y 与 j），意思是先于经验的、不依靠经验的。"}], "explanations": {"先见": "正确答案。先见 xiān jiàn，指事情还没发生就看出来的本事。", "浅见": "qiǎn（第三声）与 xiān（第一声）声母、声调都不同，意思是浅薄的见解。", "显见": "xiǎn（第三声）与 xiān（第一声）声调不同，意思是明显、看得出来。", "先验": "yàn 与 jiàn 声母不同（y 与 j），意思是先于经验的、不依靠经验的。"}, "sentence_index": null, "correct_answer": "先见"}, "level_3": {"options": [{"text": "脚印", "is_correct": false, "explanation": "语义：“脚印”是留在地上的痕迹，不是能让人佩服的能力。"}, {"text": "价钱", "is_correct": false, "explanation": "搭配：“佩服”的对象是能力或品质，不说“佩服价钱”。"}, {"text": "先见", "is_correct": true, "explanation": "正确：“佩服她的先见”指敬佩她事先看出事情的能力，与句子语境吻合。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体数据，不是可以“佩服”的对象，句子不通。"}], "explanations": {"脚印": "语义：“脚印”是留在地上的痕迹，不是能让人佩服的能力。", "价钱": "搭配：“佩服”的对象是能力或品质，不说“佩服价钱”。", "先见": "正确：“佩服她的先见”指敬佩她事先看出事情的能力，与句子语境吻合。", "体重": "体貌：“体重”是身体数据，不是可以“佩服”的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "先见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他订好了下个月的先见，准备出发。", "explanation": "这里应该用〈计划〉。“订”搭配计划、机票、房间等，“先见”是能力，不能被“订”。"}, {"text": "她的先见很开朗，大家都喜欢和她聊天。", "explanation": "这里应该用〈性格〉。“开朗”形容性格；“先见”指预见事情发展的能力，不能用来形容性格。"}, {"text": "他对工作的先见很认真，每天都早到半个小时。", "explanation": "这里应该用〈态度〉。“态度认真”说的是对待事情的看法和做法；“先见”指预见事情发展的能力，不能用来形容“认真”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师很先见，每次都提醒我们带伞。", "corrected_sentence": "这位老师很有先见，每次都提醒我们带伞。", "error_description": "“先见”前缺“有”。“很有先见”是固定说法，“很先见”不成立，应改为“很有先见”，表示有预见的能力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一件难得的先见，连天气变化都能预料到。", "corrected_sentence": "他有一种难得的先见，连天气变化都能预料到。", "error_description": "量词错误：“先见”是抽象能力，应搭配“种”，不能用“件”。“件”多用于具体的事物或事情。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97593, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱歌", "is_correct": false, "explanation": "与“冻结”没有反义关系，“唱歌”与水的状态变化无关。"}, {"text": "解冻", "is_correct": true, "explanation": "与“冻结”相反，指使冰冻的东西恢复为液态，是这一义项的反义词。"}, {"text": "散步", "is_correct": false, "explanation": "与“冻结”没有反义关系，“散步”是人的行走动作。"}, {"text": "思考", "is_correct": false, "explanation": "与“冻结”没有反义关系，“思考”是心理活动。"}], "correct_answer": "解冻", "explanations": {"唱歌": "与“冻结”没有反义关系，“唱歌”与水的状态变化无关。", "解冻": "与“冻结”相反，指使冰冻的东西恢复为液态，是这一义项的反义词。", "散步": "与“冻结”没有反义关系，“散步”是人的行走动作。", "思考": "与“冻结”没有反义关系，“思考”是心理活动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97593, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "写作", "is_correct": false, "explanation": "与“冻结”没有反义关系，“写作”是写文章的活动。"}, {"text": "解冻", "is_correct": true, "explanation": "与“冻结”相反，指使冰冻的东西恢复为液态，是这一义项的反义词。"}, {"text": "跑步", "is_correct": false, "explanation": "与“冻结”没有反义关系，“跑步”是人的运动。"}, {"text": "游泳", "is_correct": false, "explanation": "与“冻结”没有反义关系，“游泳”是在水中活动。"}], "correct_answer": "解冻", "explanations": {"写作": "与“冻结”没有反义关系，“写作”是写文章的活动。", "解冻": "与“冻结”相反，指使冰冻的东西恢复为液态，是这一义项的反义词。", "跑步": "与“冻结”没有反义关系，“跑步”是人的运动。", "游泳": "与“冻结”没有反义关系，“游泳”是在水中活动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97593, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水变冷了，变成硬硬的冰。", "primary_collocate": null, "pronunciation": "dòng jié", "ipa": "tʊŋ˥˩ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "冬天很冷，河水冻结了。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖面冻结以后，孩子们去滑冰。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太冷，水管里的水冻结了。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方的河水十二月就会冻结。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温度降到零度以下，水就会冻结。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚很冷，池塘的水冻结了。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水冻结以后，变成了硬硬的冰。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天，湖面上冻结了一层厚厚的冰。", "target_word": "冻结", "complexity_tier": "T3", "furigana": "dòng jié", "sentence_source": "generated"}, {"text": "外面零下二十度，河水都冻结了。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冻结的湖面上，有人在钓鱼。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "冻结了", "label": "体标"}, {"form": "冻结着", "label": "体标"}, {"form": "冻结过", "label": "体标"}, {"form": "凍結", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水遇冷变成冰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97593, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃烧", "is_correct": false, "explanation": "语义：水不能燃烧，“河水燃烧了”与冬天水变冷的语境矛盾。"}, {"text": "冻结", "is_correct": true, "explanation": "正确：水遇冷变成冰，与“冬天很冷”“河水”的语境相符。"}, {"text": "生长", "is_correct": false, "explanation": "语义：河水不会生长，“生长”只用于生物。"}, {"text": "打破", "is_correct": false, "explanation": "配价：“打破”需要带宾语，不能只说“河水打破了”。"}], "explanations": {"燃烧": "语义：水不能燃烧，“河水燃烧了”与冬天水变冷的语境矛盾。", "冻结": "正确：水遇冷变成冰，与“冬天很冷”“河水”的语境相符。", "生长": "语义：河水不会生长，“生长”只用于生物。", "打破": "配价：“打破”需要带宾语，不能只说“河水打破了”。"}, "sentence_index": 0, "correct_answer": "冻结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鸡蛋遇热冻结了。", "explanation": "这里应该用〈凝固〉。“冻结”指遇冷变成冰，遇热变硬要说“凝固”。"}, {"text": "铁块放进炉子里冻结了。", "explanation": "这里应该用〈熔化〉。金属受热变成液体要说“熔化”；“冻结”指遇冷变成冰，与此处的高温相反。"}, {"text": "冰块在火上冻结了。", "explanation": "这里应该用〈融化〉。冰遇火应当融化，“冻结”指遇冷变硬，两者方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97593, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融化", "is_correct": false, "explanation": "语义：水融化后不会变成硬硬的冰，与句中“变成了硬硬的冰”矛盾。"}, {"text": "冻结", "is_correct": true, "explanation": "正确：水遇冷凝结成冰，“冻结以后变成硬硬的冰”符合语境。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：水不会跳舞，“水跳舞以后”与“变成冰”无法衔接。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要带宾语，“水扔以后”不成立。"}], "explanations": {"融化": "语义：水融化后不会变成硬硬的冰，与句中“变成了硬硬的冰”矛盾。", "冻结": "正确：水遇冷凝结成冰，“冻结以后变成硬硬的冰”符合语境。", "跳舞": "语义：水不会跳舞，“水跳舞以后”与“变成冰”无法衔接。", "扔": "配价：“扔”需要带宾语，“水扔以后”不成立。"}, "sentence_index": 6, "correct_answer": "冻结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水蒸气遇冷冻结成了露水。", "explanation": "这里应该用〈凝结〉。“冻结”指液体变成冰，露水是液态水珠，应当说“凝结”。"}, {"text": "面包在烤箱里冻结了。", "explanation": "这里应该用〈烤熟〉。烤箱是加热的，面包不会冻结；“冻结”指遇冷变成冰。"}, {"text": "糖放进热水里冻结了。", "explanation": "这里应该用〈溶化〉。糖放进热水里会溶化，“冻结”指遇冷变硬，与此处语境相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池塘的水冻结了成冰。", "corrected_sentence": "池塘的水冻结成了冰。", "error_description": "体标位置错误：“冻结成冰”中“了”应放在“成”之后，即“冻结成了冰”，不能放在“成”之前。错误在“了”的位置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河水冻结很结实。", "corrected_sentence": "河水冻结得很结实。", "error_description": "补语标记错误：“冻结”后带程度补语“很结实”时要用“得”引出，漏掉“得”不成立。错误在缺少“得”，正确说法是“冻结得很结实”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97594, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃饭", "is_correct": false, "explanation": "与“冻结”没有反义关系，“吃饭”是日常活动。"}, {"text": "解冻", "is_correct": true, "explanation": "与“冻结”相反，指解除对资金、账户的限制，是这一义项的反义词。"}, {"text": "旅行", "is_correct": false, "explanation": "与“冻结”没有反义关系，“旅行”是出行活动。"}, {"text": "画画", "is_correct": false, "explanation": "与“冻结”没有反义关系，“画画”是艺术创作。"}], "correct_answer": "解冻", "explanations": {"吃饭": "与“冻结”没有反义关系，“吃饭”是日常活动。", "解冻": "与“冻结”相反，指解除对资金、账户的限制，是这一义项的反义词。", "旅行": "与“冻结”没有反义关系，“旅行”是出行活动。", "画画": "与“冻结”没有反义关系，“画画”是艺术创作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97594, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "写作", "is_correct": false, "explanation": "与“冻结”没有反义关系，“写作”是写文章的活动。"}, {"text": "解冻", "is_correct": true, "explanation": "与“冻结”相反，指解除对资金、账户的限制，是这一义项的反义词。"}, {"text": "跑步", "is_correct": false, "explanation": "与“冻结”没有反义关系，“跑步”是人的运动。"}, {"text": "游泳", "is_correct": false, "explanation": "与“冻结”没有反义关系，“游泳”是在水中活动。"}], "correct_answer": "解冻", "explanations": {"写作": "与“冻结”没有反义关系，“写作”是写文章的活动。", "解冻": "与“冻结”相反，指解除对资金、账户的限制，是这一义项的反义词。", "跑步": "与“冻结”没有反义关系，“跑步”是人的运动。", "游泳": "与“冻结”没有反义关系，“游泳”是在水中活动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97594, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "资金、账户等财产被禁止使用或转移。", "primary_collocate": null, "pronunciation": "dòng jié", "ipa": "tʊŋ˥˩ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "法院冻结了他的银行账户。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行把这笔钱冻结了。", "target_word": "冻结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院决定冻结公司的资金。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察冻结了骗子的账户。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的账户冻结了，不能取钱。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行发现问题，马上冻结了账户。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冻结资金以后，公司不能买东西了。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔货款被冻结了，供应商拿不到钱。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府冻结了这家公司的财产。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱已经冻结三个月了。", "target_word": "冻结", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "冻结了", "label": "体标"}, {"form": "冻结着", "label": "体标"}, {"form": "冻结过", "label": "体标"}, {"form": "凍結", "label": "繁体"}], "register": "书面", "sense_fingerprint": "账户或资金被禁止使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97594, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于可以擦拭的东西，不能说“擦账户”。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：银行账户是无形的，不能被烧毁，与“法院”的处理方式不符。"}, {"text": "冻结", "is_correct": true, "explanation": "正确：法院对账户采取冻结措施，禁止使用其中的资金，符合语境。"}, {"text": "翻修", "is_correct": false, "explanation": "语义：“翻修”针对建筑、设备，银行账户不能翻修。"}], "explanations": {"擦": "搭配：“擦”用于可以擦拭的东西，不能说“擦账户”。", "烧毁": "语义：银行账户是无形的，不能被烧毁，与“法院”的处理方式不符。", "冻结": "正确：法院对账户采取冻结措施，禁止使用其中的资金，符合语境。", "翻修": "语义：“翻修”针对建筑、设备，银行账户不能翻修。"}, "sentence_index": 0, "correct_answer": "冻结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察冻结了那家赌场。", "explanation": "这里应该用〈查封〉。“冻结”针对账户、资金，不能用于房屋、场所。"}, {"text": "银行冻结了他一笔新的贷款。", "explanation": "这里应该用〈发放〉。“冻结”是禁止使用已有的资金，银行给人新贷款要说“发放”。"}, {"text": "警察冻结了那名嫌疑人。", "explanation": "这里应该用〈拘留〉。“冻结”只用于资金、账户等财产，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说“煮资金”。"}, {"text": "冻结", "is_correct": true, "explanation": "正确：资金被冻结后，公司不能使用，因此“不能买东西了”，符合语境。"}, {"text": "染", "is_correct": false, "explanation": "搭配：“染”用于布料、头发等，不能说“染资金”。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：资金不是可燃物，“点燃资金”不成立。"}], "explanations": {"煮": "搭配：“煮”的对象是食物，不能说“煮资金”。", "冻结": "正确：资金被冻结后，公司不能使用，因此“不能买东西了”，符合语境。", "染": "搭配：“染”用于布料、头发等，不能说“染资金”。", "点燃": "语义：资金不是可燃物，“点燃资金”不成立。"}, "sentence_index": 6, "correct_answer": "冻结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法院冻结了这个小偷。", "explanation": "这里应该用〈逮捕〉。“冻结”只用于资金、账户等财产，不能用于人。"}, {"text": "公司冻结了一笔钱给员工发工资。", "explanation": "这里应该用〈拨出〉。“冻结”是禁止使用资金，拿出钱来发工资要说“拨出”。"}, {"text": "警察冻结了那辆偷来的汽车。", "explanation": "这里应该用〈扣押〉。“冻结”用于账户、资金，扣下车辆等实物要说“扣押”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院冻结了过他的账户。", "corrected_sentence": "法院冻结过他的账户。", "error_description": "体标错误：“过”与“了”不能同时用在动词后，应说“冻结过”或“冻结了”。错误在“了过”，正确说法是“冻结过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "银行把他的卡冻结。", "corrected_sentence": "银行把他的卡冻结了。", "error_description": "把字句语法错误：“把”字句中动词后需要带“了”等成分，光杆动词“冻结”不能单独结束句子。错误在缺少“了”，正确说法是“银行把他的卡冻结了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
