INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97598, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "车辆出动，出去载客或办事。", "primary_collocate": null, "pronunciation": "chū chē", "ipa": "tʂʰu˥ tʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "出租车司机早上五点就出车了。", "target_word": "出车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天公司有三辆车出车送货。", "target_word": "出车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，出车的人比平时少。", "target_word": "出车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个月出车的日子有二十多天。", "target_word": "出车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的救护车接到电话就马上出车。", "target_word": "出车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张今天出车去机场接客人。", "target_word": "出车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为生病，他今天没有出车。", "target_word": "出车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快过年了，司机们都不愿意出车。", "target_word": "出车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长说，明天一早大家都要出车。", "target_word": "出车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出车回来，累得连饭都不想吃。", "target_word": "出车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了车", "label": "体标"}, {"form": "出过车", "label": "体标"}], "register": "口语", "sense_fingerprint": "车辆出动去载客或办事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eca7faf1-53e9-4820-92b2-8ca5390197ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上课", "is_correct": false, "explanation": "语义：出租车司机在早上五点“上课”不合情理，与“出租车司机”的身份不符。"}, {"text": "出车", "is_correct": true, "explanation": "出车指车辆出动去载客或办事，与出租车司机早上开始工作相合。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“就结婚了”与前文的工作时间没有联系，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试”不是出租车司机日常工作的一部分，与“早上五点就”不搭。"}], "explanations": {"上课": "语义：出租车司机在早上五点“上课”不合情理，与“出租车司机”的身份不符。", "出车": "出车指车辆出动去载客或办事，与出租车司机早上开始工作相合。", "结婚": "语义：“就结婚了”与前文的工作时间没有联系，句意不通。", "考试": "搭配：“考试”不是出租车司机日常工作的一部分，与“早上五点就”不搭。"}, "sentence_index": 0, "correct_answer": "出车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店每个月出车的日子有二十多天。", "explanation": "这里的“出车”指车辆出动去载客或办事，主语应是驾驶人或车辆；商店不能作“出车”的主语，应改用〈营业〉或〈开门〉。"}, {"text": "他每个月骑自行车出车的日子有二十多天。", "explanation": "这里应该用〈骑车〉。“出车”指机动车辆出动，骑自行车上班不说“出车”。"}, {"text": "他每个月有二十多天出车去看女朋友。", "explanation": "这里应该用〈开车〉。“出车”指车辆出动去载客或办事，私人去看女朋友不说“出车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发烧", "is_correct": false, "explanation": "语义：“因为生病”与“没有发烧”的因果关系不通，句意矛盾。"}, {"text": "出车", "is_correct": true, "explanation": "出车指车辆出动去载客或办事，“因为生病，他今天没有出车”指他不能去开车。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休是长期的身份变化，不是“今天没有”做的事，与句意不合。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”是一次性的事件，不能用“今天没有”来否定。"}], "explanations": {"发烧": "语义：“因为生病”与“没有发烧”的因果关系不通，句意矛盾。", "出车": "出车指车辆出动去载客或办事，“因为生病，他今天没有出车”指他不能去开车。", "退休": "语义：退休是长期的身份变化，不是“今天没有”做的事，与句意不合。", "出生": "搭配：“出生”是一次性的事件，不能用“今天没有”来否定。"}, "sentence_index": 6, "correct_answer": "出车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天出车去上班，很方便。", "explanation": "这里应该用〈开车〉。个人开车上班不说“出车”，“出车”多指车辆出动去载客或办事。"}, {"text": "我们周末出车去郊外旅游。", "explanation": "这里应该用〈开车〉。“出车”不用于私人郊游，应说“开车去郊外”。"}, {"text": "他明天出车回老家过年。", "explanation": "这里应该用〈开车〉。“出车”不用于私人回家，应说“开车回老家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机们今天都没出车了。", "corrected_sentence": "司机们今天都没出车。", "error_description": "错误：“没”否定动作时，句末一般不加“了”，应为“都没出车”。（“不”否定时句末可以加“了”，如“不出车了”，表示不再出车。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚才出车着，现在才回来。", "corrected_sentence": "他刚才出车了，现在才回来。", "error_description": "错误：体标错误。表示“出车”这个动作已经完成要用“了”，“着”表示持续状态，“出车着”不合语法，应改为“出车了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
