INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97601, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用过以后还剩下来的。", "primary_collocate": null, "pronunciation": "shèng yú", "ipa": "ʂɤŋ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "剩余的饭菜放在冰箱里。", "target_word": "剩余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把剩余的纸交给老师。", "target_word": "剩余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画完画，剩余的颜料要收好。", "target_word": "剩余", "complexity_tier": "T3", "furigana": "shèng yú", "sentence_source": "generated"}, {"text": "他把剩余的钱存进了银行。", "target_word": "剩余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剩余的水可以浇花。", "target_word": "剩余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剩余的材料不多了。", "target_word": "剩余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完蛋糕，剩余的面粉还很多。", "target_word": "剩余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起吃完了剩余的水果。", "target_word": "剩余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剩余的零件放在这个盒子里。", "target_word": "剩余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剩余的布料明天再用。", "target_word": "剩余", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剩余物资", "label": "复合"}], "register": "中性", "sense_fingerprint": "用过之后还留下来的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剩余", "is_correct": true, "explanation": "正确：“剩余”修饰饭菜，指用过后留下的部分，句意完整。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能修饰饭菜。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”形容人的品质，不能修饰饭菜。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人或生物的年龄，不与饭菜搭配。"}], "explanations": {"剩余": "正确：“剩余”修饰饭菜，指用过后留下的部分，句意完整。", "聪明": "语义：“聪明”形容人的智力，不能修饰饭菜。", "勇敢": "语义：“勇敢”形容人的品质，不能修饰饭菜。", "年轻": "搭配：“年轻”说人或生物的年龄，不与饭菜搭配。"}, "sentence_index": 0, "correct_answer": "剩余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个句子是剩余的，可以删掉。", "explanation": "这里应该用〈多余〉。剩余指用后留下的部分，不需要的内容要说“多余”。"}, {"text": "这台旧电脑剩余在家里，已经很久没用了。", "explanation": "这里应该用〈闲置〉。剩余指用后剩下的部分，长期不用的东西要说“闲置”。"}, {"text": "墙上剩余着一块油渍。", "explanation": "这里应该用〈残留〉。油渍留下的痕迹要说“残留”，“剩余”指用后剩下的部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剩余", "is_correct": true, "explanation": "正确：“剩余的面粉”指做蛋糕后留下的面粉，与句意相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人的性格，不能修饰面粉。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”形容人的神态，不能修饰面粉。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”说人或物的身形，不用来说面粉的多少。"}], "explanations": {"剩余": "正确：“剩余的面粉”指做蛋糕后留下的面粉，与句意相符。", "幽默": "语义：“幽默”形容人的性格，不能修饰面粉。", "害羞": "语义：“害羞”形容人的神态，不能修饰面粉。", "高大": "搭配：“高大”说人或物的身形，不用来说面粉的多少。"}, "sentence_index": 6, "correct_answer": "剩余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家的生活剩余，不用担心钱。", "explanation": "这里应该用〈富裕〉。剩余指用后剩下的部分，生活宽裕要用“富裕”。"}, {"text": "这间屋子剩余着，没有人住。", "explanation": "这里应该用〈空闲〉。剩余指用后剩下的部分，没有人使用的房间要说“空闲”。"}, {"text": "这个问题已经剩余了，不用再担心。", "explanation": "这里应该用〈解决〉。剩余指用后剩下的部分，问题处理完要说“解决”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把很剩余的钱交给了妈妈。", "corrected_sentence": "他把剩余的钱交给了妈妈。", "error_description": "程度副词错误：“剩余”前不能加“很”，应直接修饰名词。应为“剩余的钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃完饭，剩余了的菜我们分给邻居。", "corrected_sentence": "吃完饭，剩余的菜我们分给邻居。", "error_description": "助词错误：“剩余”作定语修饰“菜”，后面接“的”，不能加“了”。应为“剩余的菜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
