INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97617, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "晚上十二点前后，天最黑的时候。", "primary_collocate": null, "pronunciation": "wǔ yè", "ipa": "wu˨˩˦ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "午夜十二点，街上很安静。", "target_word": "午夜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们看电影看到十二点，已经是午夜了。", "target_word": "午夜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "午夜十二点，城市的灯还亮着。", "target_word": "午夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天工作到午夜十二点才回家。", "target_word": "午夜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "午夜时天最黑，路上几乎没有人。", "target_word": "午夜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚我在午夜醒来，再也睡不着。", "target_word": "午夜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "午夜过后，外面下起了大雨。", "target_word": "午夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午夜的钟声响了，新年到了。", "target_word": "午夜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在午夜的海边一个人走着。", "target_word": "午夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说午夜以后不要再喝咖啡了。", "target_word": "午夜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "午夜时分", "label": "复合"}, {"form": "午夜场", "label": "复合"}], "register": "中性", "sense_fingerprint": "晚上十二点前后天最黑的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0aef20-8c93-4b94-980b-ea0ce9cddfeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97617, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "午夜", "is_correct": true, "explanation": "午夜 wǔ yè，指晚上十二点前后，天最黑的时候。"}, {"text": "无业", "is_correct": false, "explanation": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有工作。"}, {"text": "物业", "is_correct": false, "explanation": "wù（第四声）与 wǔ（第三声）声调不同，意思是物业管理。"}, {"text": "五一", "is_correct": false, "explanation": "yī（第一声）与 yè（第四声）声调不同，韵母也不同（-i 与 -e），意思是五一劳动节。"}], "explanations": {"午夜": "午夜 wǔ yè，指晚上十二点前后，天最黑的时候。", "无业": "wú（第二声）与 wǔ（第三声）声调不同，意思是没有工作。", "物业": "wù（第四声）与 wǔ（第三声）声调不同，意思是物业管理。", "五一": "yī（第一声）与 yè（第四声）声调不同，韵母也不同（-i 与 -e），意思是五一劳动节。"}, "sentence_index": null, "correct_answer": "午夜"}, "level_3": {"options": [{"text": "午夜", "is_correct": true, "explanation": "正确：午夜指晚上十二点前后，与“十二点”搭配，符合“街上很安静”。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨指天刚亮的时候，与“十二点”的钟点矛盾。"}, {"text": "黄昏", "is_correct": false, "explanation": "语义：黄昏指日落前后，与“十二点”的钟点矛盾。"}, {"text": "黎明", "is_correct": false, "explanation": "搭配：“黎明”指天将亮的时段，不与“十二点”这样的整点时刻连用。"}], "explanations": {"午夜": "正确：午夜指晚上十二点前后，与“十二点”搭配，符合“街上很安静”。", "清晨": "语义：清晨指天刚亮的时候，与“十二点”的钟点矛盾。", "黄昏": "语义：黄昏指日落前后，与“十二点”的钟点矛盾。", "黎明": "搭配：“黎明”指天将亮的时段，不与“十二点”这样的整点时刻连用。"}, "sentence_index": 0, "correct_answer": "午夜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天午夜十点去上班。", "explanation": "这里应该用〈上午〉。午夜指夜里十二点前后，上班多在白天，不能说“午夜十点去上班”。"}, {"text": "我们午夜六点吃晚饭。", "explanation": "这里应该用〈傍晚〉。午夜指夜里十二点前后，不能用来说六点吃晚饭。"}, {"text": "妈妈每天午夜七点叫我起床。", "explanation": "这里应该用〈早上〉。午夜指夜里十二点前后，不是叫人起床的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97617, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "午夜", "is_correct": true, "explanation": "午夜 wǔ yè，指晚上十二点前后，天最黑的时候。"}, {"text": "雨夜", "is_correct": false, "explanation": "yǔ（第三声）与 wǔ（第三声）声调相同，仅首音不同（y 与 w），意思是下雨的夜晚。"}, {"text": "武艺", "is_correct": false, "explanation": "yì（第四声）与 yè 韵母不同（-i 与 -e），意思是武术技艺。"}, {"text": "五月", "is_correct": false, "explanation": "yuè（第四声）比 yè 多一个 u 介音，意思是农历或公历的五月。"}], "explanations": {"午夜": "午夜 wǔ yè，指晚上十二点前后，天最黑的时候。", "雨夜": "yǔ（第三声）与 wǔ（第三声）声调相同，仅首音不同（y 与 w），意思是下雨的夜晚。", "武艺": "yì（第四声）与 yè 韵母不同（-i 与 -e），意思是武术技艺。", "五月": "yuè（第四声）比 yè 多一个 u 介音，意思是农历或公历的五月。"}, "sentence_index": null, "correct_answer": "午夜"}, "level_3": {"options": [{"text": "午夜", "is_correct": true, "explanation": "正确：午夜指晚上十二点前后，可以作为“过后”的时间起点，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“过后”后接时间或事件，“月亮”不能作为时间的起点。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不是时间或事件，“窗户过后”说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“过后”一般接时间或事件，“雨伞”不能这样搭配。"}], "explanations": {"午夜": "正确：午夜指晚上十二点前后，可以作为“过后”的时间起点，符合句意。", "月亮": "语义：“过后”后接时间或事件，“月亮”不能作为时间的起点。", "窗户": "语义：“窗户”不是时间或事件，“窗户过后”说不通。", "雨伞": "搭配：“过后”一般接时间或事件，“雨伞”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "午夜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民每天午夜六点下地干活。", "explanation": "这里应该用〈清晨〉。午夜指夜里十二点前后，六点下地干活是清晨的时间，不能说午夜。"}, {"text": "我午夜两点去开会。", "explanation": "这里应该用〈后半夜〉。午夜指夜里十二点前后，两点属于后半夜，不能说午夜。"}, {"text": "午夜四点，他还在写报告。", "explanation": "这里应该用〈凌晨〉。凌晨指夜里一点到天亮之前，午夜指十二点前后，四点不能说午夜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现在很午夜了。", "corrected_sentence": "现在是午夜了。", "error_description": "错误：“很午夜”；正确：“是午夜”。“午夜”是时间名词，不能受程度副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆一般很午夜才关门。", "corrected_sentence": "图书馆一般到午夜才关门。", "error_description": "错误：“很午夜”；正确：“到午夜”。“午夜”是时间名词，不能受“很”修饰；表示截止时间要用介词“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
