INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97619, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "衣服上可以放小东西的小袋子。", "primary_collocate": null, "pronunciation": "kǒu dai", "ipa": "kʰoʊ˨˩˦ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他把手放在口袋里。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的口袋里有一把钥匙。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服没有口袋。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裤子的口袋破了一个洞。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明从口袋里拿出一块糖。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的外套有两个大口袋。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机放进了口袋。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，孩子们的手都插在口袋里。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口袋太小，放不下这本书。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的口袋里是什么东西？", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "裤口袋", "label": "复合"}, {"form": "衣服口袋", "label": "复合"}], "register": "口语", "sense_fingerprint": "衣服上放小东西的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：手不能放在天空里，“天空”不是可以容纳东西的空间，与“放在……里”矛盾。"}, {"text": "口袋", "is_correct": true, "explanation": "正确：口袋指衣服上可以放小东西的袋子，手放在口袋里符合语境。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称谓，不是容器，“把手放在名字里”无法成立。"}, {"text": "桌面", "is_correct": false, "explanation": "搭配：放在平面上要用“上”，不能说“放在桌面里”。"}], "explanations": {"天空": "语义：手不能放在天空里，“天空”不是可以容纳东西的空间，与“放在……里”矛盾。", "口袋": "正确：口袋指衣服上可以放小东西的袋子，手放在口袋里符合语境。", "名字": "语义：“名字”是称谓，不是容器，“把手放在名字里”无法成立。", "桌面": "搭配：放在平面上要用“上”，不能说“放在桌面里”。"}, "sentence_index": 0, "correct_answer": "口袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服上有一张口袋。", "explanation": "这里应该用〈个〉。口袋的量词是“个”，“张”用于纸、桌子等平面的东西，不用于口袋。"}, {"text": "衣服都挂在口袋里。", "explanation": "这里应该用〈衣柜〉。衣服要挂在衣柜里；口袋是缝在衣服上的小袋，不能用来挂衣服。"}, {"text": "这件衣服有一根口袋。", "explanation": "这里应该用〈个〉。“根”用于细长条状的东西，口袋不用“根”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以装东西的容器，“放进窗户”不成立。"}, {"text": "口袋", "is_correct": true, "explanation": "正确：口袋可以装手机，“放进了口袋”符合语境。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不能装手机，“放进云朵”与常识矛盾。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”是抽象的，不能说“放进脾气”。"}], "explanations": {"窗户": "语义：窗户不是可以装东西的容器，“放进窗户”不成立。", "口袋": "正确：口袋可以装手机，“放进了口袋”符合语境。", "云朵": "语义：云朵不能装手机，“放进云朵”与常识矛盾。", "脾气": "搭配：“脾气”是抽象的，不能说“放进脾气”。"}, "sentence_index": 6, "correct_answer": "口袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服有一双口袋。", "explanation": "这里应该用〈个〉。“双”用于成对的东西，一件衣服上的口袋不用“双”来计量。"}, {"text": "她把口袋戴在手上出门。", "explanation": "这里应该用〈手套〉。口袋缝在衣服上，不能像手套一样戴在手上。"}, {"text": "天冷了，她把口袋围在脖子上。", "explanation": "这里应该用〈围巾〉。口袋缝在衣服上用来放小东西，围在脖子上保暖的是围巾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的外套上有一条口袋。", "corrected_sentence": "我的外套上有一个口袋。", "error_description": "量词错误：口袋的量词是“个”，“条”用于细长的东西。错误在“一条口袋”，正确说法是“一个口袋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把钱放进了口袋上。", "corrected_sentence": "他把钱放进了口袋里。", "error_description": "方位词错误：把东西放进口袋内部要用“里”，“口袋上”指口袋的表面。错误在方位词“上”，正确说法是“口袋里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
