INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97620, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "衣服上缝的小袋；也指装东西的袋子。", "primary_collocate": null, "pronunciation": "kǒu dai", "ipa": "kʰoʊ˨˩˦ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他的口袋里有很多硬币。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶拿出一个布口袋。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个口袋可以装十斤米。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸扛着一个大口袋回家。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把苹果装进这个口袋里吧。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在衣服口袋里找到了零钱。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口袋的拉链坏了。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她缝了一个小口袋。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裙子的口袋很可爱。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个旧口袋里装着花生。", "target_word": "口袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "布口袋", "label": "复合"}, {"form": "裤口袋", "label": "复合"}], "register": "口语", "sense_fingerprint": "衣服上缝的小袋，也指装东西的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是容器，硬币不能放在天空里。"}, {"text": "口袋", "is_correct": true, "explanation": "正确：口袋是装东西的袋子，“里有很多硬币”符合语境。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称谓，不能装硬币，“名字里有很多硬币”不成立。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”是抽象的，不能说“心情里有很多硬币”。"}], "explanations": {"天空": "语义：“天空”不是容器，硬币不能放在天空里。", "口袋": "正确：口袋是装东西的袋子，“里有很多硬币”符合语境。", "名字": "语义：“名字”是称谓，不能装硬币，“名字里有很多硬币”不成立。", "心情": "搭配：“心情”是抽象的，不能说“心情里有很多硬币”。"}, "sentence_index": 0, "correct_answer": "口袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸扛着一头大口袋回家。", "explanation": "这里应该用〈个〉。“头”用于牲畜，不用于口袋。"}, {"text": "爸爸扛着一双大口袋回家。", "explanation": "这里应该用〈个〉。“双”用于成对的东西，一个口袋不用“双”来计量。"}, {"text": "爸爸扛着一根大口袋回家。", "explanation": "这里应该用〈个〉。“根”用于细长条状的东西，口袋不用“根”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户上没有拉链，“窗户的拉链坏了”与常识矛盾。"}, {"text": "口袋", "is_correct": true, "explanation": "正确：口袋上可以有拉链，“口袋的拉链坏了”符合语境。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是衣物，没有拉链，“河流的拉链坏了”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”是抽象的，不能说“脾气的拉链”。"}], "explanations": {"窗户": "语义：窗户上没有拉链，“窗户的拉链坏了”与常识矛盾。", "口袋": "正确：口袋上可以有拉链，“口袋的拉链坏了”符合语境。", "河流": "语义：河流不是衣物，没有拉链，“河流的拉链坏了”不成立。", "脾气": "搭配：“脾气”是抽象的，不能说“脾气的拉链”。"}, "sentence_index": 6, "correct_answer": "口袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那页旧口袋里装着花生。", "explanation": "这里应该用〈个〉。“页”用于书页、纸张，不用于口袋。"}, {"text": "那辆旧口袋里装着花生。", "explanation": "这里应该用〈个〉。“辆”用于车，不用于口袋。"}, {"text": "那座旧口袋里装着花生。", "explanation": "这里应该用〈个〉。“座”用于山、桥等大型固定物，不用于口袋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷扛着一把口袋去买米。", "corrected_sentence": "爷爷扛着一个口袋去买米。", "error_description": "量词错误：“口袋”的量词应为“个”，“把”用于有柄的物件。错误在量词“把”，正确说法是“一个口袋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在围裙上缝了两颗大口袋。", "corrected_sentence": "妈妈在围裙上缝了两个大口袋。", "error_description": "量词错误：“口袋”的量词应为“个”，“颗”用于粒状、球状的东西，不用于口袋。错误在“两颗”，正确说法是“两个大口袋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
