INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97621, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以一直做下去，不会用完。", "primary_collocate": null, "pronunciation": "kě chí xù", "ipa": "kʰɤ˨˩˦ ʈʂʰɻ̩˧˥ ɕy˥˩", "syllable_count": 3, "sentences": [{"text": "每天跑步十分钟，这样的运动计划是可持续的。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样天天熬夜的生活不是可持续的。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找一种可持续的学习方法。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天学十个词，这个计划是可持续的。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存钱要慢慢来，这样才是可持续的。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天只吃一种菜，这种吃法不是可持续的。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每周见一次面，对我们来说是可持续的。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月存五百元，是我能做到的可持续办法。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慢慢地走，才是长跑中可持续的速度。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望找一种可持续的工作方式，不想天天加班。", "target_word": "可持续", "complexity_tier": "T3", "furigana": "wǒ xīwàng zhǎo yì zhǒng kěchíxù de gōngzuò fāngshì, bù xiǎng tiāntiān jiābān", "sentence_source": "generated"}], "morphological_forms": [{"form": "可持续性", "label": "复合"}, {"form": "可持续发展", "label": "复合"}], "register": "书面", "sense_fingerprint": "可以一直做下去，不会用完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ba1162-f38e-4526-87af-4a5384970596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97621, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可持续", "is_correct": true, "explanation": "可持续：能长期维持、不会用完，与“每天跑步”的长期安排相符。"}, {"text": "一次性", "is_correct": false, "explanation": "语义：“一次性”与“每天”的长期安排矛盾，句意不通。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜的”不能用来形容运动计划，句意荒谬。"}, {"text": "可消耗", "is_correct": false, "explanation": "搭配：“可消耗”多用于物品，不能用来形容运动计划。"}], "explanations": {"可持续": "可持续：能长期维持、不会用完，与“每天跑步”的长期安排相符。", "一次性": "语义：“一次性”与“每天”的长期安排矛盾，句意不通。", "甜": "语义：“甜的”不能用来形容运动计划，句意荒谬。", "可消耗": "搭配：“可消耗”多用于物品，不能用来形容运动计划。"}, "sentence_index": 0, "correct_answer": "可持续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他留下了一个可持续的印象。", "explanation": "这里应该用〈持久〉。可持续指能长期维持、不会用完，用于做法和计划；形容印象要用“持久”。"}, {"text": "这份工作带给我可持续的压力。", "explanation": "这里应该用〈持续〉。可持续说做法能否维持，形容压力、状态要用“持续”。"}, {"text": "他经历了可持续的失败。", "explanation": "这里应该用〈连续〉。可持续不表示接连发生，形容接连不断的失败要用“连续”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可持续", "is_correct": true, "explanation": "可持续：能长期维持，与“每周见一次面”这种长期安排相符。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”与“每周”的固定安排矛盾。"}, {"text": "熟练", "is_correct": false, "explanation": "搭配：“熟练”形容技能，不能用来形容见面。"}, {"text": "暂时", "is_correct": false, "explanation": "语义：“暂时”指时间很短，与“每周见一次面”的长期安排矛盾。"}], "explanations": {"可持续": "可持续：能长期维持，与“每周见一次面”这种长期安排相符。", "偶然": "语义：“偶然”与“每周”的固定安排矛盾。", "熟练": "搭配：“熟练”形容技能，不能用来形容见面。", "暂时": "语义：“暂时”指时间很短，与“每周见一次面”的长期安排矛盾。"}, "sentence_index": 6, "correct_answer": "可持续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经历了可持续的等待。", "explanation": "这里应该用〈漫长〉。可持续指能长期维持，不用来形容等待的时间很长。"}, {"text": "这是一份可持续的爱。", "explanation": "这里应该用〈恒久〉。可持续说做法能否维持，形容爱情的长久要用“恒久”。"}, {"text": "他的热情很可持续，过了两天就没了。", "explanation": "这里应该用〈短暂〉。可持续指能长期维持、不会用完，形容热情很快消失要用“短暂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要选一种可持续地锻炼方式。", "corrected_sentence": "我们要选一种可持续的锻炼方式。", "error_description": "错误：“可持续”修饰名词“锻炼方式”应用“的”，此处误用“地”；“地”用于修饰动词，不能直接修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该过可持续得生活。", "corrected_sentence": "我们应该过可持续的生活。", "error_description": "错误：修饰名词“生活”应用“的”，此处误用“得”；“得”只用于动词或形容词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
