INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97622, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能够长期维持、持续发展而不枯竭的。", "primary_collocate": null, "pronunciation": "kě chí xù", "ipa": "kʰɤ˨˩˦ ʈʂʰɻ̩˧˥ ɕy˥˩", "syllable_count": 3, "sentences": [{"text": "我们要走一条可持续的路，不能只顾眼前。", "target_word": "可持续", "complexity_tier": "T3", "furigana": "wǒmen yào zǒu yì tiáo kěchíxù de lù, bù néng zhǐ gù yǎnqián", "sentence_source": "generated"}, {"text": "这个城市正在发展可持续的经济。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能是一种可持续的能源。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护森林，才能有可持续的未来。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂改用了可持续的生产方式。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可持续农业能让土地长期有好收成。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家建议大家过可持续的生活。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请专家讲解可持续的能源利用。", "target_word": "可持续", "complexity_tier": "T3", "furigana": "xuéxiào qǐng zhuānjiā jiǎngjiě kěchíxù de néngyuán lìyòng", "sentence_source": "generated"}, {"text": "风能和水能都是可持续的资源。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有可持续的办法，才能保护河流。", "target_word": "可持续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可持续性", "label": "复合"}, {"form": "可持续发展", "label": "复合"}], "register": "书面", "sense_fingerprint": "能长期维持、持续发展而不枯竭的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ba1162-f38e-4526-87af-4a5384970596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可持续", "is_correct": true, "explanation": "可持续：能长期维持、持续发展，与“不能只顾眼前”的长远要求一致。"}, {"text": "一次性", "is_correct": false, "explanation": "语义：“一次性”的路与“不能只顾眼前”的长远要求矛盾。"}, {"text": "熟练", "is_correct": false, "explanation": "搭配：“熟练”形容人的技能，不能用来形容路。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”的路与需要长远规划的语境矛盾。"}], "explanations": {"可持续": "可持续：能长期维持、持续发展，与“不能只顾眼前”的长远要求一致。", "一次性": "语义：“一次性”的路与“不能只顾眼前”的长远要求矛盾。", "熟练": "搭配：“熟练”形容人的技能，不能用来形容路。", "偶然": "语义：“偶然”的路与需要长远规划的语境矛盾。"}, "sentence_index": 0, "correct_answer": "可持续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她留下了一个可持续的印象。", "explanation": "这里应该用〈持久〉。可持续指能长期维持、不会用完，用于做法和计划；形容印象要用“持久”。"}, {"text": "这次事故带来了可持续的伤痛。", "explanation": "这里应该用〈持续〉。可持续说做法能否维持，形容伤痛的延续要用“持续”。"}, {"text": "他遇到了可持续的困难。", "explanation": "这里应该用〈连续〉。可持续不表示接连发生，形容接连出现的困难要用“连续”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可持续", "is_correct": true, "explanation": "可持续：能长期维持，与“专家建议”的长远目标一致。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”与专家的建议相反，句意不通。"}, {"text": "痛苦", "is_correct": false, "explanation": "语义：“痛苦”的生活与专家建议的目标相反，句意矛盾。"}, {"text": "一次性", "is_correct": false, "explanation": "语义：“一次性”的生活与专家倡导的长期可持续相反，句意矛盾。"}], "explanations": {"可持续": "可持续：能长期维持，与“专家建议”的长远目标一致。", "放纵": "语义：“放纵”与专家的建议相反，句意不通。", "痛苦": "语义：“痛苦”的生活与专家建议的目标相反，句意矛盾。", "一次性": "语义：“一次性”的生活与专家倡导的长期可持续相反，句意矛盾。"}, "sentence_index": 6, "correct_answer": "可持续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们有可持续的友谊。", "explanation": "这里应该用〈长久〉。可持续指能长期维持，形容友谊的长久要用“长久”。"}, {"text": "这个城市的变化很可持续，一天就结束了。", "explanation": "这里应该用〈短暂〉。可持续指能长期维持，形容变化很快结束要用“短暂”。"}, {"text": "这个塑料袋是可持续的，用一次就扔了。", "explanation": "这里应该用〈一次性〉。可持续指能长期维持、不枯竭，用一次就扔的东西要说“一次性”的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要发展一种可持续地农业。", "corrected_sentence": "我们要发展一种可持续的农业。", "error_description": "错误：“可持续”修饰名词“农业”，应用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师建议我们过可持续得生活。", "corrected_sentence": "老师建议我们过可持续的生活。", "error_description": "错误：“可持续”修饰名词“生活”应用“的”，此处误用“得”；“得”用于动词或形容词后作补语，不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd473168b-72a9-478a-9cee-5dd52e59693b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
