INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97625, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "别人夸你，你客气地说自己没那么好。", "primary_collocate": null, "pronunciation": "nǎ lǐ nǎ lǐ", "ipa": "na˨˩ li˨˩ na˨˩ li˨˩", "syllable_count": 4, "sentences": [{"text": "“你今天真漂亮！”“哪里哪里，随便穿的。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你跑得真快！”“哪里哪里，比我朋友慢多了。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你画得真好！”“哪里哪里，我只是画着玩。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她夸我很会做饭，我说：“哪里哪里。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你真厉害，什么都会！”“哪里哪里。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你的房间真干净！”“哪里哪里，刚收拾过。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学夸我成绩好，我不好意思地说：“哪里哪里。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你真有才华！”“哪里哪里，你过奖了。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你的孩子真有礼貌！”“哪里哪里，他有时也不听话。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居夸我年轻，我笑着说：“哪里哪里。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "被夸奖时客气地表示自己没那么好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9f1fea1-908e-4ce9-8922-f29a3023b15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪里哪里", "is_correct": true, "explanation": "正确：客气地说自己没那么好，与前面的夸奖“你今天真漂亮”相呼应。"}, {"text": "糟了", "is_correct": false, "explanation": "语义：“糟了”表示出了问题，与夸奖的语境相反。"}, {"text": "对不起", "is_correct": false, "explanation": "搭配：“对不起”用于道歉，不能接在夸奖之后。"}, {"text": "再见", "is_correct": false, "explanation": "语义：“再见”是告别语，与当场夸赞的情境不符。"}], "explanations": {"哪里哪里": "正确：客气地说自己没那么好，与前面的夸奖“你今天真漂亮”相呼应。", "糟了": "语义：“糟了”表示出了问题，与夸奖的语境相反。", "对不起": "搭配：“对不起”用于道歉，不能接在夸奖之后。", "再见": "语义：“再见”是告别语，与当场夸赞的情境不符。"}, "sentence_index": 0, "correct_answer": "哪里哪里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“今天天气怎么样？”“哪里哪里，下雨了。”", "explanation": "这里是在回答天气问题，哪里哪里表示客气地说自己没那么好，不能用来报告天气，应直接说明天气情况，不加〈哪里哪里〉。"}, {"text": "“你家在哪儿？”“哪里哪里，在城东。”", "explanation": "这里是问地点，“哪里”应作疑问代词表示“哪儿”；而“哪里哪里”只作客套话，不表示地点，回答位置时不能用它。"}, {"text": "“你真聪明，哪里哪里！”", "explanation": "这里是夸别人，哪里哪里只是被夸者客气的谦辞，不能用来赞美别人，应改用〈真不错〉之类的赞美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪里哪里", "is_correct": true, "explanation": "正确：谦虚地说自己成绩没那么好，与“同学夸我成绩好”相呼应。"}, {"text": "请问", "is_correct": false, "explanation": "语义：“请问”用于提问，不能用来回应夸奖。"}, {"text": "晚安", "is_correct": false, "explanation": "语义：“晚安”是睡前问候，与称赞的语境无关。"}, {"text": "明天见", "is_correct": false, "explanation": "语义：“明天见”是分别时的告别语，不能用来回应别人的夸奖。"}], "explanations": {"哪里哪里": "正确：谦虚地说自己成绩没那么好，与“同学夸我成绩好”相呼应。", "请问": "语义：“请问”用于提问，不能用来回应夸奖。", "晚安": "语义：“晚安”是睡前问候，与称赞的语境无关。", "明天见": "语义：“明天见”是分别时的告别语，不能用来回应别人的夸奖。"}, "sentence_index": 6, "correct_answer": "哪里哪里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“你要喝茶还是咖啡？”“哪里哪里，都行。”", "explanation": "这里是在回答选择问题，哪里哪里表示客气地否认称赞，不能用来表示无所谓，应直接说〈随便〉。"}, {"text": "“这个周末你有空吗？”“哪里哪里，有空。”", "explanation": "这里是回答是否有空，哪里哪里是客气地否认称赞的话，不用来回答有没有空，应直接说〈没问题〉。"}, {"text": "“你觉得这部电影怎么样？”“哪里哪里，很精彩。”", "explanation": "哪里哪里只用来谦虚地否认别人的夸奖，用来回答对作品的看法不通顺，应直接说〈不错〉之类的评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“你的字写得真好！”“哪里哪里的，我还不太会写。”", "corrected_sentence": "“你的字写得真好！”“哪里哪里，我还不太会写。”", "error_description": "错误：“哪里哪里”后面加了结构助词“的”。正确：作为叹词的“哪里哪里”后直接接逗号，不能带“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“你的房间真整齐！”“哪里哪里哪里，我还要收拾。”", "corrected_sentence": "“你的房间真整齐！”“哪里哪里，我还要收拾。”", "error_description": "错误：“哪里哪里哪里”，多重复了一次“哪里”；正确：“哪里哪里”。客套话只用两次“哪里”的重叠形式，不能再叠加。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
