INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97626, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "客套话，用来回应别人的称赞，表示谦虚。", "primary_collocate": null, "pronunciation": "nǎ lǐ nǎ lǐ", "ipa": "na˨˩ li˨˩ na˨˩ li˨˩", "syllable_count": 4, "sentences": [{"text": "“你的字写得真漂亮！”“哪里哪里，还要多练习。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事夸我报告写得好，我说：“哪里哪里。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你做的菜真好吃！”“哪里哪里，随便做的。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“听说你工作很努力。”“哪里哪里，大家都一样。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他夸我汉语好，我笑着说：“哪里哪里。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你女儿真聪明！”“哪里哪里，她还小呢。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你唱歌真好听！”“哪里哪里，我只是喜欢唱。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说我的房子很漂亮，我说：“哪里哪里。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你的英语说得真流利！”“哪里哪里，还差得远。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“您真是个好老师！”“哪里哪里，我还要学习。”", "target_word": "哪里哪里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "回应称赞时的客套谦虚用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9f1fea1-908e-4ce9-8922-f29a3023b15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪里哪里", "is_correct": true, "explanation": "正确：回应称赞时的客套谦虚语，与前面“你的字写得真漂亮！”的夸奖相呼应。"}, {"text": "不客气", "is_correct": false, "explanation": "语义：“不客气”用于回应感谢，不能用来回应夸奖。"}, {"text": "对不起", "is_correct": false, "explanation": "搭配：“对不起”只能接在过错或打扰之后，不能接在夸奖之后。"}, {"text": "再见", "is_correct": false, "explanation": "语义：“再见”是告别语，与句中的夸奖和“还要多练习”的语境不合。"}], "explanations": {"哪里哪里": "正确：回应称赞时的客套谦虚语，与前面“你的字写得真漂亮！”的夸奖相呼应。", "不客气": "语义：“不客气”用于回应感谢，不能用来回应夸奖。", "对不起": "搭配：“对不起”只能接在过错或打扰之后，不能接在夸奖之后。", "再见": "语义：“再见”是告别语，与句中的夸奖和“还要多练习”的语境不合。"}, "sentence_index": 0, "correct_answer": "哪里哪里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“请帮我拿一下书。”“哪里哪里，我马上去。”", "explanation": "这里是答应对方的请求，应说〈好的〉；哪里哪里只表示谦虚地否认别人的称赞，不能用来答应请求。"}, {"text": "“早上好！”“哪里哪里。”", "explanation": "这里是回应问候，哪里哪里只用来谦虚地否认别人的称赞，不能用来回应问候，应说〈你也早〉。"}, {"text": "我做的蛋糕真好吃，哪里哪里。", "explanation": "这里是自己夸自己做的蛋糕，哪里哪里只能客气地否认别人的夸奖，不能接在自夸后面，应改用〈还可以〉之类的自我评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪里哪里", "is_correct": true, "explanation": "正确：客气地否认自己唱得好，与后面“我只是喜欢唱”相呼应。"}, {"text": "请问", "is_correct": false, "explanation": "语义：“请问”用于发问，不能用来回应夸奖。"}, {"text": "晚安", "is_correct": false, "explanation": "语义：“晚安”是睡前问候，与当场的称赞无关。"}, {"text": "不用谢", "is_correct": false, "explanation": "搭配：“不用谢”只能接在对方的感谢之后，不能接在夸奖之后。"}], "explanations": {"哪里哪里": "正确：客气地否认自己唱得好，与后面“我只是喜欢唱”相呼应。", "请问": "语义：“请问”用于发问，不能用来回应夸奖。", "晚安": "语义：“晚安”是睡前问候，与当场的称赞无关。", "不用谢": "搭配：“不用谢”只能接在对方的感谢之后，不能接在夸奖之后。"}, "sentence_index": 6, "correct_answer": "哪里哪里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“我的钱包丢了。”“哪里哪里，别着急。”", "explanation": "这里是安慰遇到麻烦的人，哪里哪里只用来客气地否认别人的夸奖，不能用来安慰别人，应说〈别着急，我帮你找〉。"}, {"text": "“现在几点了？”“哪里哪里，九点。”", "explanation": "这里是回答时间问题，哪里哪里表示谦虚地否认称赞，用在报时上不通顺，应直接报时间，不加〈哪里哪里〉。"}, {"text": "“你觉得这部电影怎么样？”“哪里哪里，很精彩。”", "explanation": "哪里哪里只用来谦虚地否认别人的夸奖，用来回答对作品的看法不通顺，应直接说〈不错〉之类的评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“这首歌你唱得真好！”“哪里哪里吗，我还要练。”", "corrected_sentence": "“这首歌你唱得真好！”“哪里哪里，我还要练。”", "error_description": "错误：“哪里哪里”后面加了疑问语气词“吗”；正确：“哪里哪里”。这句客套话是谦虚地回应称赞，不是在提问，后面不能加“吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“你画得真好！”“哪里哪里的，我还不太会画。”", "corrected_sentence": "“你画得真好！”“哪里哪里，我还不太会画。”", "error_description": "错误：“哪里哪里”后面加了结构助词“的”。正确：作为叹词的“哪里哪里”后直接接逗号，不能带“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e74a0de-7628-402a-bbbf-fdabd640d2fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
