INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97633, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "印在东西上，让人知道是谁家做的小图或名字。", "primary_collocate": null, "pronunciation": "shāng biāo", "ipa": "ʂɑŋ˥ piɑʊ˥", "syllable_count": 2, "sentences": [{"text": "杯子底下印着一个小商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的商标是一只小鸟。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈撕掉了衣服上的商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包上的商标掉了一半。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶水的商标是红色的。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手挡住了箱子上的商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在手机后面找到了商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表上有一个金色的商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商标是一个苹果的图案。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把盒子上的商标擦干净。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "注册商标", "label": "复合"}, {"form": "商標", "label": "繁体"}], "register": "中性", "sense_fingerprint": "印在物品上表明出自谁家的小图或名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97633, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商标", "is_correct": true, "explanation": "正确：商标是印在杯子上的小图或名字，句子说“印着”，符合语义。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不能印在杯子上，句子不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不能被印出来，句子不通。"}, {"text": "体型", "is_correct": false, "explanation": "语义：“体型”指人或动物的身材，不能印在物品上。"}], "explanations": {"商标": "正确：商标是印在杯子上的小图或名字，句子说“印着”，符合语义。", "声音": "语义：“声音”不能印在杯子上，句子不通。", "味道": "语义：“味道”不能被印出来，句子不通。", "体型": "语义：“体型”指人或动物的身材，不能印在物品上。"}, "sentence_index": 0, "correct_answer": "商标"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的商标很短，只有两个字。", "explanation": "这里应该用〈题目〉。商标是印在东西上的小图或名字，文章的标题要说“题目”。"}, {"text": "教室墙上写着商标：好好学习。", "explanation": "这里应该用〈标语〉。商标是印在东西上的小图或名字，墙上的口号要说“标语”。"}, {"text": "这首歌的商标很好听。", "explanation": "这里应该用〈歌名〉。商标是印在东西上的小图或名字，歌曲的名称要说“歌名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97633, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商标", "is_correct": true, "explanation": "正确：商标是印在物品上的小图或名字，可以在手机后面找到，句意合理。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，不是可以在手机后面找到的东西。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是测得的数值，不是实体，句子不通。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“找到”不与“呼吸”搭配，句子不通。"}], "explanations": {"商标": "正确：商标是印在物品上的小图或名字，可以在手机后面找到，句意合理。", "年龄": "语义：“年龄”是人的岁数，不是可以在手机后面找到的东西。", "温度": "语义：“温度”是测得的数值，不是实体，句子不通。", "呼吸": "搭配：“找到”不与“呼吸”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "商标"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上贴着商标，说明明天停电。", "explanation": "这里应该用〈通知〉。商标是印在东西上的小图或名字，贴在墙上说明停电要用“通知”。"}, {"text": "桌子上放着商标，是我们一家人。", "explanation": "这里应该用〈照片〉。商标是印在东西上的小图或名字，一家人的合影要说“照片”。"}, {"text": "姐姐每天晚上都写商标。", "explanation": "这里应该用〈日记〉。商标是印在东西上的小图或名字，每天记下的事情要说“日记”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书包上印着一只小商标。", "corrected_sentence": "书包上印着一个小商标。", "error_description": "量词错误：“商标”应用量词“个”，“只”用于动物或成对的东西。应为“一个小商标”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在手机后面找到了一颗商标。", "corrected_sentence": "我在手机后面找到了一个商标。", "error_description": "量词错误：“商标”应用量词“个”，“颗”用于粒状、球状的东西，不用于商标。错误在“一颗”，正确说法是“一个商标”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
