INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "商品上用来区别生产者的专用标志。", "primary_collocate": null, "pronunciation": "shāng biāo", "ipa": "ʂɑŋ˥ piɑʊ˥", "syllable_count": 2, "sentences": [{"text": "这个商标很有名。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在衣服上看到了这个商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经注册了这个商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的商标在领子后面。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认识这个商标吗？", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司换了新商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时，我先看商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人不能用我们公司的商标。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假商标会骗人，千万别买。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商标的设计很简单，也很好看。", "target_word": "商标", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "注册商标", "label": "复合"}, {"form": "商標", "label": "繁体"}], "register": "中性", "sense_fingerprint": "商品上区别生产者的专用标志", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商标", "is_correct": true, "explanation": "正确：商标是商品上用来区别生产者的标志，句子说它“很有名”，符合语义。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“有名”说的是名声，天气没有名声，不能说“很有名”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不与“有名”搭配，不能说某种年龄很有名。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不会有名，句子不通。"}], "explanations": {"商标": "正确：商标是商品上用来区别生产者的标志，句子说它“很有名”，符合语义。", "天气": "语义：“有名”说的是名声，天气没有名声，不能说“很有名”。", "年龄": "搭配：“年龄”不与“有名”搭配，不能说某种年龄很有名。", "空气": "语义：空气是无形的气体，不会有名，句子不通。"}, "sentence_index": 0, "correct_answer": "商标"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "路口立着一个禁止左转的商标。", "explanation": "这里应该用〈标志〉。商标是商品上用来区别生产者的专用标志，交通规定的标记要说“标志”。"}, {"text": "他在合同的末尾签了商标。", "explanation": "这里应该用〈签名〉。商标是印在商品上的标志，人在文件上写名字要说“签名”。"}, {"text": "这件外套是商标，穿起来很舒服。", "explanation": "这里应该用〈名牌〉。商标是标记本身，不能说衣服“是商标”；说衣服本身有名气要用“名牌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商标", "is_correct": true, "explanation": "正确：“看商标”指买东西时查看商品上的标志，句意完整。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不能带“声音”，听声音要说“听”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”不能带“味道”，要知道味道应说“尝”或“闻”。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是走路时的动作，买东西时不会去看它，句子不通。"}], "explanations": {"商标": "正确：“看商标”指买东西时查看商品上的标志，句意完整。", "声音": "搭配：“看”不能带“声音”，听声音要说“听”。", "味道": "搭配：“看”不能带“味道”，要知道味道应说“尝”或“闻”。", "脚步": "语义：脚步是走路时的动作，买东西时不会去看它，句子不通。"}, "sentence_index": 6, "correct_answer": "商标"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街上贴满了新电影的商标。", "explanation": "这里应该用〈广告〉。商标是印在商品上的标志，街上贴的宣传要说“广告”。"}, {"text": "学校发来的商标说明下周放假。", "explanation": "这里应该用〈通知〉。商标是商品上用来区别生产者的标志，学校发来的说明要用“通知”。"}, {"text": "这本小说的商标很有意思。", "explanation": "这里应该用〈题目〉。商标是商品上的专用标志，书的名称要说“题目”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服上有一只商标。", "corrected_sentence": "这件衣服上有一个商标。", "error_description": "量词错误：“商标”应用量词“个”，“只”用于动物或成对的东西。应为“一个商标”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司注册了一块商标。", "corrected_sentence": "这家公司注册了一个商标。", "error_description": "量词错误：“商标”应用量词“个”，“块”用于块状的东西。应为“一个商标”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
