INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本国的人；同一国家的人民。", "primary_collocate": null, "pronunciation": "guó rén", "ipa": "kwo˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "在国外，我遇到了很多国人。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的客人大多是国人。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外生活，常和国人聚会。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，国人要带好护照。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方国人很少来，游客很多。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国人出国旅游的越来越多。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店只卖东西给国人。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国人去那个国家不用办签证。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教国人学外语。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国外的朋友问国人爱吃什么。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "本国的人，与外国人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '626c37bb-6c51-4dc9-849b-b00c7672087d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国人", "is_correct": true, "explanation": "国人指同一国家的人，与“在国外遇到”的语境相符。"}, {"text": "国王", "is_correct": false, "explanation": "语义：国王是君主，“在国外遇到很多国王”不合常理，与国人的人民之义不符。"}, {"text": "国籍", "is_correct": false, "explanation": "搭配：“遇到”的对象应是人，不能说遇到很多国籍。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照是证件，不是人，不能与“遇到很多”搭配。"}], "explanations": {"国人": "国人指同一国家的人，与“在国外遇到”的语境相符。", "国王": "语义：国王是君主，“在国外遇到很多国王”不合常理，与国人的人民之义不符。", "国籍": "搭配：“遇到”的对象应是人，不能说遇到很多国籍。", "护照": "语义：护照是证件，不是人，不能与“遇到很多”搭配。"}, "sentence_index": 0, "correct_answer": "国人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的国人是美国，但他长期在中国生活。", "explanation": "这里应该用〈国籍〉。国人指同一国家的人民，不能用来说明一个人的国籍。"}, {"text": "这台电脑是国人。", "explanation": "这里误把〈国人〉当成了〈国货〉的意思。国人指同一国家的人，不指物品；国产的物品称为“国货”。"}, {"text": "我们学校有很多国人学生，他们来自法国、德国和巴西。", "explanation": "这里应该用〈国际〉。国人指本国的人，学生来自不同国家时应说“国际学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国人", "is_correct": true, "explanation": "国人指本国的人，“只卖东西给”的对象是本国顾客，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不能成为买东西的对象。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“卖给”需要能接受交易的人作受事，空气不能作这样的对象。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不是可以买东西的人，句意不通。"}], "explanations": {"国人": "国人指本国的人，“只卖东西给”的对象是本国顾客，符合句意。", "桌子": "语义：桌子不是人，不能成为买东西的对象。", "空气": "配价：“卖给”需要能接受交易的人作受事，空气不能作这样的对象。", "汽车": "语义：汽车是交通工具，不是可以买东西的人，句意不通。"}, "sentence_index": 6, "correct_answer": "国人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国人很大，人口超过十亿。", "explanation": "这里应该用〈国家〉。国人指人，不指国土或人口所在的国家。"}, {"text": "我们住在一个国人里。", "explanation": "国人是指人群，不是可以居住的地方，这里应说“在国内”或“在这个国家”。"}, {"text": "我家的国人是一只小白狗。", "explanation": "国人指本国的人，不能指动物。这里应该说“我家的小狗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在火车上遇到了一只国人。", "corrected_sentence": "我在火车上遇到了一位国人。", "error_description": "错误在量词：指人应用〈位〉或〈个〉，〈只〉一般不用于指人。正确说法是“一位国人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商店对这张国人很热情。", "corrected_sentence": "这家商店对这位国人很热情。", "error_description": "错误在量词：指人应用〈位〉或〈个〉，〈张〉用于平面的东西，不能修饰国人。正确说法是“这位国人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
