INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97641, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "是全国最高一级的。", "primary_collocate": null, "pronunciation": "guó jiā jí", "ipa": "kuo˧˥ tɕja˥ tɕi˧˥", "syllable_count": 3, "sentences": [{"text": "这是一个国家级的公园。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是国家级运动员。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学有三个国家级实验室。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的传统节日是国家级文化遗产。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家博物馆是国家级的，每年有很多人来参观。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画得过国家级大奖。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山是国家级风景区，门票不便宜。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当上了国家级教练。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛是国家级的，只有最好的队才能参加。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家级医院的医生都很有经验。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国家级运动员", "label": "复合"}, {"form": "國家級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "等级属于全国最高一级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家级", "is_correct": true, "explanation": "正确：国家级指全国最高一级，修饰“公园”符合句意。"}, {"text": "清醒", "is_correct": false, "explanation": "语义：公园不能“清醒”，句意不通。"}, {"text": "高速", "is_correct": false, "explanation": "搭配：“高速”多用于公路、列车，不能修饰“公园”。"}, {"text": "金属", "is_correct": false, "explanation": "语义：“金属”指材料，不能用来描述公园。"}], "explanations": {"国家级": "正确：国家级指全国最高一级，修饰“公园”符合句意。", "清醒": "语义：公园不能“清醒”，句意不通。", "高速": "搭配：“高速”多用于公路、列车，不能修饰“公园”。", "金属": "语义：“金属”指材料，不能用来描述公园。"}, "sentence_index": 0, "correct_answer": "国家级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们班的国家级朋友，我们从小一起长大。", "explanation": "这里误用了〈国家级〉，句子把它当作形容交情深浅的词。国家级指全国最高一级，朋友之间的交情没有这种等级之分。"}, {"text": "我每个月的工资是国家级的，数目很稳定。", "explanation": "这里误用了〈国家级〉，句子把它当作形容收入水平的词。国家级指全国最高一级，工资并不按全国最高一级来划分。"}, {"text": "这张桌子是国家级的，很结实。", "explanation": "这里误用了〈国家级〉，句子把它当作形容实物质量、结实程度的词。国家级指全国最高一级，桌子不属于这种等级体系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家级", "is_correct": true, "explanation": "正确：国家级指全国最高一级，与“风景区”搭配，符合句意。"}, {"text": "免费", "is_correct": false, "explanation": "语义：与后句“门票不便宜”矛盾，免费景区不会门票昂贵。"}, {"text": "室内", "is_correct": false, "explanation": "搭配：山不是室内场所，“室内”不能与“风景区”搭配描述山。"}, {"text": "数码", "is_correct": false, "explanation": "语义：“数码”指数字技术，不能用来描述一座山。"}], "explanations": {"国家级": "正确：国家级指全国最高一级，与“风景区”搭配，符合句意。", "免费": "语义：与后句“门票不便宜”矛盾，免费景区不会门票昂贵。", "室内": "搭配：山不是室内场所，“室内”不能与“风景区”搭配描述山。", "数码": "语义：“数码”指数字技术，不能用来描述一座山。"}, "sentence_index": 6, "correct_answer": "国家级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小饭馆是国家级的，只招待附近的老街坊。", "explanation": "这里误用了〈国家级〉，句子把它当作形容店铺名气大、规模大的词。国家级指全国最高一级，只招待街坊的小饭馆不可能达到这种等级，句意矛盾。"}, {"text": "我昨天擦的窗户是国家级的，很亮。", "explanation": "这里误用了〈国家级〉，句子把它当作形容物件洁净明亮的词。国家级指全国最高一级，窗户不能用这种等级来评价。"}, {"text": "这位老人的爱好是国家级的，每天都下棋。", "explanation": "这里误用了〈国家级〉，句子把它当作形容个人爱好深浅、水平高低的词。国家级指全国最高一级，爱好不按全国等级划分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家医院是很国家级的，很多人都知道。", "corrected_sentence": "那家医院是国家级的，很多人都知道。", "error_description": "错误形式：“很国家级”；正确形式：“国家级”。“国家级”是区别词，不能受程度副词“很”修饰，在“是……的”结构中直接说“国家级的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个自然保护区是最国家级的，里面有很多珍贵动物。", "corrected_sentence": "这个自然保护区是国家级的，里面有很多珍贵动物。", "error_description": "错误形式：“最国家级”；正确形式：“国家级”。区别词“国家级”不能受“最”修饰，应在“是……的”结构中直接使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
