INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97642, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "属于国家一级的；全国范围的。", "primary_collocate": null, "pronunciation": "guó jiā jí", "ipa": "kuo˧˥ tɕja˥ tɕi˧˥", "syllable_count": 3, "sentences": [{"text": "这是一次国家级的考试。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天有一个国家级的会议。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目是国家级的，全国都能用。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条新路是国家级工程。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目是国家级的，全国观众都很熟悉它。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加了国家级的比赛。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家今年做了一个国家级的调查。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家级的考试每年夏天举行。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动不是地方级的，是国家级的。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的书得了国家级的奖，全国的人都知道她。", "target_word": "国家级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国家级景区", "label": "复合"}, {"form": "國家級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由国家一级组织或覆盖全国范围的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家级", "is_correct": true, "explanation": "正确：国家级指国家层面、覆盖全国，修饰“考试”符合句意。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：考试不能“甜蜜”，句意不通。"}, {"text": "金属", "is_correct": false, "explanation": "语义：“金属”指材料，不能用来修饰考试。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：考试不能“沙哑”，句意不通。"}], "explanations": {"国家级": "正确：国家级指国家层面、覆盖全国，修饰“考试”符合句意。", "甜蜜": "语义：考试不能“甜蜜”，句意不通。", "金属": "语义：“金属”指材料，不能用来修饰考试。", "沙哑": "语义：考试不能“沙哑”，句意不通。"}, "sentence_index": 0, "correct_answer": "国家级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的小花园是国家级的，每天早上我都在里面浇花。", "explanation": "这里误用了〈国家级〉，句子把它当作形容东西漂亮、心爱的词。国家级指属于国家一级或全国范围，自家的小花园不属于这种层级。"}, {"text": "我家的猫是国家级的，很多人来看它。", "explanation": "这里误用了〈国家级〉，句子把它当作形容动物有名气、人人想看的词。国家级指属于国家一级或全国范围，一只猫并不属于这种层级或范围。"}, {"text": "我家的厨房是国家级的，每天都有人来打扫。", "explanation": "这里误用了〈国家级〉，句子把它当作形容场所高级、受重视的词。国家级指属于国家一级或全国范围，一间家里的厨房不具备这种等级或范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家级", "is_correct": true, "explanation": "正确：国家级指国家层面的等级，修饰“调查”符合句意。"}, {"text": "私立", "is_correct": false, "explanation": "搭配：“私立”多修饰学校、医院，不能修饰调查。"}, {"text": "高速", "is_correct": false, "explanation": "语义：“高速”描述速度，不能用来修饰调查。"}, {"text": "油性", "is_correct": false, "explanation": "语义：“油性”指物质的性质，不能用来修饰调查。"}], "explanations": {"国家级": "正确：国家级指国家层面的等级，修饰“调查”符合句意。", "私立": "搭配：“私立”多修饰学校、医院，不能修饰调查。", "高速": "语义：“高速”描述速度，不能用来修饰调查。", "油性": "语义：“油性”指物质的性质，不能用来修饰调查。"}, "sentence_index": 6, "correct_answer": "国家级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市的牛奶是国家级的，附近的人都在买。", "explanation": "这里误用了〈国家级〉，句子把它当作形容商品品质好、人人抢购的词。国家级指属于国家一级或全国范围，超市的牛奶不具备这种等级或范围。"}, {"text": "我妹妹的好朋友是国家级的，每天一起上学放学。", "explanation": "这里误用了〈国家级〉，句子把它当作形容人能力或名气高的词。国家级指属于国家一级或全国范围，小朋友之间的交情不具备这种等级或范围。"}, {"text": "他的日记得了国家级的奖，只有他自己看过。", "explanation": "这里误用了〈国家级〉，句子把它当作形容奖项含金量高、可以私下珍藏的词。国家级奖项要经过全国范围的评选，只有本人看过的日记不可能获得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校举办了一次国家级地考试。", "corrected_sentence": "学校举办了一次国家级的考试。", "error_description": "错误形式：“国家级地考试”；正确形式：“国家级的考试”。“地”是状语标记，只用于修饰动词，不能修饰名词“考试”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校今年组织了一个最国家级的培训。", "corrected_sentence": "学校今年组织了一个国家级的培训。", "error_description": "错误形式：“最国家级”；正确形式：“国家级”。区别词“国家级”不能受“最”修饰，应直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
