INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在某一职位上任职的期间。", "primary_collocate": null, "pronunciation": "zài rèn", "ipa": "tsai̯˥˩ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "他在任期间，学校盖了新楼。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王市长在任时，每天都很忙。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张在任十年，从来没请过假。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在任的这几年，公司越办越好。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在任时，常常和学生聊天。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在任期间，没有收过别人的礼物。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在任的时候，大家都很放心。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长在任时，修了一条新路。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老书记在任三年，大家都很尊敬他。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在任期间，她每年都去看望老人。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "在任期间", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词：处于某职位任职的期间，常说“在任期间／在任时”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b14a49c-38ec-4108-a99f-c5ec65777d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在任", "is_correct": true, "explanation": "正确：“他在任期间”指他担任职务的时期，符合语境。"}, {"text": "建造", "is_correct": false, "explanation": "配价：“建造”需要带建筑物等宾语，“他建造期间”不能指时段，语义说不通。"}, {"text": "颁布", "is_correct": false, "explanation": "配价：“颁布”的对象是法令、规定，“他颁布期间，学校盖了新楼”语义不通。"}, {"text": "抵押", "is_correct": false, "explanation": "配价：“抵押”需要抵押物作宾语，“他抵押期间”语义不通。"}], "explanations": {"在任": "正确：“他在任期间”指他担任职务的时期，符合语境。", "建造": "配价：“建造”需要带建筑物等宾语，“他建造期间”不能指时段，语义说不通。", "颁布": "配价：“颁布”的对象是法令、规定，“他颁布期间，学校盖了新楼”语义不通。", "抵押": "配价：“抵押”需要抵押物作宾语，“他抵押期间”语义不通。"}, "sentence_index": 0, "correct_answer": "在任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经去世三年，现在仍在任。", "explanation": "这里应该用〈曾任〉。在任表示目前正担任职务，与“已经去世三年”矛盾。"}, {"text": "这台电脑在任，运行得很快。", "explanation": "这里应该用〈运行〉。在任只用于人，表示担任职务，不能指机器的工作状态。"}, {"text": "他明年才正式在任。", "explanation": "这里应该用〈上任〉。在任表示目前正担任职务，不能用于尚未就职的将来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在任", "is_correct": true, "explanation": "正确：“经理在任的时候”指经理担任职务的时候，符合语境。"}, {"text": "殴打", "is_correct": false, "explanation": "配价：“殴打”需要带受事宾语，“经理殴打的时候”说不通；且与“大家都很放心”矛盾。"}, {"text": "寻衅", "is_correct": false, "explanation": "语义：“寻衅”指故意挑衅闹事，与“大家都很放心”的语境不合。"}, {"text": "生气", "is_correct": false, "explanation": "语义：经理生气时“大家都很放心”不成立，语义矛盾。"}], "explanations": {"在任": "正确：“经理在任的时候”指经理担任职务的时候，符合语境。", "殴打": "配价：“殴打”需要带受事宾语，“经理殴打的时候”说不通；且与“大家都很放心”矛盾。", "寻衅": "语义：“寻衅”指故意挑衅闹事，与“大家都很放心”的语境不合。", "生气": "语义：经理生气时“大家都很放心”不成立，语义矛盾。"}, "sentence_index": 6, "correct_answer": "在任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他已经在任，现在没有任何职务。", "explanation": "这里应该用〈辞职〉。在任表示目前正担任职务，与“没有任何职务”矛盾。"}, {"text": "他现在在任，每天在家找工作。", "explanation": "这里应该用〈失业〉。在任表示目前正担任职务，与“在家找工作”矛盾。"}, {"text": "这次比赛他在任了，很沮丧。", "explanation": "这里应该用〈失败〉。在任表示担任职务，不能用于比赛的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在任三年过，学校盖了新楼。", "corrected_sentence": "他在任三年了，学校盖了新楼。", "error_description": "错误形式：“在任三年过”；正确形式：“在任三年了”。表示任职时长并延续到现在，句末用“了”，不用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在任了期间，攒下了不少经验。", "corrected_sentence": "他在任期间，攒下了不少经验。", "error_description": "错误形式：“在任了期间”；正确形式：“在任期间”。“在任”修饰“期间”表示时段，中间不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63f7847-6db1-49aa-9cd1-20743f8d2eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
