INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97650, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "接地线；电器接入大地的导线。", "primary_collocate": null, "pronunciation": "dì xiàn", "ipa": "ti˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "冰箱后面有一根地线。", "target_word": "地线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新买的电视没有接上地线。", "target_word": "地线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器的地线松了。", "target_word": "地线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用一根铜线做地线。", "target_word": "地线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地线要接在金属外壳上。", "target_word": "地线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请先看看插座有没有地线。", "target_word": "地线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的电脑也需要地线。", "target_word": "地线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "师傅给空调装好了地线。", "target_word": "地线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地线是用来保护电器的。", "target_word": "地线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "实验室里每台仪器都连着地线。", "target_word": "地线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根地线", "label": "量词"}, {"form": "地線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电器接入大地的导线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eca7faf1-53e9-4820-92b2-8ca5390197ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地线", "is_correct": true, "explanation": "正确。「冰箱后面有一根地线」中，指的是接入大地的导线。"}, {"text": "天线", "is_correct": false, "explanation": "语义：天线用来收发信号，冰箱后面不需要这样的天线。"}, {"text": "鱼线", "is_correct": false, "explanation": "语义：鱼线属于钓鱼用品，不会出现在冰箱后面。"}, {"text": "鞋带", "is_correct": false, "explanation": "搭配：「冰箱后面有一根鞋带」不成搭配，鞋带不放在冰箱后面。"}], "explanations": {"地线": "正确。「冰箱后面有一根地线」中，指的是接入大地的导线。", "天线": "语义：天线用来收发信号，冰箱后面不需要这样的天线。", "鱼线": "语义：鱼线属于钓鱼用品，不会出现在冰箱后面。", "鞋带": "搭配：「冰箱后面有一根鞋带」不成搭配，鞋带不放在冰箱后面。"}, "sentence_index": 0, "correct_answer": "地线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把地线接在水龙头上，装好后就能浇花了。", "explanation": "这里应该用〈水管〉。地线是导电的线，用来导走漏电；接水龙头、输水浇花要用〈水管〉。"}, {"text": "这根地线直接通到灯泡上，给灯泡供电。", "explanation": "这里应该用〈火线〉。地线的作用是导走漏电，不给用电器供电。"}, {"text": "这根地线是用来钓鱼的，很结实。", "explanation": "这里应该用〈鱼线〉。地线是接地用的导线，不能用来钓鱼；钓鱼要用〈鱼线〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地线", "is_correct": true, "explanation": "正确。「我家的电脑也需要地线」中，电脑需要的是接地的导线。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：「也需要冰箱」不成搭配，电脑并不需要冰箱。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是装饰用品，电脑并不需要它。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是保暖的衣物，与电脑的需要无关。"}], "explanations": {"地线": "正确。「我家的电脑也需要地线」中，电脑需要的是接地的导线。", "冰箱": "搭配：「也需要冰箱」不成搭配，电脑并不需要冰箱。", "花瓶": "语义：花瓶是装饰用品，电脑并不需要它。", "围巾": "语义：围巾是保暖的衣物，与电脑的需要无关。"}, "sentence_index": 6, "correct_answer": "地线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "实验室里每台仪器都连着地线，可以用来存放文件。", "explanation": "这里应该用〈文件柜〉。地线只用于接地防触电，存放文件要用〈文件柜〉。"}, {"text": "实验室里每台仪器都连着地线，用来传送实验结果。", "explanation": "这里应该用〈数据线〉。地线负责导走漏电，不能传送数据；传送实验结果要用〈数据线〉。"}, {"text": "门上的地线很结实，能防止别人进来。", "explanation": "这里应该用〈门锁〉。地线是导电的线，不能用来防盗；防止别人进门要用〈门锁〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冰箱的外壳要接一只地线。", "corrected_sentence": "冰箱的外壳要接一根地线。", "error_description": "量词错误：「地线」应该用量词「根」，写成「一只地线」是把「只」用于导线。「只」用于动物或单个物件，导线要说「一根」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的电脑也需要一只地线。", "corrected_sentence": "我家的电脑也需要一根地线。", "error_description": "量词错误：「地线」应该用量词「根」，写成「一只地线」是把「只」用于导线。「只」用于动物或单个物件，导线要说「一根」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
