INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97657, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉你现在是几点钟。", "primary_collocate": null, "pronunciation": "bào shí", "ipa": "paʊ˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这个钟每到整点就会自动报时。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机可以报时，你不用看屏幕。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的老钟一响就报时，我们都知道几点了。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不方便看表，请你给我报时。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只手表会用中文报时。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲人用的闹钟能说话报时。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一按这个键，它就报时。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前我让音箱报时，已经十一点了。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小闹钟一到时间就用声音报时。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着手表，轻声给大家报时。", "target_word": "报时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报了时", "label": "了体标"}, {"form": "报过时", "label": "过体标"}, {"form": "整点报时", "label": "复合词"}], "register": "中性", "sense_fingerprint": "钟表或人告诉你现在几点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abce999f-3fc1-404e-9d60-5f1209efb4c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报时", "is_correct": true, "explanation": "“报时”指钟表告诉现在几点，“自动报时”描述钟的功能，句意通顺。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：钟不会吃饭，“自动吃饭”与句意不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：钟不会睡觉，“自动睡觉”与句意不符。"}, {"text": "洗衣", "is_correct": false, "explanation": "语义：钟不会洗衣，“自动洗衣”与句意不符。"}], "explanations": {"报时": "“报时”指钟表告诉现在几点，“自动报时”描述钟的功能，句意通顺。", "吃饭": "语义：钟不会吃饭，“自动吃饭”与句意不符。", "睡觉": "语义：钟不会睡觉，“自动睡觉”与句意不符。", "洗衣": "语义：钟不会洗衣，“自动洗衣”与句意不符。"}, "sentence_index": 0, "correct_answer": "报时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新生明天上午来学校报时。", "explanation": "这里应该用〈报到〉。“报时”只指告诉时刻，不能表示到学校登记。"}, {"text": "我想去报时参加比赛。", "explanation": "这里应该用〈报名〉。“报时”只指告诉时刻，不能表示登记参加。"}, {"text": "他发誓一定要报时。", "explanation": "这里应该用〈报仇〉。“报时”只指告诉时刻，不能表示复仇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报时", "is_correct": true, "explanation": "“报时”指告诉现在几点，“它就报时”符合按键后的功能，句意通顺。"}, {"text": "请假", "is_correct": false, "explanation": "语义：设备不会请假，“它就请假”与句意不符。"}, {"text": "挂号", "is_correct": false, "explanation": "语义：“挂号”是在医院办理就诊手续，与按键后的设备无关。"}, {"text": "借钱", "is_correct": false, "explanation": "语义：设备不会借钱，“它就借钱”与按键后的功能不符。"}], "explanations": {"报时": "“报时”指告诉现在几点，“它就报时”符合按键后的功能，句意通顺。", "请假": "语义：设备不会请假，“它就请假”与句意不符。", "挂号": "语义：“挂号”是在医院办理就诊手续，与按键后的设备无关。", "借钱": "语义：设备不会借钱，“它就借钱”与按键后的功能不符。"}, "sentence_index": 6, "correct_answer": "报时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆旧车已经报时了。", "explanation": "这里应该用〈报废〉。“报时”只指告诉时刻，不能表示车辆作废。"}, {"text": "这次出差的车费可以报时。", "explanation": "这里应该用〈报销〉。“报时”只指告诉时刻，不能表示凭单据报销费用。"}, {"text": "他连夜去派出所报时。", "explanation": "这里应该用〈报案〉。“报时”只指告诉时刻，不能表示向警察报告案件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台老钟每到整点就会被报时。", "corrected_sentence": "这台老钟每到整点就会报时。", "error_description": "错误：“报时”前多了“被”。“报时”是不及物动词，不能用“被”构成被动句；这里应直接说“就会报时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你一打开这个开关，它就报着时。", "corrected_sentence": "你一打开这个开关，它就报时。", "error_description": "错误：“报时”后面多了“着”。“报时”是一下子完成的动作，在“一……就……”句里不能加持续体标“着”。正确：你一打开这个开关，它就报时。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
