INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97661, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做了事，别人给你的钱。", "primary_collocate": null, "pronunciation": "bào chou", "ipa": "pɑʊ̯˥˩ ʈʂʰoʊ̯", "syllable_count": 2, "sentences": [{"text": "他帮我搬家，我给了他一笔报酬。", "target_word": "报酬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作的报酬很不错。", "target_word": "报酬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "干活就应该拿到报酬。", "target_word": "报酬", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她给邻居看孩子，每天有报酬。", "target_word": "报酬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不要报酬，只想帮帮忙。", "target_word": "报酬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友帮我设计网页，我想付他报酬。", "target_word": "报酬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完这件事，你能得到多少报酬？", "target_word": "报酬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板按时给了我报酬。", "target_word": "报酬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个活儿很累，报酬却很少。", "target_word": "报酬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着报酬，高兴地回家了。", "target_word": "报酬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔报酬", "label": "量词"}, {"form": "一份报酬", "label": "量词"}, {"form": "劳动报酬", "label": "复合"}, {"form": "報酬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "帮别人做事之后得到的钱，如帮忙搬家的报酬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26884cc9-df6b-4baa-9d09-a978904c3385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报酬", "is_correct": true, "explanation": "正确：他帮忙搬家后给的是钱，“一笔”修饰的是钱，用“报酬”。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“一笔”是金额量词，不能修饰礼物。"}, {"text": "谢意", "is_correct": false, "explanation": "语义：谢意是情感上的感激，不是钱，不能“给”一笔。"}, {"text": "恩情", "is_correct": false, "explanation": "语义：恩情是情感上的回报，不是钱，不能“给”一笔。"}], "explanations": {"报酬": "正确：他帮忙搬家后给的是钱，“一笔”修饰的是钱，用“报酬”。", "礼物": "搭配：“一笔”是金额量词，不能修饰礼物。", "谢意": "语义：谢意是情感上的感激，不是钱，不能“给”一笔。", "恩情": "语义：恩情是情感上的回报，不是钱，不能“给”一笔。"}, "sentence_index": 0, "correct_answer": "报酬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每年要交一笔报酬给学校。", "explanation": "这里应该用〈学费〉。报酬指为劳动付出所得的钱，交给学校的费用应说〈学费〉。"}, {"text": "朋友送给我一份报酬，祝我生日快乐。", "explanation": "这里应该用〈礼物〉。报酬指劳动所得，朋友送的生日礼物不说报酬。"}, {"text": "他因为闯红灯，被交警罚了一笔报酬。", "explanation": "这里应该用〈罚款〉。报酬是劳动所得，被罚的钱应说〈罚款〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报酬", "is_correct": true, "explanation": "正确：“得到多少”后接的是工作的回报，用“报酬”。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“得到”不与“温度”搭配，温度不是做事的回报。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不能通过做事“得到”，句意不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“得到多少寿命”不是常见说法，寿命不是做事后的回报。"}], "explanations": {"报酬": "正确：“得到多少”后接的是工作的回报，用“报酬”。", "温度": "搭配：“得到”不与“温度”搭配，温度不是做事的回报。", "体重": "语义：体重不能通过做事“得到”，句意不通。", "寿命": "搭配：“得到多少寿命”不是常见说法，寿命不是做事后的回报。"}, "sentence_index": 6, "correct_answer": "报酬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父亲去世后，留给我们一笔报酬。", "explanation": "这里应该用〈遗产〉。报酬指劳动所得，留下的财产应说〈遗产〉。"}, {"text": "他因为弄坏了邻居的车，赔了一笔报酬。", "explanation": "这里应该用〈赔偿〉。报酬是劳动所得，弄坏别人东西后付的钱应说〈赔偿〉。"}, {"text": "父母每个月给我一笔报酬，让我安心读书。", "explanation": "这里应该用〈生活费〉。报酬指为做事而得的钱，父母每月给孩子的钱应说〈生活费〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她得到了一只报酬。", "corrected_sentence": "她得到了一份报酬。", "error_description": "量词用错。报酬是钱物，常用“笔”或“份”，“只”多用于动物或单个物件，不能用来修饰报酬。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天了给他一笔报酬。", "corrected_sentence": "我昨天给了他一笔报酬。", "error_description": "“了”放在动词“给”之前，位置错误。体标“了”应紧跟动词之后，应说“给了他一笔报酬”，不能放在“给”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
