INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因付出劳动而得到的钱物。", "primary_collocate": null, "pronunciation": "bào chou", "ipa": "pɑʊ̯˥˩ ʈʂʰoʊ̯", "syllable_count": 2, "sentences": [{"text": "工人应该得到合理的报酬。", "target_word": "报酬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同样的工作，应该有同样的报酬。", "target_word": "报酬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按合同支付了报酬。", "target_word": "报酬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作很辛苦，报酬却不高。", "target_word": "报酬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者做事不求报酬。", "target_word": "报酬", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "报酬可以是钱，也可以是东西。", "target_word": "报酬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "努力工作就会有好的报酬。", "target_word": "报酬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的员工报酬很高。", "target_word": "报酬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她工作了一个月，拿到了报酬。", "target_word": "报酬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂提高了工人的报酬。", "target_word": "报酬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份报酬", "label": "量词"}, {"form": "一笔报酬", "label": "量词"}, {"form": "劳动报酬", "label": "复合"}, {"form": "報酬", "label": "繁体"}], "register": "书面", "sense_fingerprint": "劳动所得的钱或物，多指工资、酬劳等正式的回报", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26884cc9-df6b-4baa-9d09-a978904c3385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报酬", "is_correct": true, "explanation": "正确：“合理的”修饰劳动所得的回报，用“报酬”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：工人不能“得到”颜色，句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“合理”不修饰脾气，且“得到”也不与“脾气”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是工人劳动后能得到的东西，句意不通。"}], "explanations": {"报酬": "正确：“合理的”修饰劳动所得的回报，用“报酬”。", "颜色": "语义：工人不能“得到”颜色，句意不通。", "脾气": "搭配：“合理”不修饰脾气，且“得到”也不与“脾气”搭配。", "天气": "语义：天气不是工人劳动后能得到的东西，句意不通。"}, "sentence_index": 0, "correct_answer": "报酬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房东要求我先交一笔报酬。", "explanation": "这里应该用〈押金〉。报酬指劳动所得，房东要求交的租房费用应说〈押金〉。"}, {"text": "朋友结婚，我包了一笔报酬。", "explanation": "这里应该用〈礼金〉。报酬指劳动所得，随礼的钱应说〈礼金〉。"}, {"text": "他因为违章停车，被罚了一笔报酬。", "explanation": "这里应该用〈罚款〉。报酬指劳动所得，违章被罚的钱应说〈罚款〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报酬", "is_correct": true, "explanation": "正确：“努力工作”带来的回报，用“报酬”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：努力工作不能带来体温，句意不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“有好的寿命”不是常见说法，寿命不由工作“有”来。"}, {"text": "病情", "is_correct": false, "explanation": "语义：病情不能靠努力工作得到，句意不通。"}], "explanations": {"报酬": "正确：“努力工作”带来的回报，用“报酬”。", "体温": "语义：努力工作不能带来体温，句意不通。", "寿命": "搭配：“有好的寿命”不是常见说法，寿命不由工作“有”来。", "病情": "语义：病情不能靠努力工作得到，句意不通。"}, "sentence_index": 6, "correct_answer": "报酬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为弄坏了邻居的车，赔了一笔报酬。", "explanation": "这里应该用〈赔偿〉。报酬是劳动所得，弄坏别人东西后付的钱应说〈赔偿〉。"}, {"text": "我在超市买东西，付了一笔报酬。", "explanation": "这里应该用〈货款〉。报酬指劳动所得，购物所付的钱应说〈货款〉。"}, {"text": "毕业时，父母送了我一笔报酬作为礼物。", "explanation": "这里应该用〈红包〉。报酬指为劳动付出所得的钱，父母送的毕业钱属于馈赠，应说〈红包〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人得到了一只报酬。", "corrected_sentence": "工人得到了一份报酬。", "error_description": "量词用错。报酬是钱物，常用“笔”或“份”，“只”多用于动物或单个物件，不能用来修饰报酬。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司昨天支付着报酬。", "corrected_sentence": "公司昨天支付了报酬。", "error_description": "体标用错。表示昨天已经完成的动作要用“了”，“着”表示动作正在持续，不能说“支付着报酬”。应说“支付了报酬”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97666, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减少", "is_correct": true, "explanation": "减少与“增多”构成反义，都指数量的变化，“减少”指数量比原来少。"}, {"text": "出现", "is_correct": false, "explanation": "“出现”指事物显露或产生，与数量变化无关，不是“增多”的反义词。"}, {"text": "扩大", "is_correct": false, "explanation": "“扩大”指范围或规模变大，是相近的说法，不是“增多”的反义词。"}, {"text": "集中", "is_correct": false, "explanation": "“集中”指聚在一处，不表示数量的增减。"}], "correct_answer": "减少", "explanations": {"减少": "减少与“增多”构成反义，都指数量的变化，“减少”指数量比原来少。", "出现": "“出现”指事物显露或产生，与数量变化无关，不是“增多”的反义词。", "扩大": "“扩大”指范围或规模变大，是相近的说法，不是“增多”的反义词。", "集中": "“集中”指聚在一处，不表示数量的增减。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97666, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减少", "is_correct": true, "explanation": "减少与“增多”构成反义，都指数量的变化，“减少”指数量比原来少。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指维持原样，不表示数量变化。"}, {"text": "消失", "is_correct": false, "explanation": "“消失”指不见了，不是“增多”的反义词。"}, {"text": "停留", "is_correct": false, "explanation": "“停留”指暂时待在某处，与数量变化无关。"}], "correct_answer": "减少", "explanations": {"减少": "减少与“增多”构成反义，都指数量的变化，“减少”指数量比原来少。", "保持": "“保持”指维持原样，不表示数量变化。", "消失": "“消失”指不见了，不是“增多”的反义词。", "停留": "“停留”指暂时待在某处，与数量变化无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "数量比原来多。", "primary_collocate": null, "pronunciation": "zēng duō", "ipa": "tsəŋ˥ twɔ˥", "syllable_count": 2, "sentences": [{"text": "这几年城里的汽车增多了。", "target_word": "增多", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天蚊子会增多。", "target_word": "增多", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨后，河里的水增多了。", "target_word": "增多", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班的学生增多，教室不够用了。", "target_word": "增多", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天感冒的人会增多。", "target_word": "增多", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园里的游客明显增多。", "target_word": "增多", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "最近三个月，来店里的客人增多了不少。", "target_word": "增多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的病人一直在增多。", "target_word": "增多", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的人口增多，房子也越来越贵。", "target_word": "增多", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他发现书架上的书增多了。", "target_word": "增多", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "增多了", "label": "体标"}, {"form": "增多过", "label": "体标"}], "register": "中性", "sense_fingerprint": "数量比原来多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0aef20-8c93-4b94-980b-ea0ce9cddfeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增多", "is_correct": true, "explanation": "正确：增多指数量比原来多，与“城里的汽车”的数量变化相符。"}, {"text": "长高", "is_correct": false, "explanation": "搭配：“长高”说人或植物的身高，不能用于汽车。"}, {"text": "变胖", "is_correct": false, "explanation": "搭配：“变胖”只用于人或动物的体形，汽车不能变胖。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”指身体不适，与汽车无关。"}], "explanations": {"增多": "正确：增多指数量比原来多，与“城里的汽车”的数量变化相符。", "长高": "搭配：“长高”说人或植物的身高，不能用于汽车。", "变胖": "搭配：“变胖”只用于人或动物的体形，汽车不能变胖。", "生病": "语义：“生病”指身体不适，与汽车无关。"}, "sentence_index": 0, "correct_answer": "增多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的汉语水平增多了。", "explanation": "这里应该用〈提高〉。“增多”说数量变多，“水平”属于质量，应说“提高”。"}, {"text": "今年经济增多了百分之五。", "explanation": "这里应该用〈增长〉。“增多”用于数量的增加，经济的变化应说“增长”。"}, {"text": "他的信心增多了。", "explanation": "这里应该用〈增加〉。“增多”用于可数的数量，“信心”是抽象的心理状态，应说“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增多", "is_correct": true, "explanation": "正确：增多指数量比原来多，“客人”的数量增加，与“了不少”相符。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属表面氧化，与“客人”不符。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化”用于冰雪等物体，不用于人。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”一般用于植物，不能用于客人。"}], "explanations": {"增多": "正确：增多指数量比原来多，“客人”的数量增加，与“了不少”相符。", "生锈": "语义：“生锈”指金属表面氧化，与“客人”不符。", "融化": "搭配：“融化”用于冰雪等物体，不用于人。", "发芽": "搭配：“发芽”一般用于植物，不能用于客人。"}, "sentence_index": 6, "correct_answer": "增多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯为房间增多了温馨的气氛。", "explanation": "这里应该用〈增添〉。“增多”说数量变多，“气氛”是抽象的感受，应说“增添”。"}, {"text": "他的体力增多了不少。", "explanation": "这里应该用〈增强〉。“增多”用于数量，“体力”是身体的能力，应说“增强”。"}, {"text": "最近的菜价增多了。", "explanation": "这里应该用〈上升〉。“增多”用于数量，“菜价”的变化应说“上升”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近城里的汽车增多的很快。", "corrected_sentence": "最近城里的汽车增多得很快。", "error_description": "错误：“增多的很快”；正确：“增多得很快”。补语要用“得”连接动词和补语，“的”用于修饰名词，不能用来连接动词“增多”与补语“很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个季节去那家餐厅的人很增多了。", "corrected_sentence": "这个季节去那家餐厅的人明显增多了。", "error_description": "错误：“很增多了”；正确：“明显增多了”。“很”是程度副词，不能修饰动词“增多”，此处应用“明显”作状语修饰“增多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
