INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97669, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或东西能活或用多久。", "primary_collocate": null, "pronunciation": "shòu mìng", "ipa": "ʂoʊ˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生说爷爷的寿命还很长，不用太担心。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的寿命不长，穿了半年就坏了。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的动物，寿命差别很大。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠的寿命只有两三年。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的习惯可以延长人的寿命。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的寿命还有很多年。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫的寿命一般有十几年。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的寿命很短，三天就谢了。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道这台电脑的寿命有多长。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保持运动，对健康和寿命都有好处。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均寿命", "label": "复合"}, {"form": "使用寿命", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或东西能活多久、能用多久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寿命", "is_correct": true, "explanation": "正确。“医生说爷爷的寿命还很长”指爷爷还能活很久。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指轻重，不能用“还很长”来形容。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，不能用“长”来形容。"}, {"text": "表情", "is_correct": false, "explanation": "搭配：“表情”不能跟“还很长”搭配，“长”不修饰表情。"}], "explanations": {"寿命": "正确。“医生说爷爷的寿命还很长”指爷爷还能活很久。", "体重": "语义：“体重”指轻重，不能用“还很长”来形容。", "体温": "语义：“体温”指身体的温度，不能用“长”来形容。", "表情": "搭配：“表情”不能跟“还很长”搭配，“长”不修饰表情。"}, "sentence_index": 0, "correct_answer": "寿命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵老树寿命很大，已经有上千岁了。", "explanation": "这里应该用〈年龄〉。寿命说的是能活多久，树有多少岁要说“年龄”，“寿命很大”也不符合习惯。"}, {"text": "寿命似箭，转眼就到了年底。", "explanation": "这里应该用〈光阴〉。寿命指生存的年限，不能用来比喻时间飞快流逝。"}, {"text": "这次旅行的寿命很短，我们玩得很开心。", "explanation": "这里应该用〈时间〉。寿命用于人、动物或物品，旅行的长短要说“时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寿命", "is_correct": true, "explanation": "正确。“猫的寿命一般有十几年”指猫能活十几年。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”不能用“有十几年”来计算。"}, {"text": "叫声", "is_correct": false, "explanation": "语义：“叫声”没有“十几年”的长短，句子说不通。"}, {"text": "毛色", "is_correct": false, "explanation": "搭配：“毛色”不用年数来说，不能跟“有十几年”搭配。"}], "explanations": {"寿命": "正确。“猫的寿命一般有十几年”指猫能活十几年。", "脚步": "语义：“脚步”不能用“有十几年”来计算。", "叫声": "语义：“叫声”没有“十几年”的长短，句子说不通。", "毛色": "搭配：“毛色”不用年数来说，不能跟“有十几年”搭配。"}, "sentence_index": 6, "correct_answer": "寿命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同的寿命是三年，到期就要续签。", "explanation": "这里应该用〈期限〉。寿命多指人、动物或物品能活或能用多久，合同的时限要说“期限”。"}, {"text": "他一天到晚都有寿命，从来不觉得累。", "explanation": "这里应该用〈精力〉。寿命只说能活多久，形容人充沛的劲头要说“精力”。"}, {"text": "他搬起一块大石头，寿命很大。", "explanation": "这里应该用〈力气〉。寿命指年限，形容力量大小要说“力气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台冰箱的寿命那台长。", "corrected_sentence": "这台冰箱的寿命比那台长。", "error_description": "比较句要用“比”引出比较的对象，应说“寿命比那台长”，不能省去“比”说“寿命那台长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只猫的寿命长很。", "corrected_sentence": "这只猫的寿命很长。", "error_description": "程度副词“很”要放在形容词“长”前面，应说“寿命很长”，不能说“寿命长很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
