INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物生存的年限；物品可使用的期限。", "primary_collocate": null, "pronunciation": "shòu mìng", "ipa": "ʂoʊ˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "乌龟的寿命比很多动物都长。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手机电池的寿命只有两年。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着医学进步，人的平均寿命越来越长。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶的寿命很短，只能活几天。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常保养，可以延长机器的寿命。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵老树的寿命已经超过一千年了。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯泡的寿命一般是几千个小时。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的寿命大约有七十年。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好使用，这台冰箱的寿命会更长。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的寿命不会太长了。", "target_word": "寿命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均寿命", "label": "复合"}, {"form": "使用寿命", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物生存或物品使用的年限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寿命", "is_correct": true, "explanation": "正确。“寿命”指能活多久，“乌龟的寿命比很多动物都长”说的是乌龟能活的年限。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指轻重，不能用“长”来比较。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“力气”不能跟“长”搭配，“长”只用于时间或长度。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不指时间的长短，“比很多动物都长”说不通。"}], "explanations": {"寿命": "正确。“寿命”指能活多久，“乌龟的寿命比很多动物都长”说的是乌龟能活的年限。", "体重": "语义：“体重”指轻重，不能用“长”来比较。", "力气": "搭配：“力气”不能跟“长”搭配，“长”只用于时间或长度。", "声音": "语义：“声音”不指时间的长短，“比很多动物都长”说不通。"}, "sentence_index": 0, "correct_answer": "寿命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷今年八十岁，他的寿命已经很大了。", "explanation": "这里应该用〈年龄〉。寿命指能活多久，说人的岁数要用“年龄”，“寿命很大”也不符合习惯。"}, {"text": "他在战场上失去了寿命。", "explanation": "这里应该用〈生命〉。寿命指能活多久，失去的应是“生命”。"}, {"text": "今天是奶奶的寿命，我们一起吃了蛋糕。", "explanation": "这里应该用〈寿辰〉。寿命指年限，庆祝生日要说“寿辰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寿命", "is_correct": true, "explanation": "正确。“灯泡的寿命一般是几千个小时”说的是灯泡能用多久。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：“亮度”指明暗程度，不能用“几千个小时”来表示。"}, {"text": "功率", "is_correct": false, "explanation": "语义：“功率”指做功的快慢，不是用时间来计算的年限。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般用元来计算，不能说“是几千个小时”。"}], "explanations": {"寿命": "正确。“灯泡的寿命一般是几千个小时”说的是灯泡能用多久。", "亮度": "语义：“亮度”指明暗程度，不能用“几千个小时”来表示。", "功率": "语义：“功率”指做功的快慢，不是用时间来计算的年限。", "价格": "搭配：“价格”一般用元来计算，不能说“是几千个小时”。"}, "sentence_index": 6, "correct_answer": "寿命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种植物的寿命很强，风吹雨打都能活下来。", "explanation": "这里应该用〈生命力〉。寿命指能活多久，形容生存的顽强要说“生命力”。"}, {"text": "村里的寿命很多，每年都要办宴会。", "explanation": "这里应该用〈寿星〉。寿命指年限，说年纪大的人要用“寿星”。"}, {"text": "他在工作中度过了美好的寿命。", "explanation": "这里应该用〈岁月〉。寿命指生存的年限，不能说“度过美好的寿命”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药能让人的寿命长更。", "corrected_sentence": "这种药能让人的寿命更长。", "error_description": "“更”是程度副词，要放在形容词“长”前面，应说“寿命更长”，不能放在“长”后面说“长更”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吸烟会缩寿命。", "corrected_sentence": "吸烟会缩短寿命。", "error_description": "“缩寿命”不是固定说法，表示寿命变短应说“缩短寿命”，不能只说“缩寿命”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
