INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97673, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "给人看病的人，口语中对医生的称呼。", "primary_collocate": null, "pronunciation": "dài fu", "ipa": "tai˥˩ fu", "syllable_count": 2, "sentences": [{"text": "大夫说我得多休息。", "target_word": "大夫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我头疼，想去看大夫。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王大夫今天不在医院。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大夫给奶奶开了一些药。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明发烧了，妈妈带他去找大夫。", "target_word": "大夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大夫很有经验，病人都喜欢他。", "target_word": "大夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大夫让他每天早上喝水。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "您先坐下，大夫马上来。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的爸爸是一位好大夫。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大夫看了看我的嗓子，说没有大问题。", "target_word": "大夫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语里对医生的称呼，给人看病的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大夫", "is_correct": true, "explanation": "正确：“大夫说我得多休息”，指给人看病的医生，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会说话，不能“说我得多休息”，句子不通。"}, {"text": "药片", "is_correct": false, "explanation": "配价：“说”需要能说话的施事，药片不能作“说”的主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会对人提出建议，“天气说我得多休息”不合逻辑。"}], "explanations": {"大夫": "正确：“大夫说我得多休息”，指给人看病的医生，符合句意。", "椅子": "语义：椅子不会说话，不能“说我得多休息”，句子不通。", "药片": "配价：“说”需要能说话的施事，药片不能作“说”的主语。", "天气": "语义：天气不会对人提出建议，“天气说我得多休息”不合逻辑。"}, "sentence_index": 0, "correct_answer": "大夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的大夫是李老师，他每天教我们英语。", "explanation": "这里把〈大夫〉用成了〈教师〉。〈大夫〉指给人看病的医生，不指教书的人。"}, {"text": "他每天在田里当大夫，负责插秧。", "explanation": "这里把〈大夫〉用成了〈农民〉。〈大夫〉指给人看病的医生，插秧的人不叫大夫。"}, {"text": "李大夫在厨房里做菜。", "explanation": "这里把〈大夫〉用成了〈厨师〉。〈大夫〉指给人看病的医生，做菜的人要说〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大夫", "is_correct": true, "explanation": "正确：“大夫让他每天早上喝水”，指给人看病的医生，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会对人提出要求，也不能让人喝水，句子不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会提出要求，“窗户让他每天早上喝水”不合逻辑。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭不能对人下达喝水的要求，句子不通。"}], "explanations": {"大夫": "正确：“大夫让他每天早上喝水”，指给人看病的医生，符合句意。", "石头": "语义：石头不会对人提出要求，也不能让人喝水，句子不通。", "窗户": "语义：窗户不会提出要求，“窗户让他每天早上喝水”不合逻辑。", "早饭": "语义：早饭不能对人下达喝水的要求，句子不通。"}, "sentence_index": 6, "correct_answer": "大夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在建筑工地当大夫，负责砌墙。", "explanation": "这里把〈大夫〉用成了〈泥瓦工〉。〈大夫〉指给人看病的医生，砌墙的人不叫大夫。"}, {"text": "这个大夫每天在法庭上为被告辩护。", "explanation": "辩护的人是〈律师〉。〈大夫〉指给人看病的医生，不指律师。"}, {"text": "这位大夫每天开车送客人去机场。", "explanation": "这里把〈大夫〉用成了〈司机〉。〈大夫〉指给人看病的医生，开车送人的人要说〈司机〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村只有一只大夫。", "corrected_sentence": "我们村只有一位大夫。", "error_description": "错误形式：“一只大夫”。正确形式：“一位大夫”。指人的量词要用“位”，“只”多用于动物或小物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们村有两大夫。", "corrected_sentence": "我们村有两位大夫。", "error_description": "错误形式：“两大夫”。正确形式：“两位大夫”。数词和“大夫”之间需要量词，指人一般用“位”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
