INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97674, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "医生的旧称，口语中仍常用。", "primary_collocate": null, "pronunciation": "dài fu", "ipa": "tai˥˩ fu", "syllable_count": 2, "sentences": [{"text": "以前的人生病了，要请大夫来家里。", "target_word": "大夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老大夫八十岁了，还在给人看病。", "target_word": "大夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大夫的手很轻，孩子不怕他。", "target_word": "大夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的腿疼，最好问问大夫。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大夫在桌子旁边写药方。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "李大夫说他的病已经好了。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们村里只有一位大夫。", "target_word": "大夫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大夫笑着对病人说：“别怕。”", "target_word": "大夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶总是听大夫的话，按时吃药。", "target_word": "大夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想长大后当大夫，帮助别人。", "target_word": "大夫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "医生的旧称，日常口语里仍常用来称呼医生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大夫", "is_correct": true, "explanation": "正确：“要请大夫来家里”，指请医生来家里看病，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能被请来家里看病，句子不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能被请来家里看病，句子不通。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“请”搭配的是能来看病的人，汽车不能“请来家里”看病。"}], "explanations": {"大夫": "正确：“要请大夫来家里”，指请医生来家里看病，符合句意。", "手机": "语义：手机不能被请来家里看病，句子不通。", "电脑": "语义：电脑不能被请来家里看病，句子不通。", "汽车": "搭配：“请”搭配的是能来看病的人，汽车不能“请来家里”看病。"}, "sentence_index": 0, "correct_answer": "大夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在工厂当大夫，负责组装汽车。", "explanation": "这里把〈大夫〉用成了〈工人〉。〈大夫〉指给人看病的医生，组装汽车的人不叫大夫。"}, {"text": "王大夫在厨房里做菜。", "explanation": "这里把〈大夫〉用成了〈厨师〉。〈大夫〉指给人看病的医生，做菜的人要说〈厨师〉。"}, {"text": "李大夫在法庭上为被告辩护。", "explanation": "辩护的人是〈律师〉。〈大夫〉指给人看病的医生，不指律师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大夫", "is_correct": true, "explanation": "正确：“我们村里只有一位大夫”，指一位医生，符合句意。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是地方，不能用“位”来计数，句子不通。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：医院一般用“家”来计数，不能用“位”。"}, {"text": "诊所", "is_correct": false, "explanation": "搭配：诊所一般用“家”来计数，不能用“位”。"}], "explanations": {"大夫": "正确：“我们村里只有一位大夫”，指一位医生，符合句意。", "学校": "语义：学校是地方，不能用“位”来计数，句子不通。", "医院": "搭配：医院一般用“家”来计数，不能用“位”。", "诊所": "搭配：诊所一般用“家”来计数，不能用“位”。"}, "sentence_index": 6, "correct_answer": "大夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在食堂当大夫，负责打饭。", "explanation": "这里把〈大夫〉用成了〈服务员〉。〈大夫〉指给人看病的医生，打饭的人不叫大夫。"}, {"text": "他每天在超市当大夫，负责收银。", "explanation": "这里把〈大夫〉用成了〈收银员〉。〈大夫〉指给人看病的医生，收银的人不叫大夫。"}, {"text": "这位大夫每天在邮局给大家送信。", "explanation": "这里把〈大夫〉用成了〈邮递员〉。〈大夫〉指给人看病的医生，送信的人要说〈邮递员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "以前村里没有医院，病人要请一只大夫来家里看病。", "corrected_sentence": "以前村里没有医院，病人要请一位大夫来家里看病。", "error_description": "错误形式：“一只大夫”。正确形式：“一位大夫”。指人的量词要用“位”，“只”多用于动物或小物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
