INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97677, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "警察觉得可能做了坏事的人。", "primary_collocate": null, "pronunciation": "xián fàn", "ipa": "ɕjɛn˧˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "警察今天抓到了那个嫌犯。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "嫌犯一直不说话。", "target_word": "嫌犯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察把嫌犯带回了警察局。", "target_word": "嫌犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个嫌犯看起来很害怕。", "target_word": "嫌犯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察正在问嫌犯一些问题。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "嫌犯说他昨晚没有出过门。", "target_word": "嫌犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察觉得这个嫌犯在说谎。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有一名嫌犯从房子后门跑了。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察在路边看见了嫌犯的车。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "嫌犯戴着帽子，警察看不清他的脸。", "target_word": "嫌犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "警察认为可能做了坏事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0aef20-8c93-4b94-980b-ea0ce9cddfeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97677, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嫌犯", "is_correct": true, "explanation": "嫌犯 xián fàn：警察觉得可能做了坏事的人，即本题的词。"}, {"text": "掀翻", "is_correct": false, "explanation": "掀翻 xiān fān 与 嫌犯 xián fàn 两个音节的声调都不同，意思是把东西翻倒。"}, {"text": "相反", "is_correct": false, "explanation": "相反 xiāng fǎn 与 嫌犯 xián fàn 第一个音节韵母不同（-ang 与 -an），第二个音节声调也不同（第三声与第四声），意思是对立、不一样。"}, {"text": "嫌烦", "is_correct": false, "explanation": "嫌烦 xián fán 与 嫌犯 xián fàn 第二个音节声调不同（第二声与第四声），意思是厌烦。"}], "explanations": {"嫌犯": "嫌犯 xián fàn：警察觉得可能做了坏事的人，即本题的词。", "掀翻": "掀翻 xiān fān 与 嫌犯 xián fàn 两个音节的声调都不同，意思是把东西翻倒。", "相反": "相反 xiāng fǎn 与 嫌犯 xián fàn 第一个音节韵母不同（-ang 与 -an），第二个音节声调也不同（第三声与第四声），意思是对立、不一样。", "嫌烦": "嫌烦 xián fán 与 嫌犯 xián fàn 第二个音节声调不同（第二声与第四声），意思是厌烦。"}, "sentence_index": null, "correct_answer": "嫌犯"}, "level_3": {"options": [{"text": "嫌犯", "is_correct": true, "explanation": "嫌犯：被警察抓获、怀疑做了坏事的人，符合句意。"}, {"text": "证人", "is_correct": false, "explanation": "语义：证人是提供证词的人，不是被警察抓捕的对象。"}, {"text": "受害人", "is_correct": false, "explanation": "语义：受害人是遭受损失的一方，不会被警察抓到。"}, {"text": "仙女", "is_correct": false, "explanation": "语义：仙女是虚构人物，不会被警察抓到，句意不通。"}], "explanations": {"嫌犯": "嫌犯：被警察抓获、怀疑做了坏事的人，符合句意。", "证人": "语义：证人是提供证词的人，不是被警察抓捕的对象。", "受害人": "语义：受害人是遭受损失的一方，不会被警察抓到。", "仙女": "语义：仙女是虚构人物，不会被警察抓到，句意不通。"}, "sentence_index": 0, "correct_answer": "嫌犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个嫌犯正在为一名被告辩护。", "explanation": "这里应该用〈律师〉。“嫌犯”指被怀疑做了坏事的人，不能替被告辩护；辩护的是律师。"}, {"text": "那个嫌犯已经服刑三年了。", "explanation": "这里应该用〈罪犯〉。“嫌犯”只是被怀疑、尚未定罪，“服刑”只用于已经判刑的罪犯。"}, {"text": "那个嫌犯戴着帽子，正在调查案件。", "explanation": "这里应该用〈警察〉。“嫌犯”是被怀疑的人，不负责调查案件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嫌犯", "is_correct": true, "explanation": "嫌犯：警察怀疑的对象，符合句意。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会说谎，与“在说谎”的主体不符。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶没有心智，不会说谎。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不会说谎，也不会是警察怀疑的对象。"}], "explanations": {"嫌犯": "嫌犯：警察怀疑的对象，符合句意。", "婴儿": "语义：婴儿不会说谎，与“在说谎”的主体不符。", "花瓶": "语义：花瓶没有心智，不会说谎。", "小狗": "语义：小狗是动物，不会说谎，也不会是警察怀疑的对象。"}, "sentence_index": 6, "correct_answer": "嫌犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个嫌犯在法庭上宣布了判决结果。", "explanation": "这里应该用〈法官〉。“嫌犯”指被怀疑做了坏事的人，宣布判决结果的是法官。"}, {"text": "那个嫌犯昨天在法庭上提出了公诉。", "explanation": "这里应该用〈检察官〉。“嫌犯”只是被怀疑的人，提出公诉的是检察官。"}, {"text": "那个嫌犯每周都为学生做心理咨询。", "explanation": "这里应该用〈心理医生〉。“嫌犯”指被怀疑做了坏事的人，不能为学生做心理咨询。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察昨天审问了一只嫌犯。", "corrected_sentence": "警察昨天审问了一名嫌犯。", "error_description": "量词错误：“嫌犯”指人，量词应用“名”，不能用“只”（“只”多用于动物）。正确说法是「一名嫌犯」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察终于抓住了那张嫌犯。", "corrected_sentence": "警察终于抓住了那名嫌犯。", "error_description": "量词错误：“嫌犯”指人，量词应用“名”，不能用“张”（“张”多用于平面的东西）。正确说法是「那名嫌犯」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
