INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "涉嫌犯罪的人。", "primary_collocate": null, "pronunciation": "xián fàn", "ipa": "ɕjɛn˧˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "这起案子有两名嫌犯。", "target_word": "嫌犯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "检方指控嫌犯盗窃了银行的钱。", "target_word": "嫌犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院还没有判嫌犯有罪。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两名嫌犯都已经到案。", "target_word": "嫌犯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "嫌犯的律师说他是无辜的。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者在门口拍到了嫌犯。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "嫌犯涉嫌诈骗，案子还在调查。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这名嫌犯曾经做过出租车司机。", "target_word": "嫌犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说，嫌犯已经向警方投案。", "target_word": "嫌犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "嫌犯的家人每天都去法院门口等着。", "target_word": "嫌犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "涉嫌犯罪的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0aef20-8c93-4b94-980b-ea0ce9cddfeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97678, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嫌犯", "is_correct": true, "explanation": "嫌犯 xián fàn：涉嫌犯罪的人，即本题的词。"}, {"text": "掀翻", "is_correct": false, "explanation": "掀翻 xiān fān 与 嫌犯 xián fàn 两个音节的声调都不同，意思是把东西翻倒。"}, {"text": "相反", "is_correct": false, "explanation": "相反 xiāng fǎn 与 嫌犯 xián fàn 第一个音节韵母不同（-ang 与 -an），第二个音节声调也不同（第三声与第四声），意思是对立、不一样。"}, {"text": "嫌烦", "is_correct": false, "explanation": "嫌烦 xián fán 与 嫌犯 xián fàn 第二个音节声调不同（第二声与第四声），意思是厌烦。"}], "explanations": {"嫌犯": "嫌犯 xián fàn：涉嫌犯罪的人，即本题的词。", "掀翻": "掀翻 xiān fān 与 嫌犯 xián fàn 两个音节的声调都不同，意思是把东西翻倒。", "相反": "相反 xiāng fǎn 与 嫌犯 xián fàn 第一个音节韵母不同（-ang 与 -an），第二个音节声调也不同（第三声与第四声），意思是对立、不一样。", "嫌烦": "嫌烦 xián fán 与 嫌犯 xián fàn 第二个音节声调不同（第二声与第四声），意思是厌烦。"}, "sentence_index": null, "correct_answer": "嫌犯"}, "level_3": {"options": [{"text": "嫌犯", "is_correct": true, "explanation": "嫌犯：涉嫌犯罪的人，符合句意。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不可能涉及此类案件，与句意不符。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使是虚构的，不会涉及真实案件。"}, {"text": "神仙", "is_correct": false, "explanation": "语义：神仙是虚构人物，与真实案件无关，句意不通。"}], "explanations": {"嫌犯": "嫌犯：涉嫌犯罪的人，符合句意。", "婴儿": "语义：婴儿不可能涉及此类案件，与句意不符。", "天使": "语义：天使是虚构的，不会涉及真实案件。", "神仙": "语义：神仙是虚构人物，与真实案件无关，句意不通。"}, "sentence_index": 0, "correct_answer": "嫌犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那名嫌犯在法庭上负责记录庭审内容。", "explanation": "这里应该用〈书记员〉。“嫌犯”指涉嫌犯罪的人，不能负责记录庭审内容；担任这项工作的是书记员。"}, {"text": "那名嫌犯在案发现场替警方收集证据。", "explanation": "这里应该用〈侦查人员〉。“嫌犯”指涉嫌犯罪的人，不能替警方收集证据；收集证据的是侦查人员。"}, {"text": "那名嫌犯在医院为病人做手术。", "explanation": "这里应该用〈医生〉。“嫌犯”指涉嫌犯罪的人，不能用来指为病人做手术的医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嫌犯", "is_correct": true, "explanation": "嫌犯：涉嫌犯罪的人，符合句意。"}, {"text": "受害人", "is_correct": false, "explanation": "语义：受害人是被骗的一方，不会涉嫌诈骗。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不会涉嫌诈骗。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“涉嫌”一般只用于人或单位，动物不能涉嫌诈骗。"}], "explanations": {"嫌犯": "嫌犯：涉嫌犯罪的人，符合句意。", "受害人": "语义：受害人是被骗的一方，不会涉嫌诈骗。", "桌子": "语义：桌子是物品，不会涉嫌诈骗。", "小狗": "搭配：“涉嫌”一般只用于人或单位，动物不能涉嫌诈骗。"}, "sentence_index": 6, "correct_answer": "嫌犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个嫌犯正在为客户辩护。", "explanation": "这里应该用〈律师〉。“嫌犯”是被怀疑的人，不能替客户辩护。"}, {"text": "那个嫌犯宣读了判决书。", "explanation": "这里应该用〈法官〉。“嫌犯”不审判案件，宣读判决书是法官的职责。"}, {"text": "那个嫌犯正在起诉这起案件。", "explanation": "这里应该用〈检察官〉。“嫌犯”不负责起诉，起诉是检察官的职责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警方昨天抓住了两只嫌犯。", "corrected_sentence": "警方昨天抓住了两名嫌犯。", "error_description": "量词错误：“嫌犯”指人，量词应用“名”，不能用“只”。正确说法是「两名嫌犯」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察终于追上了那条嫌犯。", "corrected_sentence": "警察终于追上了那名嫌犯。", "error_description": "量词错误：“嫌犯”指人，量词应用“名”，不能用“条”（“条”多用于细长的东西或动物）。正确说法是「那名嫌犯」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c15b8e-659b-4e42-af11-af25dd622025') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97681, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动荡", "is_correct": true, "explanation": "动荡：与“安定”构成反义，指生活或局势不稳、不固定，与“安定的工作”相对。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明：形容头脑反应快，与“安定”没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜：说价格低，与“安定”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴：说人的情绪愉快，与“安定”没有反义关系。"}], "correct_answer": "动荡", "explanations": {"动荡": "动荡：与“安定”构成反义，指生活或局势不稳、不固定，与“安定的工作”相对。", "聪明": "聪明：形容头脑反应快，与“安定”没有反义关系。", "便宜": "便宜：说价格低，与“安定”没有反义关系。", "高兴": "高兴：说人的情绪愉快，与“安定”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97681, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动荡", "is_correct": true, "explanation": "动荡：与“安定”构成反义，指生活不平静、不固定，如“生活安定”与“生活动荡”相对。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容场面喧闹，与“安定”没有反义关系。"}, {"text": "方便", "is_correct": false, "explanation": "方便：说事情容易做，与“安定”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞：说空间大，与“安定”没有反义关系。"}], "correct_answer": "动荡", "explanations": {"动荡": "动荡：与“安定”构成反义，指生活不平静、不固定，如“生活安定”与“生活动荡”相对。", "热闹": "热闹：形容场面喧闹，与“安定”没有反义关系。", "方便": "方便：说事情容易做，与“安定”没有反义关系。", "宽敞": "宽敞：说空间大，与“安定”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97681, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里平静，没有乱，也不搬来搬去。", "primary_collocate": null, "pronunciation": "ān dìng", "ipa": "an˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "搬了好几次家，现在他终于安定下来了。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到妈妈的声音，孩子的心就安定了。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里不安定，晚上总是睡不着。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一份安定的工作，不想再换了。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，他的情绪慢慢安定了。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，老了就想过安定的日子。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家总是搬来搬去，生活很不安定。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考完试，我的心还是安定不下来。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在北京有了房子，心里安定多了。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗到了新家，过几天就安定了。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不安定", "label": "否定式"}, {"form": "安定下来", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人的心情平静、生活固定不再漂泊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安定", "is_correct": true, "explanation": "正确：“终于安定下来”表示生活或心情由动荡转为平静，与“搬了好几次家”的语境相符。"}, {"text": "烦躁", "is_correct": false, "explanation": "搭配：“烦躁”一般说“烦躁起来”，不说“烦躁下来”，而且与“终于……下来”表示平静的结果相反。"}, {"text": "慌乱", "is_correct": false, "explanation": "语义：“慌乱”指心里乱了，与“终于……下来”表示趋于平稳的结果相矛盾。"}, {"text": "凌乱", "is_correct": false, "explanation": "语义：“凌乱”指杂乱无序，用来说心情或生活，与“终于……下来”的平稳结果相矛盾。"}], "explanations": {"安定": "正确：“终于安定下来”表示生活或心情由动荡转为平静，与“搬了好几次家”的语境相符。", "烦躁": "搭配：“烦躁”一般说“烦躁起来”，不说“烦躁下来”，而且与“终于……下来”表示平静的结果相反。", "慌乱": "语义：“慌乱”指心里乱了，与“终于……下来”表示趋于平稳的结果相矛盾。", "凌乱": "语义：“凌乱”指杂乱无序，用来说心情或生活，与“终于……下来”的平稳结果相矛盾。"}, "sentence_index": 0, "correct_answer": "安定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的电压很安定，不用经常调整。", "explanation": "这里应该用〈稳定〉。安定多用于人的心情、生活，机器的电压等要用稳定。"}, {"text": "教室里很安定，大家都在认真听讲。", "explanation": "这里应该用〈安静〉。安定指心情或生活平稳，形容环境没有声音要用安静。"}, {"text": "这张桌子放得很安定，放东西不会晃。", "explanation": "这里应该用〈稳当〉。安定说人的心情或生活平稳，桌子放得牢固要用稳当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安定", "is_correct": true, "explanation": "正确：“生活很不安定”表示生活不固定，与“总是搬来搬去”相符。"}, {"text": "礼貌", "is_correct": false, "explanation": "搭配：“礼貌”形容人的言行，不用来评价生活，“生活很不礼貌”不成立。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的品质，不用于评价生活，“生活很不勇敢”说不通。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”指人的情绪，“生活很不高兴”与前句“总是搬来搬去”的语境也无关。"}], "explanations": {"安定": "正确：“生活很不安定”表示生活不固定，与“总是搬来搬去”相符。", "礼貌": "搭配：“礼貌”形容人的言行，不用来评价生活，“生活很不礼貌”不成立。", "勇敢": "搭配：“勇敢”形容人的品质，不用于评价生活，“生活很不勇敢”说不通。", "高兴": "语义：“高兴”指人的情绪，“生活很不高兴”与前句“总是搬来搬去”的语境也无关。"}, "sentence_index": 6, "correct_answer": "安定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每次都坐在窗边，座位很安定。", "explanation": "这里应该用〈固定〉。安定说人的心情或生活，座位、位置等要用固定。"}, {"text": "这辆车跑得很安定，坐着很舒服。", "explanation": "这里应该用〈平稳〉。安定用于人的心情或生活，车辆行驶要用平稳。"}, {"text": "这把剪刀的刀刃很安定，剪纸很利落。", "explanation": "这里应该用〈锋利〉。安定用于人的心情或生活，刀刃要用锋利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "搬到乡下以后，我们一家的生活很非常安定。", "corrected_sentence": "搬到乡下以后，我们一家的生活非常安定。", "error_description": "错误：“很非常安定”，两个程度副词“很”和“非常”叠用。形容词前只能用一个程度副词。正确：“非常安定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子到了新家，心安定很快。", "corrected_sentence": "孩子到了新家，心安定得很快。", "error_description": "错误：“安定很快”缺少“得”。正确：“安定得很快”，“得”引出状态补语，说明安定的速度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97682, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动荡", "is_correct": true, "explanation": "动荡：与“安定”构成反义，指社会或局势不稳，与“战争结束后……安定”相对。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容看得明白、说得明白，与“安定”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞：说空间大，与“安定”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴：说人的情绪愉快，与“安定”没有反义关系。"}], "correct_answer": "动荡", "explanations": {"动荡": "动荡：与“安定”构成反义，指社会或局势不稳，与“战争结束后……安定”相对。", "清楚": "清楚：形容看得明白、说得明白，与“安定”没有反义关系。", "宽敞": "宽敞：说空间大，与“安定”没有反义关系。", "高兴": "高兴：说人的情绪愉快，与“安定”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97682, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动荡", "is_correct": true, "explanation": "动荡：与“安定”构成反义，指局势或社会不稳，与“边境地区终于安定”相对。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容场面喧闹，与“安定”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线充足或颜色鲜亮，与“安定”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净：形容没有污物，与“安定”没有反义关系。"}], "correct_answer": "动荡", "explanations": {"动荡": "动荡：与“安定”构成反义，指局势或社会不稳，与“边境地区终于安定”相对。", "热闹": "热闹：形容场面喧闹，与“安定”没有反义关系。", "明亮": "明亮：形容光线充足或颜色鲜亮，与“安定”没有反义关系。", "干净": "干净：形容没有污物，与“安定”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97682, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "平静稳定，不动荡。", "primary_collocate": null, "pronunciation": "ān dìng", "ipa": "an˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的社会很安定，人们生活得很好。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的局势已经安定下来了。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政局安定，经济才能发展。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，这座城市慢慢安定了。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区多年来保持安定，外来投资越来越多。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，这个小镇一直很安定，居民们都很满意。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想国家安定，先要让人民有饭吃。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会不安定的时候，生意不好做。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的工作是维护社会安定。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过几年努力，边境地区终于安定了。", "target_word": "安定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不安定", "label": "否定式"}, {"form": "安定下来", "label": "复合"}], "register": "书面语", "sense_fingerprint": "社会、局势、物价等平稳而不动荡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安定", "is_correct": true, "explanation": "正确：“社会很安定”指社会平稳不动荡，与“人们生活得很好”相符。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：“混乱”说社会秩序乱，与后句“人们生活得很好”相矛盾。"}, {"text": "残酷", "is_correct": false, "explanation": "语义：“残酷”形容环境或行为冷酷，与“人们生活得很好”相矛盾。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”多形容景物或人，不用来形容一个社会。"}], "explanations": {"安定": "正确：“社会很安定”指社会平稳不动荡，与“人们生活得很好”相符。", "混乱": "语义：“混乱”说社会秩序乱，与后句“人们生活得很好”相矛盾。", "残酷": "语义：“残酷”形容环境或行为冷酷，与“人们生活得很好”相矛盾。", "美丽": "搭配：“美丽”多形容景物或人，不用来形容一个社会。"}, "sentence_index": 0, "correct_answer": "安定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的产品质量很安定，客户都很满意。", "explanation": "这里应该用〈稳定〉。安定用于社会、局势，产品质量要用稳定。"}, {"text": "图书馆里很安定，大家都在认真看书。", "explanation": "这里应该用〈安静〉。安定指社会或局势平稳，形容环境没有声音要用安静。"}, {"text": "我每天上下班的时间很安定。", "explanation": "这里应该用〈固定〉。安定用于社会、局势，上下班的时间要用固定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安定", "is_correct": true, "explanation": "正确：“要想国家安定”指国家平稳不动荡，与后句“先要让人民有饭吃”的目标相符。"}, {"text": "贫穷", "is_correct": false, "explanation": "语义：“贫穷”与“要想国家……”所追求的目标相反，句意不通。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“落后”与“要想……”的目标相反，前句的追求不成立。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”多形容街道、场所，不用来形容一个国家。"}], "explanations": {"安定": "正确：“要想国家安定”指国家平稳不动荡，与后句“先要让人民有饭吃”的目标相符。", "贫穷": "语义：“贫穷”与“要想国家……”所追求的目标相反，句意不通。", "落后": "语义：“落后”与“要想……”的目标相反，前句的追求不成立。", "冷清": "搭配：“冷清”多形容街道、场所，不用来形容一个国家。"}, "sentence_index": 6, "correct_answer": "安定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体检结果显示，他的心跳很安定。", "explanation": "这里应该用〈平稳〉。安定用于社会、局势，心跳、脉搏要用平稳。"}, {"text": "清晨的湖面很安定，没有一点风。", "explanation": "这里应该用〈平静〉。安定用于社会、局势，湖面等自然景物要用平静。"}, {"text": "这位老人走路很安定，从不摔跤。", "explanation": "这里应该用〈稳当〉。安定用于社会、局势，人走路要用稳当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新政府上台以后，国内的局势安定的很快。", "corrected_sentence": "新政府上台以后，国内的局势安定得很快。", "error_description": "错误：“安定的很快”，“的”应为“得”，用来引出表示程度的补语。正确：“安定得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "战乱结束后，这座城市安定很快。", "corrected_sentence": "战乱结束后，这座城市安定得很快。", "error_description": "错误：“安定很快”缺少“得”。正确：“安定得很快”，“得”引出状态补语，说明安定的速度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
