INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97685, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "特地去问一个人问题，写出来或播出来。", "primary_collocate": null, "pronunciation": "zhuān fǎng", "ipa": "ʈʂwan˥ faŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "记者专访了那位有名的老医生。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台想专访这位刚得奖的作家。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她专访过很多成功的商人。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者专程去山里专访那位老人。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章是记者专访校长以后写的。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节目里，主持人专访了一位年轻的科学家。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天下午，报社要去专访那位运动员。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想专访一下这位画家，请他讲讲自己的故事。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志社专访了她，还把文章放在网上。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者专访完歌手，马上回去写稿子。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专访了", "label": "体标"}, {"form": "专访过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "记者特地去采访某人并写成文章或做成节目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专访", "is_correct": true, "explanation": "“专访”指特地去采访某人并写成稿或播出，与“记者”搭配，符合句意。"}, {"text": "治疗", "is_correct": false, "explanation": "语义：“治疗”是给病人看病，记者不做这件事，句子说不通。"}, {"text": "辞退", "is_correct": false, "explanation": "配价：“辞退”的主语须是用人单位，记者不能辞退别人，也不指采访。"}, {"text": "拘留", "is_correct": false, "explanation": "语义：“拘留”是公安机关对人的强制措施，记者不能拘留老医生，句子说不通。"}], "explanations": {"专访": "“专访”指特地去采访某人并写成稿或播出，与“记者”搭配，符合句意。", "治疗": "语义：“治疗”是给病人看病，记者不做这件事，句子说不通。", "辞退": "配价：“辞退”的主语须是用人单位，记者不能辞退别人，也不指采访。", "拘留": "语义：“拘留”是公安机关对人的强制措施，记者不能拘留老医生，句子说不通。"}, "sentence_index": 0, "correct_answer": "专访"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他带着礼物专访了生病的老同事，给他削了一个苹果。", "explanation": "这里应该用〈探望〉。专访是特地向人提问并写成文章或播出，这里是带礼物去看病人，应用“探望”。"}, {"text": "他去公司专访了三次，最后被录用了。", "explanation": "这里应该用〈面试〉。面试是求职时的考核，专访是记者向受访人提问，不能用于求职。"}, {"text": "警察专访了这起案件。", "explanation": "这里应该用〈调查〉。调查的对象可以是案件，专访的对象必须是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专访", "is_correct": true, "explanation": "“专访”指特地去采访人，报社约请运动员接受采访，符合句意。"}, {"text": "训练", "is_correct": false, "explanation": "语义：“训练”是教练对运动员的指导，报社不负责训练运动员，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”的对象是机器、物品等，不能用于运动员，句意不通。"}, {"text": "逮捕", "is_correct": false, "explanation": "语义：“逮捕”是公安、检察机关的强制行为，报社不能逮捕运动员，句意不通。"}], "explanations": {"专访": "“专访”指特地去采访人，报社约请运动员接受采访，符合句意。", "训练": "语义：“训练”是教练对运动员的指导，报社不负责训练运动员，句意不通。", "修理": "语义：“修理”的对象是机器、物品等，不能用于运动员，句意不通。", "逮捕": "语义：“逮捕”是公安、检察机关的强制行为，报社不能逮捕运动员，句意不通。"}, "sentence_index": 6, "correct_answer": "专访"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈专访了生病的孩子，一直守在床边。", "explanation": "这里应该用〈照顾〉。专访指为提问或写作而采访人，不表示照料病人。"}, {"text": "我们周末去专访了那座古老的博物馆，买了票进去，看了很久的展品。", "explanation": "这里应该用〈参观〉。专访指特地向人提问并写成文章或播出；这里是买票进馆看展，应用“参观”。"}, {"text": "导游专访了这段历史。", "explanation": "这里应该用〈讲解〉。讲解可以说历史、文物，专访只能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "记者没专访了那位年轻的作家。", "corrected_sentence": "记者没专访那位年轻的作家。", "error_description": "错误形式：“没专访了”；正确形式：“没专访”。“没”否定动作时不与“了”同用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "记者正在专访了那位新来的歌手。", "corrected_sentence": "记者正在专访那位新来的歌手。", "error_description": "错误形式：“正在专访了”；正确形式：“正在专访”。“正在”表示动作进行中，与表示完成的“了”不能同用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
