INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97686, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "专门采访。", "primary_collocate": null, "pronunciation": "zhuān fǎng", "ipa": "ʈʂwan˥ faŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "报社派人专访了那位刚回国的科学家。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了了解情况，记者专访了当地的农民。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台专访了这次比赛的冠军。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想专访一位在大学教书的老师。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次专访名人，心里有点紧张。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者专访那位老演员，谈了两个小时。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家不愿意让记者专访。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台去机场专访了回国的足球队长。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她准备专访几位年轻的工程师。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者专访过他一次，那次谈得很好。", "target_word": "专访", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专访了", "label": "体标"}, {"form": "专访过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "专门对某人进行采访", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专访", "is_correct": true, "explanation": "“专访”指专门对某人进行采访，报社派人访问科学家，符合句意。"}, {"text": "救治", "is_correct": false, "explanation": "语义：“救治”是抢救治疗病人，报社派人采访科学家不是救治。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是房间、地面等，不能用于科学家，句意不通。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”是强行赶走，与采访的语境完全相反，句意不通。"}], "explanations": {"专访": "“专访”指专门对某人进行采访，报社派人访问科学家，符合句意。", "救治": "语义：“救治”是抢救治疗病人，报社派人采访科学家不是救治。", "打扫": "语义：“打扫”的对象是房间、地面等，不能用于科学家，句意不通。", "驱逐": "语义：“驱逐”是强行赶走，与采访的语境完全相反，句意不通。"}, "sentence_index": 0, "correct_answer": "专访"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家专访了这个问题，意见很多。", "explanation": "这里应该用〈讨论〉。专访的对象是人，不能用于问题。"}, {"text": "妈妈一直专访着生病的孩子。", "explanation": "这里应该用〈陪伴〉。专访是为提问或写作而采访人，不表示陪伴照料。"}, {"text": "医生专访了病人的眼睛。", "explanation": "这里应该用〈检查〉。检查可以针对身体部位，专访的对象必须是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专访", "is_correct": true, "explanation": "“专访”指专门采访人，句中作家不愿接受记者采访，符合句意。"}, {"text": "批准", "is_correct": false, "explanation": "配价：“批准”需要有审批权的机关或领导作主语，记者不能批准作家的事，句意不通。"}, {"text": "报销", "is_correct": false, "explanation": "语义：“报销”指凭票据领回费用，与作家是否接受采访毫无关系。"}, {"text": "赔偿", "is_correct": false, "explanation": "语义：“赔偿”指因损失而付出钱物，与句中的语境不符。"}], "explanations": {"专访": "“专访”指专门采访人，句中作家不愿接受记者采访，符合句意。", "批准": "配价：“批准”需要有审批权的机关或领导作主语，记者不能批准作家的事，句意不通。", "报销": "语义：“报销”指凭票据领回费用，与作家是否接受采访毫无关系。", "赔偿": "语义：“赔偿”指因损失而付出钱物，与句中的语境不符。"}, "sentence_index": 6, "correct_answer": "专访"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人专访了这台电脑。", "explanation": "这里应该用〈修理〉。专访只用于采访人，不能指对机器进行修理。"}, {"text": "朋友专访了他一会儿，帮他擦干了眼泪。", "explanation": "这里应该用〈安慰〉。专访指为提问或写作而采访人，朋友的安慰不是采访。"}, {"text": "他们重新专访了办公室。", "explanation": "这里应该用〈装修〉。装修的对象是房屋，专访的对象必须是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不专访过那位老师。", "corrected_sentence": "我们没专访过那位老师。", "error_description": "错误形式：“不专访过”；正确形式：“没专访过”。表示过去没有过的经历要用“没”，不用“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "记者专访了过那位老演员。", "corrected_sentence": "记者专访过那位老演员。", "error_description": "错误形式：“专访了过”；正确形式：“专访过”。“了”表示完成，“过”表示经历，二者不能同时用在同一动词后，表示经历只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
