INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "小事一桩；微不足道的东西。", "primary_collocate": null, "pronunciation": "xiǎo yì si", "ipa": "ɕiɑʊ˨˩˦ i˥˩ sɿ", "syllable_count": 3, "sentences": [{"text": "这点困难对他来说是小意思。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修电脑对我来说是小意思。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道数学题对他来说不过是小意思。", "target_word": "小意思", "complexity_tier": "T3", "furigana": "zhè dào shù xué tí duì tā lái shuō bú guò shì xiǎo yi si", "sentence_source": "generated"}, {"text": "一百块钱对他来说只是小意思。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬这座小山，对我是小意思。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译这篇短文，对她来说是小意思。", "target_word": "小意思", "complexity_tier": "T3", "furigana": "fān yì zhè piān duǎn wén, duì tā lái shuō shì xiǎo yi si", "sentence_source": "generated"}, {"text": "改一个错别字，对编辑来说是小意思。", "target_word": "小意思", "complexity_tier": "T3", "furigana": "gǎi yí ge cuò bié zì, duì biān jí lái shuō shì xiǎo yi si", "sentence_source": "generated"}, {"text": "做这道菜对妈妈来说是小意思。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点活儿，在他眼里都是小意思。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，修这个水龙头只是小意思。", "target_word": "小意思", "complexity_tier": "T3", "furigana": "bié dān xīn, xiū zhè ge shuǐ lóng tou zhǐ shì xiǎo yi si", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "轻而易举的小事，或不值钱的小礼物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb4c8f47-f9b5-4427-b6c0-3ded0add6b63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大事", "is_correct": false, "explanation": "语义：“这点困难”说明事情很小，与“大事”的意思矛盾。"}, {"text": "小意思", "is_correct": true, "explanation": "正确：“小意思”指轻而易举的小事，与“这点困难”的轻松语气相符。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：“这点困难”不至于是灾难，与“这点”的轻微语气矛盾。"}, {"text": "奇迹", "is_correct": false, "explanation": "搭配：“奇迹”指罕见的非凡之事，不用来说一点困难。"}], "explanations": {"大事": "语义：“这点困难”说明事情很小，与“大事”的意思矛盾。", "小意思": "正确：“小意思”指轻而易举的小事，与“这点困难”的轻松语气相符。", "灾难": "语义：“这点困难”不至于是灾难，与“这点”的轻微语气矛盾。", "奇迹": "搭配：“奇迹”指罕见的非凡之事，不用来说一点困难。"}, "sentence_index": 0, "correct_answer": "小意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们班的小意思。", "explanation": "“小意思”只指事情或东西，不能用来称呼人；这里把它当成了人，所以不对。"}, {"text": "他小意思地笑了。", "explanation": "“小意思”是名词性的说法，不能直接作状语修饰动词；这里用法不对。"}, {"text": "这首诗的小意思很深刻。", "explanation": "这里说的是诗的寓意，“小意思”只表示事情微小，不指文字的含义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工程", "is_correct": false, "explanation": "语义：“一个错别字”很小，与“工程”的规模矛盾。"}, {"text": "小意思", "is_correct": true, "explanation": "正确：“小意思”指轻而易举的小事，与改一个错别字的情形相符。"}, {"text": "难关", "is_correct": false, "explanation": "语义：改一个错别字不构成难关，与“一个”的数量矛盾。"}, {"text": "壮举", "is_correct": false, "explanation": "语域：“壮举”是书面语，指惊人的大事，不用于口语里说改错字。"}], "explanations": {"工程": "语义：“一个错别字”很小，与“工程”的规模矛盾。", "小意思": "正确：“小意思”指轻而易举的小事，与改一个错别字的情形相符。", "难关": "语义：改一个错别字不构成难关，与“一个”的数量矛盾。", "壮举": "语域：“壮举”是书面语，指惊人的大事，不用于口语里说改错字。"}, "sentence_index": 6, "correct_answer": "小意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只是一只小意思，不用放在心上。", "explanation": "这里的量词不对：“小意思”表示小事时一般不加量词，直接说〈只是小意思〉；不能说〈一只〉。"}, {"text": "他三分钟就把这道题小意思完了。", "explanation": "“小意思”是名词，不能当动词用；这里应说〈三分钟就做完了〉。"}, {"text": "那只小猫是小意思。", "explanation": "“小意思”只指事情或东西，不指动物，这里用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "翻修这间屋子对他来说是一只小意思。", "corrected_sentence": "翻修这间屋子对他来说是小意思。", "error_description": "错误在于“小意思”前加了“一只”。“只”用于动物或小件物品，“小意思”指事情，不能用“只”计量；去掉量词后句子自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小问题对他来说是小意思的。", "corrected_sentence": "这个小问题对他来说是小意思。", "error_description": "错误在于“小意思”后多了“的”。“是小意思”直接作判断，不需要“是……的”结构；去掉“的”句子才自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
