INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97693, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "只有一小块地方，不是很大。", "primary_collocate": null, "pronunciation": "xiǎo fàn wéi", "ipa": "ɕjɑʊ˨˩˦ fan˥˩ weɪ˧˥", "syllable_count": 3, "sentences": [{"text": "这种虫子只在小范围里生活。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员把火控制在小范围内。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪只下在小范围，别的地方是晴天。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让孩子们在小范围里玩。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花只长在山上的小范围里。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家在小范围里找一找钥匙。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次大火只烧了山脚下小范围的地方。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟只在岛上的小范围内生活。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雨很小，只下在小范围。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在公园的小范围里种了花。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小范围内", "label": "复合"}, {"form": "小範圍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地方空间小的一片区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小范围", "is_correct": true, "explanation": "小范围：指只有一小块地方，与“只在……里生活”的地点限定相合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”不是虫子生活的场所，说“只在考试里生活”不通。"}, {"text": "公式", "is_correct": false, "explanation": "语义：“公式”不是可以生活的地方，虫子不能生活在公式里。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“数字”不能作为生物生活的场所，说“只在数字里生活”不通。"}], "explanations": {"小范围": "小范围：指只有一小块地方，与“只在……里生活”的地点限定相合。", "考试": "语义：“考试”不是虫子生活的场所，说“只在考试里生活”不通。", "公式": "语义：“公式”不是可以生活的地方，虫子不能生活在公式里。", "数字": "搭配：“数字”不能作为生物生活的场所，说“只在数字里生活”不通。"}, "sentence_index": 0, "correct_answer": "小范围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃了小范围的蛋糕，然后就走了。", "explanation": "这里应该用〈一小块〉。“小范围”指地方或影响面，不用于说食物的量；这里应说“一小块蛋糕”。"}, {"text": "这种虫子只在小范围的时间里生活。", "explanation": "这里应该用〈短时间〉。“小范围”指地方或影响面，不指时间长短；表示时间短应说“短时间”。"}, {"text": "他只带了小范围的水，就出发了。", "explanation": "这里应该用〈一小瓶〉。“小范围”不用于说水的量；这里应说“一小瓶水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小范围", "is_correct": true, "explanation": "小范围：指只有一小块地方，与“只烧了山脚下……的地方”相合。"}, {"text": "世界", "is_correct": false, "explanation": "语义：“世界”范围极大，与“只烧了山脚下”的一小片地方矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是机器，不是一片地方，说“电脑的地方”不通。"}, {"text": "大地", "is_correct": false, "explanation": "语义：“大地”指广阔的陆地，与“只烧了山脚下”的一小片地方矛盾。"}], "explanations": {"小范围": "小范围：指只有一小块地方，与“只烧了山脚下……的地方”相合。", "世界": "语义：“世界”范围极大，与“只烧了山脚下”的一小片地方矛盾。", "电脑": "语义：“电脑”是机器，不是一片地方，说“电脑的地方”不通。", "大地": "语义：“大地”指广阔的陆地，与“只烧了山脚下”的一小片地方矛盾。"}, "sentence_index": 6, "correct_answer": "小范围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只拿了小范围的钱，剩下的都给了朋友。", "explanation": "这里应该用〈一小笔〉。“小范围”不用于说钱的数量；这里应说“一小笔钱”。"}, {"text": "她抓了小范围的米，煮了一锅饭。", "explanation": "这里应该用〈一小把〉。“小范围”不用于说米的数量；这里应说“一小把米”。"}, {"text": "他只喝了小范围的汽水，就饱了。", "explanation": "这里应该用〈一小杯〉。“小范围”不用于说饮料的量；这里应说“一小杯汽水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们在小范围的里玩得很开心。", "corrected_sentence": "孩子们在小范围里玩得很开心。", "error_description": "错误形式是“小范围的里”，正确形式是“小范围里”。方位词“里”前不能加“的”，“小范围里”是方位短语，直接连用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种病毒只在小范围的内传播。", "corrected_sentence": "这种病毒只在小范围内传播。", "error_description": "错误形式是“小范围的内”，正确形式是“小范围内”。“范围内”是方位词组合，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
