INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97694, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "范围不大。", "primary_collocate": null, "pronunciation": "xiǎo fàn wéi", "ipa": "ɕjɑʊ˨˩˦ fan˥˩ weɪ˧˥", "syllable_count": 3, "sentences": [{"text": "这件事只在小范围里说过，很多人不知道。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动只在小范围内举行。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名气只在小范围里传开。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会议只请了小范围的人参加。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司先在小范围内试用新办法。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题只影响小范围的学生。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作品只在小范围里有名。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息只在小范围内传开了。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先在小范围内问一问大家的想法。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种游戏只在小范围里流行。", "target_word": "小范围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小范围内", "label": "复合"}, {"form": "小範圍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人数或影响的范围小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小范围", "is_correct": true, "explanation": "小范围：指知道或影响的人不多，与“很多人不知道”相合。"}, {"text": "大范围", "is_correct": false, "explanation": "语义：“大范围”指影响很广，与“很多人不知道”不符。"}, {"text": "世界", "is_correct": false, "explanation": "语义：“世界”指所有人，说“只在世界里说过”与“很多人不知道”矛盾。"}, {"text": "大街", "is_correct": false, "explanation": "语义：“大街”是人人可见的公共场所，与“很多人不知道”相矛盾。"}], "explanations": {"小范围": "小范围：指知道或影响的人不多，与“很多人不知道”相合。", "大范围": "语义：“大范围”指影响很广，与“很多人不知道”不符。", "世界": "语义：“世界”指所有人，说“只在世界里说过”与“很多人不知道”矛盾。", "大街": "语义：“大街”是人人可见的公共场所，与“很多人不知道”相矛盾。"}, "sentence_index": 0, "correct_answer": "小范围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他只用了小范围的时间完成这次任务。", "explanation": "这里应该用〈短时间〉。“小范围”指空间或影响面，不指时间长短；表示时间短应说“短时间”。"}, {"text": "他从冰箱里拿出了小范围的饼干。", "explanation": "这里应该用〈一小包〉。“小范围”不用于说饼干的数量；这里应说“一小包饼干”。"}, {"text": "他只买了小范围的苹果，就回家了。", "explanation": "这里应该用〈几个〉。“小范围”不用于说苹果的数量；这里应说“几个苹果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小范围", "is_correct": true, "explanation": "小范围：指知名范围有限，与“作品只在……有名”相合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”不是能传播名声的范围，“只在……里有名”不通。"}, {"text": "时钟", "is_correct": false, "explanation": "语义：“时钟”是计时的器具，不能作为名声传开的范围，说“只在时钟里有名”不通。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：“宇宙”范围极大，说作品只在宇宙里有名不符合语境。"}], "explanations": {"小范围": "小范围：指知名范围有限，与“作品只在……有名”相合。", "体重": "语义：“体重”不是能传播名声的范围，“只在……里有名”不通。", "时钟": "语义：“时钟”是计时的器具，不能作为名声传开的范围，说“只在时钟里有名”不通。", "宇宙": "语义：“宇宙”范围极大，说作品只在宇宙里有名不符合语境。"}, "sentence_index": 6, "correct_answer": "小范围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只借了小范围的钱，还了一半。", "explanation": "这里应该用〈一小笔〉。“小范围”不用于说钱的数量，表示少量款项应说“一小笔”。"}, {"text": "他只倒了小范围的酱油。", "explanation": "这里应该用〈一小勺〉。“小范围”不用于说调料的量；这里应说“一小勺酱油”。"}, {"text": "她只买了小范围的糖做点心。", "explanation": "这里应该用〈一小包〉。“小范围”不用于说糖的量；这里应说“一小包糖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个秘密只在小范围的内流传，外人并不知道。", "corrected_sentence": "这个秘密只在小范围内流传，外人并不知道。", "error_description": "错误形式是“小范围的内”，正确形式是“小范围内”。“范围内”是方位词组合，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事只在一只小范围里流传，别人并不知道。", "corrected_sentence": "这件事只在一个小范围里流传，别人并不知道。", "error_description": "错误形式是“一只小范围”，正确形式是“一个小范围”。“范围”应该用“个”来量，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
