INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97697, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在一个国家里，人比较少的那些民族。", "primary_collocate": null, "pronunciation": "shǎo shù mín zú", "ipa": "ʂɑʊ²¹⁴ ʂu⁵¹ min³⁵ tsu³⁵", "syllable_count": 4, "sentences": [{"text": "中国有五十五个少数民族。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的同学是少数民族。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子里住着很多少数民族。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数民族有自己的语言和节日。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在少数民族的村子里住过一年。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数民族的衣服非常漂亮。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了一个少数民族。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个少数民族的人喜欢唱歌跳舞。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数民族的孩子也要上学。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在北京认识了一位少数民族朋友。", "target_word": "少数民族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "少数民族地区", "label": "复合"}, {"form": "少數民族", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一国之内人口较少的民族", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97697, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家", "is_correct": false, "explanation": "语义：中国本身就是一个国家，不能说中国有五十五个国家。"}, {"text": "少数民族", "is_correct": true, "explanation": "正确：指一个国家里人口较少的民族，与“五十五个”搭配，符合句意。"}, {"text": "大陆", "is_correct": false, "explanation": "语义：中国是一块大陆，说它包含五十五个大陆与常识不符。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“海洋”一般不用量词“个”计数，且一个国家不说有五十五个海洋。"}], "explanations": {"国家": "语义：中国本身就是一个国家，不能说中国有五十五个国家。", "少数民族": "正确：指一个国家里人口较少的民族，与“五十五个”搭配，符合句意。", "大陆": "语义：中国是一块大陆，说它包含五十五个大陆与常识不符。", "海洋": "搭配：“海洋”一般不用量词“个”计数，且一个国家不说有五十五个海洋。"}, "sentence_index": 0, "correct_answer": "少数民族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在银行当少数民族。", "explanation": "这里应该用〈职员〉。〈少数民族〉指人群，不能用来指职业身份，“当”后应接职业。"}, {"text": "中国人口最多的民族是少数民族。", "explanation": "这里应该用〈汉族〉。少数民族指人口较少的民族，不能用来指人口最多的汉族。"}, {"text": "这种狗是一个很古老的少数民族。", "explanation": "这里应该用〈品种〉。〈少数民族〉指人群，不能用来指动物的品种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是自然状况，不是老师可以介绍给学生的具体事物。"}, {"text": "少数民族", "is_correct": true, "explanation": "正确：指一国之内人口较少的民族，可以被介绍，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以介绍给学生的具体对象，句意不通。"}, {"text": "蓝色", "is_correct": false, "explanation": "搭配：颜色词说“一种蓝色”，不说“一个蓝色”，也不能作为被介绍的对象。"}], "explanations": {"天气": "语义：天气是自然状况，不是老师可以介绍给学生的具体事物。", "少数民族": "正确：指一国之内人口较少的民族，可以被介绍，符合句意。", "天空": "语义：天空不是可以介绍给学生的具体对象，句意不通。", "蓝色": "搭配：颜色词说“一种蓝色”，不说“一个蓝色”，也不能作为被介绍的对象。"}, "sentence_index": 6, "correct_answer": "少数民族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他会说少数民族。", "explanation": "这里应该用〈少数民族语言〉。〈少数民族〉指人群，不能当作语言的名称，“会说”后应接语言。"}, {"text": "我们去少数民族旅游。", "explanation": "这里应该用〈少数民族地区〉。〈少数民族〉指人，去某个地方旅游要说“少数民族地区”。"}, {"text": "这个学校的少数民族都来自美国。", "explanation": "这里应该用〈外国人〉。少数民族是一国之内的民族，不指来自其他国家的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村里住着一只少数民族。", "corrected_sentence": "我们村里住着一个少数民族。", "error_description": "错误形式“一只少数民族”，正确形式“一个少数民族”。“只”用于动物或单件物品，指人群的少数民族要用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在学校认识了一少数民族同学。", "corrected_sentence": "我在学校认识了一位少数民族同学。", "error_description": "错误形式“一少数民族同学”，正确形式“一位少数民族同学”。数量词“一”后必须带量词，“位”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
