INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97705, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事里特别高大的人。", "primary_collocate": null, "pronunciation": "jù rén", "ipa": "tɕy˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "故事里的巨人住在大山上。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩在梦里遇到了一个巨人。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巨人一步就能走过一条河。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本童话书里有一个好心的巨人。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我讲了巨人和小狗的故事。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的巨人比房子还高。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "童话里巨人的鞋子像两条小船。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友画了一个很高的巨人。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里，巨人看见小鸟，笑着说你好。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的巨人喜欢吃苹果。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "童话故事里的高大人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97705, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巨人", "is_correct": true, "explanation": "“巨人”指童话故事里特别高大的人物，与“故事里的”“住在大山上”的情境相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”不是能居住的主体，说“故事里的工资住在大山上”不通。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：“住”用于人或动物，鱼生活在水中，不说“住在大山上”。"}, {"text": "行人", "is_correct": false, "explanation": "语义：“行人”指路上走的人，只是路过，不能说“住在大山上”。"}], "explanations": {"巨人": "“巨人”指童话故事里特别高大的人物，与“故事里的”“住在大山上”的情境相符。", "工资": "语义：“工资”不是能居住的主体，说“故事里的工资住在大山上”不通。", "鱼": "搭配：“住”用于人或动物，鱼生活在水中，不说“住在大山上”。", "行人": "语义：“行人”指路上走的人，只是路过，不能说“住在大山上”。"}, "sentence_index": 0, "correct_answer": "巨人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本童话书里有一条巨人。", "explanation": "这里“巨人”指人，应用量词〈个〉；〈条〉多用于细长的东西，不能用来数人。"}, {"text": "书房的角落里站着一棵巨人，挡住了窗外的光。", "explanation": "这里“巨人”指人，不能用量词〈棵〉；〈棵〉用于树木等植物，指人应用〈个〉。"}, {"text": "这只小蚂蚁在草地上玩，它是童话里的巨人。", "explanation": "“巨人”指身材高大的人物，蚂蚁体型极小，与这一含义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巨人", "is_correct": true, "explanation": "“巨人”指童话里高大的人物，穿着像两条小船一样大的鞋子，与情境相符。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "体貌：“蚂蚁”体型极小，鞋子不可能像两条小船。"}, {"text": "大树", "is_correct": false, "explanation": "搭配：“大树”不穿鞋，不能说“大树的鞋子”。"}, {"text": "小鸟", "is_correct": false, "explanation": "体貌：“小鸟”个头很小，与“像两条小船”的大小不符。"}], "explanations": {"巨人": "“巨人”指童话里高大的人物，穿着像两条小船一样大的鞋子，与情境相符。", "蚂蚁": "体貌：“蚂蚁”体型极小，鞋子不可能像两条小船。", "大树": "搭配：“大树”不穿鞋，不能说“大树的鞋子”。", "小鸟": "体貌：“小鸟”个头很小，与“像两条小船”的大小不符。"}, "sentence_index": 6, "correct_answer": "巨人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小金鱼在鱼缸里游来游去，它是童话里的巨人。", "explanation": "“巨人”指童话里身材特别高大的人物，用来形容一条小金鱼，与词义相反。"}, {"text": "这只小老鼠躲在墙角，它是童话里的巨人。", "explanation": "“巨人”指身材高大的人物，老鼠体型很小，与这一含义相反。"}, {"text": "我们班那个矮矮的同学，是童话里的巨人。", "explanation": "“巨人”指童话里身材高大的人物，用来形容矮矮的同学，与这一含义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小男孩梦见了一只很高的巨人。", "corrected_sentence": "小男孩梦见了一个很高的巨人。", "error_description": "错误形式是“一只很高的巨人”，正确形式是“一个很高的巨人”。“巨人”指人，应用量词“个”，“只”一般用于动物等，不用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个故事里有一条温柔的巨人。", "corrected_sentence": "这个故事里有一个温柔的巨人。", "error_description": "错误形式是“一条温柔的巨人”，正确形式是“一个温柔的巨人”。“巨人”指人，量词用“个”，“条”多用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
