INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97706, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身材特别高大的人；比喻有大影响的人。", "primary_collocate": null, "pronunciation": "jù rén", "ipa": "tɕy˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "他两米五高，像一个巨人。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位篮球运动员身高两米三，是个巨人。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是科学界的巨人，大家都很尊敬他。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在巨人旁边，我显得特别矮。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家是中国文学的巨人。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱因斯坦是物理学的巨人。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们站在巨人的肩膀上看世界。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经成了电影行业里的巨人。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长得又高又大，朋友叫他“巨人”。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人年轻时是有名的巨人，身高两米四。", "target_word": "巨人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "身材极高的人，或影响极大的人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巨人", "is_correct": true, "explanation": "“巨人”指身材特别高大的人，与“两米五高”相符，“像一个巨人”也说得通。"}, {"text": "侏儒", "is_correct": false, "explanation": "体貌：“侏儒”指身材极矮的人，与“两米五高”直接矛盾。"}, {"text": "小人", "is_correct": false, "explanation": "语义：“小人”指品行卑劣的人，与“两米五高”的身材描写无关，这里说不通。"}, {"text": "矮子", "is_correct": false, "explanation": "体貌：“矮子”描写身材矮小，与“两米五高”正好相反。"}], "explanations": {"巨人": "“巨人”指身材特别高大的人，与“两米五高”相符，“像一个巨人”也说得通。", "侏儒": "体貌：“侏儒”指身材极矮的人，与“两米五高”直接矛盾。", "小人": "语义：“小人”指品行卑劣的人，与“两米五高”的身材描写无关，这里说不通。", "矮子": "体貌：“矮子”描写身材矮小，与“两米五高”正好相反。"}, "sentence_index": 0, "correct_answer": "巨人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在路口看见一只巨人。", "explanation": "这里“巨人”指人，应用量词〈个〉或〈位〉；〈只〉多用于动物，不能用来数人。"}, {"text": "门口站着一颗巨人，挡住了所有的光。", "explanation": "这里“巨人”指人，应用量词〈个〉或〈位〉；〈颗〉用于颗粒状或球形的东西，不能用来数人。"}, {"text": "这笔巨人的开支让公司破产了。", "explanation": "这里应该用〈巨额〉。“巨人”是名词，表示身材高大的人或比喻有大影响的人，不能用来修饰数额；表示数量大要用“巨额”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巨人", "is_correct": true, "explanation": "“巨人”比喻有大影响、值得借鉴的前人，与“站在…的肩膀上看世界”的意象相符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”没有肩膀，不能说“站在石头的肩膀上”。"}, {"text": "影子", "is_correct": false, "explanation": "体貌：“影子”没有肩膀，无法让人站在它的肩膀上，“站在影子的肩膀上”不通。"}, {"text": "小人", "is_correct": false, "explanation": "语义：“小人”指品行卑劣的人，不能作为“站在肩膀上”所借鉴的对象。"}], "explanations": {"巨人": "“巨人”比喻有大影响、值得借鉴的前人，与“站在…的肩膀上看世界”的意象相符。", "石头": "搭配：“石头”没有肩膀，不能说“站在石头的肩膀上”。", "影子": "体貌：“影子”没有肩膀，无法让人站在它的肩膀上，“站在影子的肩膀上”不通。", "小人": "语义：“小人”指品行卑劣的人，不能作为“站在肩膀上”所借鉴的对象。"}, "sentence_index": 6, "correct_answer": "巨人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小麻雀停在树枝上，它是个巨人。", "explanation": "“巨人”指身材特别高大的人，也比喻有大影响的人；用来形容一只小麻雀，与词义相反，这里不成立。"}, {"text": "这只小猫很怕人，每天躲在床底下，是个巨人。", "explanation": "“巨人”指身材特别高大的人，用来形容小猫这样体型很小的动物，与词义相反。"}, {"text": "这只小蚂蚁爬过门槛，它是个巨人。", "explanation": "“巨人”指身材特别高大的人，用来形容体型极小的蚂蚁，与词义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个篮球队里有一条巨人。", "corrected_sentence": "那个篮球队里有一位巨人。", "error_description": "“巨人”指人，量词应用“位”或“个”，不能用“条”（“条”多用于细长的东西）。应说“那个篮球队里有一位巨人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在篮球界是一条巨人。", "corrected_sentence": "他在篮球界是一位巨人。", "error_description": "错误形式是“一条巨人”，正确形式是“一位巨人”。“巨人”指人，量词用“位”或“个”，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97709, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难看", "is_correct": true, "explanation": "难看：样子不好看，与“很帅”的好看义相反。"}, {"text": "整洁", "is_correct": false, "explanation": "整洁：指干净利落，与“很帅”的好看义没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：指光线充足或颜色鲜亮，与“很帅”不构成反义。"}, {"text": "轻快", "is_correct": false, "explanation": "轻快：指动作或节奏轻松，与“很帅”没有反义关系。"}], "correct_answer": "难看", "explanations": {"难看": "难看：样子不好看，与“很帅”的好看义相反。", "整洁": "整洁：指干净利落，与“很帅”的好看义没有反义关系。", "明亮": "明亮：指光线充足或颜色鲜亮，与“很帅”不构成反义。", "轻快": "轻快：指动作或节奏轻松，与“很帅”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
