INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97709, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "样子好看，让人喜欢。", "primary_collocate": null, "pronunciation": "shuài", "ipa": "ʂwaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "这辆新车看起来真帅。", "target_word": "帅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你这个新发型很帅。", "target_word": "帅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件黑色外套太帅了。", "target_word": "帅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的新手机很帅，我也想买。", "target_word": "帅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小男孩穿着西装，很帅。", "target_word": "帅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双运动鞋又新又帅。", "target_word": "帅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他戴上帽子以后更帅了。", "target_word": "帅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟剪了头发，看起来很帅。", "target_word": "帅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只狗长得真帅。", "target_word": "帅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都说你穿这件衣服很帅。", "target_word": "帅", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "帥", "label": "繁体"}, {"form": "帅哥", "label": "复合"}, {"form": "帅气", "label": "复合"}], "register": "口语", "sense_fingerprint": "样子好看，让人喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97709, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帅", "is_correct": true, "explanation": "帅（shuài）：样子好看，让人喜欢。"}, {"text": "摔", "is_correct": false, "explanation": "摔（shuāi）与帅（shuài）声调不同，一声与四声的区别，意思是摔倒。"}, {"text": "甩", "is_correct": false, "explanation": "甩（shuǎi）与帅（shuài）声调不同，三声与四声的区别，意思是抛、扔。"}, {"text": "涮", "is_correct": false, "explanation": "涮（shuàn）与帅（shuài）韵母不同，an 与 ai 的区别，意思是把食物放入开水中烫熟。"}, {"text": "踹", "is_correct": false, "explanation": "踹（chuài）与帅（shuài）声母不同，ch 与 sh 的区别，意思是用脚猛力踢。"}], "explanations": {"帅": "帅（shuài）：样子好看，让人喜欢。", "摔": "摔（shuāi）与帅（shuài）声调不同，一声与四声的区别，意思是摔倒。", "甩": "甩（shuǎi）与帅（shuài）声调不同，三声与四声的区别，意思是抛、扔。", "涮": "涮（shuàn）与帅（shuài）韵母不同，an 与 ai 的区别，意思是把食物放入开水中烫熟。", "踹": "踹（chuài）与帅（shuài）声母不同，ch 与 sh 的区别，意思是用脚猛力踢。"}, "sentence_index": null, "correct_answer": "帅"}, "level_3": {"options": [{"text": "旧", "is_correct": false, "explanation": "语义：“旧”与“新车”矛盾，不能用来赞美新车的外观。"}, {"text": "帅", "is_correct": true, "explanation": "帅：样子好看，与“这辆新车看起来真”的外观评价一致。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用于形容车的样子。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，与“看起来”的外观判断不符。"}], "explanations": {"旧": "语义：“旧”与“新车”矛盾，不能用来赞美新车的外观。", "帅": "帅：样子好看，与“这辆新车看起来真”的外观评价一致。", "甜": "搭配：“甜”形容味道，不能用于形容车的样子。", "咸": "语义：“咸”形容味道，与“看起来”的外观判断不符。"}, "sentence_index": 0, "correct_answer": "帅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵玫瑰的香味很帅。", "explanation": "这里应该用〈浓郁〉。“帅”形容外在样子，香气要说“浓郁”。"}, {"text": "这碗汤的味道很帅。", "explanation": "这里应该用〈鲜美〉。“帅”形容外在样子，汤的味道要说“鲜美”。"}, {"text": "这家店的服务很帅。", "explanation": "这里应该用〈周到〉。“帅”形容外在样子，服务的好坏要说“周到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used =