INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97709, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帅", "is_correct": true, "explanation": "帅（shuài）：样子好看，让人喜欢。"}, {"text": "衰", "is_correct": false, "explanation": "衰（shuāi）与帅（shuài）声调不同，一声与四声的区别，意思是衰弱、衰老。"}, {"text": "拽", "is_correct": false, "explanation": "拽（zhuài）与帅（shuài）声母不同，zh 与 sh 的区别，意思是拉、拖。"}, {"text": "睡", "is_correct": false, "explanation": "睡（shuì）与帅（shuài）韵母不同，uei 与 uai 的区别，意思是睡觉。"}, {"text": "晒", "is_correct": false, "explanation": "晒（shài）比帅（shuài）少了 u，韵母不同，意思是在阳光下照射。"}], "explanations": {"帅": "帅（shuài）：样子好看，让人喜欢。", "衰": "衰（shuāi）与帅（shuài）声调不同，一声与四声的区别，意思是衰弱、衰老。", "拽": "拽（zhuài）与帅（shuài）声母不同，zh 与 sh 的区别，意思是拉、拖。", "睡": "睡（shuì）与帅（shuài）韵母不同，uei 与 uai 的区别，意思是睡觉。", "晒": "晒（shài）比帅（shuài）少了 u，韵母不同，意思是在阳光下照射。"}, "sentence_index": null, "correct_answer": "帅"}, "level_3": {"options": [{"text": "饿", "is_correct": false, "explanation": "语义：“饿”指饥饿，与“戴上帽子”没有关系，“更饿了”说不通。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”只用于食物的味道，不能用于人的样子。"}, {"text": "帅", "is_correct": true, "explanation": "帅：样子好看，戴上帽子后更引人注目，与“更……了”搭配。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”形容物体的质地，与“戴上帽子”后的变化无关。"}], "explanations": {"饿": "语义：“饿”指饥饿，与“戴上帽子”没有关系，“更饿了”说不通。", "好吃": "搭配：“好吃”只用于食物的味道，不能用于人的样子。", "帅": "帅：样子好看，戴上帽子后更引人注目，与“更……了”搭配。", "硬": "语义：“硬”形容物体的质地，与“戴上帽子”后的变化无关。"}, "sentence_index": 6, "correct_answer": "帅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首曲子的旋律很帅。", "explanation": "这里应该用〈优美〉。“帅”形容人的容貌、举止或物品的样子，旋律的美要说“优美”。"}, {"text": "外面的雨很帅，带把伞吧。", "explanation": "这里应该用〈大〉。“帅”形容外在样子，雨的强弱要说“大”。"}, {"text": "这个小饰品的价格很帅。", "explanation": "这里应该用〈便宜〉。“帅”形容外在样子，价格低要说“便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUD