INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97710, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "容貌英俊、潇洒；也指动作漂亮。", "primary_collocate": null, "pronunciation": "shuài", "ipa": "ʂwaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "他长得又高又帅。", "target_word": "帅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个男演员很帅。", "target_word": "帅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我哥哥穿西装特别帅。", "target_word": "帅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他跳起来投篮，动作真帅！", "target_word": "帅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师年轻的时候很帅。", "target_word": "帅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他踢球踢得真帅。", "target_word": "帅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天穿得真帅。", "target_word": "帅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他开车转弯的样子很帅。", "target_word": "帅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的男朋友又高又帅。", "target_word": "帅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他笑着说话的样子很帅。", "target_word": "帅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "帥", "label": "繁体"}, {"form": "帅哥", "label": "复合"}, {"form": "帅气", "label": "复合"}], "register": "口语", "sense_fingerprint": "人英俊潇洒；动作漂亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b535fa-b30b-4c50-b2e9-81bd8e0d78f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97710, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帅", "is_correct": true, "explanation": "帅（shuài）：容貌英俊、潇洒，也指动作漂亮。"}, {"text": "摔", "is_correct": false, "explanation": "摔（shuāi）与帅（shuài）声调不同，一声与四声的区别，意思是摔倒。"}, {"text": "甩", "is_correct": false, "explanation": "甩（shuǎi）与帅（shuài）声调不同，三声与四声的区别，意思是抛、扔。"}, {"text": "涮", "is_correct": false, "explanation": "涮（shuàn）与帅（shuài）韵母不同，an 与 ai 的区别，意思是把食物放入开水中烫熟。"}, {"text": "踹", "is_correct": false, "explanation": "踹（chuài）与帅（shuài）声母不同，ch 与 sh 的区别，意思是用脚猛力踢。"}], "explanations": {"帅": "帅（shuài）：容貌英俊、潇洒，也指动作漂亮。", "摔": "摔（shuāi）与帅（shuài）声调不同，一声与四声的区别，意思是摔倒。", "甩": "甩（shuǎi）与帅（shuài）声调不同，三声与四声的区别，意思是抛、扔。", "涮": "涮（shuàn）与帅（shuài）韵母不同，an 与 ai 的区别，意思是把食物放入开水中烫熟。", "踹": "踹（chuài）与帅（shuài）声母不同，ch 与 sh 的区别，意思是用脚猛力踢。"}, "sentence_index": null, "correct_answer": "帅"}, "level_3": {"options": [{"text": "矮", "is_correct": false, "explanation": "语义：矮与“高”意思相反，“又高又矮”自相矛盾。"}, {"text": "帅", "is_correct": true, "explanation": "帅：容貌英俊，与“长得又高又”的描述一致。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”不能用来形容人的外貌，“长得”后应接外貌特征。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”指距离，不能用来形容人的外貌。"}], "explanations": {"矮": "语义：矮与“高”意思相反，“又高又矮”自相矛盾。", "帅": "帅：容貌英俊，与“长得又高又”的描述一致。", "慢": "搭配：“慢”不能用来形容人的外貌，“长得”后应接外貌特征。", "远": "搭配：“远”指距离，不能用来形容人的外貌。"}, "sentence_index": 0, "correct_answer": "帅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的夜景很帅。", "explanation": "这里应该用〈漂亮〉。这一义项的“帅”只用于人的容貌或动作，景色的美一般说“漂亮”。"}, {"text": "这碗汤的颜色很帅。", "explanation": "这里应该用〈好看〉。这一义项的“帅”只用于人的容貌或动作，汤的颜色要说“好看”。"}, {"text": "她的声音很帅。", "explanation": "这里应该用〈甜美〉。“帅”用于外表或动作，形容温柔悦耳的声音要说“甜美”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97710, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帅", "is_correct": true, "explanation": "帅（shuài）：容貌英俊、潇洒，也指动作漂亮。"}, {"text": "衰", "is_correct": false, "explanation": "衰（shuāi）与帅（shuài）声调不同，一声与四声的区别，意思是衰弱、衰老。"}, {"text": "拽", "is_correct": false, "explanation": "拽（zhuài）与帅（shuài）声母不同，zh 与 sh 的区别，意思是拉、拖。"}, {"text": "睡", "is_correct": false, "explanation": "睡（shuì）与帅（shuài）韵母不同，uei 与 uai 的区别，意思是睡觉。"}, {"text": "晒", "is_correct": false, "explanation": "晒（shài）比帅（shuài）少了 u，韵母不同，意思是在阳光下照射。"}], "explanations": {"帅": "帅（shuài）：容貌英俊、潇洒，也指动作漂亮。", "衰": "衰（shuāi）与帅（shuài）声调不同，一声与四声的区别，意思是衰弱、衰老。", "拽": "拽（zhuài）与帅（shuài）声母不同，zh 与 sh 的区别，意思是拉、拖。", "睡": "睡（shuì）与帅（shuài）韵母不同，uei 与 uai 的区别，意思是睡觉。", "晒": "晒（shài）比帅（shuài）少了 u，韵母不同，意思是在阳光下照射。"}, "sentence_index": null, "correct_answer": "帅"}, "level_3": {"options": [{"text": "饿", "is_correct": false, "explanation": "语义：“饿”指饥饿，不能用来形容穿着的样子，“穿得真饿”说不通。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”只用于食物的味道，不能用于形容穿着的样子。"}, {"text": "帅", "is_correct": true, "explanation": "帅：容貌英俊、潇洒，与“你今天穿得真”后的外观评价一致。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”形容物体的质地，不能用来评价穿着的样子。"}], "explanations": {"饿": "语义：“饿”指饥饿，不能用来形容穿着的样子，“穿得真饿”说不通。", "好吃": "搭配：“好吃”只用于食物的味道，不能用于形容穿着的样子。", "帅": "帅：容貌英俊、潇洒，与“你今天穿得真”后的外观评价一致。", "硬": "语义：“硬”形容物体的质地，不能用来评价穿着的样子。"}, "sentence_index": 6, "correct_answer": "帅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片湖水在阳光下很帅。", "explanation": "这里应该用〈美丽〉。这一义项的“帅”只用于人的容貌或动作，湖水的美要说“美丽”。"}, {"text": "书架上的书排得很帅。", "explanation": "这里应该用〈整齐〉。这一义项的“帅”只用于人的容貌或动作，书排列得有序要说“整齐”。"}, {"text": "今天的天气很帅，不冷也不热。", "explanation": "这里应该用〈好〉。这一义项的“帅”只用于人的容貌或动作，天气舒服要说“天气很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他打篮球打很帅。", "corrected_sentence": "他打篮球打得很帅。", "error_description": "“打很帅”漏掉了补语标记“得”，应为“打得很帅”。“得”连接动词与描述动作的补语“很帅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚理了发，变帅着。", "corrected_sentence": "他刚理了发，变帅了。", "error_description": "“变帅着”误用了表示持续的“着”。表示变化已经完成要用“了”，应为“变帅了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ce5903-432b-4040-8a26-dc4d869867c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
