INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97715, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "老了以后，每年可以领到的钱。", "primary_collocate": null, "pronunciation": "nián jīn", "ipa": "njɛn˧˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "爷爷老了，每年都能领年金。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个月存钱，老了可以领年金。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用年金买了一件新衣服。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年六十岁，开始领年金了。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年金不多，但是够她生活。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，年轻时工作，老了才有年金。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外公把年金存在银行里。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔年金是爷爷一辈子工作换来的。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每年领的年金越来越多。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道自己老了以后有多少年金吗？", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔年金", "label": "量词"}, {"form": "企业年金", "label": "复合"}, {"form": "养老年金", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人年老后每年能领取的一笔钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97715, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "年金", "is_correct": true, "explanation": "正确：年金指老了以后每年领取的养老钱。"}, {"text": "年薪", "is_correct": false, "explanation": "xīn 与 jīn 声母不同（x / j），意思是一年的工资，不是养老钱。"}, {"text": "年均", "is_correct": false, "explanation": "jūn 与 jīn 韵母不同（ü / i），意思是一年的平均数。"}, {"text": "年仅", "is_correct": false, "explanation": "jǐn（第三声）与 jīn（第一声）声调不同，意思是年纪只有，与“年金”不同。"}, {"text": "年近", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，意思是年纪快到，不是养老钱。"}], "explanations": {"年金": "正确：年金指老了以后每年领取的养老钱。", "年薪": "xīn 与 jīn 声母不同（x / j），意思是一年的工资，不是养老钱。", "年均": "jūn 与 jīn 韵母不同（ü / i），意思是一年的平均数。", "年仅": "jǐn（第三声）与 jīn（第一声）声调不同，意思是年纪只有，与“年金”不同。", "年近": "jìn（第四声）与 jīn（第一声）声调不同，意思是年纪快到，不是养老钱。"}, "sentence_index": null, "correct_answer": "年金"}, "level_3": {"options": [{"text": "年金", "is_correct": true, "explanation": "正确：老人每年领取的养老钱，与“老了”“每年都能领”相符。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是凭工作表现发的，爷爷已经老了，不再工作，不能领奖金。"}, {"text": "压岁钱", "is_correct": false, "explanation": "语义：压岁钱是长辈给小孩过年的钱，与“爷爷老了”不符。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：学费是要付出的钱，不能说“领学费”。"}], "explanations": {"年金": "正确：老人每年领取的养老钱，与“老了”“每年都能领”相符。", "奖金": "语义：奖金是凭工作表现发的，爷爷已经老了，不再工作，不能领奖金。", "压岁钱": "语义：压岁钱是长辈给小孩过年的钱，与“爷爷老了”不符。", "学费": "搭配：学费是要付出的钱，不能说“领学费”。"}, "sentence_index": 0, "correct_answer": "年金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每个月都给我发年金。", "explanation": "这里应该用〈工资〉。年金是按年发放的养老钱，不是公司每个月发的薪水。"}, {"text": "他买房子时付了一笔年金。", "explanation": "这里应该用〈首付〉。年金是退休后按年领的养老钱，不能用来付买房的首付。"}, {"text": "政府给失业工人发放年金。", "explanation": "这里应该用〈补贴〉。年金是退休以后领的养老钱，失业工人不能领年金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年金", "is_correct": true, "explanation": "正确：年金是养老钱，外公把它存进银行是合理的。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：罚款是交给机关的钱，不能存进银行，也不是外公的收入。"}, {"text": "欠款", "is_correct": false, "explanation": "语义：欠款是要还的债，不是能存进银行的钱。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：账单是付款的凭据，不能说“把账单存在银行里”。"}], "explanations": {"年金": "正确：年金是养老钱，外公把它存进银行是合理的。", "罚款": "语义：罚款是交给机关的钱，不能存进银行，也不是外公的收入。", "欠款": "语义：欠款是要还的债，不是能存进银行的钱。", "账单": "搭配：账单是付款的凭据，不能说“把账单存在银行里”。"}, "sentence_index": 6, "correct_answer": "年金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月用年金交房租给房东。", "explanation": "这里应该用〈房租〉以外的钱，如〈工资〉。年金是老了以后按年领的养老钱，年轻人每月交房租用的是工资。"}, {"text": "司机超速，交了五百块年金。", "explanation": "这里应该用〈罚款〉。年金是养老用的钱，不能用来交罚款。"}, {"text": "他在赌场赢了一笔年金。", "explanation": "这里应该用〈赌赢的钱〉。年金是退休后按年领的养老钱，不是赌博赢来的钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲退休后，每年都能领一个年金。", "corrected_sentence": "我父亲退休后，每年都能领一笔年金。", "error_description": "“年金”的量词应为“笔”，不能用“个”。正确：一笔年金；错误：一个年金。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外公每年都能领一张年金。", "corrected_sentence": "外公每年都能领一笔年金。", "error_description": "“年金”是钱款，量词应为“笔”，不能用“张”。正确：一笔年金；错误：一张年金。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
