INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按年发放的养老金。", "primary_collocate": null, "pronunciation": "nián jīn", "ipa": "njɛn˧˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "国家每年给老人发年金。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养老院的老人每年都能按时收到年金。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年金每年十二月发一次。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚退休，这笔年金每年都会打到卡上。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府提高了老人的年金。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的年金已经到账了。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的年金比去年多了。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休工人每年可以领到一笔年金。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年金通常一年发一次，不是每月发。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办好手续后，你就能按年领年金。", "target_word": "年金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔年金", "label": "量词"}, {"form": "企业年金", "label": "复合"}, {"form": "养老年金", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家或单位按年度发放的养老金制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97716, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "年金", "is_correct": true, "explanation": "正确：年金指国家或单位按年发放的养老钱。"}, {"text": "年薪", "is_correct": false, "explanation": "xīn 与 jīn 声母不同（x / j），意思是一年的工资，不是养老金。"}, {"text": "年均", "is_correct": false, "explanation": "jūn 与 jīn 韵母不同（ü / i），意思是一年的平均数。"}, {"text": "年仅", "is_correct": false, "explanation": "jǐn（第三声）与 jīn（第一声）声调不同，意思是年纪只有，与“年金”不同。"}, {"text": "年近", "is_correct": false, "explanation": "jìn（第四声）与 jīn（第一声）声调不同，意思是年纪快到，不是养老金。"}], "explanations": {"年金": "正确：年金指国家或单位按年发放的养老钱。", "年薪": "xīn 与 jīn 声母不同（x / j），意思是一年的工资，不是养老金。", "年均": "jūn 与 jīn 韵母不同（ü / i），意思是一年的平均数。", "年仅": "jǐn（第三声）与 jīn（第一声）声调不同，意思是年纪只有，与“年金”不同。", "年近": "jìn（第四声）与 jīn（第一声）声调不同，意思是年纪快到，不是养老金。"}, "sentence_index": null, "correct_answer": "年金"}, "level_3": {"options": [{"text": "年金", "is_correct": true, "explanation": "正确：国家每年按时给老人发放的养老钱，与“国家每年给老人发”相符。"}, {"text": "压岁钱", "is_correct": false, "explanation": "语义：压岁钱是给孩子的，国家不会给老人发压岁钱。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：罚款是对违规者的处罚，国家不会把它发给老人。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：学费是要交的钱，不能说“发学费”。"}], "explanations": {"年金": "正确：国家每年按时给老人发放的养老钱，与“国家每年给老人发”相符。", "压岁钱": "语义：压岁钱是给孩子的，国家不会给老人发压岁钱。", "罚款": "语义：罚款是对违规者的处罚，国家不会把它发给老人。", "学费": "搭配：学费是要交的钱，不能说“发学费”。"}, "sentence_index": 0, "correct_answer": "年金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府给困难家庭发放年金。", "explanation": "这里应该用〈补贴〉。年金是退休后按年发放的养老钱，不是给困难家庭的救助。"}, {"text": "他去朋友的婚礼上随了一笔年金。", "explanation": "这里应该用〈礼金〉。年金是退休后按年领的养老钱，不能用来随礼。"}, {"text": "过年时，爷爷给孩子发年金。", "explanation": "这里应该用〈压岁钱〉。年金是给退休老人的养老钱，不能发给孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年金", "is_correct": true, "explanation": "正确：年金总额可以按年增加，与“这个城市的……比去年多了”相符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高是人的属性，不能说“城市的身高”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄一般指人或动物的岁数，“城市的年龄比去年多了”不是通常的说法，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重只用于人或动物，城市没有体重。"}], "explanations": {"年金": "正确：年金总额可以按年增加，与“这个城市的……比去年多了”相符。", "身高": "搭配：身高是人的属性，不能说“城市的身高”。", "年龄": "语义：年龄一般指人或动物的岁数，“城市的年龄比去年多了”不是通常的说法，句意不通。", "体重": "搭配：体重只用于人或动物，城市没有体重。"}, "sentence_index": 6, "correct_answer": "年金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为成绩好，拿到了一笔年金。", "explanation": "这里应该用〈奖学金〉。年金是退休后的养老钱，与成绩无关。"}, {"text": "车祸后，他得到了一笔年金。", "explanation": "这里应该用〈赔偿金〉。年金是退休后按年领的养老钱，不是事故后的赔偿。"}, {"text": "失业后，他领到了年金。", "explanation": "这里应该用〈救济金〉。年金要退休后才能领，失业时领的是救济金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人每年都能领一个年金。", "corrected_sentence": "这位老人每年都能领一笔年金。", "error_description": "“年金”的量词应为“笔”，不能用“个”。正确：一笔年金；错误：一个年金。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家每年都发放了这笔年金。", "corrected_sentence": "国家每年都发放这笔年金。", "error_description": "表示每年反复发生的动作不用“了”。正确：每年都发放这笔年金；错误：每年都发放了这笔年金。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
