INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97719, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很强，别人都要听他的。", "primary_collocate": null, "pronunciation": "qiáng shì", "ipa": "tɕʰjɑŋ˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "她性格很强势，家里的事都听她的。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司很强势，没人敢不同意。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈比较强势，爸爸什么都让着她。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经理说话很强势，大家都不敢反对。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太强势了，从来不听别人的意见。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强势的老板常常让员工很紧张。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看起来很温柔，其实很强势。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人在一起，总是女方比较强势。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很强势，开会时总是他一个人说。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对孩子不要太强势，要听听他的想法。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人的性格或态度强硬，让别人服从", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97719, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强势", "is_correct": true, "explanation": "强势：qiáng shì，形容性格或态度强硬、让别人服从，是本题要选的词。"}, {"text": "强制", "is_correct": false, "explanation": "强制：qiáng zhì，zh 与 sh 声母不同，意思是用强力迫使别人服从。"}, {"text": "情势", "is_correct": false, "explanation": "情势：qíng shì，韵母 ing 与 ang 不同，声调相同，意思是事情的形势。"}, {"text": "前世", "is_correct": false, "explanation": "前世：qián shì，韵母 an 与 ang 不同，声调相同，意思是前生。"}], "explanations": {"强势": "强势：qiáng shì，形容性格或态度强硬、让别人服从，是本题要选的词。", "强制": "强制：qiáng zhì，zh 与 sh 声母不同，意思是用强力迫使别人服从。", "情势": "情势：qíng shì，韵母 ing 与 ang 不同，声调相同，意思是事情的形势。", "前世": "前世：qián shì，韵母 an 与 ang 不同，声调相同，意思是前生。"}, "sentence_index": null, "correct_answer": "强势"}, "level_3": {"options": [{"text": "强势", "is_correct": true, "explanation": "正确：“家里的事都听她的”说明她在家中占主导，与“强势”的意思相符。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：“懦弱”指性格软弱，与后句“家里的事都听她的”相矛盾。"}, {"text": "胆小", "is_correct": false, "explanation": "语义：“胆小”指害怕，与“家里的事都听她的”所表现的主导地位相矛盾。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”多用于物体，不说“性格很坚硬”。"}], "explanations": {"强势": "正确：“家里的事都听她的”说明她在家中占主导，与“强势”的意思相符。", "懦弱": "语义：“懦弱”指性格软弱，与后句“家里的事都听她的”相矛盾。", "胆小": "语义：“胆小”指害怕，与“家里的事都听她的”所表现的主导地位相矛盾。", "坚硬": "搭配：“坚硬”多用于物体，不说“性格很坚硬”。"}, "sentence_index": 0, "correct_answer": "强势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥很强势，车辆经过很安全。", "explanation": "这里应该用〈坚固〉。强势用于人的性格或态度，桥梁等建筑要用坚固。"}, {"text": "这份证据很强势，足以让人信服。", "explanation": "这里应该用〈有力〉。强势说人的性格或态度，证据要用有力。"}, {"text": "他的身体很强势，能扛起两百斤的东西。", "explanation": "这里应该用〈强壮〉。强势用于人的性格或态度，身体的健壮要用强壮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强势", "is_correct": true, "explanation": "正确：“看起来很温柔，其实很强势”用“其实”转折，正与“温柔”形成对比。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”多形容空气或物体，不用来形容人的性格，“其实很干燥”说不通。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”多形容光线、颜色，不用来形容人的性格。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容身材或形象，与前句讲的性格不相符。"}], "explanations": {"强势": "正确：“看起来很温柔，其实很强势”用“其实”转折，正与“温柔”形成对比。", "干燥": "搭配：“干燥”多形容空气或物体，不用来形容人的性格，“其实很干燥”说不通。", "明亮": "搭配：“明亮”多形容光线、颜色，不用来形容人的性格。", "高大": "语义：“高大”形容身材或形象，与前句讲的性格不相符。"}, "sentence_index": 6, "correct_answer": "强势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条毛巾很强势，擦脸的时候很舒服。", "explanation": "这里应该用〈柔软〉。强势说人的性格或态度，毛巾等织物要用柔软。"}, {"text": "这条小溪的水很强势，能看见底下的石头。", "explanation": "这里应该用〈清澈〉。强势说人的性格或影响，溪水要用清澈。"}, {"text": "这条路很强势，骑车很省力。", "explanation": "这里应该用〈平坦〉。强势说人的性格或态度，道路要用平坦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
