INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97720, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "占有优势，有较大影响的。", "primary_collocate": null, "pronunciation": "qiáng shì", "ipa": "tɕʰjɑŋ˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这是一个强势品牌，很多人都在用。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美元最近很强势，别的货币都在下跌。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视曾经是最强势的媒体。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在手机市场非常强势。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强势文化常常会影响弱势文化。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队今年表现强势，一直排第一。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国内市场，这种饮料一直很强势，占了一半份额。", "target_word": "强势", "complexity_tier": "T3", "furigana": "zài guó nèi shì chǎng，zhè zhǒng yǐn liào yì zhí hěn qiáng shì，zhàn le yí bàn fèn é。", "sentence_source": "generated"}, {"text": "在这个行业里，大公司的地位比较强势。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个季度股市表现强势，价格一直在涨。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是行业里最强势的一家公司。", "target_word": "强势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "品牌、货币、媒体等在竞争中占优势、影响大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强势", "is_correct": true, "explanation": "强势：qiáng shì，指在市场或竞争中占优势、影响大，是本题要选的词。"}, {"text": "强制", "is_correct": false, "explanation": "强制：qiáng zhì，zh 与 sh 声母不同，意思是用强力迫使别人服从。"}, {"text": "情势", "is_correct": false, "explanation": "情势：qíng shì，韵母 ing 与 ang 不同，声调相同，意思是事情的形势。"}, {"text": "前世", "is_correct": false, "explanation": "前世：qián shì，韵母 an 与 ang 不同，声调相同，意思是前生。"}], "explanations": {"强势": "强势：qiáng shì，指在市场或竞争中占优势、影响大，是本题要选的词。", "强制": "强制：qiáng zhì，zh 与 sh 声母不同，意思是用强力迫使别人服从。", "情势": "情势：qíng shì，韵母 ing 与 ang 不同，声调相同，意思是事情的形势。", "前世": "前世：qián shì，韵母 an 与 ang 不同，声调相同，意思是前生。"}, "sentence_index": null, "correct_answer": "强势"}, "level_3": {"options": [{"text": "强势", "is_correct": true, "explanation": "正确：“强势品牌”指在市场上占优势的品牌，与“很多人都在用”相符。"}, {"text": "冷门", "is_correct": false, "explanation": "语义：“冷门”指不受欢迎、少人关注，与“很多人都在用”相矛盾。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“落后”指跟不上时代，与“很多人都在用”相矛盾。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”多形容质地，不用来修饰“品牌”。"}], "explanations": {"强势": "正确：“强势品牌”指在市场上占优势的品牌，与“很多人都在用”相符。", "冷门": "语义：“冷门”指不受欢迎、少人关注，与“很多人都在用”相矛盾。", "落后": "语义：“落后”指跟不上时代，与“很多人都在用”相矛盾。", "粗糙": "搭配：“粗糙”多形容质地，不用来修饰“品牌”。"}, "sentence_index": 0, "correct_answer": "强势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的力气很强势，一个人能扛起两袋米。", "explanation": "这里应该用〈大〉。强势用于占优势、影响大的人或企业，形容力气要用大。"}, {"text": "这块石头很强势，很难砸碎。", "explanation": "这里应该用〈坚硬〉。强势用于占优势、影响大的人或企业，石头要用坚硬。"}, {"text": "这床被子很强势，盖着很暖和。", "explanation": "这里应该用〈厚实〉。强势用于占优势、影响大，被子要用厚实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强势", "is_correct": true, "explanation": "正确：“一直很强势，占了一半份额”说明饮料在市场上占优势，与语境相符。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”多形容街道、场所，不用来形容饮料在市场上的表现。"}, {"text": "微弱", "is_correct": false, "explanation": "语义：“微弱”指力量小，与“占了一半份额”的表现相矛盾。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”指数量少，与“占了一半份额”的表现相矛盾。"}], "explanations": {"强势": "正确：“一直很强势，占了一半份额”说明饮料在市场上占优势，与语境相符。", "冷清": "搭配：“冷清”多形容街道、场所，不用来形容饮料在市场上的表现。", "微弱": "语义：“微弱”指力量小，与“占了一半份额”的表现相矛盾。", "稀少": "语义：“稀少”指数量少，与“占了一半份额”的表现相矛盾。"}, "sentence_index": 6, "correct_answer": "强势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把伞的骨架很强势，风大也不会翻。", "explanation": "这里应该用〈结实〉。强势用于占优势、影响大，伞骨要用结实。"}, {"text": "这把刀很强势，切菜很方便。", "explanation": "这里应该用〈锋利〉。强势用于占优势、影响大，刀具要用锋利。"}, {"text": "这张沙发很强势，坐上去很舒服。", "explanation": "这里应该用〈柔软〉。强势用于占优势、影响大，沙发要用柔软。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们强势得占领了市场。", "corrected_sentence": "他们强势地占领了市场。", "error_description": "错误：“强势得占领”，修饰动词的状语后面应该用“地”，不能用“得”。正确：“强势地占领”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家企业在行业里最很强势，别人都很难竞争。", "corrected_sentence": "这家企业在行业里最强势，别人都很难竞争。", "error_description": "错误：“最很强势”，两个程度副词“最”和“很”叠用。形容词前只能用一个程度副词。正确：“最强势”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
