INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97723, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "照着皇帝的话，写诗词。", "primary_collocate": null, "pronunciation": "yìng zhì", "ipa": "iŋ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "皇帝给了题目，大臣们照着要求应制。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝指定写梅花，诗人当即应制。", "target_word": "应制", "complexity_tier": "T3", "furigana": "huáng dì zhǐ dìng xiě méi huā, shī rén dāng jí yìng zhì.", "sentence_source": "generated"}, {"text": "他在朝廷里的工作，就是替皇帝应制。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝想看雪景诗，大臣们连夜应制。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宫里办诗会，大臣们按皇帝的意思应制。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他应制时很小心，怕写错了皇帝不高兴。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代有些官员靠应制得到皇帝的喜爱。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝出了题目，他想了想就开始应制。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位词人曾经应制，词句多歌颂太平。", "target_word": "应制", "complexity_tier": "T3", "furigana": "zhè wèi cí rén céng jīng yìng zhì, cí jù duō gē sòng tài píng.", "sentence_source": "generated"}, {"text": "他应制过几首词，都收在文集里。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应制诗", "label": "复合"}, {"form": "应制过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "按照皇帝的要求或题目写诗词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97723, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应制", "is_correct": true, "explanation": "正确。应制（yìng zhì）指照着皇帝的题目写诗词。"}, {"text": "印制", "is_correct": false, "explanation": "印制（yìn zhì）与应制（yìng zhì）韵尾不同（n 与 ng），意思是印刷、制作。"}, {"text": "英制", "is_correct": false, "explanation": "英制（yīng zhì）与应制（yìng zhì）第一个音节声调不同（第一声与第四声），意思是英国的度量衡制度。"}, {"text": "应试", "is_correct": false, "explanation": "应试（yìng shì）与应制（yìng zhì）第二个音节声母不同（sh 与 zh），意思是参加考试。"}, {"text": "硬纸", "is_correct": false, "explanation": "硬纸（yìng zhǐ）与应制（yìng zhì）第二个音节声调不同（第三声与第四声），意思是硬纸板。"}], "explanations": {"应制": "正确。应制（yìng zhì）指照着皇帝的题目写诗词。", "印制": "印制（yìn zhì）与应制（yìng zhì）韵尾不同（n 与 ng），意思是印刷、制作。", "英制": "英制（yīng zhì）与应制（yìng zhì）第一个音节声调不同（第一声与第四声），意思是英国的度量衡制度。", "应试": "应试（yìng shì）与应制（yìng zhì）第二个音节声母不同（sh 与 zh），意思是参加考试。", "硬纸": "硬纸（yìng zhǐ）与应制（yìng zhì）第二个音节声调不同（第三声与第四声），意思是硬纸板。"}, "sentence_index": null, "correct_answer": "应制"}, "level_3": {"options": [{"text": "应制", "is_correct": true, "explanation": "正确。“照着要求应制”指照着皇帝给的题目写诗词。"}, {"text": "洗涤", "is_correct": false, "explanation": "语义：“洗涤”是洗东西，与“皇帝给了题目”的情境不符。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”指剪枝或剪毛，与题目无关。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”需要搬运的东西作宾语，这句话里没有可以搬的对象。"}], "explanations": {"应制": "正确。“照着要求应制”指照着皇帝给的题目写诗词。", "洗涤": "语义：“洗涤”是洗东西，与“皇帝给了题目”的情境不符。", "修剪": "语义：“修剪”指剪枝或剪毛，与题目无关。", "搬运": "配价：“搬运”需要搬运的东西作宾语，这句话里没有可以搬的对象。"}, "sentence_index": 0, "correct_answer": "应制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为新曲应制，写得很好。", "explanation": "这里应该用〈填词〉。应制是照皇帝的题目写诗词，为曲子配词要说“填词”。"}, {"text": "老师提了一个问题，他马上站起来应制。", "explanation": "这里应该用〈回答〉。应制是照皇帝的题目写诗词，回答老师的问题要说“回答”。"}, {"text": "他在湖边应制，抒发心情。", "explanation": "这里应该用〈赋诗〉。应制必须是照皇帝的题目而作，自己在湖边随兴作诗要说“赋诗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应制", "is_correct": true, "explanation": "正确。“靠应制得到皇帝的喜爱”指凭借为皇帝写诗词获得赏识。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：“砍伐”是砍树，与“得到皇帝的喜爱”没有关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是能让人得到皇帝喜爱的途径，句子说不通。"}, {"text": "驯养", "is_correct": false, "explanation": "配价：“驯养”要有被驯养的动物作宾语，这里后面缺少宾语。"}], "explanations": {"应制": "正确。“靠应制得到皇帝的喜爱”指凭借为皇帝写诗词获得赏识。", "砍伐": "语义：“砍伐”是砍树，与“得到皇帝的喜爱”没有关系。", "睡觉": "语义：“睡觉”不是能让人得到皇帝喜爱的途径，句子说不通。", "驯养": "配价：“驯养”要有被驯养的动物作宾语，这里后面缺少宾语。"}, "sentence_index": 6, "correct_answer": "应制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为店铺应制招牌，字写得很漂亮。", "explanation": "这里应该用〈题写〉。应制只指照皇帝的题目写诗词，给店铺写招牌要说“题写”。"}, {"text": "他应制历史书，写了十年才完成。", "explanation": "这里应该用〈撰写〉。应制不能用来指写历史书，撰写书籍要说“撰写”。"}, {"text": "他很会应制，每天都画山水。", "explanation": "这里应该用〈作画〉。应制是照题目写诗词，画画要说“作画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "皇帝一出题，诗人就立刻应制过。", "corrected_sentence": "皇帝一出题，诗人就立刻应制。", "error_description": "“立刻”说的是马上发生的一次动作，不能再加“过”表示经历，应说“就立刻应制”，不能说“就立刻应制过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在应制过几首词，你先等一下。", "corrected_sentence": "他正在应制几首词，你先等一下。", "error_description": "“正在”表示动作进行中，不能与表示经历的“过”同用，应去掉“过”，说“正在应制几首词”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97724, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97724, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "奉皇帝之命写作诗文。", "primary_collocate": null, "pronunciation": "yìng zhì", "ipa": "iŋ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "唐朝的大臣常常奉命应制，写诗给皇帝看。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝在宫里设宴，席间让大臣们应制。", "target_word": "应制", "complexity_tier": "T3", "furigana": "huáng dì zài gōng lǐ shè yàn, xí jiān ràng dà chén men yìng zhì.", "sentence_source": "generated"}, {"text": "这位诗人年轻时在朝中应制，写了不少颂扬皇帝的诗。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝让他当场应制，他很快就写好了。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，皇帝去花园赏花，大臣们跟着应制。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢应制，觉得那样的诗没有真感情。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宴会上，皇帝一说题目，大家就开始应制。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宰相应制写的诗，皇帝看了很满意。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李白在宫中应制，皇帝很喜欢他的诗。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他应制过很多次，可是留下来的好诗不多。", "target_word": "应制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应制诗", "label": "复合"}, {"form": "应制过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "古代臣子奉皇帝之命写作诗文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97724, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应制", "is_correct": true, "explanation": "正确。应制（yìng zhì）指奉皇帝之命写作诗文。"}, {"text": "印制", "is_correct": false, "explanation": "印制（yìn zhì）与应制（yìng zhì）韵尾不同（n 与 ng），意思是印刷、制作。"}, {"text": "英制", "is_correct": false, "explanation": "英制（yīng zhì）与应制（yìng zhì）第一个音节声调不同（第一声与第四声），意思是英国的度量衡制度。"}, {"text": "应试", "is_correct": false, "explanation": "应试（yìng shì）与应制（yìng zhì）第二个音节声母不同（sh 与 zh），意思是参加考试。"}, {"text": "硬纸", "is_correct": false, "explanation": "硬纸（yìng zhǐ）与应制（yìng zhì）第二个音节声调不同（第三声与第四声），意思是硬纸板。"}], "explanations": {"应制": "正确。应制（yìng zhì）指奉皇帝之命写作诗文。", "印制": "印制（yìn zhì）与应制（yìng zhì）韵尾不同（n 与 ng），意思是印刷、制作。", "英制": "英制（yīng zhì）与应制（yìng zhì）第一个音节声调不同（第一声与第四声），意思是英国的度量衡制度。", "应试": "应试（yìng shì）与应制（yìng zhì）第二个音节声母不同（sh 与 zh），意思是参加考试。", "硬纸": "硬纸（yìng zhǐ）与应制（yìng zhì）第二个音节声调不同（第三声与第四声），意思是硬纸板。"}, "sentence_index": null, "correct_answer": "应制"}, "level_3": {"options": [{"text": "应制", "is_correct": true, "explanation": "正确。“奉命应制”指奉皇帝之命作诗，与后半句“写诗给皇帝看”一致。"}, {"text": "行刑", "is_correct": false, "explanation": "语义：“行刑”指执行刑罚，与后半句“写诗给皇帝看”对不上。"}, {"text": "辞官", "is_correct": false, "explanation": "语义：“辞官”是自己辞去官职，与“奉命”的前提矛盾。"}, {"text": "纳贡", "is_correct": false, "explanation": "语义：“纳贡”是向朝廷进献财物，与后半句“写诗给皇帝看”的内容不符，句意不通。"}], "explanations": {"应制": "正确。“奉命应制”指奉皇帝之命作诗，与后半句“写诗给皇帝看”一致。", "行刑": "语义：“行刑”指执行刑罚，与后半句“写诗给皇帝看”对不上。", "辞官": "语义：“辞官”是自己辞去官职，与“奉命”的前提矛盾。", "纳贡": "语义：“纳贡”是向朝廷进献财物，与后半句“写诗给皇帝看”的内容不符，句意不通。"}, "sentence_index": 0, "correct_answer": "应制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在家里没事，就应制了几首诗。", "explanation": "这里应该用〈作诗〉。应制指奉皇帝之命写作诗文，没有皇帝的命令，只能说“作诗”。"}, {"text": "他看到征兵通知，决定应制去当兵。", "explanation": "这里应该用〈应征〉。应制只指奉皇帝之命作诗文，报名当兵要说“应征”。"}, {"text": "节日里，他写了一首应制的诗送给朋友。", "explanation": "这里应该用〈应景〉。应制特指奉皇帝之命作诗，自己为节日写的诗要说“应景”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应制", "is_correct": true, "explanation": "正确。“皇帝一说题目，大家就开始应制”说的是照题目写诗，与情境相符。"}, {"text": "进攻", "is_correct": false, "explanation": "语义：“进攻”是军事行动，与宴会上的情境不合。"}, {"text": "呕吐", "is_correct": false, "explanation": "语义：“呕吐”是身体反应，与皇帝出题、大家作诗的情境无关。"}, {"text": "赠送", "is_correct": false, "explanation": "配价：“赠送”要有送的人和送的东西两个对象，这里后面缺少宾语。"}], "explanations": {"应制": "正确。“皇帝一说题目，大家就开始应制”说的是照题目写诗，与情境相符。", "进攻": "语义：“进攻”是军事行动，与宴会上的情境不合。", "呕吐": "语义：“呕吐”是身体反应，与皇帝出题、大家作诗的情境无关。", "赠送": "配价：“赠送”要有送的人和送的东西两个对象，这里后面缺少宾语。"}, "sentence_index": 6, "correct_answer": "应制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在墙上应制，留下了名字。", "explanation": "这里应该用〈题诗〉。应制指奉皇帝之命作诗文，自己在墙上题字不能说“应制”。"}, {"text": "两位诗人在酒席上互相应制，你一首我一首。", "explanation": "这里应该用〈唱和〉。应制是臣子奉命作诗，不是双方互相应和。"}, {"text": "他去考场应制，考得很好。", "explanation": "这里应该用〈应试〉。应制只用于奉命作诗文，参加考试要说“应试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在应制过三首诗，皇帝在等他。", "corrected_sentence": "他正在应制三首诗，皇帝在等他。", "error_description": "“正在”表示动作进行中，不能与表示经历的“过”同用，应去掉“过”，说“正在应制三首诗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没应制了，所以很紧张。", "corrected_sentence": "他从来没应制过，所以很紧张。", "error_description": "否定经历要用“没……过”，“了”不能用于“从来没……”，应说“从来没应制过”，不能说“从来没应制了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
