INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97727, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想起很久以前的人或事，很想再见到。", "primary_collocate": null, "pronunciation": "huái niàn", "ipa": "xu̯ai̯˧˥ n̠i̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我很怀念多年没见的老朋友。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怀念着远方的妻子和孩子。", "target_word": "怀念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业十年了，我还怀念我的老师。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出国以后，她特别怀念家人。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷常怀念已经走了的老伴。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我怀念那些一起踢球的好兄弟。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住院的时候，我最怀念家里的人。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怀念过那位帮助他的老邻居。", "target_word": "怀念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开北京后，我常常怀念那里的老朋友。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她怀念了外婆很多年。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "怀念了", "label": "体标"}, {"form": "怀念着", "label": "体标"}, {"form": "怀念过", "label": "体标"}], "register": "中性", "sense_fingerprint": "想起很久以前的人或事并渴望再见到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97727, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怀念", "is_correct": true, "explanation": "“怀念”指想起很久以前的人并很想再见到，多年没见的老朋友正符合句意。"}, {"text": "处罚", "is_correct": false, "explanation": "语义：“处罚”是对违规者施加惩戒，用于老朋友意思不通。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是物品，不能说购买一位老朋友。"}, {"text": "驳斥", "is_correct": false, "explanation": "语义：“驳斥”是反驳别人的言论，对象是观点，不能说驳斥老朋友。"}], "explanations": {"怀念": "“怀念”指想起很久以前的人并很想再见到，多年没见的老朋友正符合句意。", "处罚": "语义：“处罚”是对违规者施加惩戒，用于老朋友意思不通。", "购买": "搭配：“购买”的对象是物品，不能说购买一位老朋友。", "驳斥": "语义：“驳斥”是反驳别人的言论，对象是观点，不能说驳斥老朋友。"}, "sentence_index": 0, "correct_answer": "怀念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈怀念孩子的健康。", "explanation": "这里应该用〈担心〉。怀念指思念过去或远方的人，不能用于对当前健康的忧虑。"}, {"text": "开学第一天，大家热烈怀念新同学。", "explanation": "这里应该用〈欢迎〉。怀念指想起以前的人或事、很想再见到，刚开学的新同学还没有“过去”，应用“欢迎”。"}, {"text": "工人怀念了水管。", "explanation": "这里应该用〈修理〉。怀念的对象是人或过去的事，不能用于器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怀念", "is_correct": true, "explanation": "“怀念”指思念过去的人，住院时我最想念家里的人，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间或场所，不能说打扫家里的人。"}, {"text": "批改", "is_correct": false, "explanation": "语义：“批改”是给作业或试卷打分修改，与句中的人无关。"}, {"text": "启动", "is_correct": false, "explanation": "搭配：“启动”多用于设备或程序，不能带人作宾语。"}], "explanations": {"怀念": "“怀念”指思念过去的人，住院时我最想念家里的人，符合句意。", "打扫": "搭配：“打扫”的对象是房间或场所，不能说打扫家里的人。", "批改": "语义：“批改”是给作业或试卷打分修改，与句中的人无关。", "启动": "搭配：“启动”多用于设备或程序，不能带人作宾语。"}, "sentence_index": 6, "correct_answer": "怀念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "强盗怀念了那家商店。", "explanation": "这里应该用〈抢劫〉。怀念表示思念，抢劫是违法行为，二者意思完全不符。"}, {"text": "会计怀念了这些账目。", "explanation": "这里应该用〈统计〉。怀念的对象是人或过去的事，不能用于账目。"}, {"text": "警察怀念了小偷，把他送进了派出所。", "explanation": "这里应该用〈抓捕〉。怀念是想念过去的人或事，抓捕是执法行动，这里是把人送进派出所，不是想念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我怀念了着远方的老朋友。", "corrected_sentence": "我怀念着远方的老朋友。", "error_description": "错误形式：“怀念了着”；正确形式：“怀念着”。“了”和“着”不能同时用在同一动词后，表示持续只用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "离开家以后，我把最怀念妈妈做的饭。", "corrected_sentence": "离开家以后，我最怀念妈妈做的饭。", "error_description": "错误形式：“把最怀念”；正确形式：“最怀念”。“怀念”不是处置动词，不能用于“把”字句，应去掉“把”，副词“最”直接修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
