INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "思念；回想过去的人或事。", "primary_collocate": null, "pronunciation": "huái niàn", "ipa": "xu̯ai̯˧˥ n̠i̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我很怀念小时候的夏天。", "target_word": "怀念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他常常怀念去世的爷爷。", "target_word": "怀念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "离开家乡以后，我一直怀念妈妈做的菜。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老同学们聚在一起，怀念过去的日子。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她怀念着那座小城的春天。", "target_word": "怀念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怀念过大学时的生活。", "target_word": "怀念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶总是怀念年轻时的朋友。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬到国外后，他十分怀念老家的邻居。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到这些旧照片，我怀念了很久。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首老歌让很多人怀念那个年代。", "target_word": "怀念", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "怀念了", "label": "体标"}, {"form": "怀念着", "label": "体标"}, {"form": "怀念过", "label": "体标"}], "register": "中性", "sense_fingerprint": "思念并回想过去的人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfab81e-468a-497b-ad8b-db3659d2dc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怀念", "is_correct": true, "explanation": "“怀念”指思念过去的人或事，小时候的夏天是过去的时光，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是修补器物，不能用于夏天，句意不通。"}, {"text": "配合", "is_correct": false, "explanation": "搭配：“配合”的对象是人或工作，不能说配合一个夏天。"}, {"text": "登记", "is_correct": false, "explanation": "语义：“登记”是办理登记手续，与回想童年的语境毫不相关。"}], "explanations": {"怀念": "“怀念”指思念过去的人或事，小时候的夏天是过去的时光，符合句意。", "修理": "语义：“修理”是修补器物，不能用于夏天，句意不通。", "配合": "搭配：“配合”的对象是人或工作，不能说配合一个夏天。", "登记": "语义：“登记”是办理登记手续，与回想童年的语境毫不相关。"}, "sentence_index": 0, "correct_answer": "怀念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们怀念明天的比赛。", "explanation": "这里应该用〈期待〉。怀念指思念过去的人或事，不能用于尚未发生的比赛。"}, {"text": "我怀念着未来的生活。", "explanation": "这里应该用〈想象〉。怀念只用于过去，未来的生活不能用“怀念”。"}, {"text": "妈妈怀念着正在发烧的孩子。", "explanation": "这里应该用〈惦记〉。怀念指想念已经离开或过去的人，孩子正在发烧就在身边，应用“惦记”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怀念", "is_correct": true, "explanation": "“怀念”指思念过去的人，奶奶想念年轻时的朋友，符合句意。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等交通工具，不能说驾驶朋友。"}, {"text": "抓", "is_correct": false, "explanation": "语义：“抓”是用手握住或逮捕，用于朋友意思不通。"}, {"text": "颁发", "is_correct": false, "explanation": "配价：“颁发”需要颁发者、接受者和证书等物件，不能以朋友作宾语。"}], "explanations": {"怀念": "“怀念”指思念过去的人，奶奶想念年轻时的朋友，符合句意。", "驾驶": "搭配：“驾驶”的对象是车辆等交通工具，不能说驾驶朋友。", "抓": "语义：“抓”是用手握住或逮捕，用于朋友意思不通。", "颁发": "配价：“颁发”需要颁发者、接受者和证书等物件，不能以朋友作宾语。"}, "sentence_index": 6, "correct_answer": "怀念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天又下大雨了，我怀念这种天气，真烦人。", "explanation": "这里应该用〈讨厌〉。怀念表示思念，与“讨厌”的反感之情相反；“真烦人”说明说话人厌烦，应用“讨厌”。"}, {"text": "他怀念哥哥的成绩。", "explanation": "这里应该用〈嫉妒〉。怀念是想念过去的人或事，不能用于羡慕或妒忌别人的成绩。"}, {"text": "他怀念每一分钱。", "explanation": "这里应该用〈节省〉。怀念的对象是人或事，不能用于钱的花用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她怀念着过远方的故乡。", "corrected_sentence": "她怀念过远方的故乡。", "error_description": "错误形式：“怀念着过”；正确形式：“怀念过”。“着”表示持续状态，与表示经历的“过”不能同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把怀念那个年代。", "corrected_sentence": "他怀念那个年代。", "error_description": "错误形式：“把怀念”；正确形式：“怀念”。“怀念”不是处置动词，不能用于“把”字句，应去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b11ff30-43fe-47f4-a1d3-71dcb6449e87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97731, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "继续", "is_correct": true, "explanation": "反义：“打住”是停下来、到此为止，“继续”是接着往下做或说，两者相对。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”是探求事理，与“打住”的意思没有相对关系。"}, {"text": "购买", "is_correct": false, "explanation": "无关：“购买”是花钱得到东西，与“打住”没有相对关系。"}, {"text": "收拾", "is_correct": false, "explanation": "无关：“收拾”是整理、整顿，与“打住”的停止义不相对。"}], "correct_answer": "继续", "explanations": {"继续": "反义：“打住”是停下来、到此为止，“继续”是接着往下做或说，两者相对。", "研究": "无关：“研究”是探求事理，与“打住”的意思没有相对关系。", "购买": "无关：“购买”是花钱得到东西，与“打住”没有相对关系。", "收拾": "无关：“收拾”是整理、整顿，与“打住”的停止义不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97731, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "继续", "is_correct": true, "explanation": "反义：“打住”是停下来、到此为止，“继续”是接着往下做或说，两者相对。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”是修复坏了的东西，与“打住”没有相对关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：“旅行”是到外地游览，与“打住”的意思不相对。"}, {"text": "种植", "is_correct": false, "explanation": "无关：“种植”是栽培植物，与“打住”没有相对关系。"}], "correct_answer": "继续", "explanations": {"继续": "反义：“打住”是停下来、到此为止，“继续”是接着往下做或说，两者相对。", "修理": "无关：“修理”是修复坏了的东西，与“打住”没有相对关系。", "旅行": "无关：“旅行”是到外地游览，与“打住”的意思不相对。", "种植": "无关：“种植”是栽培植物，与“打住”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97731, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别说了，到这里为止。", "primary_collocate": null, "pronunciation": "dǎ zhù", "ipa": "ta²¹⁴ ʈʂu⁵¹", "syllable_count": 2, "sentences": [{"text": "好了好了，你打住吧。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说个没完，我只好叫他打住。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打住，这件事别再提了。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的抱怨可以打住了。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说起来没完，爸爸笑着让她打住。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友一讲笑话，我就让他打住。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个话题太伤心，请你打住。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这里，老师说：“好，打住。”", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们别吵了，都打住吧。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚想开口讲，我就叫他打住了。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打住了", "label": "体标"}], "register": "口语", "sense_fingerprint": "叫人停止说话，不要再往下说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97731, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叹气", "is_correct": false, "explanation": "语义：“叹气”是发出长长的呼气表示忧愁，不能让对方停止说话。"}, {"text": "打住", "is_correct": true, "explanation": "正确：叫人停止说话、到此为止，符合句意。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的反应，句中要表示让对方停止，两者不符。"}, {"text": "眨眼", "is_correct": false, "explanation": "搭配：“眨眼”不能用来让人停止说话，与“好了好了”的语气不搭。"}], "explanations": {"叹气": "语义：“叹气”是发出长长的呼气表示忧愁，不能让对方停止说话。", "打住": "正确：叫人停止说话、到此为止，符合句意。", "咳嗽": "语义：“咳嗽”是身体的反应，句中要表示让对方停止，两者不符。", "眨眼": "搭配：“眨眼”不能用来让人停止说话，与“好了好了”的语气不搭。"}, "sentence_index": 0, "correct_answer": "打住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂因为环保问题打住了生产。", "explanation": "这里应该用〈停止〉。“打住”多用于叫人别再说或到此为止，不用于工厂生产的停止。"}, {"text": "他打住了教室。", "explanation": "这里应该用〈进〉。“打住”表示停止或到此为止，不能表示进入某处。"}, {"text": "他一拳打住了对手的脸。", "explanation": "这里应该用〈击中〉。“打住”表示停止，不能表示击打或击中某人的身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数数", "is_correct": false, "explanation": "语义：“数数”是计算数目，不能表示请对方停止谈论伤心的话题。"}, {"text": "打住", "is_correct": true, "explanation": "正确：请对方停止谈论，到此为止，符合句意。"}, {"text": "入睡", "is_correct": false, "explanation": "语义：“入睡”是睡着，不能让对方停止谈论这个话题。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与停止谈论伤心的话题无关，句意不通。"}], "explanations": {"数数": "语义：“数数”是计算数目，不能表示请对方停止谈论伤心的话题。", "打住": "正确：请对方停止谈论，到此为止，符合句意。", "入睡": "语义：“入睡”是睡着，不能让对方停止谈论这个话题。", "洗澡": "语义：“洗澡”与停止谈论伤心的话题无关，句意不通。"}, "sentence_index": 6, "correct_answer": "打住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和家人打住了关系。", "explanation": "这里应该用〈断绝〉。“打住”用于停止说话或行动，不用于人际关系的断绝。"}, {"text": "我去超市打住了牛奶。", "explanation": "这里应该用〈买〉。“打住”表示停止或到此为止，不能表示购买东西。"}, {"text": "他的脸色很快打住了。", "explanation": "这里应该用〈变白〉。“打住”不能用来描述脸色的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚说到一半，就打住了着。", "corrected_sentence": "他刚说到一半，就打住了。", "error_description": "错误形式「打住了着」，「了」和「着」不能同时用在同一动词后。正确形式「打住了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说完这句，就打住完了。", "corrected_sentence": "他说完这句，就打住了。", "error_description": "错误形式“打住完了”，正确形式“打住了”。“打住”已表示停止，后面不能再接结果补语“完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97732, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "继续", "is_correct": true, "explanation": "反义：“打住”是停下来、不再继续，“继续”与之相对。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”是修复坏了的东西，与“打住”没有相对关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：“旅行”是到外地游览，与“打住”的意思不相对。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”是探求事理，与“打住”没有相对关系。"}], "correct_answer": "继续", "explanations": {"继续": "反义：“打住”是停下来、不再继续，“继续”与之相对。", "修理": "无关：“修理”是修复坏了的东西，与“打住”没有相对关系。", "旅行": "无关：“旅行”是到外地游览，与“打住”的意思不相对。", "研究": "无关：“研究”是探求事理，与“打住”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97732, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "继续", "is_correct": true, "explanation": "反义：“打住”是停下来、不再继续，“继续”与之相对。"}, {"text": "购买", "is_correct": false, "explanation": "无关：“购买”是花钱得到东西，与“打住”没有相对关系。"}, {"text": "收拾", "is_correct": false, "explanation": "无关：“收拾”是整理、整顿，与“打住”的停止义不相对。"}, {"text": "种植", "is_correct": false, "explanation": "无关：“种植”是栽培植物，与“打住”没有相对关系。"}], "correct_answer": "继续", "explanations": {"继续": "反义：“打住”是停下来、不再继续，“继续”与之相对。", "购买": "无关：“购买”是花钱得到东西，与“打住”没有相对关系。", "收拾": "无关：“收拾”是整理、整顿，与“打住”的停止义不相对。", "种植": "无关：“种植”是栽培植物，与“打住”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97732, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "停止；到此为止。", "primary_collocate": null, "pronunciation": "dǎ zhù", "ipa": "ta²¹⁴ ʈʂu⁵¹", "syllable_count": 2, "sentences": [{"text": "话说到这儿就打住吧。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里他说着说着，忽然打住了。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲到这儿，老师笑着打住了。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划到这里就打住吧。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想说下去，又打住了。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作先打住，我们去吃饭。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聊天打住，该上课了。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了我一眼，没再往下说，就打住了。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西不能没完没了，该打住时要打住。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "争论打住后，大家都安静了。", "target_word": "打住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打住了", "label": "体标"}], "register": "口语", "sense_fingerprint": "说话或做事停下来，不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脱鞋", "is_correct": false, "explanation": "语义：“脱鞋”是把鞋子脱下，与结束话题无关，句意不通。"}, {"text": "打住", "is_correct": true, "explanation": "正确：表示到此为止、停下来不再往下说，符合句意。"}, {"text": "登机", "is_correct": false, "explanation": "搭配：“登机”指上飞机，不能用来表示到此为止。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的反应，不能用来结束谈话。"}], "explanations": {"脱鞋": "语义：“脱鞋”是把鞋子脱下，与结束话题无关，句意不通。", "打住": "正确：表示到此为止、停下来不再往下说，符合句意。", "登机": "搭配：“登机”指上飞机，不能用来表示到此为止。", "咳嗽": "语义：“咳嗽”是身体的反应，不能用来结束谈话。"}, "sentence_index": 0, "correct_answer": "打住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打住了一封信。", "explanation": "这里应该用〈写〉。“打住”表示停下来或到此为止，不能表示完成书写一封信。"}, {"text": "他的信心打住了。", "explanation": "这里应该用〈增强〉。“打住”不能用来描述信心的增长。"}, {"text": "他打住了一百块钱。", "explanation": "这里应该用〈存〉。“打住”表示停止或到此为止，不能用于存钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出门", "is_correct": false, "explanation": "语义：“出门”是离开家，与聊天的停止无关，句意不通。"}, {"text": "打住", "is_correct": true, "explanation": "正确：聊天到此为止、停下来，符合句意。"}, {"text": "洗碗", "is_correct": false, "explanation": "语义：“洗碗”是做家务，不能表示聊天的停止。"}, {"text": "数数", "is_correct": false, "explanation": "搭配：“数数”要求计数的对象，与“聊天”及后句不搭。"}], "explanations": {"出门": "语义：“出门”是离开家，与聊天的停止无关，句意不通。", "打住": "正确：聊天到此为止、停下来，符合句意。", "洗碗": "语义：“洗碗”是做家务，不能表示聊天的停止。", "数数": "搭配：“数数”要求计数的对象，与“聊天”及后句不搭。"}, "sentence_index": 6, "correct_answer": "打住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们终于打住了协议。", "explanation": "这里应该用〈达成〉。“打住”表示停止，不能用于达成协议。"}, {"text": "你打住了我的电话号码。", "explanation": "这里应该用〈记住〉。“打住”表示停止或到此为止，不能表示记住号码。"}, {"text": "我的生日终于打住了。", "explanation": "这里应该用〈到来〉。“打住”不能用来描述生日的到来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "讲到一半，他就打住了着。", "corrected_sentence": "讲到一半，他就打住了。", "error_description": "错误形式「打住了着」，「了」和「着」不能同时用在同一动词后。正确形式「打住了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听完这句话，就打住完了。", "corrected_sentence": "他听完这句话，就打住了。", "error_description": "错误形式“打住完了”，正确形式“打住了”。“打住”已表示停止，后面不能再接结果补语“完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
