INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97733, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手拉着，让人不会倒下。", "primary_collocate": null, "pronunciation": "fú", "ipa": "fu˧˥", "syllable_count": 1, "sentences": [{"text": "老奶奶过马路时，小李扶着她。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩摔倒了，妈妈马上把他扶起来。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走不稳，我一直扶着他的手臂。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人想下床，护士扶他慢慢站起来。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路很滑，你扶好奶奶，别让她摔倒。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝多了，两个同学扶他回家。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人上车很慢，司机下来扶了他一把。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我受伤了，你能扶我去医院吗？", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕妇上楼不方便，丈夫在旁边扶着她。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路人看见老人摔倒，马上跑去扶他。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扶着", "label": "体标（着）"}, {"form": "扶了", "label": "体标（了）"}, {"form": "扶过", "label": "体标（过）"}, {"form": "扶起", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手搀扶或拉住人（老人、病人、孩子等），帮他站稳或站起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97733, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扶", "is_correct": true, "explanation": "正确答案。扶指用手拉着或搀着人，让人不倒下。"}, {"text": "夫", "is_correct": false, "explanation": "夫的 fū（第一声）与扶的 fú（第二声）声调不同，夫指丈夫。"}, {"text": "富", "is_correct": false, "explanation": "富的 fù（第四声）与扶的 fú（第二声）声调不同，富指财产多。"}, {"text": "湖", "is_correct": false, "explanation": "湖的声母 h 与扶的 f 不同，湖指水面宽阔的湖泊。"}, {"text": "父", "is_correct": false, "explanation": "父的 fù（第四声）与扶的 fú（第二声）声调不同，父指父亲。"}], "explanations": {"扶": "正确答案。扶指用手拉着或搀着人，让人不倒下。", "夫": "夫的 fū（第一声）与扶的 fú（第二声）声调不同，夫指丈夫。", "富": "富的 fù（第四声）与扶的 fú（第二声）声调不同，富指财产多。", "湖": "湖的声母 h 与扶的 f 不同，湖指水面宽阔的湖泊。", "父": "父的 fù（第四声）与扶的 fú（第二声）声调不同，父指父亲。"}, "sentence_index": null, "correct_answer": "扶"}, "level_3": {"options": [{"text": "扶", "is_correct": true, "explanation": "扶指搀着人帮助行走，符合“老奶奶过马路时，小李扶着她”的语境。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”与帮老奶奶过马路的行为矛盾，句子说的是帮助。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”的对象是人时表示殴打，不能说“打着她过马路”。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”与“过马路时”的照顾性动作相矛盾。"}], "explanations": {"扶": "扶指搀着人帮助行走，符合“老奶奶过马路时，小李扶着她”的语境。", "批评": "语义：“批评”与帮老奶奶过马路的行为矛盾，句子说的是帮助。", "打": "搭配：“打”的对象是人时表示殴打，不能说“打着她过马路”。", "骂": "语义：“骂”与“过马路时”的照顾性动作相矛盾。"}, "sentence_index": 0, "correct_answer": "扶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士扶他聊天，病人很开心。", "explanation": "这里应该用〈陪〉。扶表示搀着人使其不倒，陪人聊天要用陪。"}, {"text": "她从柜子里扶出了一本书。", "explanation": "这里应该用〈取〉。扶表示用手搀着使人不倒，从柜子里拿出书要用取。"}, {"text": "他扶通了朋友的电话。", "explanation": "这里应该用〈拨〉。扶表示用手支撑或搀着，不能用来拨号，拨通电话要用拨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97733, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扶", "is_correct": true, "explanation": "正确答案。扶指用手拉着或搀着人，让人不倒下。"}, {"text": "付", "is_correct": false, "explanation": "付的 fù（第四声）与扶的 fú（第二声）声调不同，付指支付、交给。"}, {"text": "副", "is_correct": false, "explanation": "副的 fù（第四声）与扶的 fú（第二声）声调不同，副指副手、次要的。"}, {"text": "斧", "is_correct": false, "explanation": "斧的 fǔ（第三声）与扶的 fú（第二声）声调不同，斧指斧头。"}, {"text": "壶", "is_correct": false, "explanation": "壶的声母 h 与扶的 f 不同，壶指盛水或泡茶的器具。"}], "explanations": {"扶": "正确答案。扶指用手拉着或搀着人，让人不倒下。", "付": "付的 fù（第四声）与扶的 fú（第二声）声调不同，付指支付、交给。", "副": "副的 fù（第四声）与扶的 fú（第二声）声调不同，副指副手、次要的。", "斧": "斧的 fǔ（第三声）与扶的 fú（第二声）声调不同，斧指斧头。", "壶": "壶的声母 h 与扶的 f 不同，壶指盛水或泡茶的器具。"}, "sentence_index": null, "correct_answer": "扶"}, "level_3": {"options": [{"text": "扶", "is_correct": true, "explanation": "扶指伸手帮人稳住身体，符合“司机下来扶了他一把”的帮助语境。"}, {"text": "按", "is_correct": false, "explanation": "搭配：“按”与“一把”组合表示用力压，不能用来表示帮老人上车。"}, {"text": "掐", "is_correct": false, "explanation": "语义：“掐”指用指甲捏，与老人上车很慢时的帮助相矛盾。"}, {"text": "踹", "is_correct": false, "explanation": "语义：“踹”是用脚猛踢，与帮助老人上车的语境相矛盾。"}], "explanations": {"扶": "扶指伸手帮人稳住身体，符合“司机下来扶了他一把”的帮助语境。", "按": "搭配：“按”与“一把”组合表示用力压，不能用来表示帮老人上车。", "掐": "语义：“掐”指用指甲捏，与老人上车很慢时的帮助相矛盾。", "踹": "语义：“踹”是用脚猛踢，与帮助老人上车的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "扶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她认真地扶了一封信。", "explanation": "这里应该用〈写〉。扶表示用手支撑，不能用来写信，写信要用写。"}, {"text": "他扶了一口水。", "explanation": "这里应该用〈喝〉。扶表示支撑，不能表示喝水，喝水要用喝。"}, {"text": "老师扶了一个故事。", "explanation": "这里应该用〈讲〉。扶表示支撑，不能表示讲述故事，讲故事要用讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人摔倒了，路人赶紧把他扶起了来。", "corrected_sentence": "老人摔倒了，路人赶紧把他扶起来。", "error_description": "补语错误：趋向补语“起来”不能拆开插入“了”，应说“扶起来”，不能说“扶起了来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子走不稳，你扶他一个。", "corrected_sentence": "孩子走不稳，你扶他一下。", "error_description": "补语错误：动量补语应用“一下”，不能用量词“个”。应说“扶他一下”，不能说“扶他一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
