INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97734, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手支撑或搀着，使不倒。", "primary_collocate": null, "pronunciation": "fú", "ipa": "fu˧˥", "syllable_count": 1, "sentences": [{"text": "他扶着墙慢慢地走进了房间。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请扶好梯子，我要爬上去换灯泡。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用一只手扶着自行车，另一只手拿着包。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在晃，你快扶住桌子，别摔倒。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开得很快，站着的人都扶着栏杆。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝醉了，扶着路灯站了很久。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，你扶住这棵小树，我去拿绳子。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学骑车，爸爸在后面扶着车座。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板很滑，他扶着桌边一步一步地走。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你扶一下这块板，我来钉钉子。", "target_word": "扶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扶着", "label": "体标（着）"}, {"form": "扶了", "label": "体标（了）"}, {"form": "扶过", "label": "体标（过）"}, {"form": "扶住", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手扶住物体（墙、梯子、栏杆、车等），使它或自己稳住不倒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97734, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扶", "is_correct": true, "explanation": "正确答案。扶指用手支撑或搀着，使不倒。"}, {"text": "夫", "is_correct": false, "explanation": "夫的 fū（第一声）与扶的 fú（第二声）声调不同，夫指丈夫。"}, {"text": "富", "is_correct": false, "explanation": "富的 fù（第四声）与扶的 fú（第二声）声调不同，富指财产多。"}, {"text": "湖", "is_correct": false, "explanation": "湖的声母 h 与扶的 f 不同，湖指水面宽阔的湖泊。"}, {"text": "父", "is_correct": false, "explanation": "父的 fù（第四声）与扶的 fú（第二声）声调不同，父指父亲。"}], "explanations": {"扶": "正确答案。扶指用手支撑或搀着，使不倒。", "夫": "夫的 fū（第一声）与扶的 fú（第二声）声调不同，夫指丈夫。", "富": "富的 fù（第四声）与扶的 fú（第二声）声调不同，富指财产多。", "湖": "湖的声母 h 与扶的 f 不同，湖指水面宽阔的湖泊。", "父": "父的 fù（第四声）与扶的 fú（第二声）声调不同，父指父亲。"}, "sentence_index": null, "correct_answer": "扶"}, "level_3": {"options": [{"text": "扶", "is_correct": true, "explanation": "扶指用手支撑，符合“扶着墙”的身体动作，与“慢慢地走进房间”相合。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿”的对象应是可手持的物品，墙不能拿。"}, {"text": "提", "is_correct": false, "explanation": "搭配：“提”多用于可拎的东西，不能说“提着墙”。"}, {"text": "砌", "is_correct": false, "explanation": "语义：“砌”指用砖石垒墙，与“慢慢地走进房间”的动作不符。"}], "explanations": {"扶": "扶指用手支撑，符合“扶着墙”的身体动作，与“慢慢地走进房间”相合。", "拿": "搭配：“拿”的对象应是可手持的物品，墙不能拿。", "提": "搭配：“提”多用于可拎的东西，不能说“提着墙”。", "砌": "语义：“砌”指用砖石垒墙，与“慢慢地走进房间”的动作不符。"}, "sentence_index": 0, "correct_answer": "扶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力扶开了门。", "explanation": "这里应该用〈推〉。扶指用手支撑使不倒，用力把门打开要用推。"}, {"text": "他用手扶了一下开关，灯就亮了。", "explanation": "这里应该用〈按〉。扶表示支撑使不倒，按开关要用按。"}, {"text": "她把桌上的杯子扶走了。", "explanation": "这里应该用〈拿〉。扶表示用手支撑或搀着使不倒，拿走杯子要用拿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97734, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扶", "is_correct": true, "explanation": "正确答案。扶指用手支撑或搀着，使不倒。"}, {"text": "付", "is_correct": false, "explanation": "付的 fù（第四声）与扶的 fú（第二声）声调不同，付指支付、交给。"}, {"text": "副", "is_correct": false, "explanation": "副的 fù（第四声）与扶的 fú（第二声）声调不同，副指副手、次要的。"}, {"text": "腐", "is_correct": false, "explanation": "腐的 fǔ（第三声）与扶的 fú（第二声）声调不同，腐指腐烂。"}, {"text": "壶", "is_correct": false, "explanation": "壶的声母 h 与扶的 f 不同，壶指盛水或泡茶的器具。"}], "explanations": {"扶": "正确答案。扶指用手支撑或搀着，使不倒。", "付": "付的 fù（第四声）与扶的 fú（第二声）声调不同，付指支付、交给。", "副": "副的 fù（第四声）与扶的 fú（第二声）声调不同，副指副手、次要的。", "腐": "腐的 fǔ（第三声）与扶的 fú（第二声）声调不同，腐指腐烂。", "壶": "壶的声母 h 与扶的 f 不同，壶指盛水或泡茶的器具。"}, "sentence_index": null, "correct_answer": "扶"}, "level_3": {"options": [{"text": "扶", "is_correct": true, "explanation": "扶指用手稳住，符合“扶住这棵小树”的语境，防止它被风吹倒。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指掘土，与“防止小树被风吹倒”的意思不符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”与小树无关，句子表达的是用手稳住小树。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：“砍”会伤害小树，与“住”组合也不表达稳住小树的意思。"}], "explanations": {"扶": "扶指用手稳住，符合“扶住这棵小树”的语境，防止它被风吹倒。", "挖": "语义：“挖”指掘土，与“防止小树被风吹倒”的意思不符。", "写": "语义：“写”与小树无关，句子表达的是用手稳住小树。", "砍": "搭配：“砍”会伤害小树，与“住”组合也不表达稳住小树的意思。"}, "sentence_index": 6, "correct_answer": "扶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他扶住了飞来的球。", "explanation": "这里应该用〈接〉。扶指用手支撑使不倒，接住飞来的球要用接。"}, {"text": "她把桌子扶干净了。", "explanation": "这里应该用〈擦〉。扶表示支撑，不能表示擦拭，把桌子擦干净要用擦。"}, {"text": "她从树上扶下一朵花。", "explanation": "这里应该用〈摘〉。扶表示支撑，不能表示采下花朵，从树上摘花要用摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他扶了住墙，才没摔倒。", "corrected_sentence": "他扶住了墙，才没摔倒。", "error_description": "补语错误：结果补语“住”不能被“了”隔开，应说“扶住了墙”，不能说“扶了住墙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你扶一个这扇门，我去拿工具。", "corrected_sentence": "你扶一下这扇门，我去拿工具。", "error_description": "补语错误：扶的动量补语应用“一下”，不能用量词“个”。应说“扶一下这扇门”，不能说“扶一个这扇门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
