INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97737, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不要慢吞吞的，快一点做。", "primary_collocate": null, "pronunciation": "zhuā jǐn", "ipa": "ʈʂwa˥ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "快迟到了，你抓紧吃饭吧。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别玩手机了，抓紧写作业。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车马上就要开了，大家抓紧上车。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你动作太慢了，抓紧一点。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“大家抓紧做，十分钟后交。”", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭已经凉了，你抓紧吃。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快要下雨了，抓紧收衣服。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人快到了，我们抓紧打扫房间。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别慢吞吞的，抓紧穿鞋。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影七点开始，我们抓紧出门吧。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抓紧了", "label": "完成体"}, {"form": "抓緊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "催人别拖拉，快点做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抓紧", "is_correct": true, "explanation": "抓紧：赶快去做，不拖拉，与“快迟到了”的催促语境相合。"}, {"text": "放松", "is_correct": false, "explanation": "语义：“放松”表示不紧张、休息，与“快迟到了”的催促相矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指以愉快的心情得到什么，不能用来催促快吃，与“快迟到了”不合。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”指故意耽搁，与“快迟到了”的催促语境相反。"}], "explanations": {"抓紧": "抓紧：赶快去做，不拖拉，与“快迟到了”的催促语境相合。", "放松": "语义：“放松”表示不紧张、休息，与“快迟到了”的催促相矛盾。", "享受": "语义：“享受”指以愉快的心情得到什么，不能用来催促快吃，与“快迟到了”不合。", "拖延": "语义：“拖延”指故意耽搁，与“快迟到了”的催促语境相反。"}, "sentence_index": 0, "correct_answer": "抓紧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她抓紧了心情，安心地睡了一觉。", "explanation": "这里应该用〈放松〉。“抓紧”表示握牢或催人快做，不与“心情”搭配；放松心情才是常见说法。"}, {"text": "我们要抓紧环境，不乱扔垃圾。", "explanation": "这里应该用〈保护〉。“抓紧”表示催人快做，不与“环境”搭配；保护环境才是常见说法。"}, {"text": "上课时，他总是抓紧注意力。", "explanation": "这里应该用〈集中〉。“抓紧”表示握牢或催人快做，不与“注意力”搭配；注意力应说“集中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抓紧", "is_correct": true, "explanation": "正确：“快要下雨了，抓紧收衣服”，赶快去做，与紧迫的语境相合。"}, {"text": "发呆", "is_correct": false, "explanation": "配价：“发呆”是不及物动词，不能带“收衣服”作宾语。"}, {"text": "休息", "is_correct": false, "explanation": "语义：“休息”表示停下来不做事，与“快要下雨了”要赶快收衣服的语境相矛盾。"}, {"text": "玩耍", "is_correct": false, "explanation": "语义：“玩耍”表示游戏娱乐，与“快要下雨了”要收衣服的紧迫感相矛盾。"}], "explanations": {"抓紧": "正确：“快要下雨了，抓紧收衣服”，赶快去做，与紧迫的语境相合。", "发呆": "配价：“发呆”是不及物动词，不能带“收衣服”作宾语。", "休息": "语义：“休息”表示停下来不做事，与“快要下雨了”要赶快收衣服的语境相矛盾。", "玩耍": "语义：“玩耍”表示游戏娱乐，与“快要下雨了”要收衣服的紧迫感相矛盾。"}, "sentence_index": 6, "correct_answer": "抓紧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每天锻炼能抓紧体质。", "explanation": "这里应该用〈加强〉。“抓紧”表示催人快做，不用于说体质，加强体质才是常见说法。"}, {"text": "多运动能抓紧免疫力。", "explanation": "这里应该用〈增强〉。“抓紧”不用于免疫力等身体机能，增强免疫力是固定说法。"}, {"text": "他终于抓紧了早睡的习惯。", "explanation": "这里应该用〈养成〉。“抓紧”不与“习惯”搭配；养成习惯才是常见说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天快黑了，我们很抓紧回家吧。", "corrected_sentence": "天快黑了，我们抓紧回家吧。", "error_description": "错误形式：“我们很抓紧回家”。正确形式：“我们抓紧回家”。“很”是程度副词，不能修饰表示催促、赶快做事的“抓紧”；“抓紧”后面直接接要做的动作即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "时间不多了，大家抓紧了吃饭吧。", "corrected_sentence": "时间不多了，大家抓紧吃饭吧。", "error_description": "错误形式是“抓紧了吃饭吧”，正确形式是“抓紧吃饭吧”。表示催促的祈使句中，“抓紧”后不能加表示完成的“了”，否则与祈使语气相矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
