INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97738, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抓住时机，加快进行。", "primary_collocate": null, "pronunciation": "zhuā jǐn", "ipa": "ʈʂwa˥ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "天气好，我们抓紧时间晒被子。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试快到了，他抓紧时间复习。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "趁着年轻，要抓紧学习。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，农民抓紧播种。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抓紧午休时间练习说汉语。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期不长，我们抓紧时间去旅行。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨还没下，抓紧把衣服收进来。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师抓紧时间讲完了这一课。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一有空就抓紧练习写字。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛还有半小时，大家抓紧时间热身。", "target_word": "抓紧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抓紧了", "label": "完成体"}, {"form": "抓緊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "利用时间或机会，加快去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9506348c-cb1e-4868-b1b2-23c7a1b15607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抓紧", "is_correct": true, "explanation": "抓紧：抓住时机去做，与“天气好”“晒被子”的利用时机语境相合。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”指白白耗费，与“抓紧时间”的积极利用相反。"}, {"text": "耽误", "is_correct": false, "explanation": "语义：“耽误”指因拖延而误事，与“天气好”这一有利条件相矛盾。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”指故意耽搁，与“天气好”要抓紧时间晒被子的语境相反。"}], "explanations": {"抓紧": "抓紧：抓住时机去做，与“天气好”“晒被子”的利用时机语境相合。", "浪费": "语义：“浪费”指白白耗费，与“抓紧时间”的积极利用相反。", "耽误": "语义：“耽误”指因拖延而误事，与“天气好”这一有利条件相矛盾。", "拖延": "语义：“拖延”指故意耽搁，与“天气好”要抓紧时间晒被子的语境相反。"}, "sentence_index": 0, "correct_answer": "抓紧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抓紧了那份委屈，一句话也不说。", "explanation": "这里应该用〈忍住〉。“抓紧”不与“委屈”搭配，表示抓住时机、催促快做，忍住委屈才是常见说法。"}, {"text": "她抓紧了眼泪，不让它流下来。", "explanation": "这里应该用〈忍住〉。“抓紧”不与“眼泪”搭配，忍住眼泪才是常见说法。"}, {"text": "他抓紧了那个生词，却怎么也记不住。", "explanation": "这里应该用〈掌握〉。“抓紧”不与“生词”搭配；掌握生词才是常见说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抓紧", "is_correct": true, "explanation": "抓紧：趁雨还没下赶快做，与“雨还没下”的时机相合。"}, {"text": "放松", "is_correct": false, "explanation": "语义：“放松”表示不紧张、休息，与“雨还没下”需要赶快收衣服相矛盾。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”表示耽搁，与“雨还没下”需要抓紧时间的语境相矛盾。"}, {"text": "推迟", "is_correct": false, "explanation": "语义：“推迟”表示延后，与“雨还没下”需要趁早收衣服的紧迫语境相反。"}], "explanations": {"抓紧": "抓紧：趁雨还没下赶快做，与“雨还没下”的时机相合。", "放松": "语义：“放松”表示不紧张、休息，与“雨还没下”需要赶快收衣服相矛盾。", "拖延": "语义：“拖延”表示耽搁，与“雨还没下”需要抓紧时间的语境相矛盾。", "推迟": "语义：“推迟”表示延后，与“雨还没下”需要趁早收衣服的紧迫语境相反。"}, "sentence_index": 6, "correct_answer": "抓紧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抓紧了这次比赛的冠军。", "explanation": "这里应该用〈获得〉。“抓紧”表示抓住时机加快去做，不与“冠军”搭配；获得冠军才是常见说法。"}, {"text": "多运动能抓紧免疫力。", "explanation": "这里应该用〈增强〉。“抓紧”不用于免疫力，增强免疫力是常见说法。"}, {"text": "每天锻炼能抓紧体质。", "explanation": "这里应该用〈加强〉。“抓紧”不用于体质，加强体质才是常见说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要抓紧了时间练习口语。", "corrected_sentence": "我们要抓紧时间练习口语。", "error_description": "错误形式：“抓紧了时间”。正确形式：“抓紧时间”。“要”表示将来或意愿，与表示完成的“了”相矛盾，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛快开始了，大家抓紧了热身吧。", "corrected_sentence": "比赛快开始了，大家抓紧热身吧。", "error_description": "错误形式是“抓紧了热身吧”，正确形式是“抓紧热身吧”。表示催促的祈使句中，“抓紧”后不能加表示完成的“了”，否则与祈使语气相矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98c9a6c7-d054-4f6c-bb94-e38486118de4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
