INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保卫；坚决保护。", "primary_collocate": null, "pronunciation": "hàn wèi", "ipa": "xan˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "国家坚决捍卫自己的主权。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要捍卫每个人的合法权利。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用行动捍卫了自己的尊严。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家一直捍卫着真理。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师的工作是捍卫法律的公正。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律捍卫着公民的自由。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队的责任是捍卫国家的安全。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他勇敢地站出来，捍卫自己的看法。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者应该捍卫新闻的真实。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把捍卫和平当作最大的责任。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捍卫了", "label": "完成体"}, {"form": "捍卫着", "label": "持续体"}, {"form": "捍卫过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "坚决保护主权、权利、尊严、真理等重要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '626c37bb-6c51-4dc9-849b-b00c7672087d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出卖", "is_correct": false, "explanation": "语义：“出卖”是背叛、卖掉，与“坚决”的态度矛盾。"}, {"text": "捍卫", "is_correct": true, "explanation": "正确：“捍卫”表示坚决保护，与“坚决”“自己的主权”相符。"}, {"text": "批判", "is_correct": false, "explanation": "搭配：“批判”针对观点或错误，不说“批判主权”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“坚决”的态度矛盾，不能用来维护主权。"}], "explanations": {"出卖": "语义：“出卖”是背叛、卖掉，与“坚决”的态度矛盾。", "捍卫": "正确：“捍卫”表示坚决保护，与“坚决”“自己的主权”相符。", "批判": "搭配：“批判”针对观点或错误，不说“批判主权”。", "忘记": "语义：“忘记”与“坚决”的态度矛盾，不能用来维护主权。"}, "sentence_index": 0, "correct_answer": "捍卫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坚决捍卫这次的失败。", "explanation": "这里应该用〈承认〉。捍卫是坚决保护值得守护的东西，失败应坦然承认。"}, {"text": "老师捍卫了那份抄来的作业。", "explanation": "这里应该用〈揭穿〉。捍卫用于正当的权利或真理，对抄袭的作业要用揭穿。"}, {"text": "他捍卫了那张偷来的照片。", "explanation": "这里应该用〈归还〉。捍卫用于正当拥有或值得守护的东西，偷来的照片应说归还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”与“军队的责任”相反，句意矛盾。"}, {"text": "捍卫", "is_correct": true, "explanation": "正确：“捍卫”表示坚决保护，与“军队的责任”“国家的安全”相符。"}, {"text": "威胁", "is_correct": false, "explanation": "语义：“威胁”是对安全造成危害，不能作军队的责任。"}, {"text": "打击", "is_correct": false, "explanation": "搭配：“打击”的对象是敌人或犯罪，不说“打击安全”。"}], "explanations": {"破坏": "语义：“破坏”与“军队的责任”相反，句意矛盾。", "捍卫": "正确：“捍卫”表示坚决保护，与“军队的责任”“国家的安全”相符。", "威胁": "语义：“威胁”是对安全造成危害，不能作军队的责任。", "打击": "搭配：“打击”的对象是敌人或犯罪，不说“打击安全”。"}, "sentence_index": 6, "correct_answer": "捍卫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的纵容捍卫了歪风邪气。", "explanation": "这里应该用〈助长〉。捍卫用于值得守护的正面事物，助长坏风气要用助长。"}, {"text": "这些人捍卫了这场争端。", "explanation": "这里应该用〈挑起〉。捍卫不用于需要平息的争端，引发争端要用挑起。"}, {"text": "他捍卫了这场闹事。", "explanation": "这里应该用〈煽动〉。捍卫不用于闹事这类负面行为，煽动别人闹事要用煽动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把国家的主权捍卫。", "corrected_sentence": "我们要把国家的主权捍卫好。", "error_description": "错误形式：“把国家的主权捍卫”；正确形式：“把国家的主权捍卫好”。“把”字句中动词不能单独收尾，要加上补语等其他成分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "律师捍卫了着公民的权利。", "corrected_sentence": "律师捍卫着公民的权利。", "error_description": "错误形式：“捍卫了着”；正确形式：“捍卫着”。“了”和“着”都是动态助词，不能同时用在同一动词后，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己的东西或钱送给别人，帮助他们。", "primary_collocate": null, "pronunciation": "juān zèng", "ipa": "tɕɥɛn˥ tsɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他把旧衣服捐赠给了山区的孩子。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每年都捐赠一些钱。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这些书捐赠给图书馆。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人捐赠了自己一半的钱。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请大家捐赠不用的玩具。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她捐赠过很多东西，从不说出来。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们捐赠食物，帮助生病的老人。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他捐赠了一笔钱，帮助穷孩子上学。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们捐赠自己的零花钱，帮助灾区的人。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家捐赠了一台旧电视。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捐赠了", "label": "完成体"}, {"form": "捐赠过", "label": "经历体"}, {"form": "捐赠者", "label": "复合词"}], "register": "正式", "sense_fingerprint": "把自己的东西或钱送给需要的人，帮助他们", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '626c37bb-6c51-4dc9-849b-b00c7672087d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捐赠", "is_correct": true, "explanation": "捐赠：无偿把东西送给山区的孩子，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧给”多用于给已故的人烧纸钱，山区的孩子是活人，句意不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”指把衣物穿在身上，不表示把东西送给别人，句意不通。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是打碎，与“给了山区的孩子”的赠予意思相反。"}], "explanations": {"捐赠": "捐赠：无偿把东西送给山区的孩子，符合句意。", "烧": "语义：“烧给”多用于给已故的人烧纸钱，山区的孩子是活人，句意不通。", "穿": "搭配：“穿”指把衣物穿在身上，不表示把东西送给别人，句意不通。", "砸": "语义：“砸”是打碎，与“给了山区的孩子”的赠予意思相反。"}, "sentence_index": 0, "correct_answer": "捐赠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈把一条围巾捐赠给了我。", "explanation": "这里应该用〈赠送〉。捐赠是为了帮助需要的人，送给自己的孩子作日常礼物应用〈赠送〉。"}, {"text": "我把一本旧书捐赠给书店，收了一百块钱。", "explanation": "这里应该用〈卖〉。捐赠是无偿送出，句中“收了一百块钱”说明是有偿交易。"}, {"text": "我把这本书捐赠给了朋友，说好下周还给我。", "explanation": "这里应该用〈借〉。捐赠是永久送出，不会再还回来；句中“下周还给我”说明是借出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捐赠", "is_correct": true, "explanation": "捐赠：无偿把食物送给需要帮助的人，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，扔掉食物与“帮助生病的老人”的意思相反。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与“帮助生病的老人”的意思矛盾。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”指修理器物，不能与“食物”搭配，句子不通。"}], "explanations": {"捐赠": "捐赠：无偿把食物送给需要帮助的人，符合句意。", "扔": "语义：“扔”是丢弃，扔掉食物与“帮助生病的老人”的意思相反。", "偷": "语义：“偷”是窃取，与“帮助生病的老人”的意思矛盾。", "修": "搭配：“修”指修理器物，不能与“食物”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "捐赠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这台旧电视捐赠给了我自己。", "explanation": "这里应该用〈留着〉。捐赠的对象必须是他人或机构，自己留用应说留着。"}, {"text": "公司把总经理的职位捐赠给了小王。", "explanation": "这里应该用〈让给〉。捐赠的对象必须是财物，职位不是财物，应说把职位让给别人。"}, {"text": "我家从希望小学捐赠了一台旧电视。", "explanation": "这里应该用〈受赠〉。捐赠是把东西送出去，句中“从希望小学”说明方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司明天向小学捐赠了一台电脑。", "corrected_sentence": "公司明天向小学捐赠一台电脑。", "error_description": "“明天”指将来，动作尚未发生，动词后不能加“了”。应去掉“了”，改为“公司明天向小学捐赠一台电脑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校给山区捐赠了过很多图书。", "corrected_sentence": "学校给山区捐赠过很多图书。", "error_description": "“了”和“过”不能同时用在同一动词后。应去掉“了”，改为“学校给山区捐赠过很多图书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
