INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97750, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "揭起；也指引发、掀动。", "primary_collocate": null, "pronunciation": "xiān qǐ", "ipa": "ɕjɛn˥˥ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "风把窗帘掀起了一角。", "target_word": "掀起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他轻轻掀起被子，下了床。", "target_word": "掀起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈掀起锅盖，看了看汤。", "target_word": "掀起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海上的大风掀起了高高的浪。", "target_word": "掀起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影掀起了一阵热潮。", "target_word": "掀起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他掀起帘子走进来。", "target_word": "掀起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这首歌在网上掀起了热潮。", "target_word": "掀起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩掀起衣服，给我看他的伤。", "target_word": "掀起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新政策掀起了一场讨论。", "target_word": "掀起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车跑过去，掀起一片尘土。", "target_word": "掀起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "掀起了", "label": "体标"}, {"form": "掀起过", "label": "体标"}], "register": "中性", "sense_fingerprint": "揭起东西，或引发热潮、波浪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eca7faf1-53e9-4820-92b2-8ca5390197ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97750, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仙气", "is_correct": false, "explanation": "仙气（xiān qì）第一音节与掀起相同，第二音节 qì 为第四声，qǐ 为第三声，只差声调；意思是仙人般的气质。"}, {"text": "掀起", "is_correct": true, "explanation": "掀起（xiān qǐ）：揭起东西，或引发热潮、波浪，即本题词条。"}, {"text": "先期", "is_correct": false, "explanation": "先期（xiān qī）第一音节相同，第二音节 qī 为第一声，qǐ 为第三声，只差声调；意思是事先、提前。"}, {"text": "闲气", "is_correct": false, "explanation": "闲气（xián qì）两个音节声调都与掀起不同（xián 为第二声，qì 为第四声）；意思是受的闲气、窝囊气。"}], "explanations": {"仙气": "仙气（xiān qì）第一音节与掀起相同，第二音节 qì 为第四声，qǐ 为第三声，只差声调；意思是仙人般的气质。", "掀起": "掀起（xiān qǐ）：揭起东西，或引发热潮、波浪，即本题词条。", "先期": "先期（xiān qī）第一音节相同，第二音节 qī 为第一声，qǐ 为第三声，只差声调；意思是事先、提前。", "闲气": "闲气（xián qì）两个音节声调都与掀起不同（xián 为第二声，qì 为第四声）；意思是受的闲气、窝囊气。"}, "sentence_index": null, "correct_answer": "掀起"}, "level_3": {"options": [{"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉是丢弃，风不会把窗帘的一角扔掉，与句中“风”的动作不符。"}, {"text": "掀起", "is_correct": true, "explanation": "掀起：揭起，风把窗帘的一角揭起，与“窗帘”和“一角”搭配。"}, {"text": "烧掉", "is_correct": false, "explanation": "语义：烧掉需要火，风不能把窗帘烧掉一角，与句意不合。"}, {"text": "擦干", "is_correct": false, "explanation": "搭配：擦干用于水、泪等液体，窗帘的一角不能被擦干。"}], "explanations": {"扔掉": "语义：扔掉是丢弃，风不会把窗帘的一角扔掉，与句中“风”的动作不符。", "掀起": "掀起：揭起，风把窗帘的一角揭起，与“窗帘”和“一角”搭配。", "烧掉": "语义：烧掉需要火，风不能把窗帘烧掉一角，与句意不合。", "擦干": "搭配：擦干用于水、泪等液体，窗帘的一角不能被擦干。"}, "sentence_index": 0, "correct_answer": "掀起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事掀起了大家的注意，大家都在议论。", "explanation": "这里应该用〈引起〉。掀起多指浪、热潮、风波这类大规模的动静；“注意”是心理活动，要用引起。"}, {"text": "他掀起手，向我打招呼。", "explanation": "这里应该用〈扬起〉。掀起指把覆盖物或薄片状的东西揭起，不能用于抬手；挥手应说扬起。"}, {"text": "他说完这句话，掀起了沉默。", "explanation": "这里应该用〈打破〉。掀起用于浪、热潮、风波，沉默是一种状态，要用打破。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱出", "is_correct": false, "explanation": "搭配：唱出的对象是歌词或声音，不能接“热潮”，与“这首歌”的句意不符。"}, {"text": "掀起", "is_correct": true, "explanation": "掀起：引发、兴起，可与“热潮”搭配，表示这首歌在网上引起一阵风潮。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉指把东西咽下去，热潮不能被吃掉。"}, {"text": "写满", "is_correct": false, "explanation": "搭配：写满要接能被写满的载体，“热潮”不能被写满。"}], "explanations": {"唱出": "搭配：唱出的对象是歌词或声音，不能接“热潮”，与“这首歌”的句意不符。", "掀起": "掀起：引发、兴起，可与“热潮”搭配，表示这首歌在网上引起一阵风潮。", "吃掉": "语义：吃掉指把东西咽下去，热潮不能被吃掉。", "写满": "搭配：写满要接能被写满的载体，“热潮”不能被写满。"}, "sentence_index": 6, "correct_answer": "掀起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他掀起了头，看了我一眼。", "explanation": "这里应该用〈抬起〉。掀起用于揭开覆盖物或引发事件，抬头要用抬起。"}, {"text": "他掀起了脚步，走出了教室。", "explanation": "这里应该用〈加快〉。掀起不表示速度，加快脚步要用加快。"}, {"text": "她掀起了眼泪，慢慢走开。", "explanation": "这里应该用〈擦干〉。掀起不能用于眼泪，擦干眼泪要用擦干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈轻轻掀起来被角，看了看孩子。", "corrected_sentence": "妈妈轻轻掀起被角，看了看孩子。", "error_description": "补语位置错误：“掀起”后应直接接宾语，说“掀起被角”；“起来”不能放在宾语前，写成“掀起来被角”不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一阵风吹过，湖面掀起着细细的波纹。", "corrected_sentence": "一阵风吹过，湖面掀起了细细的波纹。", "error_description": "体标误用：“掀起”带趋向补语“起”，表示动作完成、有了结果，不能再加持续体“着”。这里应说“掀起了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
