INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97753, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做事得到钱。", "primary_collocate": null, "pronunciation": "zhèng", "ipa": "ʈʂəŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他每个月挣五千块钱。", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在银行工作，挣得不少。", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想打工挣点钱买手机。", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天挣了两百块。", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一天挣的钱不多。", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个月能挣多少钱？", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在饭店工作，挣钱养家。", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟周末送饭，挣些零花钱。", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作挣得多，也很累。", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有挣过这么多钱。", "target_word": "挣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挣了", "label": "体标"}, {"form": "挣过", "label": "体标"}, {"form": "挣钱", "label": "复合"}], "register": "口语", "sense_fingerprint": "通过工作得到收入、赚钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97753, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挣", "is_correct": true, "explanation": "正确：挣指通过工作得到钱。"}, {"text": "争", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争夺、争取。"}, {"text": "秤", "is_correct": false, "explanation": "chèng 与 zhèng 声母不同（ch / zh），意思是称重量的秤。"}, {"text": "众", "is_correct": false, "explanation": "zhòng 与 zhèng 韵母不同（ong / eng），意思是人多、群众。"}, {"text": "账", "is_correct": false, "explanation": "zhàng 与 zhèng 韵母不同（ang / eng），意思是账目、账单。"}, {"text": "整", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整、整理。"}], "explanations": {"挣": "正确：挣指通过工作得到钱。", "争": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争夺、争取。", "秤": "chèng 与 zhèng 声母不同（ch / zh），意思是称重量的秤。", "众": "zhòng 与 zhèng 韵母不同（ong / eng），意思是人多、群众。", "账": "zhàng 与 zhèng 韵母不同（ang / eng），意思是账目、账单。", "整": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整、整理。"}, "sentence_index": null, "correct_answer": "挣"}, "level_3": {"options": [{"text": "挣", "is_correct": true, "explanation": "正确：挣指通过工作得到收入，与“每个月”“五千块钱”相符。"}, {"text": "抢", "is_correct": false, "explanation": "语义：抢是强行夺取，与按月的正常工作收入不符。"}, {"text": "偷", "is_correct": false, "explanation": "语义：偷是非法取得，不是每月的正当收入。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能说“喝五千块钱”。"}], "explanations": {"挣": "正确：挣指通过工作得到收入，与“每个月”“五千块钱”相符。", "抢": "语义：抢是强行夺取，与按月的正常工作收入不符。", "偷": "语义：偷是非法取得，不是每月的正当收入。", "喝": "搭配：“喝”的对象是饮料，不能说“喝五千块钱”。"}, "sentence_index": 0, "correct_answer": "挣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈挣到了一份生日礼物。", "explanation": "这里应该用〈收到〉。挣指靠劳动换来钱，收到礼物不能用“挣”。"}, {"text": "他从银行挣了一千块。", "explanation": "这里应该用〈取〉。挣要靠自己劳动得钱，从银行取钱不能用“挣”。"}, {"text": "小偷挣走了他的自行车。", "explanation": "这里应该用〈偷〉。挣指靠劳动得钱，偷东西不能用“挣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97753, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挣", "is_correct": true, "explanation": "正确：挣指通过工作得到钱。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是用水汽加热食物。"}, {"text": "睁", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是把眼睛张开。"}, {"text": "征", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是征收、征服。"}, {"text": "胀", "is_correct": false, "explanation": "zhàng 与 zhèng 韵母不同（ang / eng），意思是膨胀、鼓起。"}, {"text": "重", "is_correct": false, "explanation": "zhòng 与 zhèng 韵母不同（ong / eng），意思是重量大。"}], "explanations": {"挣": "正确：挣指通过工作得到钱。", "蒸": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是用水汽加热食物。", "睁": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是把眼睛张开。", "征": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是征收、征服。", "胀": "zhàng 与 zhèng 韵母不同（ang / eng），意思是膨胀、鼓起。", "重": "zhòng 与 zhèng 韵母不同（ong / eng），意思是重量大。"}, "sentence_index": null, "correct_answer": "挣"}, "level_3": {"options": [{"text": "挣", "is_correct": true, "explanation": "正确：挣钱养家指靠工作得到收入来养家，与“在饭店工作”相符。"}, {"text": "讨", "is_correct": false, "explanation": "语义：讨是乞求，与“在饭店工作”不符。"}, {"text": "捡", "is_correct": false, "explanation": "语义：捡是拾到，不能作为养家的固定来源。"}, {"text": "扣", "is_correct": false, "explanation": "搭配：“扣”是扣除、克扣，不能与“养家”搭配。"}], "explanations": {"挣": "正确：挣钱养家指靠工作得到收入来养家，与“在饭店工作”相符。", "讨": "语义：讨是乞求，与“在饭店工作”不符。", "捡": "语义：捡是拾到，不能作为养家的固定来源。", "扣": "搭配：“扣”是扣除、克扣，不能与“养家”搭配。"}, "sentence_index": 6, "correct_answer": "挣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上挣到一百块。", "explanation": "这里应该用〈捡〉。挣要靠劳动换来钱，路上捡到的钱不能说“挣”。"}, {"text": "他向朋友挣了一千块。", "explanation": "这里应该用〈借〉。挣指自己劳动所得，不能从朋友那里挣来。"}, {"text": "他挣给我一封信。", "explanation": "这里应该用〈寄〉。挣指靠劳动换来钱，寄信给别人不能用“挣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年挣了过两万块。", "corrected_sentence": "他去年挣过两万块。", "error_description": "“过”和“了”不能同时用在同一动词后，表示经历只用“过”。正确：挣过两万块；错误：挣了过两万块。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在外地打工，全靠钱挣养家。", "corrected_sentence": "他在外地打工，全靠挣钱养家。", "error_description": "“挣钱”是动宾结构，语素顺序不能颠倒。正确：挣钱养家；错误：钱挣养家。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
