INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97757, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指头拨，让东西动起来或转起来。", "primary_collocate": null, "pronunciation": "bō", "ipa": "pwɔ˥", "syllable_count": 1, "sentences": [{"text": "他用手指拨了一下地球仪。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩伸手拨转盘，看它转起来。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用手指拨陀螺，陀螺转个不停。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你轻轻拨一下风车，它就会转。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用食指拨着算盘珠子，算得很快。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拨了拨桌上的小球，球滚走了。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拨了一下开关，灯就亮了。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手指拨一下转盘，指针转了起来。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟总爱拨桌上的小风车玩。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你拨一下这个轮子，看它转不转。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拨了", "label": "了体标"}, {"form": "拨着", "label": "着体标"}, {"form": "拨过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "用手指拨动物体使其转动或移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abce999f-3fc1-404e-9d60-5f1209efb4c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97757, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拨", "is_correct": true, "explanation": "正确：拨 bō，指用手指拨动，使东西动起来或转起来。"}, {"text": "跛", "is_correct": false, "explanation": "bǒ（第三声）与 bō（第一声）声调不同，意思是腿脚有毛病、走路不稳。"}, {"text": "博", "is_correct": false, "explanation": "bó（第二声）与 bō（第一声）声调不同，意思是广博，如博物馆。"}, {"text": "坡", "is_correct": false, "explanation": "pō 与 bō 声母不同（p 与 b），意思是斜坡。"}, {"text": "泼", "is_correct": false, "explanation": "pō 与 bō 声母不同（p 与 b），意思是把液体猛地倒出去。"}], "explanations": {"拨": "正确：拨 bō，指用手指拨动，使东西动起来或转起来。", "跛": "bǒ（第三声）与 bō（第一声）声调不同，意思是腿脚有毛病、走路不稳。", "博": "bó（第二声）与 bō（第一声）声调不同，意思是广博，如博物馆。", "坡": "pō 与 bō 声母不同（p 与 b），意思是斜坡。", "泼": "pō 与 bō 声母不同（p 与 b），意思是把液体猛地倒出去。"}, "sentence_index": null, "correct_answer": "拨"}, "level_3": {"options": [{"text": "拨", "is_correct": true, "explanation": "正确：“拨”指用手指轻拨，使地球仪转动，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，不能用手指作用于地球仪。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”要求以歌曲作宾语，不能以地球仪作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热食物，与用手指转动地球仪的动作不符。"}], "explanations": {"拨": "正确：“拨”指用手指轻拨，使地球仪转动，符合句意。", "写": "语义：“写”指书写文字，不能用手指作用于地球仪。", "唱": "配价：“唱”要求以歌曲作宾语，不能以地球仪作宾语。", "煮": "语义：“煮”指用水加热食物，与用手指转动地球仪的动作不符。"}, "sentence_index": 0, "correct_answer": "拨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拨了一下石头，石头就碎了。", "explanation": "这里应该用〈砸〉。“拨”是用手指轻拨，使东西动起来或转起来，不能让石头碎裂；把石头击碎要用〈砸〉。"}, {"text": "他用力拨紧了水龙头，不让水再流出来。", "explanation": "这里应该用〈拧〉。“拨”指用手指轻拨，使东西动起来或转起来；拧紧水龙头要用力转动，应该用〈拧〉。"}, {"text": "孩子们合力拨着大石头，慢慢往山下走。", "explanation": "这里应该用〈推〉。“拨”只能轻轻拨动，不能合力移动大石头；使重物移动要用〈推〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97757, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拨", "is_correct": true, "explanation": "正确：拨 bō，指用手指拨动，使东西动起来或转起来。"}, {"text": "伯", "is_correct": false, "explanation": "bó（第二声）与 bō（第一声）声调不同，意思是伯伯、伯父。"}, {"text": "驳", "is_correct": false, "explanation": "bó（第二声）与 bō（第一声）声调不同，意思是反驳、驳斥。"}, {"text": "摸", "is_correct": false, "explanation": "mō 与 bō 声母不同（m 与 b），意思是用手轻触。"}, {"text": "搏", "is_correct": false, "explanation": "bó（第二声）与 bō（第一声）声调不同，意思是搏斗、脉搏。"}], "explanations": {"拨": "正确：拨 bō，指用手指拨动，使东西动起来或转起来。", "伯": "bó（第二声）与 bō（第一声）声调不同，意思是伯伯、伯父。", "驳": "bó（第二声）与 bō（第一声）声调不同，意思是反驳、驳斥。", "摸": "mō 与 bō 声母不同（m 与 b），意思是用手轻触。", "搏": "bó（第二声）与 bō（第一声）声调不同，意思是搏斗、脉搏。"}, "sentence_index": null, "correct_answer": "拨"}, "level_3": {"options": [{"text": "拨", "is_correct": true, "explanation": "正确：“拨”指用手拨动开关，使灯亮起，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用来形容按动开关的动作。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服、鞋袜，不能说穿开关。"}, {"text": "骑", "is_correct": false, "explanation": "配价：“骑”要求以车、马等作宾语，开关不能作它的宾语。"}], "explanations": {"拨": "正确：“拨”指用手拨动开关，使灯亮起，符合句意。", "吃": "语义：“吃”指进食，不能用来形容按动开关的动作。", "穿": "搭配：“穿”的对象是衣服、鞋袜，不能说穿开关。", "骑": "配价：“骑”要求以车、马等作宾语，开关不能作它的宾语。"}, "sentence_index": 6, "correct_answer": "拨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拨了一脚足球，球就进了球门。", "explanation": "这里应该用〈踢〉。“拨”是用手指或工具轻拨，不能用脚击球；用脚把球踢出去要用〈踢〉。"}, {"text": "他用力拨了三下门，门就被推开了。", "explanation": "这里应该用〈推〉。“拨”是用手指拨动小物件，使其动起来或转起来，不能用来把门推开；推开门要用〈推〉。"}, {"text": "他拨了一下墙，墙就塌了。", "explanation": "这里应该用〈撞〉。“拨”是轻轻拨动，不能让墙倒塌；用身体猛力冲击墙要用〈撞〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我轻轻拨了一下了陀螺，它就转了起来。", "corrected_sentence": "我轻轻拨了一下陀螺，它就转了起来。", "error_description": "错误：“一下”后多了一个“了”。动态助词“了”只用一次，紧跟动词，应写作“拨了一下陀螺”，“一下”之后直接接宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你拨了这个开关，灯就会亮。", "corrected_sentence": "请你拨一下这个开关，灯就会亮。", "error_description": "错误形式“拨了这个开关”：祈使句是请对方去做，不能用“了”表示完成；应说“拨一下这个开关”，“一下”表示动作的次数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
