INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97758, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指或工具推动，使移动或转动。", "primary_collocate": null, "pronunciation": "bō", "ipa": "pwɔ˥", "syllable_count": 1, "sentences": [{"text": "他用木棍拨了拨火，火烧得更旺了。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用筷子把菜拨到盘子一边。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手指拨了拨额前的头发。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用小棍拨一下指针，让它指向三点。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用鞋尖拨着地上的小石子。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用勺子拨一拨汤里的葱花。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸拿钳子拨了拨炉子里的炭。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别把桌上的杯子拨到地上。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手拨了拨水面，小鱼游走了。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用手杖拨着路边的草往前走。", "target_word": "拨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拨了", "label": "了体标"}, {"form": "拨着", "label": "着体标"}, {"form": "拨过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "用手指或棍子等工具推开、挪动物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abce999f-3fc1-404e-9d60-5f1209efb4c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97758, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拨", "is_correct": true, "explanation": "正确：拨 bō，指用手指或工具推动，使物体移动或转动。"}, {"text": "坡", "is_correct": false, "explanation": "pō 与 bō 声母不同（p 与 b），意思是斜坡。"}, {"text": "泼", "is_correct": false, "explanation": "pō 与 bō 声母不同（p 与 b），意思是把液体猛地倒出去。"}, {"text": "薄", "is_correct": false, "explanation": "bó（第二声）与 bō（第一声）声调不同，意思是不厚。"}, {"text": "伯", "is_correct": false, "explanation": "bó（第二声）与 bō（第一声）声调不同，意思是伯伯、伯父。"}], "explanations": {"拨": "正确：拨 bō，指用手指或工具推动，使物体移动或转动。", "坡": "pō 与 bō 声母不同（p 与 b），意思是斜坡。", "泼": "pō 与 bō 声母不同（p 与 b），意思是把液体猛地倒出去。", "薄": "bó（第二声）与 bō（第一声）声调不同，意思是不厚。", "伯": "bó（第二声）与 bō（第一声）声调不同，意思是伯伯、伯父。"}, "sentence_index": null, "correct_answer": "拨"}, "level_3": {"options": [{"text": "拨", "is_correct": true, "explanation": "正确：“拨了拨火”指用木棍拨动炉火，使火烧得更旺，符合句意。"}, {"text": "灭", "is_correct": false, "explanation": "语义：“灭”指使火熄灭，与后半句“火烧得更旺了”相矛盾。"}, {"text": "熄", "is_correct": false, "explanation": "语义：“熄”指火停止燃烧，与后半句“火烧得更旺了”相矛盾。"}, {"text": "捆", "is_correct": false, "explanation": "搭配：“捆”用于绳索、柴草等物，不能说捆火。"}], "explanations": {"拨": "正确：“拨了拨火”指用木棍拨动炉火，使火烧得更旺，符合句意。", "灭": "语义：“灭”指使火熄灭，与后半句“火烧得更旺了”相矛盾。", "熄": "语义：“熄”指火停止燃烧，与后半句“火烧得更旺了”相矛盾。", "捆": "搭配：“捆”用于绳索、柴草等物，不能说捆火。"}, "sentence_index": 0, "correct_answer": "拨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拨着一碗热汤走进厨房。", "explanation": "这里应该用〈端〉。“拨”是用手指或工具推动使东西移动，不能用来端着盛满热汤的碗；端着碗走要用〈端〉。"}, {"text": "妈妈拨了一下西瓜，西瓜就分成了两半。", "explanation": "这里应该用〈切〉。“拨”是推动或转动，不能把西瓜弄成两半；把西瓜切开要用〈切〉。"}, {"text": "她拨着一只小猫走出房间。", "explanation": "这里应该用〈抱〉。“拨”只是推动或转动物体，不能把小猫带着走；抱着小猫走要用〈抱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97758, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拨", "is_correct": true, "explanation": "正确：拨 bō，指用手指或工具推动，使物体移动或转动。"}, {"text": "博", "is_correct": false, "explanation": "bó（第二声）与 bō（第一声）声调不同，意思是广博、博士。"}, {"text": "摸", "is_correct": false, "explanation": "mō 与 bō 声母不同（m 与 b），意思是用手轻触。"}, {"text": "驳", "is_correct": false, "explanation": "bó（第二声）与 bō（第一声）声调不同，意思是反驳、驳斥。"}, {"text": "搏", "is_correct": false, "explanation": "bó（第二声）与 bō（第一声）声调不同，意思是搏斗、脉搏。"}], "explanations": {"拨": "正确：拨 bō，指用手指或工具推动，使物体移动或转动。", "博": "bó（第二声）与 bō（第一声）声调不同，意思是广博、博士。", "摸": "mō 与 bō 声母不同（m 与 b），意思是用手轻触。", "驳": "bó（第二声）与 bō（第一声）声调不同，意思是反驳、驳斥。", "搏": "bó（第二声）与 bō（第一声）声调不同，意思是搏斗、脉搏。"}, "sentence_index": null, "correct_answer": "拨"}, "level_3": {"options": [{"text": "拨", "is_correct": true, "explanation": "正确：“拨”指用钳子拨动炉中的炭，符合句意。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指用针线连缀布料，不能用钳子对炭进行这样的动作。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语要是食物，炭不能作它的宾语。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”用于线、毛线等，不能说织炉子里的炭。"}], "explanations": {"拨": "正确：“拨”指用钳子拨动炉中的炭，符合句意。", "缝": "语义：“缝”指用针线连缀布料，不能用钳子对炭进行这样的动作。", "吃": "配价：“吃”的宾语要是食物，炭不能作它的宾语。", "织": "搭配：“织”用于线、毛线等，不能说织炉子里的炭。"}, "sentence_index": 6, "correct_answer": "拨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拨了一下水，水就开了。", "explanation": "这里应该用〈烧〉。“拨”是用手指或工具推动物体，不能让水变热；把水加热到沸腾要用〈烧〉。"}, {"text": "她拨了一下面团，面团就变成了小人。", "explanation": "这里应该用〈捏〉。“拨”只能轻推物体，不能改变面团的形状；把面团捏成东西要用〈捏〉。"}, {"text": "她拨了一下鸡蛋，鸡蛋就熟了。", "explanation": "这里应该用〈煮〉。“拨”只是推动或转动物体，不能使鸡蛋变熟；把鸡蛋煮熟要用〈煮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用铁钩拨了开炉子里的灰。", "corrected_sentence": "妈妈用铁钩拨开了炉子里的灰。", "error_description": "错误形式“拨了开”：结果补语“开”应紧跟动词，“了”放在补语之后，应说“拨开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈用勺子把饭拨了碗的一边。", "corrected_sentence": "妈妈用勺子把饭拨到碗的一边。", "error_description": "错误：表示位置的补语应用“到”，此处误用“了”。“了”是动态助词，不能引出处所，“拨了碗的一边”不成立，应说“拨到碗的一边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76c8c315-6d4f-42ac-a9aa-f27134e2f2eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
