INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97765, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把拿来的东西放回去。", "primary_collocate": null, "pronunciation": "fàng huán", "ipa": "faŋ˥˩ xwan˧˥", "syllable_count": 2, "sentences": [{"text": "用完书以后，请放还原处。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把借来的工具放还原处。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看完杂志，随手放还原处。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩完玩具，要放还原处。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书看完请放还书架。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把拿出来的碗放还柜子里。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你拿了我的钥匙，请放还桌上。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人看过样品后，请放还展示架。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把借来的东西都放还了。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拿来的文件用完后，请及时放还。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放还了", "label": "体标"}, {"form": "放还过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把借来或拿走的物品放回原来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放还", "is_correct": true, "explanation": "“放还”指把拿来的东西放回原处，符合“用完书以后，请……原处”的语境。"}, {"text": "拿走", "is_correct": false, "explanation": "语义：“拿走”指取走，与“放回原处”的要求相反。"}, {"text": "站", "is_correct": false, "explanation": "语义：“站”指站立，不能表示把书放回原处。"}, {"text": "守", "is_correct": false, "explanation": "搭配：“守”强调看守或坚守，处所要说“守在……”，不说“守原处”。"}], "explanations": {"放还": "“放还”指把拿来的东西放回原处，符合“用完书以后，请……原处”的语境。", "拿走": "语义：“拿走”指取走，与“放回原处”的要求相反。", "站": "语义：“站”指站立，不能表示把书放回原处。", "守": "搭配：“守”强调看守或坚守，处所要说“守在……”，不说“守原处”。"}, "sentence_index": 0, "correct_answer": "放还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于放还了欠朋友的债。", "explanation": "这里应该用〈偿还〉。放还指把物品放回原处，不能用于还债。"}, {"text": "医生终于放还了病人的健康。", "explanation": "这里应该用〈恢复〉。放还指把拿来的物品放回原处，不能用于健康。"}, {"text": "商场同意放还我买的衣服。", "explanation": "这里应该用〈退还〉。放还指把东西放回原处，不能用于退货。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放还", "is_correct": true, "explanation": "“放还”指把拿走的东西放回原处，这里是请对方把钥匙放回桌上。"}, {"text": "坐", "is_correct": false, "explanation": "语义：“坐”指就座，钥匙不能坐在桌上。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指人或动物睡觉，不能用于钥匙。"}, {"text": "躺", "is_correct": false, "explanation": "搭配：“躺”表示平躺，处所要说“躺在桌上”，不说“请躺桌上”。"}], "explanations": {"放还": "“放还”指把拿走的东西放回原处，这里是请对方把钥匙放回桌上。", "坐": "语义：“坐”指就座，钥匙不能坐在桌上。", "睡": "语义：“睡”指人或动物睡觉，不能用于钥匙。", "躺": "搭配：“躺”表示平躺，处所要说“躺在桌上”，不说“请躺桌上”。"}, "sentence_index": 6, "correct_answer": "放还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生都在放还父母的养育之恩。", "explanation": "这里应该用〈报答〉。放还指把东西放回原处，不能用于恩情。"}, {"text": "他用优异的成绩放还了老师的栽培。", "explanation": "这里应该用〈回报〉。放还指把东西放回原处，不能用于老师的栽培。"}, {"text": "他放还了对方的损失。", "explanation": "这里应该用〈赔偿〉。放还只表示把东西放回原处，不能用于损失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾经把借来的剪刀放还了过原处。", "corrected_sentence": "他曾经把借来的剪刀放还过原处。", "error_description": "“过”和“了”不能同时用在同一动词后，表示经历只用“过”。正确：放还过原处；错误：放还了过原处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经放还着那本书。", "corrected_sentence": "他曾经放还过那本书。", "error_description": "“着”表示进行或持续的状态，与表示经历的“曾经”不搭；表示经历要用“过”，且“过”紧跟动词。正确：放还过那本书；错误：放还着那本书。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
