INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "释放被扣留或关押的人，让其回家。", "primary_collocate": null, "pronunciation": "fàng huán", "ipa": "faŋ˥˩ xwan˧˥", "syllable_count": 2, "sentences": [{"text": "警察问完话，就放还了他。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绑匪收到钱后，放还了人质。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官决定放还他回家。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗放还了船上的工人。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查结束后，他们放还了这些人。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方查清事实，当天放还了他。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方答应放还孩子，让他回家。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队放还了抓到的农民。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，他们放还了俘虏。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们答应放还那几个工人回家。", "target_word": "放还", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放还了", "label": "体标"}, {"form": "放还过", "label": "体标"}], "register": "书面", "sense_fingerprint": "释放被扣留或关押的人，让其回家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbb1e39-abce-448a-a3b2-b460ec8179ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放还", "is_correct": true, "explanation": "“放还”指释放被扣留的人让其回家，符合“警察问完话，就……了他”的语境。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”指称赞，问完话后警察不会因此赞美他，与语境不合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与“问完话”之后的处理不合。"}, {"text": "丢掉", "is_correct": false, "explanation": "语域：“丢掉”是口语，含嫌弃的意味，不用于描述司法机关的处理。"}], "explanations": {"放还": "“放还”指释放被扣留的人让其回家，符合“警察问完话，就……了他”的语境。", "赞美": "语义：“赞美”指称赞，问完话后警察不会因此赞美他，与语境不合。", "感谢": "语义：“感谢”表示谢意，与“问完话”之后的处理不合。", "丢掉": "语域：“丢掉”是口语，含嫌弃的意味，不用于描述司法机关的处理。"}, "sentence_index": 0, "correct_answer": "放还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把迷路的学生放还了家。", "explanation": "这里应该用〈送回〉。放还指释放被扣留的人，迷路的学生并没有被扣留，应说“送回”。"}, {"text": "商场放还了顾客的钱。", "explanation": "这里应该用〈退还〉。放还指放回原处或释放被扣留的人，钱款的退回要用退还。"}, {"text": "政府把这片土地放还给了农民。", "explanation": "这里应该用〈归还〉。放还的对象是被扣留的人，土地交还给原主要用归还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放还", "is_correct": true, "explanation": "“放还”指释放被扣留的人让其回家，与后半句“让他回家”一致。"}, {"text": "关押", "is_correct": false, "explanation": "语义：“关押”表示拘禁，与“让他回家”的承诺矛盾。"}, {"text": "扣留", "is_correct": false, "explanation": "语义：“扣留”表示扣下不放，与“让他回家”的承诺矛盾。"}, {"text": "绑走", "is_correct": false, "explanation": "语义：“绑走”是强行带走，与“让他回家”相矛盾。"}], "explanations": {"放还": "“放还”指释放被扣留的人让其回家，与后半句“让他回家”一致。", "关押": "语义：“关押”表示拘禁，与“让他回家”的承诺矛盾。", "扣留": "语义：“扣留”表示扣下不放，与“让他回家”的承诺矛盾。", "绑走": "语义：“绑走”是强行带走，与“让他回家”相矛盾。"}, "sentence_index": 6, "correct_answer": "放还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父母终于把走失的孩子放还了家。", "explanation": "这里应该用〈接回〉。放还指释放被扣留的人，走失的孩子并没有被扣留，应说“接回”。"}, {"text": "军队放还了这座城市。", "explanation": "这里应该用〈解放〉。放还的对象是被扣留的人，不能用于城市。"}, {"text": "他在约定的时间放还了欠款。", "explanation": "这里应该用〈偿还〉。放还指放回原处或释放被扣留的人，欠款的清偿要用偿还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们昨天不放还了那个工人。", "corrected_sentence": "他们昨天放还了那个工人。", "error_description": "错误形式为“不放还了”，正确形式为“放还了”。“了”表示动作已经完成，不能与否定词“不”一起用于已经发生的动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "案情查清后，警方放还着那位证人。", "corrected_sentence": "案情查清后，警方放还了那位证人。", "error_description": "“着”表示动作的持续或状态，与“案情查清后”这一已完成的时间不合；已完成的动作用“了”。正确：放还了那位证人；错误：放还着那位证人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01f8fecc-eb53-4839-8a99-0f11814bef4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
