INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97770, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不再严加管束，放宽对价格、政策等的限制。", "primary_collocate": null, "pronunciation": "fàng kāi", "ipa": "faŋ˥˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "政府放开了对价格的管理。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家放开了生育限制。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校放开了手机的使用限制。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场放开以后，价格有了变化。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市放开了对外地车的限制。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师终于放开手让我们自己做。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长要放开手，让孩子自己长大。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司放开了对员工的上网限制。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放开价格后，买东西的人多了。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院放开了探视时间的限制。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放开了", "label": "完成体"}, {"form": "放开过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "不再管得很严，放宽对价格、政策、行为等的限制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '626c37bb-6c51-4dc9-849b-b00c7672087d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放开", "is_correct": true, "explanation": "放开：放宽限制，与“对价格的管理”搭配，符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣物，不能和“对价格的管理”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”是饮用，与政府对价格的管理无关，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是进食，与政府对价格的管理无关，句意不通。"}], "explanations": {"放开": "放开：放宽限制，与“对价格的管理”搭配，符合句意。", "穿": "搭配：“穿”用于衣物，不能和“对价格的管理”搭配。", "喝": "语义：“喝”是饮用，与政府对价格的管理无关，句意不通。", "吃": "语义：“吃”是进食，与政府对价格的管理无关，句意不通。"}, "sentence_index": 0, "correct_answer": "放开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府放开了这项计划。", "explanation": "这里应该用〈放弃〉。“放开”指放宽限制，计划不能被“放开”，应说放弃计划。"}, {"text": "政府放开了这个城市的面积。", "explanation": "这里应该用〈扩大〉。放开指放宽限制，面积增大要说扩大，不能用放开。"}, {"text": "政府昨天放开了一场新闻发布会。", "explanation": "这里应该用〈召开〉。放开指放宽限制，举行会议要说召开，不能说放开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放开", "is_correct": true, "explanation": "放开：不再过多管束，符合“家长要……手，让孩子自己长大”的语境。"}, {"text": "抓紧", "is_correct": false, "explanation": "语义：“抓紧”是握牢，与“让孩子自己长大”的要求相反。"}, {"text": "握紧", "is_correct": false, "explanation": "语义：“握紧”是握牢不放，与“让孩子自己长大”的意思相反。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣物、鞋袜，不能用于“手”，句子不通。"}], "explanations": {"放开": "放开：不再过多管束，符合“家长要……手，让孩子自己长大”的语境。", "抓紧": "语义：“抓紧”是握牢，与“让孩子自己长大”的要求相反。", "握紧": "语义：“握紧”是握牢不放，与“让孩子自己长大”的意思相反。", "穿": "搭配：“穿”用于衣物、鞋袜，不能用于“手”，句子不通。"}, "sentence_index": 6, "correct_answer": "放开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院放开了探视的大门。", "explanation": "这里应该用〈打开〉。大门要用“打开”，“放开”不能用于门。"}, {"text": "医院放开了那个病人的手术。", "explanation": "这里应该用〈进行〉。放开指松手或放宽限制，手术要进行，不能说放开。"}, {"text": "医院放开了病人的时间。", "explanation": "这里应该用〈占用〉。放开指松手或放宽限制，占用时间要说占用，不能说放开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府还没放开了对房价的限制。", "corrected_sentence": "政府还没放开对房价的限制。", "error_description": "“还没”表示尚未发生，不能与“了”同用。应去掉“了”，改为“政府还没放开对房价的限制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府正在放开了汽车的购买限制。", "corrected_sentence": "政府正在放开汽车的购买限制。", "error_description": "“正在”表示动作正在进行，不能与“了”同用。应去掉“了”，改为“政府正在放开汽车的购买限制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71c02708-c39d-419b-b9f4-ec310e98cdbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
