INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97773, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "早上见面互相说的好话。", "primary_collocate": null, "pronunciation": "zǎo ān", "ipa": "tsɑʊ˨˩˦ an˥˥", "syllable_count": 2, "sentences": [{"text": "每天早上，我都对邻居说早安。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着对大家说了一声早安。", "target_word": "早安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早安，今天天气真好！", "target_word": "早安", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同学们见到老师，都说早安。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给妈妈发了一条早安短信。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在我们公司，同事见面先说早安。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子学会了用中文说早安。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每天早上都等着我的早安。", "target_word": "早安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是在早上七点对我说早安。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个邻居在楼道里碰到，互相说了声早安。", "target_word": "早安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "早上见面互相说的问候话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eca7faf1-53e9-4820-92b2-8ca5390197ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚安", "is_correct": false, "explanation": "语义：晚安是晚上道别时说的话，与句中“每天早上”的时间矛盾。"}, {"text": "早安", "is_correct": true, "explanation": "早安：早上见面时互相说的好话，与“对邻居说”搭配，符合句意。"}, {"text": "午安", "is_correct": false, "explanation": "语义：午安是中午的问候，与句中“每天早上”不符。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“说”后接的是话语，“早餐”是食物，不能说早餐。"}], "explanations": {"晚安": "语义：晚安是晚上道别时说的话，与句中“每天早上”的时间矛盾。", "早安": "早安：早上见面时互相说的好话，与“对邻居说”搭配，符合句意。", "午安": "语义：午安是中午的问候，与句中“每天早上”不符。", "早餐": "搭配：“说”后接的是话语，“早餐”是食物，不能说早餐。"}, "sentence_index": 0, "correct_answer": "早安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不小心摔倒了，朋友连忙跑过来，说了声早安。", "explanation": "这里应该用〈你没事吧〉。早安是见面时的问候，看到别人受伤或摔倒应先关心，不能说早安。"}, {"text": "每天晚上，爸爸都对我说早安。", "explanation": "这里应该用〈晚安〉。早安用于早晨见面，晚上道别要说晚安，这句话的时间不合。"}, {"text": "他向大家挥手道别，说了一声早安。", "explanation": "这里应该用〈再见〉。早安是见面时的问候，分别时要说再见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早饭", "is_correct": false, "explanation": "搭配：“说”后面接的是话语，“早饭”是食物，不能说出来。"}, {"text": "早安", "is_correct": true, "explanation": "早安：见面时的问候语，与“用中文说”搭配，符合句意。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：晚饭是晚上吃的饭，与“用中文说”的内容无关。"}, {"text": "早茶", "is_correct": false, "explanation": "搭配：早茶指饮茶的活动，“说”不能接“早茶”。"}], "explanations": {"早饭": "搭配：“说”后面接的是话语，“早饭”是食物，不能说出来。", "早安": "早安：见面时的问候语，与“用中文说”搭配，符合句意。", "晚饭": "语义：晚饭是晚上吃的饭，与“用中文说”的内容无关。", "早茶": "搭配：早茶指饮茶的活动，“说”不能接“早茶”。"}, "sentence_index": 6, "correct_answer": "早安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我帮老师拿了书，他连忙说了声早安。", "explanation": "这里应该用〈谢谢〉。别人帮了忙要表示感谢，应说谢谢；早安是见面时的问候。"}, {"text": "我不小心撞到他，我连忙说了声早安。", "explanation": "这里应该用〈对不起〉。撞到别人要道歉，应说对不起；早安不能表示歉意。"}, {"text": "他考上大学，大家都向他说了声早安。", "explanation": "这里应该用〈恭喜〉。别人有喜事时要道贺，应说恭喜；早安是见面问候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天早上都对我说一只早安。", "corrected_sentence": "妈妈每天早上都对我说一声早安。", "error_description": "量词用错：早安是问候，应与“声”搭配，说“一声早安”；“一只”是用于动物的量词，不能用来数问候语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈早上起床后，总是笑着对我说一只早安。", "corrected_sentence": "妈妈早上起床后，总是笑着对我说一句早安。", "error_description": "量词用错：早安是一句问候语，应说“一句早安”；“一只”是用于动物的量词，不能用来数问候语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
