INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "早晨见面时的问候语。", "primary_collocate": null, "pronunciation": "zǎo ān", "ipa": "tsɑʊ˨˩˦ an˥˥", "syllable_count": 2, "sentences": [{"text": "早安是早晨见面时说的话。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门口的保安向我们点头说早安。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你替我向奶奶问声早安。", "target_word": "早安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台主持人说：“听众朋友，早安！”", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机里有很多好看的早安图片。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在微信上给朋友发了早安。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在很多人也爱说早安。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他进办公室，先向大家道了声早安。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明大声说早安，老师也笑了。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早安是一句很简单的问候。", "target_word": "早安", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "早晨见面时的问候语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eca7faf1-53e9-4820-92b2-8ca5390197ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚安", "is_correct": false, "explanation": "语义：晚安是晚上道别时用的，与句中“早晨”矛盾。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是中午吃的饭，不是见面时说的话。"}, {"text": "早安", "is_correct": true, "explanation": "早安：早晨见面时说的话，与句中“早晨见面时”一致。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“说的话”指问候语，早餐是食物，不能作为见面时说的话。"}], "explanations": {"晚安": "语义：晚安是晚上道别时用的，与句中“早晨”矛盾。", "午饭": "语义：午饭是中午吃的饭，不是见面时说的话。", "早安": "早安：早晨见面时说的话，与句中“早晨见面时”一致。", "早餐": "搭配：“说的话”指问候语，早餐是食物，不能作为见面时说的话。"}, "sentence_index": 0, "correct_answer": "早安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天是小明的生日，我对他说了声早安。", "explanation": "这里应该用〈生日快乐〉。早安是早晨见面时的问候，生日祝福要说生日快乐。"}, {"text": "夜里十点，他对同学说了早安。", "explanation": "这里应该用〈晚安〉。早安用于早晨见面，夜里道别要说晚安，这里时间不对。"}, {"text": "他转身离开，对大家说了早安。", "explanation": "这里应该用〈再见〉。离开时要说再见，早安只用于见面问候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夜景", "is_correct": false, "explanation": "搭配：“说”接的是话语，“夜景”是景色，不能说夜景。"}, {"text": "早安", "is_correct": true, "explanation": "早安：见面时的问候语，与“说”搭配，符合句意。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，不是可以说出口的话。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“说”后面接的是问候语，“早饭”是食物，不能说。"}], "explanations": {"夜景": "搭配：“说”接的是话语，“夜景”是景色，不能说夜景。", "早安": "早安：见面时的问候语，与“说”搭配，符合句意。", "咖啡": "语义：咖啡是饮料，不是可以说出口的话。", "早饭": "搭配：“说”后面接的是问候语，“早饭”是食物，不能说。"}, "sentence_index": 6, "correct_answer": "早安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被老板批评后，低声说了早安。", "explanation": "这里应该用〈对不起〉。被批评后要道歉，应说对不起；早安是见面问候。"}, {"text": "我借了同学的笔，连声说早安。", "explanation": "这里应该用〈谢谢〉。别人借出东西后要表示感谢，应说谢谢。"}, {"text": "他拿到了第一名，大家都向他说了声早安。", "explanation": "这里应该用〈恭喜〉。别人取得成绩时要道贺，应说恭喜；早安是见面问候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我进门的时候，先向大家说了一只早安。", "corrected_sentence": "我进门的时候，先向大家说了一句早安。", "error_description": "量词用错：早安是一句问候语，应说“一句早安”；“一只”是用于动物的量词，不能用来数问候语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们都站起来，向老师说了一只早安。", "corrected_sentence": "同学们都站起来，向老师说了一句早安。", "error_description": "量词用错：早安是一句问候语，应说“一句早安”；“一只”用于动物，不能用来数问候语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b3a7ac-56c1-4aa2-be93-c9f97bf0717c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
