INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97775, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人一起乱闹，打砸东西。", "primary_collocate": null, "pronunciation": "bào dòng", "ipa": "pɑʊ˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "比赛结束后，街上发生了暴动，商店的玻璃都碎了。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察来了，人群的暴动才停下来。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚城里出现了一场暴动，不少商店着了火。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场暴动让街上到处都是碎玻璃。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看到暴动的人在砸商店的门。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为食物太少，监狱里发生了暴动。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴动结束后，工人们开始打扫街道。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在报道城里的暴动。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球场外的暴动很快变得越来越大。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，别去人多的地方，那里可能有暴动。", "target_word": "暴动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场暴动", "label": "量词（场）"}, {"form": "一次暴动", "label": "量词（次）"}], "register": "中性", "sense_fingerprint": "一群人失去控制，一起打砸、制造混乱的骚乱事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03361c-6118-4fa9-b7cc-62eda923a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暴动", "is_correct": true, "explanation": "“暴动”指很多人一起乱闹、打砸东西，与“商店的玻璃都碎了”相符。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：“讲座”是学术报告，比赛后街上发生讲座不会让商店玻璃碎，句子不通。"}, {"text": "演出", "is_correct": false, "explanation": "搭配：“发生”不搭配“演出”，一般说“举行演出”。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：“婚礼”是喜庆仪式，与商店玻璃被砸碎的场面不符。"}], "explanations": {"暴动": "“暴动”指很多人一起乱闹、打砸东西，与“商店的玻璃都碎了”相符。", "讲座": "语义：“讲座”是学术报告，比赛后街上发生讲座不会让商店玻璃碎，句子不通。", "演出": "搭配：“发生”不搭配“演出”，一般说“举行演出”。", "婚礼": "语义：“婚礼”是喜庆仪式，与商店玻璃被砸碎的场面不符。"}, "sentence_index": 0, "correct_answer": "暴动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆里的读者在安静地暴动，认真看书。", "explanation": "这里应该用〈阅读〉。“暴动”指很多人一起乱闹、打砸东西，与安静看书的场景完全相反，应说“阅读”。"}, {"text": "学生们举着横幅暴动，要求保护环境。", "explanation": "这里应该用〈游行〉。“暴动”指乱闹打砸，举横幅有秩序地走是游行。"}, {"text": "同学们在操场上暴动，唱歌跳舞。", "explanation": "这里应该用〈聚会〉。“暴动”指乱闹打砸，和“唱歌跳舞”的欢聚气氛不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暴动", "is_correct": true, "explanation": "“暴动”结束后街道会一片狼藉，工人们开始打扫，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不是可以结束的活动，句子不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不能作为“结束”的事件，句子不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“结束”多搭配活动、比赛、考试，不说“咖啡结束”。"}], "explanations": {"暴动": "“暴动”结束后街道会一片狼藉，工人们开始打扫，符合语境。", "冰箱": "语义：“冰箱”是家电，不是可以结束的活动，句子不通。", "钢琴": "语义：“钢琴”是乐器，不能作为“结束”的事件，句子不通。", "咖啡": "搭配：“结束”多搭配活动、比赛、考试，不说“咖啡结束”。"}, "sentence_index": 6, "correct_answer": "暴动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "演员在舞台上暴动，观众很开心。", "explanation": "这里应该用〈表演〉。“暴动”指乱闹打砸，与“观众很开心”的演出场面不符。"}, {"text": "老师在台上暴动，同学们认真听。", "explanation": "这里应该用〈讲课〉。“暴动”指乱闹打砸，不是讲课的意思。"}, {"text": "爷爷每天在公园里暴动，心情很好。", "explanation": "这里应该用〈散步〉。“暴动”指乱闹打砸，和悠闲散步的语境不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里街上发生了一个暴动，很多商店的窗户都被砸碎了。", "corrected_sentence": "夜里街上发生了一场暴动，很多商店的窗户都被砸碎了。", "error_description": "量词错误：“暴动”计数应用“场”或“次”，不说“一个暴动”，应改为“一场暴动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "报纸上正在报道镇上的一只暴动。", "corrected_sentence": "报纸上正在报道镇上的一场暴动。", "error_description": "量词错误：“暴动”计数应用“场”或“次”，“一只”只用于动物等，应改为“一场暴动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c73a1b-fb87-497d-bb08-ccdc9a2365ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
